-- =============================================================================
-- HSK1 — «Гүнзгий заах» агуулга (15 хичээл)  (2026-09-16)
-- =============================================================================
--
-- ӨМНӨХ НӨХЦӨЛ: migrations/061_lesson_deep_teaching.sql ажилласан байх.
--
-- HSK1 бол суурь тавьдаг түвшин тул хичээл бүрийг илүү дэлгэрэнгүй заах
-- агуулгыг нэмэв:
--   • үг бүрд — тайлбар, хэрэглээ, 3–5 жишээ, түгээмэл алдаа, ойролцоо
--     үгтэй харьцуулалт;
--   • дүрэм бүрд — 3–4 алхмын задаргаа, бүтцийн томьёо, 5–8 жишээ, алдаа,
--     шууд хариултаа шалгадаг 3–4 дасгал;
--   • ханз бүрд — язгуур, бүрэлдэхүүн, санамж, зурлагын зөвлөгөө, андуурч
--     болох ханз, тэр ханз орсон үгс;
--   • хичээл бүрд — дуудлагын 3 дасгал (ойролцоо дуудлагатай хосууд).
--
-- Эх багц (lessons.source_note) ХӨНДӨГДӨХГҮЙ — энэ нь дээрээс нь давхарлах
-- нэмэлт давхарга. Мөр байхгүй хичээл урьдын адил ажиллана.
--
-- Дахин ажиллуулахад аюулгүй (upsert).
-- =============================================================================

begin;

insert into public.lesson_deep_teaching (lesson_id, version, payload)
values ('hsk1-l01', 1, '{"words": [{"zh": "你", "pinyin": "nǐ", "teach_mn": "«你» гэдэг нь монгол хэлний «чи» гэсэн үгтэй адил, ярианд байгаа хүнд шууд хандахад хэрэглэдэг төлөөний үг. Өгүүлбэрийн эхэнд ордог бөгөөд ихэвчлэн ард нь 好 гэх мэт үг залгаж мэндчилнэ. Хятад хэлэнд «чи» гэдгийг насны ялгаагаар хоёр янзаар хэлдэг: үе тэнгийнхэндээ 你, ахмад хүнд 您. Монгол хэлэнд ийм ялгаа байдаггүй тул энэ бол шинэ ойлголт.", "usage_mn": ["Үе тэнгийн найз, дүү, өөртэйгээ ойролцоо насныхандаа хэрэглэнэ", "Ахмад хүн, багш, шинэ танилдаа хэрэглэхгүй — тэдэнд 您 хэлнэ"], "examples": [{"zh": "你好！", "pinyin": "Nǐ hǎo!", "mn": "Сайн уу!", "note_mn": "хамгийн түгээмэл, энгийн мэндчилгээ"}, {"zh": "你好，你好！", "pinyin": "Nǐ hǎo, nǐ hǎo!", "mn": "Сайн уу, сайн уу!", "note_mn": "хоёр найз уулзаад зэрэг мэндлэхэд ийн давтаж хэлэх нь элбэг"}, {"zh": "你们好！", "pinyin": "Nǐmen hǎo!", "mn": "Та нар сайн уу!", "note_mn": "你 нь 你们 (та нар) гэдэг үгийн язгуур болж байгааг ажигла"}, {"zh": "对不起，你好！", "pinyin": "Duìbuqǐ, nǐ hǎo!", "mn": "Уучлаарай, сайн уу!", "note_mn": "ангидаа оройтож ирээд эхлээд уучлал гуйгаад дараа нь мэндэлж байна"}], "mistakes": [{"wrong": "你好你！", "right": "你好！", "why_mn": "你好 өөрөө бүрэн, дуусгасан мэндчилгээ тул ард нь 你-г дахин давтах шаардлагагүй."}], "compare": [{"zh": "您", "pinyin": "nín", "mn": "та", "diff_mn": "хүндэтгэлийн хэлбэр — ахмад хүн, багш, шинэ танилд хэрэглэнэ."}]}, {"zh": "好", "pinyin": "hǎo", "teach_mn": "«好» нь «сайн» гэсэн утгатай ч HSK1-д ихэвчлэн 你/您/你们-ийн ард залгаж мэндчилгээ болгон хэрэглэдэг. Дангаараа хэлэхэд ч «сайн, зүгээр» гэсэн үнэлэмж заана. Өгүүлбэрт үргэлж хандаж буй хүнийхээ ард ордог, урд нь ордоггүй. Монгол хэлний «сайн уу» гэдэг тогтсон мэндчилгээтэй ижил зарчмаар санаж болно.", "usage_mn": ["你/您/你们-ийн ард залгаж мэндэлнэ", "Дангаараа хэлэхэд ерөнхий «сайн» гэсэн үнэлэмж заана"], "examples": [{"zh": "你好！", "pinyin": "Nǐ hǎo!", "mn": "Сайн уу!", "note_mn": "хамгийн энгийн хэлбэр"}, {"zh": "您好！", "pinyin": "Nín hǎo!", "mn": "Та сайн байна уу!", "note_mn": "хүндэтгэлийн хэлбэртэй хослуулсан"}, {"zh": "你们好！", "pinyin": "Nǐmen hǎo!", "mn": "Та нар сайн уу!", "note_mn": "олон хүнд зэрэг мэндэлж байна"}], "mistakes": [{"wrong": "好你！", "right": "你好！", "why_mn": "好 үргэлж хандаж буй хүнийг заасан үгийн ард ордог тогтсон дараалалтай."}]}, {"zh": "您", "pinyin": "nín", "teach_mn": "«您» нь 你-ийн хүндэтгэлийн хэлбэр — «та» гэж орчуулна. Ахмад хүн, багш, дарга, шинэ танилдаа хүндэтгэл үзүүлж хэлдэг. Бүтэц, хэрэглээ нь 你-тэй адилхан, зөвхөн илүү хүндэтгэлтэй нөхцөлд сонгож хэрэглэнэ гэдгээрээ ялгаатай. Монгол хэлэнд ч бид ахмад хүнд илүү хүндэтгэлтэй хандах ёстой, гэхдээ үгээр биш аяны өнгөөр илэрхийлдэг нь ялгаа.", "usage_mn": ["Ахмад хүн, багш, дарга, шинэ танилдаа хэрэглэнэ", "Найз нөхөд, дүү нартаа хэрэглэхгүй — тэдэнд 你 хангалттай"], "examples": [{"zh": "您好！", "pinyin": "Nín hǎo!", "mn": "Та сайн байна уу!", "note_mn": "багш, ахмад хүнд хэлэх стандарт мэндчилгээ"}, {"zh": "您好，对不起！", "pinyin": "Nín hǎo, duìbuqǐ!", "mn": "Та сайн байна уу, уучлаарай!", "note_mn": "ахмад хүнтэй уулзаад эхлээд мэндэлж, дараа нь жижиг зүйлд уучлал гуйж байна"}, {"zh": "你们好，您好！", "pinyin": "Nǐmen hǎo, nín hǎo!", "mn": "Та нар сайн уу, та сайн байна уу!", "note_mn": "олон хүнд ерөнхийд нь мэндлээд, дундах ахмад хүнд тусад нь дахин хүндэтгэл үзүүлж байна"}], "mistakes": [{"wrong": "你好！（багшдаа хэлэхэд）", "right": "您好！", "why_mn": "багш бол хүндэтгэх ёстой хүн тул энгийн 你 биш хүндэтгэлийн 您-г хэрэглэнэ."}], "compare": [{"zh": "你", "pinyin": "nǐ", "mn": "чи", "diff_mn": "энгийн, хүндэтгэлгүй хэлбэр — үе тэнгийн хүн, дүү нарт хэрэглэнэ."}]}, {"zh": "你们", "pinyin": "nǐmen", "teach_mn": "«你们» нь 你 (чи) дээр 们 гэдэг олон тооны дагавар залгаж «та нар» болгосон үг. Хоёр ба түүнээс дээш хүнд хамтад нь хандахад хэрэглэнэ. Ганц хүнд хандахдаа 你们 хэрэглэдэггүй — тэр үед 你 эсвэл 您. Монгол хэлэнд «та нар» гэдэг нөхцөл залгаж олон тоо болгодогтой адил, хятад хэлэнд 们 дагавар олон тоог заана.", "usage_mn": ["Хоёр ба түүнээс дээш хүнд зэрэг хандахад хэрэглэнэ", "Ганц хүнд хандахдаа хэрэглэхгүй"], "examples": [{"zh": "你们好！", "pinyin": "Nǐmen hǎo!", "mn": "Та нар сайн уу!", "note_mn": "ангийн олон хүнд зэрэг мэндэлж байна"}, {"zh": "你们好，对不起！", "pinyin": "Nǐmen hǎo, duìbuqǐ!", "mn": "Та нар сайн уу, уучлаарай!", "note_mn": "олон хүнд мэндлээд дараа нь жижиг зүйлд уучлал гуйж байна"}, {"zh": "没关系，你们好！", "pinyin": "Méi guānxi, nǐmen hǎo!", "mn": "Зүгээр ээ, та нар сайн уу!", "note_mn": "хэн нэгний уучлалыг хүлээж аваад, шинээр орж ирсэн хүмүүст мэндэлж байна"}], "mistakes": [{"wrong": "你好！（хоёр хүнд зэрэг хэлэхэд）", "right": "你们好！", "why_mn": "нэгээс олон хүнд ярихдаа 你-г бус олон тооны 你们-г хэрэглэнэ."}], "compare": [{"zh": "您们", "pinyin": "nínmen", "mn": "та нар (хүндэтгэл)", "diff_mn": "утга дээрээ зөв ч ярианд бараг хэрэглэдэггүй — олон хүнд ахмад эсэхийг үл харгалзан ердийн байдлаар 你们 гэж хэлдэг."}]}, {"zh": "对不起", "pinyin": "duìbuqǐ", "teach_mn": "«对不起» нь «уучлаарай» гэсэн утгатай тогтсон хэллэг — задалж, өөрчилж хэрэглэдэггүй бүхэл нэг блок гэж цээжил. Санамсаргүй жижиг алдаа гаргах үед хэрэглэнэ: жишээ нь хожимдох, хэн нэгэнтэй мөргөлдөх, ярианд саад учруулах. Монгол хэлний «уучлаарай» гэдэг ганц үгтэй адилхан, гэхдээ хятад хэлэнд энэ нь дөрвөн үзгээс бүтсэн тогтмол хэллэг.", "usage_mn": ["Санамсаргүй жижиг алдаа гаргах үед (хожимдох, мөргөх, саад болох)", "Хэллэгийг задалж дундуур нь өөр үг оруулахгүй"], "examples": [{"zh": "对不起！", "pinyin": "Duìbuqǐ!", "mn": "Уучлаарай!", "note_mn": "хамгийн энгийн, шууд хэлбэр"}, {"zh": "你好，对不起！", "pinyin": "Nǐ hǎo, duìbuqǐ!", "mn": "Сайн уу, уучлаарай!", "note_mn": "мэндэлж байгаад дараа нь оройтсондоо уучлал гуйж байна"}, {"zh": "您好，对不起！", "pinyin": "Nín hǎo, duìbuqǐ!", "mn": "Та сайн байна уу, уучлаарай!", "note_mn": "ахмад хүнд хандаж уучлал гуйж байна"}], "mistakes": [{"wrong": "对不起您！", "right": "对不起！", "why_mn": "对不起 өөрөө бүрэн хэллэг тул ард нь хэнд хэлж байгаагаа нэмж заах шаардлагагүй."}]}, {"zh": "没关系", "pinyin": "méi guānxi", "teach_mn": "«没关系» нь «зүгээр, хамаагүй ээ» гэсэн утгатай, хэн нэгэн 对不起 гэж уучлал гуйхад хариулж хэлдэг тогтсон хэллэг. Энэ хоёр үг үргэлж хос болж явдаг — 对不起 асуудал гаргасан хүнээс, 没关系 хариу үгээс гардаг. Ярианы эхэнд өөрөө санаачлан хэлдэггүй, зөвхөн хариу болгож хэрэглэнэ.", "usage_mn": ["Хэн нэгэн 对不起 гэхэд хариу болгож хэлнэ", "Ярианы эхэнд өөрөө санаачлан хэлдэггүй"], "examples": [{"zh": "没关系！", "pinyin": "Méi guānxi!", "mn": "Зүгээр зүгээр ээ!", "note_mn": "уучлалыг хүлээж авах хамгийн энгийн хариу"}, {"zh": "对不起！没关系！", "pinyin": "Duìbuqǐ! Méi guānxi!", "mn": "Уучлаарай! — Зүгээр ээ!", "note_mn": "хоёр хүний ярианы бүтэн солилцоог харуулж байна"}, {"zh": "没关系，你好！", "pinyin": "Méi guānxi, nǐ hǎo!", "mn": "Зүгээр ээ, сайн уу!", "note_mn": "уучлалыг хүлээж аваад дараа нь мэндэлж байна"}], "mistakes": [{"wrong": "没关系你", "right": "没关系！", "why_mn": "没关系 бол тогтсон хэллэг, ард нь өөр үг залгаж уртасгахгүй."}]}], "grammar": [{"point": "你 / 您 / 你们 — мэндчилгээний хэлбэрүүд", "gloss_mn": "чи / та / та нар", "structure": "你 / 您 / 你们 + 好 → 你好 / 您好 / 你们好", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "你 нь «чи», 您 нь хүндэтгэлийн «та», 你们 нь «та нар». Гурав нь бүгд ярианд байгаа хүн рүү хандаж буйгаа заана, зөвхөн хэн рүү, хэдэн хүнд хандаж байгаагаараа ялгаатай.", "example": {"zh": "你 / 您 / 你们", "pinyin": "nǐ / nín / nǐmen", "mn": "чи / та / та нар"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Хандаж буй үгийнхээ ард шууд 好-г залгана, өөр ямар ч үг завсарт нь оруулахгүй.", "example": {"zh": "你+好=你好", "pinyin": "nǐ + hǎo = nǐ hǎo", "mn": "чи+сайн=сайн уу"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Анх танилцах, өдөр бүр уулзах үедээ ярианы эхэнд мэндчилнэ. Хэн рүү хандаж байгаагаас хамаарч гурвын аль тохирохыг нь сонгоно: найздаа 你, багшдаа 您, олон хүнд 你们.", "example": {"zh": "你们好！", "pinyin": "Nǐmen hǎo!", "mn": "Та нар сайн уу!"}}, {"title_mn": "4. Өргөтгөл, ялгаа", "body_mn": "你们 бол 你 дээр 们 (олон тооны дагавар) залгасан үг. 您 нь ганц хүнд л хэрэглэгддэг хүндэтгэлийн хэлбэр тул 您们 гэж бараг хэлдэггүй, олон хүнд ахмад эсэхийг үл харгалзан 你们 хэрэглэнэ.", "example": {"zh": "您们(ховор) → 你们", "pinyin": "nínmen → nǐmen", "mn": "олон ахмад хүнд ч гэсэн 你们 гэж хэлнэ"}}], "examples": [{"zh": "你好！", "pinyin": "Nǐ hǎo!", "mn": "Сайн уу!"}, {"zh": "您好！", "pinyin": "Nín hǎo!", "mn": "Та сайн байна уу!"}, {"zh": "你们好！", "pinyin": "Nǐmen hǎo!", "mn": "Та нар сайн уу!"}, {"zh": "你好，你好！", "pinyin": "Nǐ hǎo, nǐ hǎo!", "mn": "Сайн уу, сайн уу!"}, {"zh": "您好，您好！", "pinyin": "Nín hǎo, nín hǎo!", "mn": "Та сайн байна уу, та сайн байна уу!"}, {"zh": "您好，对不起！", "pinyin": "Nín hǎo, duìbuqǐ!", "mn": "Та сайн байна уу, уучлаарай!"}, {"zh": "你们好，没关系！", "pinyin": "Nǐmen hǎo, méi guānxi!", "mn": "Та нар сайн уу, зүгээр ээ!"}, {"zh": "你好，您好，你们好！", "pinyin": "Nǐ hǎo, nín hǎo, nǐmen hǎo!", "mn": "Сайн уу, та сайн байна уу, та нар сайн уу!"}], "mistakes": [{"wrong": "您们好！", "right": "你们好！", "why_mn": "您们 гэдэг хэлбэр ярианд бараг хэрэглэгддэггүй, олон хүнд ахмад эсэхээс үл хамааран 你们 хэрэглэнэ."}, {"wrong": "你好您！", "right": "您好！", "why_mn": "хүндэтгэлийн үг (您) болон энгийн үг (你)-г нэг өгүүлбэрт хольж хэрэглэхгүй, аль нэгийг сонго."}], "drills": [{"type": "choice", "question": "___ 好！（багшдаа）", "options": ["你", "您", "你们"], "answer": "您", "why_mn": "Багш бол ахмад тул хүндэтгэлийн 您-г хэрэглэнэ."}, {"type": "choice", "question": "___ 好！（ангийн олон найздаа зэрэг）", "options": ["你", "您", "你们"], "answer": "你们", "why_mn": "Олон хүнд ярихдаа олон тооны хэлбэр 你们-г хэрэглэнэ."}, {"type": "judge", "question": "您们 гэдэг үг ердийн ярианд элбэг хэрэглэгддэг.", "answer": "false", "why_mn": "Ярианд бараг хэрэглэгддэггүй, олон хүнд 你们-г л хэрэглэдэг."}, {"type": "fill", "question": "你 + 好 = ___", "answer": "你好", "why_mn": "Хандах үгийн ард 好-г шууд залгаж бичнэ, зай, өөр үг нэмэхгүй."}]}, {"point": "对不起 — 没关系", "gloss_mn": "уучлаарай — зүгээр зүгээр", "structure": "对不起！(алдаа гаргасан хүн) → 没关系！(хариулж буй хүн)", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "对不起 нь «уучлаарай», 没关系 нь «зүгээр, хамаагүй ээ» гэсэн утгатай. Хоёул бие даасан, задардаггүй тогтсон хэллэг.", "example": {"zh": "对不起 / 没关系", "pinyin": "duìbuqǐ / méi guānxi", "mn": "уучлаарай / зүгээр"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Хоёул HSK1-д бэлэн хэллэг маягаар л цээжилнэ, үг тус бүрийг задалж утга шинжлэх шаардлагагүй.", "example": {"zh": "对不起！", "pinyin": "Duìbuqǐ!", "mn": "Уучлаарай!"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Хожимдох, мөргөх, ярианд саад болох зэрэг санамсаргүй жижиг зүйлд 对不起 гэж уучлал гуйна. Үүнд хариулахдаа 没关系 гэж хэлнэ.", "example": {"zh": "对不起！没关系！", "pinyin": "Duìbuqǐ! Méi guānxi!", "mn": "Уучлаарай! — Зүгээр ээ!"}}, {"title_mn": "4. Өргөтгөл", "body_mn": "没关系-г ярианы эхэнд өөрөө санаачлан хэлдэггүй, энэ бол зөвхөн 对不起-д өгөх хариу.", "example": {"zh": "没关系！", "pinyin": "Méi guānxi!", "mn": "Зүгээр ээ! (зөвхөн хариу болгож)"}}], "examples": [{"zh": "对不起！", "pinyin": "Duìbuqǐ!", "mn": "Уучлаарай!"}, {"zh": "没关系！", "pinyin": "Méi guānxi!", "mn": "Зүгээр зүгээр ээ!"}, {"zh": "你好，对不起！", "pinyin": "Nǐ hǎo, duìbuqǐ!", "mn": "Сайн уу, уучлаарай!"}, {"zh": "您好，对不起！", "pinyin": "Nín hǎo, duìbuqǐ!", "mn": "Та сайн байна уу, уучлаарай!"}, {"zh": "没关系，你们好！", "pinyin": "Méi guānxi, nǐmen hǎo!", "mn": "Зүгээр ээ, та нар сайн уу!"}, {"zh": "对不起！没关系！", "pinyin": "Duìbuqǐ! Méi guānxi!", "mn": "Уучлаарай! — Зүгээр ээ!"}], "mistakes": [{"wrong": "关系没！", "right": "没关系！", "why_mn": "没关系 тогтсон дараалалтай хэллэг, үгсийг эргүүлж хэлж болохгүй."}, {"wrong": "对不起您！", "right": "对不起！", "why_mn": "对不起 өөрөө бүрэн хэллэг, ард нь хэнд хэлж байгаагаа нэмэхгүй."}], "drills": [{"type": "judge", "question": "没关系-г ярианы эхэнд өөрөө санаачлан хэлж болно.", "answer": "false", "why_mn": "没关系 бол зөвхөн 对不起-д хариулах хэллэг, өөрөө ярианы эхлэл болдоггүй."}, {"type": "choice", "question": "「对不起！」гэхэд хамгийн зохимжтой хариу аль нь вэ?", "options": ["你好", "没关系", "你们好"], "answer": "没关系", "why_mn": "对不起-д стандарт хариу бол 没关系."}, {"type": "fill", "question": "Ангид хожимдож ирвэл юу гэж хэлэх вэ?", "answer": "对不起", "why_mn": "Хожимдох нь санамсаргүй жижиг алдаа тул 对不起 гэж уучлал гуйна."}, {"type": "judge", "question": "对不起 болон 没关系-г дундуур нь өөр үг оруулж уртасгаж болно.", "answer": "false", "why_mn": "Хоёул тогтсон хэллэг тул задлахгүй бүхлээр нь хэрэглэнэ."}]}, {"point": "Ханзны үндсэн зурлага (1)：一 丨 丿 丶 ㇏", "gloss_mn": "хэвтээ · босоо · зүүн налуу · цэг · баруун налуу", "structure": "héng(一) · shù(丨) · piě(丿) · diǎn(丶) · nà(㇏)", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "Зурлага бол ханз бичихэд хэрэглэдэг хамгийн жижиг нэгж, гэрийн тоосго шиг. Тав нь: 一 хэвтээ, 丨 босоо, 丿 зүүн налуу, 丶 цэг, ㇏ баруун налуу.", "example": {"zh": "一 丨 丿 丶 ㇏", "pinyin": "héng shù piě diǎn nà", "mn": "таван үндсэн зурлага"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Ганц ханз дотор хэд хэдэн зурлага хосолж нэгддэг. Жишээ нь 十 бол 一 (хэвтээ) дээр 丨 (босоо) нэмсэн хоёр зурлагатай ханз.", "example": {"zh": "十 = 一 + 丨", "pinyin": "shí", "mn": "арав = хэвтээ + босоо"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Ханз бичих болгонд эдгээр зурлагыг тогтсон дараалал, чиглэлээр татна: ихэвчлэн зүүнээс баруун, дээрээс доош.", "example": {"zh": "一", "pinyin": "yī", "mn": "зүүнээс баруун тийш нэг зураас"}}, {"title_mn": "4. Ялгаа", "body_mn": "Монгол бичигт нэг төрлийн зураас байдаг бол хятад ханзанд чиглэл, урт багаараа ялгаатай таван үндсэн зурлага байдгийг сана.", "example": {"zh": "丨 vs 丿", "pinyin": "shù vs piě", "mn": "босоо ба зүүн налуугийн ялгаа"}}], "examples": [{"zh": "一 · 二", "pinyin": "yī · èr", "mn": "нэг, хоёр — зөвхөн хэвтээ зурлагаас тогтоно"}, {"zh": "十 · 人", "pinyin": "shí · rén", "mn": "арав (хэвтээ+босоо), хүн (зүүн ба баруун налуу)"}, {"zh": "不 · 大", "pinyin": "bù · dà", "mn": "үгүй, том — цэг, налуу зурлагатай жишээ"}, {"zh": "三", "pinyin": "sān", "mn": "гурав — гурван хэвтээ зурлагаас тогтоно"}, {"zh": "八", "pinyin": "bā", "mn": "найм — зүүн налуу, баруун налуугаас тогтоно"}, {"zh": "六", "pinyin": "liù", "mn": "зургаа — цэг, хэвтээ, хоёр цэгээс тогтоно"}], "mistakes": [{"wrong": "一-г баруунаас зүүн тийш татах", "right": "一-г зүүнээс баруун тийш татах", "why_mn": "Хэвтээ зурлагыг үргэлж зүүнээс баруун тийш татдаг стандарт дүрэм."}, {"wrong": "丨-г доороос дээш татах", "right": "丨-г дээрээс доош татах", "why_mn": "Босоо зурлагыг үргэлж дээрээс доош татна."}], "drills": [{"type": "choice", "question": "十 ямар хоёр зурлагаас тогтдог вэ?", "options": ["一 ба 丨", "丿 ба ㇏", "丶 ба 一"], "answer": "一 ба 丨", "why_mn": "十 нь хэвтээ зурлага дунд нь босоо зурлага огтолцсон хэлбэртэй."}, {"type": "judge", "question": "丨-г дээрээс доош татдаг.", "answer": "true", "why_mn": "Босоо зурлагын стандарт бичих чиглэл дээрээс доош."}, {"type": "fill", "question": "一 ямар зурлага вэ? (нэрийг нь бич)", "answer": "héng (хэвтээ)", "why_mn": "一 бол хэвтээ зурлагыг илэрхийлдэг."}, {"type": "choice", "question": "八 ямар хоёр зурлагаас тогтдог вэ?", "options": ["丿 ба ㇏", "一 ба 丨", "丶 ба 一"], "answer": "丿 ба ㇏", "why_mn": "八 нь зүүн налуу, баруун налуу хоёр зурлагаас тогтоно."}]}, {"point": "Дан бүтэцт ханз：一 二 三 十 八 六", "gloss_mn": "эхний зургаан ханз — тоонууд", "structure": "Дан бүтэцт ханз — өөр жижиг ханз, радикал агуулаагүй, өөрөө бүхэл дүрс", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "Эдгээр зургаан ханз нь «дан бүтэцт» гэж нэрлэгддэг, өөр ямар ч жижиг ханз, радикал агуулаагүй, өөрөө бие даасан бүхэл дүрс.", "example": {"zh": "三", "pinyin": "sān", "mn": "гурав — өөрөө бүхэл, задрахгүй дүрс"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Зөвхөн үндсэн зурлагуудаас шууд тогтоно, өөр ханз орж ирдэггүй. Жишээ нь 三 бол гурван хэвтээ зурлага, өөр юу ч биш.", "example": {"zh": "三 = 一+一+一", "pinyin": "sān", "mn": "гурав = гурван хэвтээ зурлага"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Тоо хэлэх, тоолох, огноо, нас зэргийг хэлэхдээ энэ зурган тэмдгүүдийг ашиглана.", "example": {"zh": "十", "pinyin": "shí", "mn": "арав"}}, {"title_mn": "4. Ялгаа", "body_mn": "Монгол бичигт тоог тусгай тоон тэмдгээр (араб тоо) бичдэг бол хятад хэлэнд ярианд болон бичгэнд тоог ханзаар ч бичиж, уншиж болно.", "example": {"zh": "六", "pinyin": "liù", "mn": "зургаа"}}], "examples": [{"zh": "一、二、三", "pinyin": "yī, èr, sān", "mn": "нэг, хоёр, гурав"}, {"zh": "六、八、十", "pinyin": "liù, bā, shí", "mn": "зургаа, найм, арав"}, {"zh": "一", "pinyin": "yī", "mn": "нэг"}, {"zh": "二", "pinyin": "èr", "mn": "хоёр"}, {"zh": "三", "pinyin": "sān", "mn": "гурав"}, {"zh": "十", "pinyin": "shí", "mn": "арав"}, {"zh": "八", "pinyin": "bā", "mn": "найм"}, {"zh": "六", "pinyin": "liù", "mn": "зургаа"}], "mistakes": [{"wrong": "十 = зургаа", "right": "十 = арав, 六 = зургаа", "why_mn": "十 ба 六 дүрсээрээ андуурч болзошгүй, 十 загалмай хэлбэртэй (арав), 六 дээвэртэй байшин мэт дүрстэй (зургаа)."}, {"wrong": "八 = хоёр", "right": "八 = найм", "why_mn": "八 нь хоёр налуу зурлагатай ч утга нь «хоёр» биш «найм» гэдгийг сана."}], "drills": [{"type": "choice", "question": "十 гэдэг ханз ямар тоо вэ?", "options": ["зургаа", "арав", "найм"], "answer": "арав", "why_mn": "十 бол «арав» гэсэн утгатай."}, {"type": "choice", "question": "六 гэдэг ханз ямар тоо вэ?", "options": ["зургаа", "найм", "гурав"], "answer": "зургаа", "why_mn": "六 бол «зургаа» гэсэн утгатай."}, {"type": "fill", "question": "8 гэдэг тоог ханзаар бич.", "answer": "八", "why_mn": "Найм гэдэг тоог 八 гэж бичдэг."}, {"type": "judge", "question": "三 гэдэг ханз гурван хэвтээ зурлагаас тогтдог.", "answer": "true", "why_mn": "三 бол гурван хэвтээ зурлагаас бүтнэ."}]}], "hanzi": [{"hanzi": "一", "pinyin": "yī", "meaning_mn": "нэг", "story_mn": "一 бол хамгийн энгийн ханз — ганц хэвтээ зурлага. Эрт цагт хүмүүс тоолохдоо саваа зэрэгцүүлж тавьдаг байсан, нэг саваа = нэг тоо гэсэн энгийн дүрслэлээс гаралтай гэж үздэг.", "stroke_count": 1, "stroke_tips_mn": ["Зүүнээс баруун тийш нэг удаад татна", "Хэт богино биш, дунд зэргийн уртаар тат"], "confusable": [{"zh": "二", "pinyin": "èr", "mn": "хоёр", "diff_mn": "зурлагын тоогоор ялгана — 一 нэг зурлага, 二 хоёр зурлага."}], "words": [{"zh": "一个", "pinyin": "yí ge", "mn": "нэг ширхэг"}, {"zh": "第一", "pinyin": "dì yī", "mn": "нэгдүгээр"}]}, {"hanzi": "二", "pinyin": "èr", "meaning_mn": "хоёр", "story_mn": "二 нь хоёр зэрэгцсэн хэвтээ зурлагаас тогтоно — тоолж буй зүйлээ хоёр саваагаар харуулсан хамгийн энгийн тэмдэглэгээ.", "stroke_count": 2, "stroke_tips_mn": ["Дээд зурлагыг богино, доод зурлагыг арай урт тат", "Хоёуланг нь зүүнээс баруун тийш тат"], "confusable": [{"zh": "一", "pinyin": "yī", "mn": "нэг", "diff_mn": "зурлагын тоогоор ялгана — 二 хоёр зурлага, 一 нэг зурлага."}, {"zh": "两", "pinyin": "liǎng", "mn": "хоёр (тоолуурын өмнө)", "diff_mn": "тоо дараалалд 二 хэрэглэнэ (жишээ нь 二年级), харин зүйл тоолоход 两 хэрэглэнэ (жишээ нь 两个人)."}], "words": [{"zh": "二月", "pinyin": "èr yuè", "mn": "хоёрдугаар сар"}, {"zh": "第二", "pinyin": "dì èr", "mn": "хоёрдугаар"}]}, {"hanzi": "三", "pinyin": "sān", "meaning_mn": "гурав", "story_mn": "三 нь гурван хэвтээ зурлага дараалсан хэлбэртэй — 一, 二-той адил тоолох зурлагын зарчмаар үргэлжилсэн.", "stroke_count": 3, "stroke_tips_mn": ["Гурван зурлагыг дээрээс доош дараалуулан тат", "Зурлага бүрийг зүүнээс баруун тийш тат"], "confusable": [{"zh": "二", "pinyin": "èr", "mn": "хоёр", "diff_mn": "зурлагын тоогоор ялгана — 三 гурван зурлага, 二 хоёр зурлага."}], "words": [{"zh": "三月", "pinyin": "sān yuè", "mn": "гуравдугаар сар"}, {"zh": "第三", "pinyin": "dì sān", "mn": "гуравдугаар"}]}, {"hanzi": "十", "pinyin": "shí", "meaning_mn": "арав", "story_mn": "十 нь эрт цагт зөвхөн нэг босоо зурлага байсан бөгөөд хожим дунд нь хэвтээ зураас нэмэгдэж, одоогийн загалмай хэлбэртэй болсон гэж үздэг — арав дахь тоог тэмдэглэх тусгай тэмдэг.", "stroke_count": 2, "stroke_tips_mn": ["Эхлээд хэвтээ зурлагыг зүүнээс баруун тийш тат", "Дараа нь дундуур нь босоо зурлагыг дээрээс доош тат"], "confusable": [{"zh": "千", "pinyin": "qiān", "mn": "мянга", "diff_mn": "十-т хэвтээ зурлага дунд нь босоо зурлага огтолцоно, 千-д дээр нь налуу зурлага нэмэгдсэн байдгаараа ялгаатай."}], "words": [{"zh": "十一", "pinyin": "shí yī", "mn": "арван нэг"}, {"zh": "十个", "pinyin": "shí ge", "mn": "арван ширхэг"}]}, {"hanzi": "八", "pinyin": "bā", "meaning_mn": "найм", "story_mn": "八 нь эртний бичигт хоорондоо холбогдохгүй, эсрэг тийш чиглэсэн хоёр зурлагаас тогтож, анх «хуваах» гэсэн санааг илэрхийлж байсан гэж үздэг. Хожим энэ дүрсийг «найм» тоог тэмдэглэхэд зээлж хэрэглэх болсон.", "stroke_count": 2, "stroke_tips_mn": ["Эхлээд зүүн налуу зурлагыг дээрээс доош зүүн тийш тат", "Дараа нь баруун налуу зурлагыг дээрээс доош баруун тийш тат — хоёр зурлага дундуураа тулахгүй"], "confusable": [{"zh": "人", "pinyin": "rén", "mn": "хүн", "diff_mn": "хоёул зүүн ба баруун налуу хоёр зурлагатай ч 人-ийн зурлагууд дээд цэгээрээ тулдаг, 八-ийнх тулдаггүй, завсартай."}], "words": [{"zh": "八月", "pinyin": "bā yuè", "mn": "наймдугаар сар"}, {"zh": "十八", "pinyin": "shí bā", "mn": "арван найм"}]}, {"hanzi": "六", "pinyin": "liù", "meaning_mn": "зургаа", "story_mn": "六-ийн яг гарал үүсэл тодорхойгүй ч бүтэц нь дээрээ цэг, дунд нь хэвтээ зурлага, доор нь зүүн ба баруун тийш хоёр цэг байрлуулсан энгийн дүрстэй — санахдаа «дээвэртэй байшингийн доор хоёр хүн» гэж төсөөлж болно.", "stroke_count": 4, "stroke_tips_mn": ["Эхлээд дээд цэгийг тат", "Дараа нь хэвтээ зурлага, дараа нь зүүн доод цэг, эцэст нь баруун доод цэгийг тат"], "confusable": [{"zh": "八", "pinyin": "bā", "mn": "найм", "diff_mn": "六-д дээр нь цэг, доор нь хэвтээ зурлага, хоёр цэг байдаг бол 八-д зөвхөн хоёр налуу зурлага байдаг."}], "words": [{"zh": "六月", "pinyin": "liù yuè", "mn": "зургаадугаар сар"}, {"zh": "十六", "pinyin": "shí liù", "mn": "арван зургаа"}]}], "pronunciation": {"focus_mn": "Энэ хичээлд юуны түрүүнд дөрвөн аялгыг (mā/má/mǎ/mà) чихээрээ ялгаж, амаараа давтахад анхаар. Мөн 你好, 您好 мэндчилгээгээ чангаар, тод аялгаар хэлж дадлагажуулбал дараагийн хичээлүүдэд амархан болно.", "drills": [{"title_mn": "Аялга ялгах: mā / má / mǎ / mà", "instruction_mn": "Хосыг дараалан чангаар хэлж, аялгын ялгааг чихээрээ мэдэр.", "pairs": [{"a": {"zh": "妈", "pinyin": "mā", "mn": "ээж"}, "b": {"zh": "麻", "pinyin": "má", "mn": "олс"}, "note_mn": "1-р хөг тэгш өндөр, 2-р хөг доороос дээш өгсөнө."}, {"a": {"zh": "妈", "pinyin": "mā", "mn": "ээж"}, "b": {"zh": "马", "pinyin": "mǎ", "mn": "морь"}, "note_mn": "1-р хөг тэгш өндөр, 3-р хөг буугаад эргэж дээшилнэ."}, {"a": {"zh": "妈", "pinyin": "mā", "mn": "ээж"}, "b": {"zh": "骂", "pinyin": "mà", "mn": "загнах"}, "note_mn": "1-р хөг тэгш өндөр, 4-р хөг огцом буудаг."}, {"a": {"zh": "马", "pinyin": "mǎ", "mn": "морь"}, "b": {"zh": "骂", "pinyin": "mà", "mn": "загнах"}, "note_mn": "3-р хөг доошлоод дээшилнэ, 4-р хөг шууд огцом буудаг — эхлэл нь адилхан ч төгсгөл нь эсрэг."}]}, {"title_mn": "Уруулын авиа ялгах: b p m f", "instruction_mn": "Гараа амныхаа өмнө барьж, аль үгэнд салхи мэдрэгдэж байгааг ажигла.", "pairs": [{"a": {"zh": "爸爸", "pinyin": "bàba", "mn": "аав"}, "b": {"zh": "妈妈", "pinyin": "māma", "mn": "ээж"}, "note_mn": "хоёул уруулын авиа ч 爸 (b) зогсоц, 妈 (m) хамрын авиа тул чанга сонсогдол өөр."}, {"a": {"zh": "苹果", "pinyin": "píngguǒ", "mn": "алим"}, "b": {"zh": "飞机", "pinyin": "fēijī", "mn": "нисэх онгоц"}, "note_mn": "p ба f хоёул амьсгал шаардсан авиа ч гарах байрлал өөр: p уруулаараа, f уруул-шүдээрээ."}, {"a": {"zh": "猫", "pinyin": "māo", "mn": "муур"}, "b": {"zh": "飞机", "pinyin": "fēijī", "mn": "нисэх онгоц"}, "note_mn": "m хамрын авиа, f үрэлтэт авиа — дуудлагын мэдрэмж эрс ялгаатай."}, {"a": {"zh": "爸爸", "pinyin": "bàba", "mn": "аав"}, "b": {"zh": "苹果", "pinyin": "píngguǒ", "mn": "алим"}, "note_mn": "b амьсгалгүй, p амьсгалтай — гараа амныхаа өмнө барьж ялгааг мэдэр."}]}, {"title_mn": "Нэг үет үгсийн дуудлага тогтоох", "instruction_mn": "Үг бүрийг тод, оновчтой хэлж, эгшиг-гийгүүлэгчийн хослолыг санаж ав.", "pairs": [{"a": {"zh": "一", "pinyin": "yī", "mn": "нэг"}, "b": {"zh": "五", "pinyin": "wǔ", "mn": "тав"}, "note_mn": "i дангаараа y авдаг, u дангаараа w авдаг дүрмийг санагдуулна."}, {"a": {"zh": "鱼", "pinyin": "yú", "mn": "загас"}, "b": {"zh": "耳", "pinyin": "ěr", "mn": "чих"}, "note_mn": "ü ба er — ховор тохиолддог сүүл авиануудыг ялгаж сур."}, {"a": {"zh": "笔", "pinyin": "bǐ", "mn": "үзэг"}, "b": {"zh": "猫", "pinyin": "māo", "mn": "муур"}, "note_mn": "богино i ба ao хос эгшгийг ялгаж дуудна."}, {"a": {"zh": "鸡", "pinyin": "jī", "mn": "тахиа"}, "b": {"zh": "七", "pinyin": "qī", "mn": "долоо"}, "note_mn": "ижил эгшигтэй (ī) хос — j амьсгалгүй, q амьсгалтай гэдгээрээ ялгана."}, {"a": {"zh": "鞋", "pinyin": "xié", "mn": "гутал"}, "b": {"zh": "雪", "pinyin": "xuě", "mn": "цас"}, "note_mn": "ижил x эхлэлтэй ч ie ба üe сүүл авиагаараа ялгаатай."}]}], "tips_mn": ["3-р хөгийг дэндүү гүнзгий бүү ав — «намхан хөг» гэж бод, дараа нь бага зэрэг өгсгө.", "p t k-г хэлэхдээ гараа амныхаа өмнө бариад, салхи мэдрэгдэж байвал зөв дуудаж байна гэсэн үг.", "Пиньинийг Монгол үсгээр буулгаж цээжлэхгүй, латин үсэг дээр нь хөгийн тэмдгийг шууд харж дадлагажаарай.", "你好, 您好-г өдөр бүр хэдэн удаа чангаар давтаж хэл, аялга чинь аяндаа сайжирна."]}}'::jsonb)
