insert into public.lesson_deep_teaching (lesson_id, version, payload)
values ('hsk1-l02', 1, '{"words": [{"zh": "谢谢", "pinyin": "xièxie", "teach_mn": "«谢谢» гэдэг нь монгол хэлний «баярлалаа» гэсэн үгтэй шууд дүйцэх талархал илэрхийлэх хэллэг. Энэ үг хоёр ижил үений давталтаас тогтсон бөгөөд хоёр дахь 谢 нь сул хөгтэй, богино дуудагдана. Дангаараа хэлж болох ба ард нь хүнийг заасан үг (你, 您, 你们) залгаж илүү тодорхой болгож болно. Монгол хэлэнд адилхан энгийн, өдөр тутам хамгийн их хэрэглэгддэг ёс зүйн үг.", "usage_mn": ["Хэн нэгэн танд туслах, зүйл өгөх, сайн үйл хийх үед хэрэглэнэ", "Дангаараа эсвэл ард нь 你/您/你们 залгаж илүү тодорхой хэлж болно"], "examples": [{"zh": "谢谢！", "pinyin": "Xièxie!", "mn": "Баярлалаа!", "note_mn": "энгийн, ерөнхий талархал"}, {"zh": "谢谢你！", "pinyin": "Xièxie nǐ!", "mn": "Чамд баярлалаа!", "note_mn": "тодорхой хэнд талархаж байгааг заасан"}, {"zh": "谢谢您！", "pinyin": "Xièxie nín!", "mn": "Танд баярлалаа!", "note_mn": "ахмад хүн, багшид хэлэх хүндэтгэлтэй хэлбэр"}, {"zh": "你好，谢谢！", "pinyin": "Nǐ hǎo, xièxie!", "mn": "Сайн уу, баярлалаа!", "note_mn": "мэндчилгээ, талархлыг хамт хэлж байна"}], "mistakes": [{"wrong": "谢谢谢谢你", "right": "谢谢你", "why_mn": "谢谢 өөрөө хоёр үет тогтсон үг тул дахин давхар давтах шаардлагагүй."}]}, {"zh": "不", "pinyin": "bù", "teach_mn": "«不» нь монгол хэлний «үгүй, биш» гэсэн үгүйсгэх утгатай тэнцэнэ. Монголд үгүйсгэх нөхцөл (жишээ нь «-гүй») үгийн ард залгадаг бол хятадад 不 үргэлж үгүйсгэж буй үгийнхээ өмнө тусдаа үг байдлаар ордог. 不 өөрөө 4-р хөгтэй боловч ард нь дахин 4-р хөгтэй үе ирвэл дуудлагад хялбар болгохын тулд 2-р хөг рүү хувирдаг тухай дараагийн дүрмийн цэгт дэлгэрэнгүй үзнэ.", "usage_mn": ["Ямар нэгэн зүйл, байдлыг үгүйсгэхэд тухайн үгийн өмнө тавина", "Ганцаараа хэлж «үгүй ээ» гэсэн товч хариу болгож болно"], "examples": [{"zh": "不客气！", "pinyin": "Bú kèqi!", "mn": "Зүгээр зүгээр ээ!", "note_mn": "谢谢-д хариулах хэллэгийн нэг хэсэг"}, {"zh": "不谢！", "pinyin": "Bú xiè!", "mn": "Зүгээр ээ!", "note_mn": "талархал хэрэггүй гэсэн богино хариу"}, {"zh": "不好。", "pinyin": "Bù hǎo.", "mn": "Сайнгүй, муу байна.", "note_mn": "3-р хөгийн өмнө 不 хэвээрээ bù"}], "mistakes": [{"wrong": "客气不", "right": "不客气", "why_mn": "Монголд үгүйсгэх нөхцөл үгийн ард ордог боловч хятадад 不 үргэлж үгийнхээ өмнө байрладаг тогтсон дараалалтай."}]}, {"zh": "不客气", "pinyin": "bú kèqi", "teach_mn": "«不客气» нь 谢谢 гэж хэн нэгэн танд талархахад хариу болгож хэлдэг тогтсон хэллэг. Шууд утгаараа 不 (үгүй) + 客气 (ёс төдий, хэт зан гаргах) гэсэн хоёр хэсгээс тогтдог ч ярианд «зүгээр зүгээр ээ, яахав» гэсэн утгаар л ойлгож болно. 客气 нь 4-р хөгтэй тул 不 нь энд bú болж хувирдгийг анхаар.", "usage_mn": ["Хэн нэгэн 谢谢 гэхэд хариу болгож хэлнэ", "Ярианы эхэнд өөрөө санаачлан ашигладаггүй"], "examples": [{"zh": "谢谢你！— 不客气！", "pinyin": "Xièxie nǐ! — Bú kèqi!", "mn": "Чамд баярлалаа! — Зүгээр зүгээр ээ!", "note_mn": "хамгийн түгээмэл хос хэллэг"}, {"zh": "不客气，再见！", "pinyin": "Bú kèqi, zàijiàn!", "mn": "Зүгээр ээ, баяртай!", "note_mn": "хариулаад дараа нь салах ёс хийж байна"}, {"zh": "您好！谢谢！— 不客气！", "pinyin": "Nín hǎo! Xièxie! — Bú kèqi!", "mn": "Та сайн байна уу! Баярлалаа! — Зүгээр ээ!", "note_mn": "ахмад хүнтэй бүтэн ярианы жишээ"}], "mistakes": [{"wrong": "客气！", "right": "不客气！", "why_mn": "客气 гэдэг ганц үгийг хариу болгож хэлбэл утга дутуу болно, 不-г заавал урд нь нэмнэ."}], "compare": [{"zh": "没关系", "pinyin": "méi guānxi", "mn": "зүгээр ээ (уучлалд)", "diff_mn": "没关系 нь 对不起 (уучлаарай)-д хариулна, харин 不客气 нь 谢谢 (баярлалаа)-д хариулна — хоёр өөр нөхцөлд хэрэглэгддэг тул андуурч болохгүй."}]}, {"zh": "再见", "pinyin": "zàijiàn", "teach_mn": "«再见» нь монгол хэлний «баяртай» гэсэн салах ёс гүйцэтгэх үгтэй адил хэрэглэгддэг. Үгчлэн орчуулбал 再 (дахин) + 见 (уулзах) буюу «дахин уулзъя» гэсэн санаатай ч ярианд ердийн «баяртай» гэж ойлгож болно. Хэнтэй ч, ямар нөхцөлд ч салахдаа хэлж болох бөгөөд 你/您 гэсэн хүндэтгэлийн ялгаа энд байхгүй.", "usage_mn": ["Хэнтэй ч, албан ёсны эсэхээс үл хамааран салахдаа хэлж болно", "Ихэвчлэн хоёр тал ээлжлэн давтаж хэлдэг"], "examples": [{"zh": "再见！", "pinyin": "Zàijiàn!", "mn": "Баяртай!", "note_mn": "хамгийн энгийн салах ёс"}, {"zh": "再见，再见！", "pinyin": "Zàijiàn, zàijiàn!", "mn": "Баяртай, баяртай!", "note_mn": "хоёр тал ээлжлэн давтаж хэлж байна"}, {"zh": "谢谢，再见！", "pinyin": "Xièxie, zàijiàn!", "mn": "Баярлалаа, баяртай!", "note_mn": "талархаад дараа нь салж байна"}], "mistakes": [{"wrong": "再见你", "right": "再见", "why_mn": "再见 өөрөө бүрэн хэллэг тул ард нь хэнтэй салж байгаагаа нэмж заах шаардлагагүй, 你好-той адил зарчим."}]}], "grammar": [{"point": "不 bù — үгүйсгэл ба хөгийн хувирал", "gloss_mn": "үгүй, биш — 4-р хөгийн өмнө bú болж хувирна", "structure": "不(bù) + 4-р хөгтэй үг → bú + ...", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "不 нь монгол «үгүй, биш» гэдэгтэй адил, аливаа зүйлийг үгүйсгэхэд хэрэглэдэг үг.", "example": {"zh": "不好", "pinyin": "bù hǎo", "mn": "муу, сайнгүй"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "不-г үгүйсгэх гэж буй үгийнхээ шууд өмнө тавина, дунд нь өөр юу ч оруулахгүй.", "example": {"zh": "不+客气", "pinyin": "bù + kèqi", "mn": "үгүй + ёс төдий"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Ямар нэгэн зүйл, байдлыг үгүйсгэхэд, эсвэл ганцаараа «үгүй» гэж товч хариулахад хэрэглэнэ.", "example": {"zh": "不客气", "pinyin": "bú kèqi", "mn": "зүгээр ээ"}}, {"title_mn": "4. Онцлог — хөгийн хувирал", "body_mn": "不 өөрөө 4-р хөгтэй (bù) боловч ард нь дахин 4-р хөгтэй үе ирвэл хэлэхэд хэцүү тул 2-р хөг рүү хувирч bú болно: 不谢→bú xiè, 不客气→bú kèqi.", "example": {"zh": "不谢", "pinyin": "bú xiè", "mn": "зүгээр ээ"}}], "examples": [{"zh": "不客气！", "pinyin": "Bú kèqi!", "mn": "Зүгээр зүгээр ээ!"}, {"zh": "不谢！", "pinyin": "Bú xiè!", "mn": "Зүгээр ээ!"}, {"zh": "不好。", "pinyin": "Bù hǎo.", "mn": "Муу байна."}, {"zh": "谢谢你！— 不客气！", "pinyin": "Xièxie nǐ! — Bú kèqi!", "mn": "Чамд баярлалаа! — Зүгээр зүгээр ээ!"}, {"zh": "您好，不客气。", "pinyin": "Nín hǎo, bú kèqi.", "mn": "Та сайн байна уу, зүгээр ээ."}, {"zh": "不客气，再见！", "pinyin": "Bú kèqi, zàijiàn!", "mn": "Зүгээр ээ, баяртай!"}], "mistakes": [{"wrong": "客气不", "right": "不客气", "why_mn": "不 үргэлж үгийн өмнө ордог, ард нь тавьж болохгүй."}, {"wrong": "bù kèqi (тэмдэг хувиргалгүй дуудах)", "right": "bú kèqi", "why_mn": "客气-ийн эхний үе 4-р хөгтэй тул 不 заавал bú болж хувирна."}], "drills": [{"type": "choice", "question": "不客气 гэдгийг хэрхэн зөв дуудах вэ?", "options": ["bù kèqi", "bú kèqi", "bǔ kèqi"], "answer": "bú kèqi", "why_mn": "客气-ийн 客 нь 4-р хөгтэй тул 不 нь bú болж хувирна."}, {"type": "judge", "question": "不 үргэлж bù гэсэн 4-р хөгөөр дуудагдана.", "answer": "false", "why_mn": "4-р хөгтэй үгийн өмнө bú болж хувирдаг тул үргэлж адил биш."}, {"type": "fill", "question": "不 + 谢 = ___ (зөв пиньинээр бич)", "answer": "bú xiè", "why_mn": "谢 4-р хөгтэй тул 不 нь bú болно."}, {"type": "choice", "question": "«谢谢你！» гэхэд юу гэж хариулах вэ?", "options": ["不客气", "没关系", "再见"], "answer": "不客气", "why_mn": "баярлалт гэхэд 不客气 гэж хариулдаг тогтсон дараалал."}]}, {"point": "轻声 — сул хөг", "gloss_mn": "тэмдэггүй, богино, сул дуудагддаг тав дахь хөг", "structure": "...CV(сул) — тэмдэг тавихгүй, богино, хөнгөн дуудна", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "4 үндсэн хөгөөс гадна зарим үений сүүлчийн үе маш богино, сул, бараг «унтарсан» мэт дуудагддаг — үүнийг 轻声 (сул хөг) гэнэ.", "example": {"zh": "谢谢", "pinyin": "xièxie", "mn": "баярлалаа"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Пиньинд сул хөгийг ямар ч тэмдэггүй бичнэ — жишээ нь xièxie-гийн хоёр дахь xie дээр тэмдэг байхгүй.", "example": {"zh": "谢谢", "pinyin": "xièxie", "mn": "(хоёр дахь үе тэмдэггүй)"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Ихэвчлэн давхардсан үг (谢谢), гэр бүлийн зарим нэр (妈妈, 爸爸), болон 你们-ийн 们 мэт дагаварт тохиолддог.", "example": {"zh": "你们", "pinyin": "nǐmen", "mn": "та нар"}}, {"title_mn": "4. Ялгаа, санамж", "body_mn": "Сул хөгийг хэт тодотгож, сунжруулан хэлбэл гадаад дуудлагатай сонсогдоно — өмнөх үеэсээ богино, бага хүчээр «унагаж» хэл.", "example": {"zh": "妈妈", "pinyin": "māma", "mn": "ээж"}}], "examples": [{"zh": "谢谢", "pinyin": "xièxie", "mn": "баярлалаа"}, {"zh": "妈妈", "pinyin": "māma", "mn": "ээж"}, {"zh": "爸爸", "pinyin": "bàba", "mn": "аав"}, {"zh": "朋友", "pinyin": "péngyou", "mn": "найз"}, {"zh": "你们", "pinyin": "nǐmen", "mn": "та нар"}], "mistakes": [{"wrong": "xièxié (сүүлийн үед тэмдэг тавих)", "right": "xièxie", "why_mn": "Сул хөгт хэзээ ч дүрсний тэмдэг тавьдаггүй."}], "drills": [{"type": "judge", "question": "谢谢-ийн хоёр дахь үе сунжирсан 2-р хөгөөр дуудагдана.", "answer": "false", "why_mn": "Хоёр дахь 谢 сул хөгтэй тул богино, тэмдэггүй дуудна."}, {"type": "choice", "question": "Дараах алинд нь сул хөг байдаг вэ?", "options": ["谢谢", "你好", "再见"], "answer": "谢谢", "why_mn": "谢谢-ийн хоёр дахь 谢 сул хөгтэй."}, {"type": "fill", "question": "妈妈 гэдгийг пиньинээр зөв бичвэл ___", "answer": "māma", "why_mn": "Хоёр дахь ma сул хөгтэй тул тэмдэггүй."}, {"type": "judge", "question": "Сул хөгийг тод, сунжруулан дуудах ёстой.", "answer": "false", "why_mn": "Сул хөгийг богино, хөнгөн дуудна."}]}, {"point": "标调法 — хөгийн тэмдэг хаана тавих вэ", "gloss_mn": "a o e i u ü дараалал; хос эгшигт эхнийхэд нь тэмдэг", "structure": "a > o/e > i/u/ü; iu → тэмдэг u дээрээ", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "Хөгийн тэмдгийг үргэлж эгшиг дээр тавина, гийгүүлэгч дээр хэзээ ч тавьдаггүй.", "example": {"zh": "好", "pinyin": "hǎo", "mn": "сайн"}}, {"title_mn": "2. Бүтэц", "body_mn": "Хоёр буюу түүнээс олон эгшигтэй бол ам хамгийн их ангайдаг нь буюу a o e i u ü дарааллын эхнийх дээр тэмдэг тавина.", "example": {"zh": "学校", "pinyin": "xuéxiào", "mn": "сургууль"}}, {"title_mn": "3. Онцгой тохиолдол", "body_mn": "iu гэсэн товчлолд тэмдэг үргэлж эцсийн u дээр очно, учир нь iu нь бодит байдалд iou-гийн товчлол.", "example": {"zh": "牛", "pinyin": "niú", "mn": "үхэр"}}, {"title_mn": "4. Санамж", "body_mn": "Сул хөгтэй үед тэмдэг огт тавихгүй гэдгийг өмнөх дүрмийн цэгээс сана.", "example": {"zh": "谢谢", "pinyin": "xièxie", "mn": "баярлалаа"}}], "examples": [{"zh": "你好", "pinyin": "nǐ hǎo", "mn": "сайн уу"}, {"zh": "您好", "pinyin": "nín hǎo", "mn": "та сайн байна уу"}, {"zh": "学校", "pinyin": "xuéxiào", "mn": "сургууль"}, {"zh": "牛", "pinyin": "niú", "mn": "үхэр"}, {"zh": "再见", "pinyin": "zàijiàn", "mn": "баяртай"}], "mistakes": [{"wrong": "xuéxiao (тэмдэггүй бичих)", "right": "xuéxiào", "why_mn": "a o e i u ü дарааллаар a нь тэргүүлэх тул тэмдэг a дээр очно."}], "drills": [{"type": "choice", "question": "学校-ийн xiào дээр тэмдэг хаана очих вэ?", "options": ["x дээр", "i дээр", "a дээр"], "answer": "a дээр", "why_mn": "a o e i u ü дарааллаар a хамгийн түрүүнд ордог тул тэмдэг a дээр очно."}, {"type": "judge", "question": "iu гэсэн товчлолд тэмдэг үргэлж i дээр очдог.", "answer": "false", "why_mn": "iu нь iou-гийн товчлол тул тэмдэг сүүлийн u дээр очдог."}, {"type": "fill", "question": "牛 гэдгийг зөв пиньинээр бич (тэмдэгтэй).", "answer": "niú", "why_mn": "iu товчлолд тэмдэг u дээр очно."}, {"type": "choice", "question": "好-гийн тэмдэг хаана байрлах ёстой вэ?", "options": ["h дээр", "a дээр", "o дээр"], "answer": "a дээр", "why_mn": "ao хос эгшигт a нь тэргүүлэх эгшиг тул тэмдэг a дээр очно."}]}, {"point": "省写 — iou/uei/uen-ий товчлол", "gloss_mn": "эхний авиатай хослоход дундах эгшгийг гээж бичнэ", "structure": "n+iou→niu, g+uei→gui, l+uen→lun", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "iou, uei, uen гэсэн гурван нийлмэл сүүл авиа өмнөө эхний авиа авахад бичихдээ дундах эгшгээ гээдэг — үүнийг 省写 (товчлол) гэнэ.", "example": {"zh": "牛", "pinyin": "niú", "mn": "үхэр (niou→niu)"}}, {"title_mn": "2. Бүтэц", "body_mn": "n+iou→niu, g+uei→gui, l+uen→lun гэх мэтээр дундах o/e үсэг унана, гэхдээ дуудлага өөрчлөгдөхгүй.", "example": {"zh": "水", "pinyin": "shuǐ", "mn": "ус (shuei→shui)"}}, {"title_mn": "3. Хаана хэрэглэх", "body_mn": "Бичихдээ л товчилно — дуудахдаа гээгдсэн эгшгийг сул мэдрэгдэхүйц хэлдэг.", "example": {"zh": "对不起", "pinyin": "duìbuqǐ", "mn": "уучлаарай (duei→dui)"}}, {"title_mn": "4. Санамж", "body_mn": "Товчлогдсон хэлбэрийг л зөв стандарт бичиг гэж цээжил, дэлгэрэнгүй хэлбэрээр бичихгүй.", "example": {"zh": "六", "pinyin": "liù", "mn": "зургаа (liou→liu)"}}], "examples": [{"zh": "牛奶", "pinyin": "niúnǎi", "mn": "сүү"}, {"zh": "水果", "pinyin": "shuǐguǒ", "mn": "жимс"}, {"zh": "对不起", "pinyin": "duìbuqǐ", "mn": "уучлаарай"}, {"zh": "六", "pinyin": "liù", "mn": "зургаа"}, {"zh": "牛", "pinyin": "niú", "mn": "үхэр"}], "mistakes": [{"wrong": "niou nǎi (бүтэн хэлбэрээр бичих)", "right": "niúnǎi", "why_mn": "n-ийн ард iou ирэхэд заавал niu гэж товчлон бичнэ, бүтэн iou гэж бичдэггүй."}], "drills": [{"type": "fill", "question": "n + iou (үхэр) = ___", "answer": "niú", "why_mn": "n-ийн ард iou ирэхэд товчлож niu гэж бичнэ."}, {"type": "choice", "question": "水 (ус)-ыг зөв бичвэл алин вэ?", "options": ["shuei", "shuǐ", "shiu"], "answer": "shuǐ", "why_mn": "uei нь shu-гийн ард товчлогдож ui болдог."}, {"type": "judge", "question": "对不起-ийн 对 нь бодитоор duei гэж дуудагддаг ч dui гэж бичдэг.", "answer": "true", "why_mn": "uei эхний авиатай хослоход ui болж товчлогддог."}, {"type": "choice", "question": "l + uen = ?", "options": ["luen", "lun", "luien"], "answer": "lun", "why_mn": "uen товчлогдож un болно."}]}, {"point": "汉字笔画 (2) — ㇕ ㇗ 亅", "gloss_mn": "хэвтээ-эргэлт, босоо-эргэлт, босоо-дэгээ", "structure": "héngzhé(㇕): 口 · shùzhé(㇗): 山 · shùgōu(亅): 小", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "Энэ хичээлээр 3 шинэ нийлмэл зурлагатай танилцана: 横折 (хэвтээгээс доош эргэдэг), 竖折 (босоогоос баруун тийш эргэдэг), 竖钩 (босоо татаад дэгээ хийдэг).", "example": {"zh": "口", "pinyin": "kǒu", "mn": "ам"}}, {"title_mn": "2. Бүтэц", "body_mn": "㇕ нь 口, 见 мэт ханзанд, ㇗ нь 山 мэт ханзанд, 亅 нь 小 мэт ханзанд орно.", "example": {"zh": "山", "pinyin": "shān", "mn": "уул"}}, {"title_mn": "3. Хаана хэрэглэх", "body_mn": "Эдгээр зурлагыг таньж чадвал ханз бичихдээ зөв дарааллаар, зөв чиглэлээр татаж сурна.", "example": {"zh": "小", "pinyin": "xiǎo", "mn": "жижиг"}}, {"title_mn": "4.