insert into public.lesson_deep_teaching (lesson_id, version, payload)
values ('hsk1-l03', 1, '{"words": [{"zh": "叫", "pinyin": "jiào", "teach_mn": "«叫» нь хүний нэрийг хэлэхэд хэрэглэдэг үйл үг, монголоор «...гэдэг» гэж орчуулагдана. Өгүүлбэрт ихэвчлэн «Хэн + 叫 + Нэр» дараалалтай ордог: 我叫... (намайг ... гэдэг). Асуухдаа 什么 (юу) үгтэй хослуулж 你叫什么名字？гэж хэлдэг. Монгол хэлний «намайг ... гэдэг» гэсэн тогтсон хэллэгтэй утга дүйнэ.", "usage_mn": ["Өөрийн болон бусдын нэрийг танилцуулахад хэрэглэнэ", "Ард нь шууд хүний нэр ордог, өөр үг завсарлуулахгүй"], "examples": [{"zh": "我叫李月。", "pinyin": "Wǒ jiào Lǐ Yuè.", "mn": "Намайг Ли Юэ гэдэг.", "note_mn": "хамгийн энгийн танилцуулах хэлбэр"}, {"zh": "你叫什么名字？", "pinyin": "Nǐ jiào shénme míngzi?", "mn": "Чамайг хэн гэдэг вэ?", "note_mn": "нэр асуух тогтсон бүтэц"}, {"zh": "你好，我叫李月。", "pinyin": "Nǐ hǎo, wǒ jiào Lǐ Yuè.", "mn": "Сайн уу, намайг Ли Юэ гэдэг.", "note_mn": "мэндэлж байгаад өөрийгөө танилцуулж байна"}, {"zh": "您叫什么名字？", "pinyin": "Nín jiào shénme míngzi?", "mn": "Таны нэрийг хэн гэдэг вэ?", "note_mn": "ахмад хүнээс хүндэтгэлтэй асууж байна"}], "mistakes": [{"wrong": "我是叫李月", "right": "我叫李月", "why_mn": "叫 өөрөө «...гэдэг нэртэй» гэсэн бүрэн утгатай үйл үг тул 是-г нэмж хэрэглэх шаардлагагүй."}], "compare": [{"zh": "是", "pinyin": "shì", "mn": "мөн, байх", "diff_mn": "叫 зөвхөн нэр хэлэхэд, 是 бол хэн, юу болохыг ерөнхийд нь тодорхойлоход хэрэглэгддэг — хоёрыг андуурч хольж болохгүй."}]}, {"zh": "什么", "pinyin": "shénme", "teach_mn": "«什么» нь монгол «юу, ямар» гэсэн асуух төлөөний үгтэй адил. Онцлог нь: хятад хэлэнд асуух үгийг өгүүлбэрийн бусад хэсгийг хөдөлгөлгүй, шууд хариултын байранд нь тавьдаг. Жишээ нь нэрийг асуухдаа нэрний оронд шууд 什么-г тавина.", "usage_mn": ["Юу, ямар зүйл болохыг асуухад хэрэглэнэ", "Асуух үгийг өгүүлбэрийн энгийн байрлалд нь тавина, эхэнд гаргаж эргүүлдэггүй"], "examples": [{"zh": "你叫什么名字？", "pinyin": "Nǐ jiào shénme míngzi?", "mn": "Чамайг хэн гэдэг вэ?", "note_mn": "хамгийн түгээмэл хэрэглээ"}, {"zh": "您叫什么名字？", "pinyin": "Nín jiào shénme míngzi?", "mn": "Таны нэрийг хэн гэдэг вэ?", "note_mn": "ахмад хүнд хандаж асууж байна"}, {"zh": "你们叫什么名字？", "pinyin": "Nǐmen jiào shénme míngzi?", "mn": "Та нарыг хэн гэдэг вэ?", "note_mn": "олон хүнээс зэрэг асууж байна"}], "mistakes": [{"wrong": "什么你叫名字", "right": "你叫什么名字", "why_mn": "什么 нь энгийн өгүүлбэрийн дарааллаар, 名字-ийн өмнө орно, өгүүлбэрийг эргүүлж эхэнд гаргахгүй."}]}, {"zh": "名字", "pinyin": "míngzi", "teach_mn": "«名字» нь монгол «нэр» гэдэгтэй тэнцэх нэр үг. Ихэвчлэн 什么 (юу) асуух үгтэй хамт 你叫什么名字？гэсэн бүтэцэд орж хэрэглэгддэг. 字-ийн үе сул хөгтэй тул богино дуудагдана гэдгийг сана.", "usage_mn": ["叫什么名字 бүтэцэд нэрийг асуухад хэрэглэнэ", "Сүүлийн 字 нь сул хөгтэй, богино дуудагдана"], "examples": [{"zh": "你叫什么名字？", "pinyin": "Nǐ jiào shénme míngzi?", "mn": "Чамайг хэн гэдэг вэ?", "note_mn": "нэр асуух стандарт асуулт"}, {"zh": "老师叫什么名字？", "pinyin": "Lǎoshī jiào shénme míngzi?", "mn": "Багшийг хэн гэдэг вэ?", "note_mn": "гуравдагч этгээдийн нэрийг асууж байна"}, {"zh": "你们叫什么名字？", "pinyin": "Nǐmen jiào shénme míngzi?", "mn": "Та нарыг хэн гэдэг вэ?", "note_mn": "олон хүнээс зэрэг асууж байна"}], "mistakes": [{"wrong": "你叫名字什么", "right": "你叫什么名字", "why_mn": "什么 нь 名字-ийн өмнө орж «ямар нэр» гэдгийг тодотгодог тул дараалал өөрчлөгдөхгүй."}]}, {"zh": "我", "pinyin": "wǒ", "teach_mn": "«我» нь өөрийгөө илэрхийлэх бие даасан төлөөний үг, өгүүлбэрийн эхэнд ордог. Монгол хэлэнд «би, миний, надад» гэж нөхцөлөөрөө хувирдаг бол хятадад 我 үргэлж ижил хэлбэртэй хэвээр байж, үүргийг нь байрлал шийддэг.", "usage_mn": ["Өөрийгөө илэрхийлж өгүүлбэрийн эхэнд орно", "Нөхцөл залгаж хувирдаггүй, үргэлж ижил хэлбэртэй"], "examples": [{"zh": "我叫李月。", "pinyin": "Wǒ jiào Lǐ Yuè.", "mn": "Намайг Ли Юэ гэдэг.", "note_mn": "нэрээ танилцуулж байна"}, {"zh": "我是学生。", "pinyin": "Wǒ shì xuésheng.", "mn": "Би сурагч.", "note_mn": "статусаа хэлж байна"}, {"zh": "我是美国人。", "pinyin": "Wǒ shì Měiguó rén.", "mn": "Би Америк хүн.", "note_mn": "харьяалалаа хэлж байна"}, {"zh": "我不是老师。", "pinyin": "Wǒ bú shì lǎoshī.", "mn": "Би багш биш.", "note_mn": "үгүйсгэсэн хэлбэр"}], "mistakes": [{"wrong": "你叫李月（өөрийгөө танилцуулахдаа）", "right": "我叫李月", "why_mn": "Өөрийнхөө нэрийг хэлэхдээ 我-г ашиглана, 你 бол ярилцаж буй хүнийг заана."}], "compare": [{"zh": "你", "pinyin": "nǐ", "mn": "чи", "diff_mn": "我 нь ярьж буй хүн өөрийгөө, 你 нь ярилцаж буй ярилцагчийг заана."}]}, {"zh": "是", "pinyin": "shì", "teach_mn": "«是» нь монгол «бол» гэдэгтэй утга дүйх холбоос үйл үг бөгөөд «А 是 Б» гэсэн бүтэцтэй хэрэглэгдэнэ. Монгол хэлэнд «Би сурагч» гэхэд «бол» гэдэг үгийг орхиж болдог ч хятад хэлэнд 是-г орхиж болохгүй, өгүүлбэр бүрд заавал байх ёстой.", "usage_mn": ["Хэн, юу болохыг тодорхойлоход А 是 Б хэлбэрээр хэрэглэнэ", "Үгүйсгэхдээ 是-гийн өмнө 不 тавьж 不是 болгоно"], "examples": [{"zh": "我是学生。", "pinyin": "Wǒ shì xuésheng.", "mn": "Би сурагч.", "note_mn": "энгийн батлах өгүүлбэр"}, {"zh": "我是美国人。", "pinyin": "Wǒ shì Měiguó rén.", "mn": "Би Америк хүн.", "note_mn": "харьяалал тодорхойлж байна"}, {"zh": "李月是老师。", "pinyin": "Lǐ Yuè shì lǎoshī.", "mn": "Ли Юэ бол багш.", "note_mn": "гуравдагч этгээдийг тодорхойлж байна"}, {"zh": "我不是老师。", "pinyin": "Wǒ bú shì lǎoshī.", "mn": "Би багш биш.", "note_mn": "үгүйсгэсэн хэлбэр 不是"}, {"zh": "你是老师吗？", "pinyin": "Nǐ shì lǎoshī ma?", "mn": "Та багш уу?", "note_mn": "吗-тай хамт асуулт болгосон"}], "mistakes": [{"wrong": "我学生。", "right": "我是学生。", "why_mn": "Монгол хэлэнд «бол» гэдгийг заримдаа орхидог ч хятад хэлэнд 是-г орхиж болохгүй."}]}, {"zh": "老师", "pinyin": "lǎoshī", "teach_mn": "«老师» нь монгол «багш» гэдэгтэй тэнцэх нэр үг, мөн хүнийг шууд хандаж дуудахад ч хэрэглэж болно. HSK1-д ихэвчлэн 是-тэй хамт «... бол багш» гэсэн бүтэцэд ордог.", "usage_mn": ["Хүний мэргэжлийг хэлэхдээ 是-тэй хамт хэрэглэнэ", "Шууд хандаж дуудахдаа нэрийн оронд ашиглаж болно"], "examples": [{"zh": "你是老师吗？", "pinyin": "Nǐ shì lǎoshī ma?", "mn": "Та багш уу?", "note_mn": "ажил мэргэжлийг асууж байна"}, {"zh": "我不是老师，我是学生。", "pinyin": "Wǒ bú shì lǎoshī, wǒ shì xuésheng.", "mn": "Би багш биш, би сурагч.", "note_mn": "үгүйсгээд зөв хариултаа хэлж байна"}, {"zh": "老师叫什么名字？", "pinyin": "Lǎoshī jiào shénme míngzi?", "mn": "Багшийг хэн гэдэг вэ?", "note_mn": "багшийн нэрийг асууж байна"}], "mistakes": [{"wrong": "你老师吗？", "right": "你是老师吗？", "why_mn": "是 холбоос үгийг орхиж болохгүй, «Та багш уу?» гэхдээ ч 是 заавал орно."}], "compare": [{"zh": "学生", "pinyin": "xuésheng", "mn": "сурагч, оюутан", "diff_mn": "老师 хэн нэгнийг заадаг, 学生 хэн нэгэн сурдаг — эсрэг үүрэгтэй хос үг тул андуурч болохгүй."}]}, {"zh": "吗", "pinyin": "ma", "teach_mn": "«吗» нь өгүүлбэрийн төгсгөлд залгаж «тийм үү, үгүй юу» гэсэн ерөнхий асуулт үүсгэдэг сул үг, тэмдэг тавихгүй, сул хөгтэй. Монгол хэлний «уу/үү» асуултын нөхцөлтэй утга дүйнэ, гэхдээ хятадад тусдаа үг байдлаар өгүүлбэрийн төгсгөлд зогсдог.", "usage_mn": ["Хүүрнэх өгүүлбэрийн ард залгаж ерөнхий асуулт болгоно", "什么 мэт асуух үгтэй нэг өгүүлбэрт хамт ордоггүй"], "examples": [{"zh": "你是老师吗？", "pinyin": "Nǐ shì lǎoshī ma?", "mn": "Та багш уу?", "note_mn": "мэргэжлийг асууж байна"}, {"zh": "你是学生吗？", "pinyin": "Nǐ shì xuésheng ma?", "mn": "Чи сурагч уу?", "note_mn": "статусыг асууж байна"}, {"zh": "你是美国人吗？", "pinyin": "Nǐ shì Měiguó rén ma?", "mn": "Чи Америк хүн үү?", "note_mn": "харьяалалыг асууж байна"}, {"zh": "你是中国人吗？", "pinyin": "Nǐ shì Zhōngguó rén ma?", "mn": "Чи Хятад хүн үү?", "note_mn": "харьяалалыг асууж байна"}], "mistakes": [{"wrong": "你是什么吗？", "right": "你是什么？", "why_mn": "什么 мэт асуух үгтэй өгүүлбэрт 吗-г нэмж хэрэглэдэггүй, аль нэгийг л сонгоно."}]}, {"zh": "学生", "pinyin": "xuésheng", "teach_mn": "«学生» нь монгол «сурагч, оюутан» гэдэгтэй тэнцэх нэр үг. Сүүлийн 生 нь сул хөгтэй тул богино, хөнгөн дуудагдана. 是-тэй хамт өөрийн статусыг хэлэхэд хэрэглэнэ.", "usage_mn": ["Өөрийгөө сурагч, оюутан гэдгээ танилцуулахад хэрэглэнэ", "Сүүлийн 生 сул хөгтэй, тэмдэг тавихгүй"], "examples": [{"zh": "我是学生。", "pinyin": "Wǒ shì xuésheng.", "mn": "Би сурагч.", "note_mn": "энгийн танилцуулга"}, {"zh": "你是学生吗？", "pinyin": "Nǐ shì xuésheng ma?", "mn": "Чи сурагч уу?", "note_mn": "吗-тай асуулт"}, {"zh": "我不是老师，我是学生。", "pinyin": "Wǒ bú shì lǎoshī, wǒ shì xuésheng.", "mn": "Би багш биш, би сурагч.", "note_mn": "эсрэг хос үгтэй харьцуулж хэлж байна"}], "mistakes": [{"wrong": "xuéshēng (тэмдэгтэй дуудах)", "right": "xuésheng", "why_mn": "Сүүлийн 生 сул хөгтэй тул тэмдэг тавихгүй, богино дуудна."}]}, {"zh": "人", "pinyin": "rén", "teach_mn": "«人» нь өөрөө «хүн» гэсэн ерөнхий утгатай. Ямар улсын хүн болохыг хэлэхдээ улсын нэрний ард шууд 人-г залгана: 中国人 (хятад хүн), 美国人 (америк хүн). Улсын нэр эхэнд, 人 үргэлж ард нь ордог.", "usage_mn": ["Улсын нэрний ард залгаж «... хүн» гэсэн утга үүсгэнэ", "Дангаараа хэрэглэхэд ерөнхий «хүн» гэсэн утгатай"], "examples": [{"zh": "我是美国人。", "pinyin": "Wǒ shì Měiguó rén.", "mn": "Би Америк хүн.", "note_mn": "харьяалалаа хэлж байна"}, {"zh": "我是中国人。", "pinyin": "Wǒ shì Zhōngguó rén.", "mn": "Би Хятад хүн.", "note_mn": "харьяалалаа хэлж байна"}, {"zh": "你是中国人吗？", "pinyin": "Nǐ shì Zhōngguó rén ma?", "mn": "Чи Хятад хүн үү?", "note_mn": "吗-тай асуулт"}], "mistakes": [{"wrong": "人中国", "right": "中国人", "why_mn": "Улсын нэр эхэнд, 人 ард нь ордог тогтсон дараалал, эргүүлбэл утгагүй болно."}]}, {"zh": "李月", "pinyin": "Lǐ Yuè", "teach_mn": "«李月» бол энэ хичээлийн харилцан ярианд гардаг хүний нэр — 李 овог, 月 нэр. Хятадад овгоо эхэнд, нэрээ ард нь бичдэг бөгөөд энэ нь монгол зан заншлаас өөр дараалал.", "usage_mn": ["Хүний өөрийгөө танилцуулах жишээ нэр болгон ашиглана", "Овог эхэнд, нэр ард нь ордог дарааллыг ажигла"], "examples": [{"zh": "我叫李月。", "pinyin": "Wǒ jiào Lǐ Yuè.", "mn": "Намайг Ли Юэ гэдэг.", "note_mn": "өөрийгөө танилцуулж байна"}, {"zh": "李月是老师。", "pinyin": "Lǐ Yuè shì lǎoshī.", "mn": "Ли Юэ бол багш.", "note_mn": "гуравдагч этгээдийг тодорхойлж байна"}, {"zh": "李月是中国人吗？", "pinyin": "Lǐ Yuè shì Zhōngguó rén ma?", "mn": "Ли Юэ Хятад хүн үү?", "note_mn": "吗-тай асуулт"}], "mistakes": [{"wrong": "我是李月叫", "right": "我叫李月", "why_mn": "Нэрээ хэлэхдээ «Хэн+叫+Нэр» дараалалтай, 是 болон 叫-г хольж хэрэглэдэггүй."}]}, {"zh": "中国", "pinyin": "Zhōngguó", "teach_mn": "«中国» нь Хятад улсын нэр, 中 (дунд) + 国 (улс) хоёроос тогтож «дундад улс» гэсэн шууд утгатай. Хүний харьяаллыг хэлэхдээ ард нь 人-г залгана: 中国人 (хятад хүн).", "usage_mn": ["Улс орныг нэрлэхэд хэрэглэнэ", "Ард нь 人 залгаж тухайн улсын харьяат хүнийг заана"], "examples": [{"zh": "你是中国人吗？", "pinyin": "Nǐ shì Zhōngguó rén ma?", "mn": "Чи Хятад хүн үү?", "note_mn": "харьяалал асууж байна"}, {"zh": "我不是中国人，我是美国人。", "pinyin": "Wǒ bú shì Zhōngguó rén, wǒ shì Měiguó rén.", "mn": "Би Хятад хүн биш, би Америк хүн.", "note_mn": "хоёр улсыг харьцуулж хэлж байна"}, {"zh": "李月是中国人。", "pinyin": "Lǐ Yuè shì Zhōngguó rén.", "mn": "Ли Юэ бол хятад хүн.", "note_mn": "гуравдагч этгээдийн харьяалал"}], "mistakes": [{"wrong": "中国人是我", "right": "我是中国人", "why_mn": "Өгүүлбэрийн эхэнд өөрийгөө заасан 我-г тавьж, дараа нь 是, эцэст нь тодорхойлолтоо хэлнэ."}], "compare": [{"zh": "美国", "pinyin": "Měiguó", "mn": "Америк", "diff_mn": "中国 (Хятад) ба 美国 (Америк) хоёр өөр улсын нэр, утгаараа андуурч болохгүй ялгаатай ойлголт."}]}, {"zh": "美国", "pinyin": "Měiguó", "teach_mn": "«美国» нь Америк (АНУ)-ыг илэрхийлэх улсын нэр, 美 (сайхан) + 国 (улс) хоёроос тогтсон. Ард нь 人 залгаж 美国人 (америк хүн) гэдэг үг үүснэ.", "usage_mn": ["Улс орныг нэрлэхэд хэрэглэнэ", "Ард нь 人 залгаж америк хүнийг заана"], "examples": [{"zh": "我是美国人。", "pinyin": "Wǒ shì Měiguó rén.", "mn": "Би Америк хүн.", "note_mn": "харьяалалаа хэлж байна"}, {"zh": "你是美国人吗？", "pinyin": "Nǐ shì Měiguó rén ma?", "mn": "Чи Америк хүн үү?", "note_mn": "吗-тай асуулт"}, {"zh": "我不是美国人，我是中国人。", "pinyin": "Wǒ bú shì Měiguó rén, wǒ shì Zhōngguó rén.", "mn": "Би Америк хүн биш, би Хятад хүн.", "note_mn": "хоёр улсыг харьцуулж хэлж байна"}], "mistakes": [{"wrong": "美国是人", "right": "美国人", "why_mn": "美国人 бол «улс+хүн» гэсэн нэг бүхэл нэр үг, 是-г дунд нь оруулбал утгагүй болно."}]}], "grammar": [{"point": "疑问代词 什么 — «юу/ямар»", "gloss_mn": "юу, ямар — асуух төлөөний үг", "structure": "什么 + нэр үг → ямар..., эсвэл дангаараа «юу»", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "什么 нь монгол «юу, ямар» гэдэгтэй адил, тодорхойгүй зүйлийг асуухад хэрэглэдэг төлөөний үг.", "example": {"zh": "什么", "pinyin": "shénme", "mn": "юу, ямар"}}, {"title_mn": "2. Бүтэц", "body_mn": "什么-г асуух гэж буй зүйлийнхээ байранд нь шууд тавина, өгүүлбэрийн бусад хэсгийг хөдөлгөхгүй.", "example": {"zh": "叫+什么+名字", "pinyin": "jiào shénme míngzi", "mn": "ямар нэртэй гэдэг"}}, {"title_mn": "3. Хаана хэрэглэх", "body_mn": "Нэр, зүйл, зүйлийн төрлийг тодруулж асуухад ашиглана.", "example": {"zh": "你叫什么名字？", "pinyin": "Nǐ jiào shénme míngzi?", "mn": "Чамайг хэн гэдэг вэ?"}}, {"title_mn": "4. Монгол хэлтэй ялгаа", "body_mn": "Монгол хэлэнд асуух үгийг өгүүлбэрийн эхэнд гаргадаггүйтэй адил, хятад хэлэнд ч 什么-г эхэнд гаргаж эргүүлдэггүй — энгийн дарааллаа хэвээр хадгална.", "example": {"zh": "你们叫什么名字？", "pinyin": "Nǐmen jiào shénme míngzi?", "mn": "Та нарыг хэн гэдэг вэ?"}}], "examples": [{"zh": "你叫什么名字？", "pinyin": "Nǐ jiào shénme míngzi?", "mn": "Чамайг хэн гэдэг вэ?"}, {"zh": "您叫什么名字？", "pinyin": "Nín jiào shénme míngzi?", "mn": "Таны нэрийг хэн гэдэг вэ?"}, {"zh": "你们叫什么名字？", "pinyin": "Nǐmen jiào shénme míngzi?", "mn": "Та нарыг хэн гэдэг вэ?"}, {"zh": "老师叫什么名字？", "pinyin": "Lǎoshī jiào shénme míngzi?", "mn": "Багшийг хэн гэдэг вэ?"}, {"zh": "学生叫什么名字？", "pinyin": "Xuésheng jiào shénme míngzi?", "mn": "Сурагчийг хэн гэдэг вэ?"}], "mistakes": [{"wrong": "什么你叫名字？", "right": "你叫什么名字？", "why_mn": "什么 асуух үгийг өгүүлбэрийн энгийн байранд нь тавина, эхэнд гаргаж эргүүлдэггүй."}, {"wrong": "你叫什么名字吗？", "right": "你叫什么名字？", "why_mn": "什么 мэт асуух үгтэй өгүүлбэрт 吗-г дахин нэмдэггүй."}], "drills": [{"type": "choice", "question": "«Чамайг хэн гэдэг вэ?» гэдгийг хятадаар хэрхэн хэлэх вэ?", "options": ["你叫名字什么？", "你叫什么名字？", "什么你叫名字？"], "answer": "你叫什么名字？", "why_mn": "什么 нь 名字-ийн өмнө орж, өгүүлбэрийн энгийн дараалал хадгалагдана."}, {"type": "judge", "question": "什么 асуух үгтэй өгүүлбэрт 吗-г бас нэмж хэрэглэдэг.", "answer": "false", "why_mn": "什么 өөрөө асуулт үүсгэдэг тул 吗-г дахин нэмэхгүй."}, {"type": "fill", "question": "你叫___名字？(нэр асуух)", "answer": "什么", "why_mn": "«ямар нэртэй» гэдгийг асуухдаа 什么-г 名字-ийн өмнө тавина."}, {"type": "choice", "question": "老师叫什么名字？гэдгийн зөв орчуулга аль нь вэ?", "options": ["Багш хэн бэ?", "Багшийг хэн гэдэг вэ?", "Багш хаана байна?"], "answer": "Багшийг хэн гэдэг вэ?", "why_mn": "叫什么名字 нь нэрийг нь асуух тогтсон бүтэц."}]}, {"point": "是 өгүүлбэр", "gloss_mn": "«А бол Б» — 是-тэй өгүүлбэр", "structure": "А + 是 + Б; үгүйсгэхдээ А + 不是 + Б", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "是 нь «мөн, бол» гэсэн утгатай холбоос үйл үг, хоёр нэрийг холбож адилтгана.", "example": {"zh": "我是学生", "pinyin": "Wǒ shì xuésheng", "mn": "Би сурагч"}}, {"title_mn": "2. Бүтэц", "body_mn": "А (хэн/юу) + 是 + Б (юу мөн) гэсэн энгийн дарааллаар угсардаг, 是-г хэзээ ч орхидоггүй.", "example": {"zh": "李月是老师", "pinyin": "Lǐ Yuè shì lǎoshī", "mn": "Ли Юэ бол багш"}}, {"title_mn": "3. Хаана хэрэглэх", "body_mn": "Хэн нэгний мэргэжил, харьяалал, хэн болохыг тодорхойлоход өргөн хэрэглэнэ.", "example": {"zh": "我是美国人", "pinyin": "Wǒ shì Měiguó rén", "mn": "Би Америк хүн"}}, {"title_mn": "4. Үгүйсгэх", "body_mn": "是-гийн өмнө 不 тавьж 不是 болгоно, бөгөөд 是 4-р хөгтэй тул 不 нь bú болж хувирна.", "example": {"zh": "我不是老师", "pinyin": "Wǒ bú shì lǎoshī", "mn": "Би багш биш"}}], "examples": [{"zh": "我是学生。", "pinyin": "Wǒ shì xuésheng.", "mn": "Би сурагч."}, {"zh": "我是美国人。", "pinyin": "Wǒ shì Měiguó rén.", "mn": "Би Америк хүн."}, {"zh": "李月是老师。", "pinyin": "Lǐ Yuè shì lǎoshī.", "mn": "Ли Юэ бол багш."}, {"zh": "我不是老师。", "pinyin": "Wǒ bú shì lǎoshī.", "mn": "Би багш биш."}, {"zh": "你是老师吗？", "pinyin": "Nǐ shì lǎoshī ma?", "mn": "Та багш уу?"}, {"zh": "我不是中国人，我是美国人。", "pinyin": "Wǒ bú shì Zhōngguó rén, wǒ shì Měiguó rén.", "mn": "Би Хятад хүн биш, би Америк хүн."}], "mistakes": [{"wrong": "我学生。", "right": "我是学生。", "why_mn": "是-г орхивол өгүүлбэр буруу болно, монгол хэлэнд «бол»-г орхидог ч хятадад орхидоггүй."}, {"wrong": "我不老师。", "right": "我不是老师。", "why_mn": "是-г үгүйсгэхдээ 不是 гэж хамт бичих ёстой, зөвхөн 不-г дангаар нь тавьж болохгүй."}], "drills": [{"type": "fill", "question": "我___学生。(Би сурагч гэдгийг илэрхийлэх)", "answer": "是", "why_mn": "«А бол Б» бүтэцэд 是 заавал ордог."}, {"type": "choice", "question": "«Би багш биш» гэдгийг хэрхэн хэлэх вэ?", "options": ["我不老师", "我不是老师", "我是不老师"], "answer": "我不是老师", "why_mn": "Үгүйсгэхдээ 不是 гэж хамт бичнэ."}, {"type": "judge", "question": "是-г заримдаа орхиж болно.", "answer": "false", "why_mn": "是-г хэзээ ч орхиж болохгүй, өгүүлбэр болгонд байх ёстой."}, {"type": "choice", "question": "李月是老师。 гэдгийн зөв орчуулга аль нь вэ?", "options": ["Ли Юэ багш уу?", "Ли Юэ бол багш.", "Ли Юэ багш биш."], "answer": "Ли Юэ бол багш.", "why_mn": "是 энд «бол» гэсэн утгаар холбож байна."}]}, {"point": "吗 асуулт", "gloss_mn": "Өгүүлбэрийн төгсгөлд 吗 залгаж асуулт болгоно", "structure": "Хүүрнэх өгүүлбэр + 吗？", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "吗 бол өгүүлбэрийн төгсгөлд ордог сул үг, залгасны дараа хүүрнэх өгүүлбэр ерөнхий асуулт болно.", "example": {"zh": "你是老师吗？", "pinyin": "Nǐ shì lǎoshī ma?", "mn": "Та багш уу?"}}, {"title_mn": "2. Бүтэц", "body_mn": "Хүүрнэх өгүүлбэрийн төгсгөлд шууд 吗-г залгана, өгүүлбэрийн бусад хэсгийг өөрчлөхгүй.", "example": {"zh": "你是学生+吗", "pinyin": "nǐ shì xuésheng + ma", "mn": "чи сурагч + уу?"}}, {"title_mn": "3. Хариулах", "body_mn": "Хариулахдаа тийм/үгүй гэхийн оронд 是/不是 гэсэн бүтэн өгүүлбэрээр хариулна.", "example": {"zh": "是，我是老师。", "pinyin": "Shì, wǒ shì lǎoshī.", "mn": "Тийм ээ, би багш."}}, {"title_mn": "4. Санамж", "body_mn": "什么 мэт асуух үгтэй өгүүлбэрт 吗-г нэмж хэрэглэдэггүй — аль нэгийг л сонгоно.", "example": {"zh": "你叫什么名字？", "pinyin": "Nǐ jiào shénme míngzi?", "mn": "Чамайг хэн гэдэг вэ?"}}], "examples": [{"zh": "你是老师吗？", "pinyin": "Nǐ shì lǎoshī ma?", "mn": "Та багш уу?"}, {"zh": "你