values ('hsk1-l04', 1, '{"words": [{"zh": "她", "pinyin": "tā", "teach_mn": "她 нь эмэгтэй хүнийг зайнаас нэрлэхэд хэрэглэдэг «тэр» гэсэн төлөөний үг. Бичихдээ 女 (эмэгтэй) радикалтай, учир нь зөвхөн эмэгтэй хүнд хэрэглэнэ. Ярихад 他-тэй яг адилхан «tā» гэж дуудагдана, ялгаа нь зөвхөн бичгэн дээр гардаг. Монгол хэлэнд «тэр» гэдэг үг эрэгтэй эмэгтэйг ялгадаггүй, харин хятад бичигт заавал ялгаж бичнэ.", "usage_mn": ["Ярианд байхгүй эмэгтэй хүний тухай ярихад хэрэглэнэ", "Эрэгтэй хүний тухай ярихад 他 хэрэглэнэ, 她 биш"], "examples": [{"zh": "她是谁？", "pinyin": "Tā shì shéi?", "mn": "Тэр хэн бэ?", "note_mn": "эмэгтэй хүний тухай асууж байна"}, {"zh": "她是我的汉语老师。", "pinyin": "Tā shì wǒ de Hànyǔ lǎoshī.", "mn": "Тэр бол миний хятад хэлний багш.", "note_mn": ""}, {"zh": "她是我朋友。", "pinyin": "Tā shì wǒ péngyou.", "mn": "Тэр миний найз.", "note_mn": ""}, {"zh": "她叫李月。", "pinyin": "Tā jiào Lǐ Yuè.", "mn": "Түүнийг Ли Юэ гэдэг.", "note_mn": ""}], "mistakes": [{"wrong": "他是我的汉语老师。（эмэгтэй багшийн тухай ярихад）", "right": "她是我的汉语老师。", "why_mn": "Ярьж буй хүн эмэгтэй бол бичихдээ 女-радикалтай 她-г хэрэглэнэ, дуудлага адилхан ч бичиг өөр."}], "compare": [{"zh": "他", "pinyin": "tā", "mn": "тэр (эрэгтэй)", "diff_mn": "дуудлага ижил ч радикал өөр — 亻(хүн) эрэгтэйд, 女(эмэгтэй) эмэгтэйд хэрэглэнэ."}]}, {"zh": "谁", "pinyin": "shéi", "teach_mn": "谁 нь хүнийг зааж асуух асуултын үг, монголоор «хэн» гэсэн утгатай. Хятад хэлэнд асуултын үг өөрийн байрандаа (хариулт орох газраа) зогсоно, өгүүлбэрийн эхэнд заавал гаргах шаардлагагүй. Жишээ нь «Тэр хэн бэ?» гэхдээ 谁 нь 是-ийн ард, 他/她-ийн байранд ордог газраа орно. Монгол хэлэнд ч «хэн» асуултын үг өгүүлбэрийн дундуур байдгаараа төстэй.", "usage_mn": ["Хүний нэр, хэн болохыг мэдэхгүй үед асуухад хэрэглэнэ", "谁 асуусан өгүүлбэрт ард нь 吗 нэмж болохгүй — 谁 өөрөө аль хэдийн асуулт болгодог"], "examples": [{"zh": "她是谁？", "pinyin": "Tā shì shéi?", "mn": "Тэр хэн бэ?", "note_mn": ""}, {"zh": "你是谁？", "pinyin": "Nǐ shì shéi?", "mn": "Чи хэн бэ?", "note_mn": ""}, {"zh": "谁是老师？", "pinyin": "Shéi shì lǎoshī?", "mn": "Хэн нь багш вэ?", "note_mn": ""}, {"zh": "谁是你朋友？", "pinyin": "Shéi shì nǐ péngyou?", "mn": "Хэн чиний найз вэ?", "note_mn": ""}], "mistakes": [{"wrong": "她是谁吗？", "right": "她是谁？", "why_mn": "谁 өөрөө асуултын утгатай тул ард нь дахин 吗 нэмэхгүй."}]}, {"zh": "的", "pinyin": "de", "teach_mn": "的 нь монгол хэлний харьяалалын нөхцөл (-ийн, -ний, -ы) шиг үүрэг гүйцэтгэдэг туслах үг. Монгол хэлэнд нөхцөл нь үгийн ард залгадаг бол хятад хэлэнд 的 гэдэг тусдаа үг хоёр үгийн дунд орж харьяалал үзүүлнэ: 我的老师 (миний багш). Гэхдээ маш ойрын хамаатан садан, найз нөхдийн өмнө 的-г ихэвчлэн орхидог: 我妈妈, 我朋友.", "usage_mn": ["Хамааралгүй, харь зүйлийг харьяалуулахад 的 заавал хэрэглэнэ", "Ойрын хамаатан, найз нөхдийн өмнө 的-г ихэвчлэн орхино (我朋友)"], "examples": [{"zh": "她是我的汉语老师。", "pinyin": "Tā shì wǒ de Hànyǔ lǎoshī.", "mn": "Тэр бол миний хятад хэлний багш.", "note_mn": ""}, {"zh": "我的名字是李月。", "pinyin": "Wǒ de míngzi shì Lǐ Yuè.", "mn": "Миний нэрийг Ли Юэ гэдэг.", "note_mn": ""}, {"zh": "她是我朋友。", "pinyin": "Tā shì wǒ péngyou.", "mn": "Тэр миний найз.", "note_mn": "的 орхигдсон жишээ"}, {"zh": "她不是我同学，她是我朋友。", "pinyin": "Tā bú shì wǒ tóngxué, tā shì wǒ péngyou.", "mn": "Тэр миний ангийнх биш, миний найз.", "note_mn": ""}], "mistakes": [{"wrong": "我的朋友是谁的？", "right": "谁是我的朋友？", "why_mn": "的-г үг бүрийн ард дур мэдэн нэмэхгүй, зөвхөн харьяалал заах газарт нэг л удаа хэрэглэнэ."}]}, {"zh": "汉语", "pinyin": "Hànyǔ", "teach_mn": "汉语 нь «хятад хэл» гэсэн нэр үг, 汉 (Хань үндэстэн) + 语 (хэл) гэсэн хоёр ханзнаас тогтоно. Ихэвчлэн 老师, 书 зэрэг үгсийн өмнө нэмж 汉语老师 (хятад хэлний багш) гэх мэт хослол үүсгэнэ. Монгол хэлэнд «хятад хэл» гэдэг хос үгтэй яг адилхан бүтэцтэй.", "usage_mn": ["Хятад хэлийг өөрийг нь эсвэл хятад хэлтэй холбоотой зүйлийг нэрлэхэд хэрэглэнэ", "Хүнийг нэрлэхэд хэрэглэдэггүй — хүнийг 中国人 гэнэ"], "examples": [{"zh": "她是我的汉语老师。", "pinyin": "Tā shì wǒ de Hànyǔ lǎoshī.", "mn": "Тэр бол миний хятад хэлний багш.", "note_mn": ""}, {"zh": "她是汉语老师。", "pinyin": "Tā shì Hànyǔ lǎoshī.", "mn": "Тэр хятад хэлний багш.", "note_mn": ""}], "mistakes": [{"wrong": "她是汉语人。", "right": "她是中国人。", "why_mn": "хэл нэрлэхэд 汉语, харин хүн үндэстнийг нэрлэхэд 中国人 хэрэглэнэ, хольж болохгүй."}]}, {"zh": "哪", "pinyin": "nǎ", "teach_mn": "哪 нь сонголт хийхийг шаардсан асуултын үг, монголоор «аль» гэж орчуулна. Ганцаараа хэрэглэгддэггүй, ард нь тоо хэмжигч эсвэл нэр үг заавал орно: 哪国 (аль улс). Хамгийн түгээмэл хэрэглээ нь хаанаас ирснийг асуух 你是哪国人？(Чи аль улсын хүн бэ?) гэсэн өгүүлбэр.", "usage_mn": ["Хэд хэдэн сонголтоос аль нэгийг зааж асуухад хэрэглэнэ", "Ганцаараа хэрэглэдэггүй, ард нь тоо хэмжигч эсвэл нэр үг заавал орно"], "examples": [{"zh": "你是哪国人？", "pinyin": "Nǐ shì nǎ guó rén?", "mn": "Чи аль улсын хүн бэ?", "note_mn": ""}, {"zh": "她是哪国人？", "pinyin": "Tā shì nǎ guó rén?", "mn": "Тэр аль улсын хүн бэ?", "note_mn": ""}], "mistakes": [{"wrong": "你是哪人？", "right": "你是哪国人？", "why_mn": "哪-гийн ард тоо хэмжигч үг (国 гэх мэт) орох ёстой, ганцаараа 哪人 гэж хэлдэггүй."}], "compare": [{"zh": "什么", "pinyin": "shénme", "mn": "юу", "diff_mn": "什么 ерөнхий зүйл юу болохыг асуух, 哪 сонголтоос аль нэгийг зааж асуух ялгаатай."}]}, {"zh": "国", "pinyin": "guó", "teach_mn": "国 нь «улс» гэсэн утгатай нэр үг, дангаараа бага хэрэглэгдэж ихэвчлэн улсын нэрийн ард залгагдана: 中国 (Дундад улс), 美国 (Америк улс). 哪国 гэвэл «аль улс» гэсэн утгатай болно. Монгол хэлэнд ч «улс» гэдэг үгийг тусдаа болон нийлмэл үгэнд адилхан ашигладаг.", "usage_mn": ["Улсын нэрийг угтвар үгтэй хамт хэлэхэд хэрэглэнэ (中国, 美国)", "哪 асуултын үгийн ард залгаж «аль улс» гэсэн утга үүсгэнэ"], "examples": [{"zh": "你是哪国人？", "pinyin": "Nǐ shì nǎ guó rén?", "mn": "Чи аль улсын хүн бэ?", "note_mn": ""}, {"zh": "我是中国人。", "pinyin": "Wǒ shì Zhōngguó rén.", "mn": "Би Хятад хүн.", "note_mn": ""}, {"zh": "我是美国人。", "pinyin": "Wǒ shì Měiguó rén.", "mn": "Би Америк хүн.", "note_mn": ""}], "mistakes": [{"wrong": "我是国人。", "right": "我是中国人。", "why_mn": "国 дангаараа улсыг зааж чадахгүй, урд нь заавал улсын нэр (中, 美 гэх мэт) орно."}]}, {"zh": "呢", "pinyin": "ne", "teach_mn": "呢 нь өмнөх өгүүлбэртэй ижил төстэй асуултыг богиносгож давтахад хэрэглэдэг сул үг, монголоор «харин...?» гэж орчуулж болно. 我是美国人。你呢？гэвэл «Би Америк хүн. Харин чи?» буюу «чи ямар улсын хүн бэ?» гэсэн бүтэн асуултыг товчилж байна. Асуултаа бүрэн давтахгүйгээр ярианы хурдыг хурдасгадаг өгүүлбэрийн төгсгөлийн сул үг.", "usage_mn": ["Өмнөх өгүүлбэрийн сэдвийг өөр хүн рүү шилжүүлэн богино асуухад хэрэглэнэ", "Нэр/төлөөний үгийн ард шууд залгана, өөр үг завсарт оруулахгүй"], "examples": [{"zh": "我是美国人。你呢？", "pinyin": "Wǒ shì Měiguó rén. Nǐ ne?", "mn": "Би Америк хүн. Харин чи?", "note_mn": ""}, {"zh": "她叫李月。他呢？", "pinyin": "Tā jiào Lǐ Yuè. Tā ne?", "mn": "Түүнийг Ли Юэ гэдэг. Харин түүнийг?", "note_mn": ""}, {"zh": "我是学生，你呢？", "pinyin": "Wǒ shì xuésheng, nǐ ne?", "mn": "Би сурагч, харин чи?", "note_mn": ""}], "mistakes": [{"wrong": "你呢是谁？", "right": "你呢？", "why_mn": "呢 өөрөө бүтэн асуултыг товчилсон учир ард нь дахин 是谁 гэх мэт нэмэлт үг оруулахгүй."}]}, {"zh": "他", "pinyin": "tā", "teach_mn": "他 нь эрэгтэй хүнийг зайнаас нэрлэх «тэр» гэсэн төлөөний үг, 亻(хүн) радикалтай учир хүнтэй холбоотойг заана. Дуудлага нь 她-тэй яг адилхан «tā», гагцхүү бичихдээ л ялгаатай. Ярианд сонсоод хэн гэдгийг мэдэхгүй бол текст, зурагтай хамт л ялгаж ойлгоно.", "usage_mn": ["Ярианд байхгүй эрэгтэй хүний тухай ярихад хэрэглэнэ", "Эмэгтэй хүний тухай ярихад 她 хэрэглэнэ, 他 биш"], "examples": [{"zh": "他是谁？", "pinyin": "Tā shì shéi?", "mn": "Тэр хэн бэ?", "note_mn": "эрэгтэй хүний тухай асууж байна"}, {"zh": "他是我同学。", "pinyin": "Tā shì wǒ tóngxué.", "mn": "Тэр миний ангийн найз.", "note_mn": ""}, {"zh": "他是我朋友。", "pinyin": "Tā shì wǒ péngyou.", "mn": "Тэр миний найз.", "note_mn": ""}], "mistakes": [{"wrong": "她是我同学。（эрэгтэй хүний тухай ярихад）", "right": "他是我同学。", "why_mn": "Ярьж буй хүн эрэгтэй бол 亻-радикалтай 他-г хэрэглэнэ."}], "compare": [{"zh": "她", "pinyin": "tā", "mn": "тэр (эмэгтэй)", "diff_mn": "дуудлага ижил ч радикал өөр — 女(эмэгтэй) эмэгтэйд, 亻(хүн) эрэгтэйд хэрэглэнэ."}]}, {"zh": "同学", "pinyin": "tóngxué", "teach_mn": "同学 нь нэг ангид, нэг сургуульд хамт суралцаж буй хүнийг нэрлэдэг үг, монголоор «ангийн найз, хамт суралцагч» гэж орчуулж болно. 同 (хамт) + 学 (сурах) гэсэн хоёр ханзнаас тогтдог. Багш нар сурагчдаа хамтад нь дуудахдаа ч 同学们 (сурагчид оо) гэж хэлдэг.", "usage_mn": ["Нэг сургууль, ангид хамт суралцдаг хүнийг нэрлэхэд хэрэглэнэ", "Ердийн, сургуультай холбоогүй найзыг нэрлэхэд 朋友 хэрэглэнэ"], "examples": [{"zh": "他是我同学。", "pinyin": "Tā shì wǒ tóngxué.", "mn": "Тэр миний ангийн найз.", "note_mn": ""}, {"zh": "她是你同学吗？", "pinyin": "Tā shì nǐ tóngxué ma?", "mn": "Тэр чиний ангийнх уу?", "note_mn": ""}, {"zh": "她不是我同学，她是我朋友。", "pinyin": "Tā bú shì wǒ tóngxué, tā shì wǒ péngyou.", "mn": "Тэр миний ангийнх биш, миний найз.", "note_mn": ""}], "mistakes": [{"wrong": "他是我的同学的。", "right": "他是我同学。", "why_mn": "хамаатан, ойр хүний өмнө 的-г ихэвчлэн орхидог тул 同学-ийн өмнө 的 нэмэх шаардлагагүй."}], "compare": [{"zh": "朋友", "pinyin": "péngyou", "mn": "найз", "diff_mn": "同学 зөвхөн сургуулийн хүнд, 朋友 хэн ч байж болно."}]}, {"zh": "朋友", "pinyin": "péngyou", "teach_mn": "朋友 нь «найз» гэсэн ерөнхий утгатай нэр үг, сургуультай холбоотой эсэхээс үл хамааран хэн ч байж болно. Хятад хэлэнд 朋 болон 友 хоёулаа тусдаа «найз» гэсэн ойролцоо утгатай ханз байсан, хамт орж нэг үг болсон. Ойрын найзын өмнө 的-г ихэвчлэн орхидог: 我朋友.", "usage_mn": ["Хэн ч байсан дотно найзыг нэрлэхэд хэрэглэнэ", "Сургуулийн найзыг тодотгож хэлэхийг хүсвэл 同学 хэрэглэнэ"], "examples": [{"zh": "她是我朋友。", "pinyin": "Tā shì wǒ péngyou.", "mn": "Тэр миний найз.", "note_mn": ""}, {"zh": "她不是我同学，她是我朋友。", "pinyin": "Tā bú shì wǒ tóngxué, tā shì wǒ péngyou.", "mn": "Тэр миний ангийнх биш, миний найз.", "note_mn": ""}, {"zh": "他是我朋友。", "pinyin": "Tā shì wǒ péngyou.", "mn": "Тэр миний найз.", "note_mn": ""}], "mistakes": [{"wrong": "她是我的朋友吗？（ойр найзынхаа тухай хэлэхдээ）", "right": "她是我朋友。", "why_mn": "дотно найзын өмнө 的-г ихэвчлэн орхиж 我朋友 гэж хэлдэг, 的 заавал биш."}], "compare": [{"zh": "同学", "pinyin": "tóngxué", "mn": "ангийн найз", "diff_mn": "朋友 ерөнхий найз, 同学 сургуультай холбоотой найз."}]}], "grammar": [{"point": "疑问代词 谁 — «хэн»", "gloss_mn": "хэн", "structure": "谁 нь хариулт орох тэр л байранд ордог: 她是谁？", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "谁 нь хүн хэн болохыг мэдэхгүй үед асуух асуултын үг, монголоор «хэн» гэж орчуулна.", "example": {"zh": "谁", "pinyin": "shéi", "mn": "хэн"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "谁 нь өгүүлбэрт хариулт орох тэр л байранд ордог — 他/她-ийн байранд шууд тавина, өгүүлбэрийн эхэнд хамаагүй гаргахгүй.", "example": {"zh": "她是谁？", "pinyin": "Tā shì shéi?", "mn": "Тэр хэн бэ? (谁 нь 是-ийн ард)"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Шинэ хүнтэй танилцах үед, зурагт хэн буйг мэдэхгүй байхад асуухад хэрэглэнэ.", "example": {"zh": "谁是老师？", "pinyin": "Shéi shì lǎoshī?", "mn": "Хэн нь багш вэ?"}}, {"title_mn": "4. Өргөтгөл", "body_mn": "谁 нь өөрөө аль хэдийн асуултын утгатай тул ард нь дахин 吗-г нэмэхгүй.", "example": {"zh": "她是谁？(吗-гүй)", "pinyin": "Tā shì shéi?", "mn": "Тэр хэн бэ?"}}], "examples": [{"zh": "她是谁？", "pinyin": "Tā shì shéi?", "mn": "Тэр хэн бэ?"}, {"zh": "他是谁？", "pinyin": "Tā shì shéi?", "mn": "Тэр хэн бэ?"}, {"zh": "你是谁？", "pinyin": "Nǐ shì shéi?", "mn": "Чи хэн бэ?"}, {"zh": "谁是老师？", "pinyin": "Shéi shì lǎoshī?", "mn": "Хэн нь багш вэ?"}, {"zh": "谁是学生？", "pinyin": "Shéi shì xuésheng?", "mn": "Хэн нь сурагч вэ?"}, {"zh": "谁是你朋友？", "pinyin": "Shéi shì nǐ péngyou?", "mn": "Хэн чиний найз вэ?"}], "mistakes": [{"wrong": "她是谁吗？", "right": "她是谁？", "why_mn": "谁 өөрөө асуултын утгатай тул ард нь 吗 нэмэлт хэрэггүй, бүр буруу болно."}, {"wrong": "是谁她？", "right": "她是谁？", "why_mn": "谁 хариулт орох байранд ордог тул үгийн дараалал 是-ийн ард байх ёстой, өгүүлбэрийн эхэнд биш."}], "drills": [{"type": "choice", "question": "她是___？（хэн болохыг мэдэхгүй асуухад）", "options": ["谁", "什么", "哪"], "answer": "谁", "why_mn": "хүн хэн болохыг асуухад 谁 хэрэглэнэ, 什么 юу гэдгийг, 哪 алийг нь гэдгийг асуудаг."}, {"type": "judge", "question": "谁 асуусан өгүүлбэрийн төгсгөлд 吗 нэмж болно.", "answer": "false", "why_mn": "谁 өөрөө асуултын утгатай тул 吗 нэмэлт хэрэггүй."}, {"type": "fill", "question": "«Тэр хэн бэ?» гэдгийг хятадаар бич.", "answer": "她是谁？", "why_mn": "«тэр (эм)» 她, «хэн» 谁, 是-ийн ард орно."}, {"type": "fill", "question": "«Хэн нь багш вэ?» гэдгийг хятадаар бич.", "answer": "谁是老师？", "why_mn": "谁 энд өгүүлэгдэхүүний байранд орж «хэн нь» гэсэн утгыг өгнө."}]}, {"point": "疑问代词 哪 — «аль»", "gloss_mn": "аль", "structure": "哪 + тоо хэмжигч/нэр үг → 哪国", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "哪 нь хэд хэдэн сонголтоос аль нэгийг зааж асуух үг, монголоор «аль» гэдэгтэй адил.", "example": {"zh": "哪", "pinyin": "nǎ", "mn": "аль"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "哪-гийн ард заавал тоо хэмжигч эсвэл нэр үг орно, ганцаараа зогсдоггүй: 哪国 (аль улс).", "example": {"zh": "哪国", "pinyin": "nǎ guó", "mn": "аль улс"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Хаанаас ирснийг, аль зүйлийг сонгож байгааг асуухад хэрэглэнэ.", "example": {"zh": "你是哪国人？", "pinyin": "Nǐ shì nǎ guó rén?", "mn": "Чи аль улсын хүн бэ?"}}, {"title_mn": "4. Ялгаа", "body_mn": "什么 (юу)-тай бүү андуур — 什么 ерөнхий зүйл юуг асууна, 哪 тодорхой сонголтоос заана.", "example": {"zh": "哪 vs 什么", "pinyin": "nǎ vs shénme", "mn": "аль (сонголт) vs юу (ерөнхий)"}}], "examples": [{"zh": "你是哪国人？", "pinyin": "Nǐ shì nǎ guó rén?", "mn": "Чи аль улсын хүн бэ?"}, {"zh": "她是哪国人？", "pinyin": "Tā shì nǎ guó rén?", "mn": "Тэр аль улсын хүн бэ?"}, {"zh": "他是哪国人？", "pinyin": "Tā shì nǎ guó rén?", "mn": "Тэр аль улсын хүн бэ?"}, {"zh": "你是哪国人？我是中国人。", "pinyin": "Nǐ shì nǎ guó rén? Wǒ shì Zhōngguó rén.", "mn": "Чи аль улсын хүн бэ? — Би Хятад хүн."}, {"zh": "你是哪国人？我是美国人。", "pinyin": "Nǐ shì nǎ guó rén? Wǒ shì Měiguó rén.", "mn": "Чи аль улсын хүн бэ? — Би Америк хүн."}], "mistakes": [{"wrong": "你是哪人？", "right": "你是哪国人？", "why_mn": "哪-гийн ард тоо хэмжигч/нэр үг зайлшгүй орно, ганцаараа зогсохгүй."}, {"wrong": "你是什么国人？", "right": "你是哪国人？", "why_mn": "улс сонгож асуухад 哪 хэрэглэнэ, 什么 биш."}], "drills": [{"type": "choice", "question": "你是___国人？", "options": ["谁", "什么", "哪"], "answer": "哪", "why_mn": "улсаа сонгуулан асуухад 哪 хэрэглэнэ."}, {"type": "fill", "question": "«Чи аль улсын хүн бэ?» гэдгийг хятадаар бич.", "answer": "你是哪国人？", "why_mn": "哪 + 国 + 人 гэсэн дараалалтай."}, {"type": "judge", "question": "哪 ганцаараа хэрэглэгдэж болно, ард нь юу ч нэмэхгүй.", "answer": "false", "why_mn": "哪-гийн ард заавал тоо хэмжигч эсвэл нэр үг орно."}]}, {"point": "结构助词 的", "gloss_mn": "-ийн/-ний (харьяалал)", "structure": "Эзэмшигч + 的 + эзэмшигдэх зүйл → 我的老师", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "的 нь монгол хэлний харьяалалын нөхцөл (-ийн, -ний) шиг үүрэгтэй туслах үг.", "example": {"zh": "的", "pinyin": "de", "mn": "-ийн/-ний"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "[Эзэмшигч] + 的 + [эзэмшигдэх зүйл] гэсэн дарааллаар орно: 我的老师 (миний багш).", "example": {"zh": "我+的+老师", "pinyin": "wǒ de lǎoshī", "mn": "миний багш"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Харь, албан ёсны харьцаа заахад (миний багш, чиний ном) 的-г заавал хэрэглэнэ.", "example": {"zh": "她是我的汉语老师。", "pinyin": "Tā shì wǒ de Hànyǔ lǎoshī.", "mn": "Тэр бол миний хятад хэлний багш."}}, {"title_mn": "4. Өргөтгөл, ялгаа", "body_mn": "Маш ойр хамаатан, найзын өмнө 的-г ихэвчлэн орхидог: 我朋友, 我同学 гэхэд 的 хэрэггүй.", "example": {"zh": "我朋友 (的 орхигдсон)", "pinyin": "wǒ péngyou", "mn": "миний найз"}}], "examples": [{"zh": "她是我的汉语老师。", "pinyin": "Tā shì wǒ de Hànyǔ lǎoshī.", "mn": "Тэр бол миний хятад хэлний багш."}, {"zh": "我的名字是李月。", "pinyin": "Wǒ de míngzi shì Lǐ Yuè.", "mn": "Миний нэрийг Ли Юэ гэдэг."}, {"zh": "她是我朋友。", "pinyin": "Tā shì wǒ péngyou.", "mn": "Тэр миний найз. (的 орхигдсон)"}, {"zh": "他是我同学。", "pinyin": "Tā shì wǒ tóngxué.", "mn": "Тэр миний ангийн найз. (的 орхигдсон)"}, {"zh": "你的老师是谁？", "pinyin": "Nǐ de lǎoshī shì shéi?", "mn": "Чиний багш хэн бэ?"}, {"zh": "她不是我同学，她是我朋友。", "pinyin": "Tā bú shì wǒ tóngxué, tā shì wǒ péngyou.", "mn": "Тэр миний ангийнх биш, миний найз."}], "mistakes": [{"wrong": "我朋友的是谁？", "right": "谁是我的朋友？", "why_mn": "的 нь эзэмшигч ба эзэмшигдэх зүйлийн хооронд ордог, өгүүлбэрийн төгсгөлд ганцаараа үлдэхгүй."}, {"wrong": "她是我的朋友。（дотно найзын тухай ярихад заавал 的-тэй хэлэх ёстой гэж бодох）", "right": "她是我朋友。", "why_mn": "дотно найзын өмнө 的-г ихэвчлэн орхино, хоёул зөв ч ярианд 的-гүй нь илүү байгалийн."}], "drills": [{"type": "fill", "question": "«Миний нэр» гэдгийг хятадаар бич (的-г ашиглаж).", "answer": "我的名字", "why_mn": "нэр бол харь зүйл тул 的 заавал орно."}, {"type": "choice", "question": "她是我___汉语老师。", "options": ["的", "吗", "呢"], "answer": "的", "why_mn": "харьяалал заахад 的 хэрэглэнэ."}, {"type": "judge", "question": "的-г найз, гэр бүлийн өмнө үргэлж заавал бичих ёстой.", "answer": "false", "why_mn": "ойрын хүний өмнө 的-г ихэвчлэн орхидог."}, {"type": "fill", "question": "«Тэр миний найз» гэдгийг 的-гүйгээр хятадаар бич.", "answer": "她是我朋友", "why_mn": "дотно найзын өмнө 的 хэрэггүй."}]}, {"point": "疑问助词 呢 (1)", "gloss_mn": "«А...... B呢？» — Харин B?", "structure": "Нэр/төлөөний үг + 呢？", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "呢 нь өмнөх өгүүлбэртэй ижил төстэй асуултыг богиносгож давтахад хэрэглэдэг сул үг.", "example": {"zh": "呢", "pinyin": "ne", "mn": "харин...?"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Нэр/төлөөний үгийн ард шууд 呢-г залгана, өөр үг завсарт оруулахгүй.", "example": {"zh": "你呢？", "pinyin": "Nǐ ne?", "mn": "Харин чи?"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Өмнөх өгүүлбэрийн сэдвийг өөр хүн рүү шилжүүлэн богино асуухад хэрэглэнэ.", "example": {"zh": "我是美国人。你呢？", "pinyin": "Wǒ shì Měiguó rén. Nǐ ne?", "mn": "Би Америк хүн. Харин чи?"}}, {"title_mn": "4. Өргөтгөл", "body_mn": "呢 өөрөө бүтэн асуултыг орлодог тул дахин бүтэн өгүүлбэр хэлэх шаардлагагүй.", "example": {"zh": "她叫李月。他呢？", "pinyin": "Tā jiào Lǐ Yuè. Tā ne?", "mn": "Түүнийг Ли Юэ гэдэг. Харин түүнийг?"}}], "examples": [{"zh": "我是美国人。你呢？", "pinyin": "Wǒ shì Měiguó rén. Nǐ ne?", "mn": "Би Америк хүн. Харин чи?"}, {"zh": "她叫李月。他呢？", "pinyin": "Tā jiào Lǐ Yuè. Tā ne?", "mn": "Түүнийг Ли Юэ гэдэг. Харин түүнийг?"}, {"zh": "我是学生，你呢？", "pinyin": "Wǒ shì xuésheng, nǐ ne?", "mn": "Би сурагч, харин чи?"}, {"zh": "他是我同学，她呢？", "pinyin": "Tā shì wǒ tóngxué, tā ne?", "mn": "Тэр миний ангийн найз, харин тэр (эм)?"}, {"zh": "我是中国人，你呢？", "pinyin": "Wǒ shì Zhōngguó rén, nǐ ne?", "mn": "Би Хятад хүн, харин чи?"}], "mistakes": [{"wrong": "你呢是学生吗？", "right": "你呢？", "why_mn": "呢 өөрөө бүтэн асуултыг орлодог тул дахин бүтэн өгүүлбэр хэлэх шаардлагагүй."}, {"wrong": "你是呢？", "right": "你呢？", "why_mn": "呢-гийн өмнө 是 нэмэхгүй, зөвхөн нэр/төлөөний үгийн ард шууд залгана."}], "drills": [{"type": "choice", "question": "我是老师。你___？", "options": ["呢", "吗", "的"], "answer": "呢", "why_mn": "өмнөх сэдвийг өөр хүн рүү шилжүүлэн товч асуухад 呢 хэрэглэнэ."}, {"type": "fill", "question": "«Би сурагч. Харин чи?» гэдгийг хятадаар бич.", "answer": "我是学生。你呢？", "why_mn": "呢 нь 你-ийн ард орж бүтэн асуултыг товчилно."}, {"type": "judge", "question": "呢-г ямар ч өгүүлбэрийн ард нэмж болно.", "answer": "false", "why_mn": "呢(1) зөвхөн өмнөх сэдвийг давтан асуухад хэрэглэгддэг, дур мэдэн бүх өгүүлбэрт нэмдэггүй."}, {"type": "choice", "question": "她叫李月。他___？", "options": ["呢", "哪", "谁"], "answer": "呢", "why_mn": "өмнөх сэдвийг (нэр) шилжүүлэн асуухад 呢 хэрэглэнэ."}]}, {"point": "一-гийн хөгийн хувирал", "gloss_mn": "yī → yì / yí", "structure": "一 + 1/2/3-р хөгийн үг → yì; 一 + 4-р хөгийн үг → yí; дангаараа/тоонд → yī", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "一(нэг) гэдэг тоо ганцаараа болон тоо дараалалд үргэлж yī гэж дуудагдана, гэхдээ өөр үгийн өмнө орвол хөг нь өөрчлөгддөг тусгай дүрэмтэй.", "example": {"zh": "一", "pinyin": "yī", "mn": "нэг"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Дараагийн үгийн хөгөөс хамаарч 一 нь: 1,2,3-р хөгийн өмнө → yì (4-р хөг), 4-р хөгийн өмнө → yí (2-р хөг) болж хувирна.", "example": {"zh": "一张 / 一块", "pinyin": "yì zhāng / yí kuài", "mn": "нэг хуудас / нэг ширхэг"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "一 хэмжигдэхүүнтэй хамт орж тоолж байгаа үед энэ дүрэм хэрэгждэг.", "example": {"zh": "一天", "pinyin": "yìtiān", "mn": "нэг өдөр"}}, {"title_mn": "4. Ялгаа", "body_mn": "Дангаараа хэлэхэд (yī) болон тоо дараалалд (shíyī, dì yī) хувирахгүй, хэвээрээ үлдэнэ.", "example": {"zh": "十一", "pinyin": "shíyī", "mn": "арван нэг (хэвээрээ)"}}], "examples": [{"zh": "一张", "pinyin": "yì zhāng", "mn": "нэг хуудас"}, {"zh": "一块", "pinyin": "yí kuài", "mn": "нэг ширхэг"}, {"zh": "十一", "pinyin": "shíyī", "mn": "арван нэг (хэвээрээ)"}, {"zh": "第一", "pinyin": "dì yī", "mn": "нэгдүгээр (хэвээрээ)"}, {"zh": "一、二、三", "pinyin": "yī, èr, sān", "mn": "нэг, хоёр, гурав (тоолоход хэвээрээ)"}, {"zh": "星期一", "pinyin": "xīngqīyī", "mn": "даваа гараг (хэвээрээ)"}], "mistakes": [{"wrong": "yī zhāng гэж хэвээр нь дуудах", "right": "yì zhāng", "why_mn": "张 1-р хөгтэй тул 一 нь yì (4-р хөг) болж хувирна."}, {"wrong": "yì kuài гэж дуудах", "right": "yí kuài", "why_mn": "块 4-р хөгтэй тул 一 нь yí (2-р хөг) болж хувирна."}], "drills": [{"type": "choice", "question": "一张 хэрхэн дуудагдах вэ?", "options": ["yī zhāng", "yì zhāng", "yí zhāng"], "answer": "yì zhāng", "why_mn": "张 1-р хөгтэй тул 一 → yì болно."}, {"type": "choice", "question": "十一 хэрхэн дуудагдах вэ?", "options": ["shí yī", "shí yì", "shí yí"], "answer": "shí yī", "why_mn": "тоо дараалалд 一 хувирахгүй, yī хэвээр үлдэнэ."}, {"type": "judge", "question": "一 үргэлж адилхан хөгөөр дуудагдана.", "answer": "false", "why_mn": "дараагийн үгийн хөгөөс хамаарч yī, yì, yí гэж хувирна."}, {"type": "fill", "question": "«一块» гэдгийг зөв дуудлагаар (пиньинь) бич.", "answer": "yí kuài", "why_mn": "块 4-р хөгтэй тул