, {"type": "choice", "question": "九 ямар зурлагатай вэ?", "options": ["㇙ (竖弯钩)", "㇈ (横折弯钩)", "丶 (цэг)"], "answer": "㇈ (横折弯钩)", "why_mn": "九 нь ㇈ зурлагатай ханз."}, {"type": "judge", "question": "儿 ба 几 хоёр яг адилхан бичигддэг.", "answer": "false", "why_mn": "几-д нэмэлт хэвтээ хэсэг байдгаараа ялгаатай."}, {"type": "fill", "question": "«Ес» гэсэн ханзыг бич.", "answer": "九", "why_mn": "九 бол «ес» гэсэн утгатай."}]}], "hanzi": [{"hanzi": "七", "pinyin": "qī", "meaning_mn": "долоо", "story_mn": "七 бол хамгийн эртний тоон тэмдгүүдийн нэг. Яг гарал үүслийг нь тодорхой тайлбарлаж чадахгүй ч, хэвтээ зурлага дунд нь доошоо нугалж дэгээ хийсэн энгийн бүтэцтэй — өнөөдөр зөвхөн «долоо» тоог тэмдэглэдэг.", "stroke_count": 2, "stroke_tips_mn": ["Эхлээд хэвтээ зурлагыг зүүнээс баруун тат", "Дараа нь доошоо нугалж дэгээтэй зурлагыг тат"], "words": [{"zh": "七月", "pinyin": "qī yuè", "mn": "долоодугаар сар"}, {"zh": "十七", "pinyin": "shí qī", "mn": "арван долоо"}]}, {"hanzi": "儿", "pinyin": "ér", "meaning_mn": "хүү, хүүхэд", "story_mn": "儿 нь эртний бичигт жижигхэн хүүхдийн толгой, гэдийсэн хөлийг дүрсэлсэн энгийн зурган тэмдгээс гаралтай гэж үздэг. 女儿 (охин), 儿子 (хүү) гэх мэт үгэнд «хүүхэд» гэсэн утгаараа орно.", "stroke_count": 2, "stroke_tips_mn": ["Эхлээд зүүн налуу зурлагыг дээрээс доош тат", "Дараа нь нугалж дэгээтэй зурлагаар төгсгө"], "confusable": [{"zh": "几", "pinyin": "jǐ", "mn": "хэд", "diff_mn": "хоёул ижил төстэй нугалаа зурлагатай ч 几-д нэмэлт хэвтээ хэсэг бий, 儿 хоёр зурлагаас л тогтоно."}], "words": [{"zh": "女儿", "pinyin": "nǚ''ér", "mn": "охин"}, {"zh": "儿子", "pinyin": "érzi", "mn": "хүү"}]}, {"hanzi": "几", "pinyin": "jǐ", "meaning_mn": "хэд", "story_mn": "几 анхандаа жижиг, намхан ширээ, тавцангийн дүрсийг зурсан ханз байсан гэж үздэг, хожим дуудлагаар нь зээлж «хэд» гэсэн асуултын үгийг тэмдэглэхэд хэрэглэх болсон.", "stroke_count": 2, "stroke_tips_mn": ["Эхлээд зүүн налуу зурлагыг тат", "Дараа нь хэвтээ-эргэлт-нугалаа-дэгээ зурлагаар барь"], "confusable": [{"zh": "儿", "pinyin": "ér", "mn": "хүү, хүүхэд", "diff_mn": "儿-д зөвхөн нугалаа зурлага байхад 几-д хэвтээ хэсэг нэмэгдсэн байдгаараа ялгаатай."}], "words": [{"zh": "几口人", "pinyin": "jǐ kǒu rén", "mn": "хэдэн ам бүл"}, {"zh": "几岁", "pinyin": "jǐ suì", "mn": "хэдэн настай"}]}, {"hanzi": "九", "pinyin": "jiǔ", "meaning_mn": "ес", "story_mn": "九-ийн яг тодорхой гарал үүсэл эцэслэн тогтоогдоогүй, зарим судлаачид гулзайсан гар эсвэл амьтны биеийн дүрснээс үүссэн гэж таамагладаг. Бүтэц нь энгийн — зүүн налуу дараа нь баруун тийш урт дэгээтэй нугалаа зурлага.", "stroke_count": 2, "stroke_tips_mn": ["Эхлээд зүүн налуу зурлагыг тат", "Дараа нь баруун тийш нугалж, доош сунасан дэгээтэй зурлагаар төгсгө"], "confusable": [{"zh": "几", "pinyin": "jǐ", "mn": "хэд", "diff_mn": "хоёул төстэй нугалаа хэлбэртэй ч 九-ийн дэгээ илүү урт, доош сунадаг."}], "words": [{"zh": "九月", "pinyin": "jiǔ yuè", "mn": "есдүгээр сар"}, {"zh": "十九", "pinyin": "shí jiǔ", "mn": "арван ес"}]}], "pronunciation": {"focus_mn": "Энэ хичээлд zh ch sh r-ийн нарийн ялгаа, -n/-ng ялгаа, мөн 一-гийн хөгийн хувирлыг сайн эзэмшихэд анхаар — эдгээр нь монгол хүнд хамгийн хэцүү, чихээр ялгахад цаг хугацаа шаардсан авиа юм.", "drills": [{"title_mn": "zh / ch / sh / r ялгах", "instruction_mn": "Хосыг дараалан чангаар хэлж, хэлний үзүүрийнхээ байрлал, амьсгалын хүчийг ажигла.", "pairs": [{"a": {"zh": "知识", "pinyin": "zhīshi", "mn": "мэдлэг"}, "b": {"zh": "厨师", "pinyin": "chúshī", "mn": "тогооч"}, "note_mn": "zh хэлний үзүүр тагнайд хүрч нээгдэнэ (салхигүй), ch адил байрлалд ч хүчтэй салхитай."}, {"a": {"zh": "生日", "pinyin": "shēngrì", "mn": "төрсөн өдөр"}, "b": {"zh": "认识", "pinyin": "rènshi", "mn": "таних"}, "note_mn": "sh хэл тагнайд хүрэлгүй завсар үлдээнэ, r ижил байрлалд ч хоолой чичирнэ (дуутай)."}, {"a": {"zh": "上车", "pinyin": "shàngchē", "mn": "машинд суух"}, "b": {"zh": "超人", "pinyin": "chāorén", "mn": "супермэн"}, "note_mn": "sh, ch хоёрын ялгааг чихээрээ анхааралтай сонсож дадлагажих."}, {"a": {"zh": "常识", "pinyin": "chángshí", "mn": "энгийн мэдлэг"}, "b": {"zh": "事实", "pinyin": "shìshí", "mn": "үнэн зүйл"}, "note_mn": "ch хүчтэй амьсгалтай, sh амьсгал сул, завсар мэдрэгдэнэ."}]}, {"title_mn": "-n / -ng ялгах", "instruction_mn": "Хос үгийг дараалан хэлж, хамрын ард гарах авиаг мэдэр.", "pairs": [{"a": {"zh": "山", "pinyin": "shān", "mn": "уул"}, "b": {"zh": "伤", "pinyin": "shāng", "mn": "шарх"}, "note_mn": "-n: хэлний үзүүр дээд буйланд наалдана. -ng: хэлний уг хойшоо татагдаж ам илүү ангайна."}, {"a": {"zh": "心", "pinyin": "xīn", "mn": "зүрх"}, "b": {"zh": "星", "pinyin": "xīng", "mn": "од"}, "note_mn": "xīn-г хэлж дуусахад ам аньж, xīng-г хэлэхэд ам нээлттэй үлдэнэ."}, {"a": {"zh": "音", "pinyin": "yīn", "mn": "авиа"}, "b": {"zh": "英", "pinyin": "yīng", "mn": "Английн"}, "note_mn": "утга огт өөр болдгийг сана — -n/-ng андуурвал ойлголцоход саад болно."}]}, {"title_mn": "一-гийн хөгийн хувирал дадлага", "instruction_mn": "Хосыг харьцуулж хэлээд 一-гийн хөг өөрчлөгдөж байгааг чихээрээ шалга.", "pairs": [{"a": {"zh": "一", "pinyin": "yī", "mn": "нэг (дангаараа)"}, "b": {"zh": "一张", "pinyin": "yì zhāng", "mn": "нэг хуудас"}, "note_mn": "дангаараа yī хэвээр, 张(1-р хөг)-ийн өмнө yì (4-р хөг) болно."}, {"a": {"zh": "十一", "pinyin": "shíyī", "mn": "арван нэг"}, "b": {"zh": "一块", "pinyin": "yí kuài", "mn": "нэг ширхэг"}, "note_mn": "тоо дараалалд yī хэвээр, 块(4-р хөг)-ийн өмнө yí (2-р хөг) болно."}, {"a": {"zh": "一天", "pinyin": "yìtiān", "mn": "нэг өдөр"}, "b": {"zh": "一定", "pinyin": "yídìng", "mn": "заавал"}, "note_mn": "天 1-р хөг тул yì, 定 4-р хөг тул yí болно."}]}], "tips_mn": ["zh ch sh r-г ялгахдаа толинд амаа хараарай — хэлний байрлал өөр өөр байх ёстой.", "-n/-ng ялгааг мэдрэхийн тулд хамраа гараараа дараад дуудаж үз, -ng үед хамраар гарах агаар илүү их байна.", "一-гийн хувирлыг тогтоохын тулд эхлээд дараагийн үгийн хөгийг мэдэж аваад, дараа нь 一-гээ түүнд тааруулж дуудаарай."]}}'::jsonb)
