insert into public.lesson_deep_teaching (lesson_id, version, payload)
values ('hsk1-l05', 1, '{"words": [{"zh": "家", "pinyin": "jiā", "teach_mn": "家 нь «гэр, гэр бүл» гэсэн утгатай нэр үг, хүн амьдардаг байшинг төдийгүй гэр бүлийн гишүүдийг хамтад нь илэрхийлж болно. 你家 гэвэл «танай гэр бүл» гэсэн утгаар ойлгогдоно. Монгол хэлэнд ч «гэр» гэдэг үг байшин болон гэр бүлийг хоёуланг нь илэрхийлдэгтэй адил төстэй.", "usage_mn": ["Хэний гэр бүлийн тухай ярьж байгаагаа заахдаа өмнө нь хүн/төлөөний үг тавина (你家, 我家)", "的-г ихэвчлэн орхиод шууд хэлнэ: 你家 (的 хэрэггүй)"], "examples": [{"zh": "你家有几口人？", "pinyin": "Nǐ jiā yǒu jǐ kǒu rén?", "mn": "Танайх хэдүүлээ вэ?", "note_mn": ""}, {"zh": "我家有三口人。", "pinyin": "Wǒ jiā yǒu sān kǒu rén.", "mn": "Манайх гурвуулаа.", "note_mn": ""}, {"zh": "你女儿几岁了？", "pinyin": "Nǐ nǚ''ér jǐ suì le?", "mn": "Охин чинь хэдэн настай вэ?", "note_mn": "家-тай холбоотой гэр бүлийн сэдэв"}], "mistakes": [{"wrong": "你的家有几口人？", "right": "你家有几口人？", "why_mn": "家-ийн өмнө хүн/төлөөний үг ирэхэд 的-г ихэвчлэн орхидог, хэт албан ёсны сонсогдоно."}]}, {"zh": "有", "pinyin": "yǒu", "teach_mn": "有 нь «байх, эзэмшдэг» гэсэн утгатай үйл үг, юмтай эсэхийг эсвэл тоо хэмжээг илэрхийлэхэд хэрэглэнэ: 我家有三口人 (Манайх гурвуулаа, шууд утгаараа «гурван ам бүлтэй байна»). 有-г үгүйсгэхдээ бусад үйл үг шиг 不-г биш, зөвхөн 没-г хэрэглэдэг өвөрмөц үйл үг.", "usage_mn": ["Тоо хэмжээ, гэр бүлийн гишүүн зэргийг хэлэхэд хэрэглэнэ", "Үгүйсгэхдээ 不有 гэж хэлдэггүй, 没有 гэнэ"], "examples": [{"zh": "我家有三口人。", "pinyin": "Wǒ jiā yǒu sān kǒu rén.", "mn": "Манайх гурвуулаа.", "note_mn": ""}, {"zh": "你家有几口人？", "pinyin": "Nǐ jiā yǒu jǐ kǒu rén?", "mn": "Танайх хэдүүлээ вэ?", "note_mn": ""}], "mistakes": [{"wrong": "我家不有三口人。", "right": "我家没有三口人。（эсрэг санаа илэрхийлэхэд）", "why_mn": "有-г үгүйсгэхдээ 不 биш 没-г ашигладаг онцгой үйл үг."}]}, {"zh": "口", "pinyin": "kǒu", "teach_mn": "口 нь өөрөө «ам» гэсэн утгатай ханз боловч гэр бүлийн гишүүдийг тоолоход тусгай тоолуур үг болж хувирдаг: 三口人 (гурван ам бүл). Монгол хэлэнд «гурван ам бүлтэй» гэхэд яг ижил зарчмаар «ам» гэдэг үгийг гэр бүлийн гишүүн тоолоход хэрэглэдэг нь сонирхолтой төстэй тал.", "usage_mn": ["Зөвхөн гэр бүлийн гишүүдийг тоолоход хэрэглэнэ (三口人)", "Бусад хүнийг тоолоход өөр тоолуур үг хэрэглэнэ, 口 биш"], "examples": [{"zh": "我家有三口人。", "pinyin": "Wǒ jiā yǒu sān kǒu rén.", "mn": "Манайх гурвуулаа.", "note_mn": ""}, {"zh": "你家有几口人？", "pinyin": "Nǐ jiā yǒu jǐ kǒu rén?", "mn": "Танайх хэдүүлээ вэ?", "note_mn": ""}], "mistakes": [{"wrong": "我家有三口老师。", "right": "我家有三口人。", "why_mn": "口 зөвхөн гэр бүлийн «хүн» (人) тоолоход хэрэглэгддэг, өөр үгэнд хэрэглэдэггүй."}]}, {"zh": "女儿", "pinyin": "nǚ''ér", "teach_mn": "女儿 нь эцэг эхийн «охин» хүүхдийг нэрлэдэг үг, 女(эмэгтэй)+儿(хүүхэд) гэсэн хоёр ханзнаас тогтоно. Пиньинь бичихдээ дунд нь '' (тусгаарлах тэмдэг) заавал тавьдаг, эс тэгвэл nǚér гэж буруу уншигдана.", "usage_mn": ["Өөрийн болон бусдын охин хүүхдийн тухай ярихад хэрэглэнэ", "Пиньинь бичихдээ '' тэмдгийг мартаж болохгүй"], "examples": [{"zh": "你女儿几岁了？", "pinyin": "Nǐ nǚ''ér jǐ suì le?", "mn": "Охин чинь хэдэн настай вэ?", "note_mn": ""}, {"zh": "她女儿今年二十岁。", "pinyin": "Tā nǚ''ér jīnnián èrshí suì.", "mn": "Түүний охин энэ жил хорин настай.", "note_mn": ""}, {"zh": "我朋友的女儿今年四岁了。", "pinyin": "Wǒ péngyou de nǚ''ér jīnnián sì suì le.", "mn": "Найзын минь охин энэ жил дөрөв хүрлээ.", "note_mn": ""}], "mistakes": [{"wrong": "nǚér гэж бичих", "right": "nǚ''ér гэж '' тэмдэгтэй бичих", "why_mn": "'' тэмдгийг орхивол уншигч nǚér гэж нэг үе шиг андуурч уншина."}]}, {"zh": "几", "pinyin": "jǐ", "teach_mn": "几 нь ихэвчлэн 10-аас бага тоог таамаглаж асуухад хэрэглэдэг асуултын үг, өмнөх хичээлд ханз хэлбэрээр нь үзсэн. Энэ хичээлд 几口人 (хэдэн ам бүл), 几岁 (хэдэн нас) гэсэн шинэ хэрэглээгээр дахин гарч байна. Ард нь заавал тоо хэмжигч үг орно.", "usage_mn": ["Жижиг тоо (ойролцоогоор 10-аас доош) таамаглаж асуухад хэрэглэнэ", "Насны хувьд том хүнээс асуухдаа 多大 хэрэглэнэ, 几岁 биш"], "examples": [{"zh": "你家有几口人？", "pinyin": "Nǐ jiā yǒu jǐ kǒu rén?", "mn": "Танайх хэдүүлээ вэ?", "note_mn": ""}, {"zh": "你女儿几岁了？", "pinyin": "Nǐ nǚ''ér jǐ suì le?", "mn": "Охин чинь хэдэн настай вэ?", "note_mn": ""}], "mistakes": [{"wrong": "李老师几岁了？（ахмад хүнээс）", "right": "李老师多大了？", "why_mn": "几岁 зөвхөн бага насны хүүхдээс асуухад тохиромжтой, ахмад хүнээс 多大 гэж эелдэгээр асууна."}], "compare": [{"zh": "多大", "pinyin": "duō dà", "mn": "хэдэн настай (том хүнд)", "diff_mn": "几岁 бага хүүхдэд, 多大 өсвөр болон насанд хүрэгчид хэрэглэнэ."}]}, {"zh": "岁", "pinyin": "suì", "teach_mn": "岁 нь нас тоолох нэгж үг, ард нь заавал тоо орно: 四岁 (дөрвөн нас). Монгол хэлэнд «нас» гэдэг үгийг тоогийн ард залгадагтай адилхан бүтэцтэй.", "usage_mn": ["Тооны ард залгаж нас хэлэхэд хэрэглэнэ (四岁, 二十岁)", "几岁 хэлбэрээр бага насны хүүхдийн нас асуухад хэрэглэнэ"], "examples": [{"zh": "她今年四岁了。", "pinyin": "Tā jīnnián sì suì le.", "mn": "Тэр энэ жил дөрвөн настай болсон.", "note_mn": ""}, {"zh": "你女儿几岁了？", "pinyin": "Nǐ nǚ''ér jǐ suì le?", "mn": "Охин чинь хэдэн настай вэ?", "note_mn": ""}, {"zh": "她女儿今年二十岁。", "pinyin": "Tā nǚ''ér jīnnián èrshí suì.", "mn": "Түүний охин энэ жил хорин настай.", "note_mn": ""}], "mistakes": [{"wrong": "她四岁今年了。", "right": "她今年四岁了。", "why_mn": "今年(энэ жил) цагийн үг ихэвчлэн эхэнд ордог, тоо+岁-ийн дунд орохгүй."}]}, {"zh": "了", "pinyin": "le", "teach_mn": "了 нь өгүүлбэрийн төгсгөлд орж, өмнө нь байгаагүй шинэ байдал үүссэн, өөрчлөлт гарсныг мэдэгдэх сул үг. «Дөрөв ХҮРЛЭЭ» гэдгийг 四岁了 гэж хэлж байгаа нь урьд нь дөрвөн настай байгаагүй, ОДОО л дөрөвт хүрснийг заана. Монгол хэлэнд ийм тусгай өөрчлөлт заасан үг байдаггүй тул анхаарал шаардсан шинэ ойлголт.", "usage_mn": ["Нас, байдал өөрчлөгдсөнийг мэдэгдэхэд өгүүлбэрийн төгсгөлд нэмнэ", "«Өнгөрсөн цаг» гэж бүү андуур — энэ бол өөрчлөлт заасан үг"], "examples": [{"zh": "她今年四岁了。", "pinyin": "Tā jīnnián sì suì le.", "mn": "Тэр энэ жил дөрвөн настай болсон.", "note_mn": ""}, {"zh": "李老师今年50岁了。", "pinyin": "Lǐ lǎoshī jīnnián wǔshí suì le.", "mn": "Ли багш энэ жил 50 хүрсэн.", "note_mn": ""}, {"zh": "我朋友的女儿今年四岁了。", "pinyin": "Wǒ péngyou de nǚ''ér jīnnián sì suì le.", "mn": "Найзын минь охин энэ жил дөрөв хүрлээ.", "note_mn": ""}], "mistakes": [{"wrong": "«她今年四岁了»-г «тэр дөрвөн настай байсан» гэж орчуулах", "right": "«тэр дөрөв хүрлээ/болсон» гэж орчуулна", "why_mn": "了 өнгөрсөн цаг заахгүй, харин шинэ байдал (одоо дөрөвт хүрсэн) үүссэнийг заана."}]}, {"zh": "今年", "pinyin": "jīnnián", "teach_mn": "今年 нь «энэ жил» гэсэн цаг заасан үг, ихэвчлэн өгүүлбэрийн эхэнд эсвэл эзэн биеийн ард, үйл үг/тэмдэг нэрийн өмнө ордог. 今(одоо)+年(жил) гэсэн хоёр ханзнаас бүтнэ.", "usage_mn": ["Насаа, энэ жилийн байдлаа хэлэхдээ хэрэглэнэ", "Эзэн биеийн дараа, тэмдэг нэрийн өмнө байрлана (她今年...)"], "examples": [{"zh": "她今年四岁了。", "pinyin": "Tā jīnnián sì suì le.", "mn": "Тэр энэ жил дөрвөн настай болсон.", "note_mn": ""}, {"zh": "她今年二十岁。", "pinyin": "Tā jīnnián èrshí suì.", "mn": "Тэр энэ жил хорин настай.", "note_mn": ""}, {"zh": "李老师今年50岁了。", "pinyin": "Lǐ lǎoshī jīnnián wǔshí suì le.", "mn": "Ли багш энэ жил 50 хүрсэн.", "note_mn": ""}], "mistakes": [{"wrong": "她四岁今年了。", "right": "她今年四岁了。", "why_mn": "今年 нь тоо+岁-ийн өмнө орох ёстой, дунд нь орохгүй."}]}, {"zh": "多", "pinyin": "duō", "teach_mn": "多 нь өөрөө «олон» гэсэн утгатай ч 多大 гэх мэт бүтцэд «хэр, хэчнээн» гэсэн хэмжээ асуух утга гаргадаг. Энэ хичээлд 多大了 (хэдэн настай болов) гэдэг хэллэгт л үздэг.", "usage_mn": ["大(том)-тай хослуулж 多大 хэмжээ/нас асуух хэллэг үүсгэнэ", "Ганцаараа хэрэглэхдээ «олон» гэсэн өөр утгатай болохыг сана"], "examples": [{"zh": "你今年多大了？", "pinyin": "Nǐ jīnnián duō dà le?", "mn": "Чи энэ жил хэдэн настай болов?", "note_mn": ""}, {"zh": "李老师多大了？", "pinyin": "Lǐ lǎoshī duō dà le?", "mn": "Ли багш хэдэн настай вэ?", "note_mn": ""}, {"zh": "你女儿今年多大了？", "pinyin": "Nǐ nǚ''ér jīnnián duō dà le?", "mn": "Охин чинь энэ жил хэдтэй болов?", "note_mn": ""}], "mistakes": [{"wrong": "你多大岁了？", "right": "你多大了？", "why_mn": "多大 өөрөө бүрэн хэллэг, ард нь дахин 岁 нэмэхгүй."}]}, {"zh": "大", "pinyin": "dà", "teach_mn": "大 нь үндсэндээ «том» гэсэн утгатай тэмдэг нэр боловч 多大 хэллэгт орж «хэдэн настай» гэсэн шинэ утга гаргана. Дангаараа хэмжээ, овор хэлэхэд ч, тэмдэг нэр болгож хэрэглэдэг.", "usage_mn": ["多-тай хамт 多大 хэлбэрээр нас асуухад хэрэглэнэ", "Ганцаараа зүйлийн хэмжээ, оврыг «том» гэж тодорхойлоход хэрэглэнэ"], "examples": [{"zh": "李老师多大了？", "pinyin": "Lǐ lǎoshī duō dà le?", "mn": "Ли багш хэдэн настай вэ?", "note_mn": ""}, {"zh": "你今年多大了？", "pinyin": "Nǐ jīnnián duō dà le?", "mn": "Чи энэ жил хэдэн настай болов?", "note_mn": ""}], "mistakes": [{"wrong": "你大了吗？（нас асуухдаа）", "right": "你多大了？", "why_mn": "нас асуухдаа 大-г ганцаараа биш 多-тай хослуулж 多大 гэж хэлнэ."}]}], "grammar": [{"point": "疑问代词 几 — «хэд»", "gloss_mn": "хэд (10-аас бага тоо асуухад)", "structure": "几 + тоо хэмжигч → 几口人, 几岁", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "几 нь ерөнхийдөө 10-аас бага байх магадлалтай тоог таамаглаж асуух үг, монголоор «хэд» гэдэгтэй адил.", "example": {"zh": "几", "pinyin": "jǐ", "mn": "хэд"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "几-ийн ард заавал тоо хэмжигч үг ордог, дангаараа зогсдоггүй: 几口(хэдэн ам), 几岁(хэдэн нас).", "example": {"zh": "几口人", "pinyin": "jǐ kǒu rén", "mn": "хэдэн ам бүл"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Гэр бүлийн гишүүний тоо, бага насны хүүхдийн нас зэрэг жижиг тоог асуухад хэрэглэнэ.", "example": {"zh": "你女儿几岁了？", "pinyin": "Nǐ nǚ''ér jǐ suì le?", "mn": "Охин чинь хэдэн настай вэ?"}}, {"title_mn": "4. Ялгаа", "body_mn": "Том тоо эсвэл насанд хүрсэн хүний нас асуухад 几-г бус 多大 хэрэглэнэ.", "example": {"zh": "多大了？", "pinyin": "Duō dà le?", "mn": "Хэдэн настай вэ? (том хүнд)"}}], "examples": [{"zh": "你家有几口人？", "pinyin": "Nǐ jiā yǒu jǐ kǒu rén?", "mn": "Танайх хэдүүлээ вэ?"}, {"zh": "你女儿几岁了？", "pinyin": "Nǐ nǚ''ér jǐ suì le?", "mn": "Охин чинь хэдэн настай вэ?"}, {"zh": "她女儿几岁了？", "pinyin": "Tā nǚ''ér jǐ suì le?", "mn": "Түүний охин хэдэн настай вэ?"}, {"zh": "你女儿今年几岁了？", "pinyin": "Nǐ nǚ''ér jīnnián jǐ suì le?", "mn": "Охин чинь энэ жил хэдэн настай вэ?"}, {"zh": "你家有几口人？我家有三口人。", "pinyin": "Nǐ jiā yǒu jǐ kǒu rén? Wǒ jiā yǒu sān kǒu rén.", "mn": "Танайх хэдүүлээ вэ? — Манайх гурвуулаа."}], "mistakes": [{"wrong": "你家有几口人吗？", "right": "你家有几口人？", "why_mn": "几 өөрөө асуултын утгатай тул ард нь дахин 吗 нэмэхгүй."}, {"wrong": "李老师几岁了？（ахмад хүнээс）", "right": "李老师多大了？", "why_mn": "几岁 зөвхөн бага насны хүүхдэд, ахмад хүнд 多大 хэрэглэнэ."}], "drills": [{"type": "choice", "question": "你女儿___岁了？", "options": ["几", "多", "哪"], "answer": "几", "why_mn": "бага насны хүүхдийн нас асуухад 几 хэрэглэнэ."}, {"type": "fill", "question": "«Танайх хэдүүлээ вэ?» гэдгийг хятадаар бич.", "answer": "你家有几口人？", "why_mn": "几 + 口 + 人 гэсэн дараалалтай."}, {"type": "judge", "question": "几-г ямар ч насны хүнээс нас асуухад адилхан хэрэглэж болно.", "answer": "false", "why_mn": "том хүнээс нас асуухдаа 多大 хэрэглэнэ, 几-г биш."}, {"type": "choice", "question": "几-ийн ард юу заавал ордог вэ?", "options": ["тоо хэмжигч үг", "тэмдэг нэр", "өөр төлөөний үг"], "answer": "тоо хэмжигч үг", "why_mn": "几 дангаараа зогсдоггүй, ард нь тоо хэмжигч үг (口, 岁 гэх мэт) орно."}]}, {"point": "百以内的数字 — 1–99 тоо", "gloss_mn": "аравт+нэгж бүтэцтэй тоо", "structure": "X十Y → 二十三 (2×10+3)", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "10-аас 99 хүртэлх тоог хятадаар «арав» (十) ба нэгж тоог хослуулж хэлдэг.", "example": {"zh": "十九", "pinyin": "shíjiǔ", "mn": "19"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Аравтын орон × 十 + нэгжийн орон. Жишээ нь 二十三 = 二(2)×十(10)+三(3) = 23.", "example": {"zh": "二十三", "pinyin": "èrshísān", "mn": "23"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Нас, тоо хэмжээ, огноо зэргийг хэлэхэд өдөр тутам хэрэглэгддэг.", "example": {"zh": "她女儿今年二十岁。", "pinyin": "Tā nǚ''ér jīnnián èrshí suì.", "mn": "Түүний охин энэ жил хорин настай."}}, {"title_mn": "4. Ялгаа", "body_mn": "Монгол хэлэнд «хорин гурав» гэдэг шиг эрэмбэ ижил (аравт эхэлж нэгж дараа орно) тул логик нь харьцангуй ойлгомжтой.", "example": {"zh": 