       payload = excluded.payload;

insert into public.lesson_deep_teaching (lesson_id, version, payload)
values ('hsk1-l06', 1, '{"words": [{"zh": "会", "pinyin": "huì", "teach_mn": "«会» нь монгол хэлний «чадна» гэдэгтэй төстэй тусламж үйл үг боловч зөвхөн СУРЧ, ДАДЛАГАЖИЖ олж авсан чадварыг л заана — төрөлхийн чадвар, боломж заахгүй. Үргэлж гол үйл үгийнхээ өмнө ордог: 会 + үйл үг. Монгол хэлэнд «чадна» гэдгийг нөхцөл (-ж чадна) залгаж илэрхийлдэг бол хятад хэлэнд 会 гэдэг тусдаа үгээр илэрхийлдэг нь ялгаа.", "usage_mn": ["Сурч дадлагажиж олж авсан чадварт хэрэглэнэ: хэл ярих, хоол хийх, бичих", "Биеийн байгалиас заяасан чадвар, тухайн мөчийн боломжид хэрэглэдэггүй"], "examples": [{"zh": "我会说汉语。", "pinyin": "Wǒ huì shuō Hànyǔ.", "mn": "Би хятадаар ярьж чадна."}, {"zh": "你会说汉语吗？", "pinyin": "Nǐ huì shuō Hànyǔ ma?", "mn": "Чи хятадаар ярьж чадах уу?"}, {"zh": "你妈妈会说汉语吗？", "pinyin": "Nǐ māma huì shuō Hànyǔ ma?", "mn": "Ээж чинь хятадаар ярьдаг уу?"}, {"zh": "我不会做中国菜。", "pinyin": "Wǒ bú huì zuò Zhōngguó cài.", "mn": "Би хятад хоол хийж чадахгүй."}, {"zh": "我会写汉字。", "pinyin": "Wǒ huì xiě Hànzì.", "mn": "Би ханз бичиж чадна."}], "mistakes": [{"wrong": "我会不说汉语。", "right": "我不会说汉语。", "why_mn": "Үгүйсгэх 不-г 会-ийн ӨМНӨ тавина, 会 ба үйл үгийн хооронд оруулахгүй."}, {"wrong": "我是会说汉语。", "right": "我会说汉语。", "why_mn": "会 өөрөө чадвар заасан үйл үг тул урд нь 是 нэмэх шаардлагагүй."}], "compare": [{"zh": "能", "pinyin": "néng", "mn": "чадна (нөхцөл байдлын хувьд)", "diff_mn": "会 нь СУРЧ олж авсан чадварыг, 能 нь тухайн үеийн нөхцөл, эрх, биеийн байдлаас шалтгаалан чадахыг заана (жишээ нь өвчтэй тул явж чадахгүй — 能 хэрэглэнэ)."}]}, {"zh": "说", "pinyin": "shuō", "teach_mn": "«说» нь «ярих, хэлэх» гэсэн энгийн үйл үг. Ихэвчлэн ямар хэлээр ярьж байгаагаа заасан үгийн (汉语, 中文 гэх мэт) ард шууд ордог: 说 + хэл. Монгол хэлэнд «хятадаар ярих» гэхдээ хэлний нэрэнд нөхцөл залгадаг бол хятад хэлэнд 说 гол үйл үгийн ард шууд хэлний нэрийг залгана, өөр угтвар үг хэрэггүй.", "usage_mn": ["Ямар хэлээр ярьдгаа хэлэхэд: 说 + хэлний нэр", "会-ийн ард орж «ярьж чадна» гэсэн чадварыг илэрхийлэхэд түгээмэл хэрэглэнэ"], "examples": [{"zh": "我会说汉语。", "pinyin": "Wǒ huì shuō Hànyǔ.", "mn": "Би хятадаар ярьж чадна."}, {"zh": "你会说汉语吗？", "pinyin": "Nǐ huì shuō Hànyǔ ma?", "mn": "Чи хятадаар ярьж чадах уу?"}, {"zh": "她不会说。", "pinyin": "Tā bú huì shuō.", "mn": "Тэр ярьж чадахгүй."}, {"zh": "我妈妈说汉语。", "pinyin": "Wǒ māma shuō Hànyǔ.", "mn": "Ээж минь хятадаар ярьдаг."}], "mistakes": [{"wrong": "我说汉语很好。", "right": "我汉语说得很好。", "why_mn": "Энгийн HSK1 түвшинд «汉语说得很好» гэсэн бүтэц хожим орно; HSK1-д зүгээр л «我会说汉语» гэж хэлж сураад дараа нь өргөтгөнө."}]}, {"zh": "妈妈", "pinyin": "māma", "teach_mn": "«妈妈» нь «ээж» гэсэн үг, хоёр дахь 妈 хөгөө алдаж хөнгөн аяар дуудагдана (māma, хоёр дахь үе тэгш биш). 爸爸 (аав)-тай хамт гэр бүлийн хамгийн эхний үгсийн нэг. Монгол хэлэнд ч «ээж» гэдэг үг давхардаагүй ч энгийн, дотно дуудлагатай төстэй.", "usage_mn": ["Өөрийн болон бусдын ээжийг нэрлэхэд хэрэглэнэ", "妈妈 гэдгийн хоёр дахь үе хөнгөн, богино дуудагдана"], "examples": [{"zh": "你妈妈会说汉语吗？", "pinyin": "Nǐ māma huì shuō Hànyǔ ma?", "mn": "Ээж чинь хятадаар ярьдаг уу?"}, {"zh": "我妈妈的汉语不好。", "pinyin": "Wǒ māma de Hànyǔ bù hǎo.", "mn": "Ээжийн минь хятад хэл сайн биш."}, {"zh": "我妈妈是老师。", "pinyin": "Wǒ māma shì lǎoshī.", "mn": "Ээж минь багш."}], "mistakes": [{"wrong": "我的妈妈", "right": "我妈妈", "why_mn": "Гэр бүлийн нэр (妈妈, 爸爸) өмнө 的-г ихэвчлэн орхидог, ярианд шууд «我妈妈» гэж хэлдэг нь дотно харьцааг илэрхийлнэ."}]}, {"zh": "菜", "pinyin": "cài", "teach_mn": "«菜» нь «хоол, ногоо» гэсэн утгатай. Ганцаараа «ногоо» гэсэн утгаар ч, ямар нэг орны нэрийн ард орж «тухайн орны хоол» гэсэн утгаар ч хэрэглэгддэг: 中国菜 (хятад хоол). Монгол хэлэнд «хоол» гэдэг ерөнхий үг байдаг бол хятад хэлэнд 菜 илүү задгай хоол, тавагт хийсэн хоолны ойлголтод дөхөж байна (будаа 米饭-с ялгаатай).", "usage_mn": ["Орны нэрийн ард орж тухайн үндэстний хоолыг заана: 中国菜", "Ганцаараа ерөнхий хоол, ногоо гэсэн утгаар ч хэрэглэгдэнэ"], "examples": [{"zh": "中国菜好吃吗？", "pinyin": "Zhōngguó cài hǎochī ma?", "mn": "Хятад хоол амттай юу?"}, {"zh": "中国菜很好吃。", "pinyin": "Zhōngguó cài hěn hǎochī.", "mn": "Хятад хоол их амттай."}, {"zh": "你会做中国菜吗？", "pinyin": "Nǐ huì zuò Zhōngguó cài ma?", "mn": "Чи хятад хоол хийж чадах уу?"}, {"zh": "我不会做中国菜。", "pinyin": "Wǒ bú huì zuò Zhōngguó cài.", "mn": "Би хятад хоол хийж чадахгүй."}], "mistakes": []}, {"zh": "很", "pinyin": "hěn", "teach_mn": "«很» нь утгаараа «их, маш» гэсэн үг боловч HSK1-ийн ихэнх өгүүлбэрт тэмдэг нэрийн өмнө орж зүгээр л дүрмийн холбоос үүрэг гүйцэтгэдэг тул орчуулгад заавал «их» гэж оноож болохгүй: 我很好 нь «Би их сайн» гэхээсээ илүү «Би сайн байна» гэсэн энгийн утгатай. Монгол хэлэнд тэмдэг нэрийг өгүүлэхүүн болгоход нэмэлт үг хэрэггүй бол хятад хэлэнд 很 заавал орно.", "usage_mn": ["Тэмдэг нэрийн өмнө орж «S + 很 + тэмдэг нэр» бүтэц үүсгэнэ", "Ихэнхдээ орчуулгад тусгайлан гарахгүй, зөвхөн 是-г орлох дүрмийн үүрэгтэй"], "examples": [{"zh": "我很好。", "pinyin": "Wǒ hěn hǎo.", "mn": "Би сайн байна."}, {"zh": "中国菜很好吃。", "pinyin": "Zhōngguó cài hěn hǎochī.", "mn": "Хятад хоол их амттай."}, {"zh": "我妈妈的汉语不好。", "pinyin": "Wǒ māma de Hànyǔ bù hǎo.", "mn": "Ээжийн минь хятад хэл сайн биш."}], "mistakes": [{"wrong": "中国菜是好吃。", "right": "中国菜很好吃。", "why_mn": "Тэмдэг нэрийн өмнө 是 биш 很 хэрэглэнэ — хятад хэлэнд тэмдэг нэр өөрөө өгүүлэхүүн болдог тул 是 хэрэггүй."}]}, {"zh": "好吃", "pinyin": "hǎochī", "teach_mn": "«好吃» нь 好 (сайн) ба 吃 (идэх) хоёр үгээс тогтсон, «амттай» гэсэн шинэ утгыг үүсгэсэн үг. Зөвхөн хоол, идэх зүйлд хэрэглэнэ — хүн, зүйлийн бусад чанарт хэрэглэдэггүй. Монгол хэлэнд «сайн» ба «амттай» тусдаа үг байдаг бол хятад хэлэнд 好 язгуураас олон ижил төрлийн үг үүсдэгийг энэ жишээгээр анзаар (好看 үзэсгэлэнтэй, 好喝 уухад амттай гэх мэт хожим сурна).", "usage_mn": ["Зөвхөн идэх хоол, зүйлийн амтыг тодорхойлоход хэрэглэнэ", "Өмнөө 很 авч байдал заана: 很好吃"], "examples": [{"zh": "中国菜好吃吗？", "pinyin": "Zhōngguó cài hǎochī ma?", "mn": "Хятад хоол амттай юу?"}, {"zh": "中国菜很好吃。", "pinyin": "Zhōngguó cài hěn hǎochī.", "mn": "Хятад хоол их амттай."}], "mistakes": [{"wrong": "我很好吃。", "right": "中国菜很好吃。", "why_mn": "好吃 зөвхөн хоолны амтыг зааж чадна, хүний талаар «би амттай» гэж хэлж болохгүй."}]}, {"zh": "做", "pinyin": "zuò", "teach_mn": "«做» нь «хийх, бэлтгэх» гэсэн өргөн хэрэглээтэй үйл үг — хоол хийх, ажил хийх зэрэг олон зүйлд хэрэглэнэ. HSK1-д ялангуяа 做菜 (хоол хийх) гэдэг холбоост түгээмэл тааралдана. Монгол хэлний «хийх» гэдэг үгтэй маш төстэй өргөн хэрэглээтэй.", "usage_mn": ["Хоол хийх, ажил хийх зэрэг үйл ажиллагаанд өргөнөөр хэрэглэнэ", "会-ийн ард орж «хийж чадна» гэсэн чадвар илэрхийлнэ"], "examples": [{"zh": "你会做中国菜吗？", "pinyin": "Nǐ huì zuò Zhōngguó cài ma?", "mn": "Чи хятад хоол хийж чадах уу?"}, {"zh": "我不会做。", "pinyin": "Wǒ bú huì zuò.", "mn": "Би хийж чадахгүй."}, {"zh": "我会做中国菜。", "pinyin": "Wǒ huì zuò Zhōngguó cài.", "mn": "Би хятад хоол хийж чадна."}], "mistakes": []}, {"zh": "写", "pinyin": "xiě", "teach_mn": "«写» нь «бичих» гэсэн үйл үг, ялангуяа ханз бичихэд хэрэглэнэ: 写汉字. 会-ийн ард орж «бичиж чадна» гэсэн шинэ чадвар заана. Уншихыг заасан 读-тэй ихэвчлэн зэрэгцүүлж харьцуулагддаг — нэг ханзыг уншиж чаддаг ч бичиж чаддаггүй байх нь элбэг.", "usage_mn": ["Ханз, үсэг бичихэд хэрэглэнэ: 写汉字, 写字", "读 (унших)-тай харьцуулж ялгаатай хэрэглэдгийг сана"], "examples": [{"zh": "你会写汉字吗？", "pinyin": "Nǐ huì xiě Hànzì ma?", "mn": "Чи ханз бичиж чадах уу?"}, {"zh": "我会写。", "pinyin": "Wǒ huì xiě.", "mn": "Би бичиж чадна."}, {"zh": "这个字怎么写？", "pinyin": "Zhège zì zěnme xiě?", "mn": "Энэ үсгийг яаж бичих вэ?"}, {"zh": "这个字我会读，不会写。", "pinyin": "Zhège zì wǒ huì dú, bú huì xiě.", "mn": "Энэ үсгийг би уншиж чадна, бичиж чадахгүй."}], "mistakes": []}, {"zh": "汉字", "pinyin": "Hànzì", "teach_mn": "«汉字» нь «ханз үсэг» — хятад хэлний бичгийн тэмдэгтийг нэрлэдэг үг. 汉 (хятад үндэстэн) ба 字 (үсэг) хоёр үгээс тогтсон. Латин үсэг, кирилл үсгээс огт өөр дүрст бичиг гэдгийг сануул — монгол хэлэнд бичиг үсэг гэдэг ерөнхий ойлголт байдаг бол 汉字 нь тодорхой хятад бичгийг л заана.", "usage_mn": ["Хятад бичгийн тэмдэгт бүхэлд нь нэрлэхэд хэрэглэнэ", "写 (бичих), 读 (унших) зэрэг үйл үгтэй хамт хэрэглэгддэг"], "examples": [{"zh": "你会写汉字吗？", "pinyin": "Nǐ huì xiě Hànzì ma?", "mn": "Чи ханз бичиж чадах уу?"}, {"zh": "我会写汉字。", "pinyin": "Wǒ huì xiě Hànzì.", "mn": "Би ханз бичиж чадна."}], "mistakes": [], "compare": [{"zh": "字", "pinyin": "zì", "mn": "үсэг, тэмдэгт", "diff_mn": "汉字 нь тодорхойлон «хятад» гэсэн утгыг агуулна, харин 字 нь ерөнхий утгаар ямар ч үсэг, тэмдэгтэд хэрэглэгдэнэ."}]}, {"zh": "字", "pinyin": "zì", "teach_mn": "«字» нь «үсэг, тэмдэгт» гэсэн ерөнхий үг, тодорхой нэг ханзыг зааж болно: 这个字 (энэ үсэг). 汉字-ийн товчилсон хэлбэр биш, харин илүү өргөн ойлголт — өөрийн нэр (名字)-нд ч энэ язгуур орсон байгааг ажигла.", "usage_mn": ["Тодорхой нэг ханзыг зааж хэрэглэнэ: 这个字", "名字 (нэр) гэх мэт бусад үгэнд язгуур болж ордог"], "examples": [{"zh": "这个字怎么写？", "pinyin": "Zhège zì zěnme xiě?", "mn": "Энэ үсгийг яаж бичих вэ?"}, {"zh": "这个字我会读。", "pinyin": "Zhège zì wǒ huì dú.", "mn": "Энэ үсгийг би уншиж чадна."}, {"zh": "这个字我会读，不会写。", "pinyin": "Zhège zì wǒ huì dú, bú huì xiě.", "mn": "Энэ үсгийг би уншиж чадна, бичиж чадахгүй."}], "mistakes": []}, {"zh": "怎么", "pinyin": "zěnme", "teach_mn": "«怎么» нь «яаж, хэрхэн» гэсэн асуух төлөөний үг, үйл үгийн ӨМНӨ ордог: 怎么 + үйл үг. Ямар нэг зүйлийг хэрхэн хийхийг асуухад хэрэглэнэ. Монгол хэлэнд «яаж» гэдэг үг өгүүлбэрийн эхэнд ч, дундуур ч орж болдог бол хятад хэлэнд 怎么 үргэлж үйл үгийнхээ өмнө байрлана.", "usage_mn": ["Арга, хэлбэрийг асуухад: 怎么 + үйл үг", "Асуух өгүүлбэрт 吗 нэмэлт хэрэггүй, 怎么 өөрөө асуултын утга илэрхийлнэ"], "examples": [{"zh": "这个字怎么写？", "pinyin": "Zhège zì zěnme xiě?", "mn": "Энэ үсгийг яаж бичих вэ?"}, {"zh": "这个字怎么读？", "pinyin": "Zhège zì zěnme dú?", "mn": "Энэ үсгийг яаж унших вэ?"}], "mistakes": [{"wrong": "这个字怎么写吗？", "right": "这个字怎么写？", "why_mn": "怎么 өөрөө асуултын утга агуулсан тул ард нь дахин 吗 нэмэхгүй."}]}, {"zh": "读", "pinyin": "dú", "teach_mn": "«读» нь «унших» гэсэн үйл үг, ном унших, ханз унших (авиагаар нь дуудах) гэсэн хоёр утгад хэрэглэгдэнэ. HSK1-д ихэвчлэн ханзыг «хэрхэн уншдаг вэ» гэдгийг асуухад тааралддаг: 怎么读. 写 (бичих)-тэй хослуулж ялгаатай чадварыг харьцуулна.", "usage_mn": ["Ханз, үг хэрхэн дуудагддагийг асуухад: 怎么读", "写 (бичих)-тэй эсрэгцүүлж хоёр өөр чадварыг тодорхойлно"], "examples": [{"zh": "这个字怎么读？", "pinyin": "Zhège zì zěnme dú?", "mn": "Энэ үсгийг яаж унших вэ?"}, {"zh": "这个字我会读。", "pinyin": "Zhège zì wǒ huì dú.", "mn": "Энэ үсгийг би уншиж чадна."}, {"zh": "这个字我会读，不会写。", "pinyin": "Zhège zì wǒ huì dú, bú huì xiě.", "mn": "Энэ үсгийг би уншиж чадна, бичиж чадахгүй."}], "mistakes": []}], "grammar": [{"point": "能愿动词 会 (1)", "gloss_mn": "сурч эзэмшсэн чадвар — 会 + үйл үг", "structure": "主语 + 会 + үйл үг (+ 宾语)", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "会 бол тусламж үйл үг — ганцаараа орж чадахгүй, үргэлж өөр үйл үгийн өмнө орж «тэр үйлийг хийж чадна» гэдгийг заана. Гагцхүү СУРЧ, дадлагажиж олж авсан чадварт л хэрэглэнэ.", "example": {"zh": "我会说汉语。", "pinyin": "Wǒ huì shuō Hànyǔ.", "mn": "Би хятадаар ярьж чадна."}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Өгүүлбэрийн дараалал: эзэн бие + 会 + үйл үг (+ юуг). Жишээ нь 我 (би) + 会 (чадна) + 写 (бичих) + 汉字 (ханз) = 我会写汉字.", "example": {"zh": "我 + 会 + 写 + 汉字", "pinyin": "wǒ + huì + xiě + Hànzì", "mn": "би + чадна + бичих + ханз"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Хэл ярих, хоол хийх, бичих зэрэг сурч олж авдаг чадварын талаар ярихад хэрэглэнэ. Асуухдаа өгүүлбэрийн төгсгөлд 吗 нэмнэ: 你会说汉语吗？", "example": {"zh": "你会说汉语吗？", "pinyin": "Nǐ huì shuō Hànyǔ ma?", "mn": "Чи хятадаар ярьж чадах уу?"}}, {"title_mn": "4. Үгүйсгэл", "body_mn": "Үгүйсгэхдээ 不-г 会-ийн ӨМНӨ тавина: 不会. 会-ийн ард биш, 会-ийн өмнө орно гэдгийг сайн сана.", "example": {"zh": "我不会做中国菜。", "pinyin": "Wǒ bú huì zuò Zhōngguó cài.", "mn": "Би хятад хоол хийж чадахгүй."}}], "examples": [{"zh": "我会说汉语。", "pinyin": "Wǒ huì shuō Hànyǔ.", "mn": "Би хятадаар ярьж чадна."}, {"zh": "你会说汉语吗？", "pinyin": "Nǐ huì shuō Hànyǔ ma?", "mn": "Чи хятадаар ярьж чадах уу?"}, {"zh": "你妈妈会说汉语吗？", "pinyin": "Nǐ māma huì shuō Hànyǔ ma?", "mn": "Ээж чинь хятадаар ярьдаг уу?"}, {"zh": "她不会说。", "pinyin": "Tā bú huì shuō.", "mn": "Тэр ярьж чадахгүй."}, {"zh": "我不会做中国菜。", "pinyin": "Wǒ bú huì zuò Zhōngguó cài.", "mn": "Би хятад хоол хийж чадахгүй."}, {"zh": "你会写汉字吗？", "pinyin": "Nǐ huì xiě Hànzì ma?", "mn": "Чи ханз бичиж чадах уу?"}, {"zh": "我会写。", "pinyin": "Wǒ huì xiě.", "mn": "Би бичиж чадна."}, {"zh": "这个字我会读，不会写。", "pinyin": "Zhège zì wǒ huì dú, bú huì xiě.", "mn": "Энэ үсгийг би уншиж чадна, бичиж чадахгүй."}], "mistakes": [{"wrong": "我会不说汉语。", "right": "我不会说汉语。", "why_mn": "不-г 会-ийн ӨМНӨ тавина, 会 ба үйл үгийн хооронд оруулахгүй."}, {"wrong": "我是会说汉语。", "right": "我会说汉语。", "why_mn": "会 өөрөө чадвар заадаг тул урд нь 是 нэмэхгүй."}], "drills": [{"type": "choice", "question": "Би хоол хийж чаддаггүй гэдгийг зөв бичсэн нь аль вэ?", "options": ["我不会做菜。", "我会不做菜。", "我做不会菜。"], "answer": "我不会做菜。", "why_mn": "不-г 会-ийн өмнө тавьж «不会» болгоно."}, {"type": "fill", "question": "你会说汉语___？（асуулт болгох）", "answer": "吗", "why_mn": "会-тэй асуулт хэлэхдээ өгүүлбэрийн төгсгөлд 吗 нэмнэ."}, {"type": "judge", "question": "会 нь төрөлхийн чадвар (жишээ нь нүдээрээ харах)-д хэрэглэгддэг.", "answer": "false", "why_mn": "会 зөвхөн СУРЧ олж авсан чадварт хэрэглэгддэг, төрөлхийн чадварт хэрэглэдэггүй."}, {"type": "choice", "question": "「你妈妈___说汉语吗？」гэдэг өгүүлбэрт юу дутуу вэ?", "options": ["会", "很", "吗"], "answer": "会", "why_mn": "«ярьж чадах уу» гэсэн чадвар асуухад 会 тусламж үйл үг заавал хэрэгтэй."}]}, {"point": "形容词谓语句", "gloss_mn": "тэмдэг нэр өгүүлэхүүн болох нь: S + 很 + тэмдэг нэр", "structure": "主语 + 很 + тэмдэг нэр", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "«А ямар вэ» гэдгийг хэлэхдээ (жишээ нь «сайн», «амттай») хятад хэлэнд 是 огт хэрэггүй, тэмдэг нэр өөрөө шууд өгүүлэхүүн болно.", "example": {"zh": "我很好。", "pinyin": "Wǒ hěn hǎo.", "mn": "Би сайн байна."}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Эзэн бие + 很 + тэмдэг нэр гэсэн энгийн дараалалтай. 很-г ихэнхдээ орчуулгад «их» гэж заавал гаргах шаардлагагүй, зөвхөн дүрмийн холбоос үүрэгтэй.", "example": {"zh": "中国菜 + 很 + 好吃", "pinyin": "Zhōngguó cài + hěn + hǎochī", "mn": "хятад хоол + (холбоос) + амттай"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Хоолны амт, хүний байдал, зүйлийн чанарыг тодорхойлоход өдөр тутам хэрэглэнэ: 中国菜很好吃, 我很好.", "example": {"zh": "中国菜很好吃。", "pinyin": "Zhōngguó cài hěn hǎochī.", "mn": "Хятад хоол их амттай."}}, {"title_mn": "4. Үгүйсгэл", "body_mn": "Үгүйсгэхдээ 很-г хасаад 不-г тэмдэг нэрийн өмнө тавина: S + 不 + тэмдэг нэр.", "example": {"zh": "我妈妈的汉语不好。", "pinyin": "Wǒ māma de Hànyǔ bù hǎo.", "mn": "Ээжийн минь хятад хэл сайн биш."}}], "examples": [{"zh": "我很好。", "pinyin": "Wǒ hěn hǎo.", "mn": "Би сайн байна."}, {"zh": "中国菜很好吃。", "pinyin": "Zhōngguó cài hěn hǎochī.", "mn": "Хятад хоол их амттай."}, {"zh": "我妈妈的汉语不好。", "pinyin": "Wǒ māma de Hànyǔ bù hǎo.", "mn": "Ээжийн минь хятад хэл сайн биш."}, {"zh": "中国菜好吃吗？", "pinyin": "Zhōngguó cài hǎochī ma?", "mn": "Хятад хоол амттай юу?"}, {"zh": "你好！", "pinyin": "Nǐ hǎo!", "mn": "Сайн уу!"}, {"zh": "您好！", "pinyin": "Nín hǎo!", "mn": "Та сайн байна уу!"}], "mistakes": [{"wrong": "中国菜是好吃。", "right": "中国菜很好吃。", "why_mn": "Тэмдэг нэрийн өмнө 是 биш 很 хэрэглэнэ."}, {"wrong": "我很好吗？", "right": "你好吗？", "why_mn": "Асуухдаа өөрийгөө биш нөгөө хүнийг заана — «чи сайн уу» гэхдээ 你 хэрэглэнэ, 我 биш."}], "drills": [{"type": "choice", "question": "«Хятад хоол амттай» гэдгийг зөв бичсэн нь аль вэ?", "options": ["中国菜是好吃。", "中国菜很好吃。", "中国菜好吃是。"], "answer": "中国菜很好吃。", "why_mn": "Тэмдэг нэрийн өмнө 是 биш 很 орно."}, {"type": "judge", "question": "很 нь энэ бүтэцэд үргэлж «маш их» гэсэн онцгой чанга утгатай.", "answer": "false", "why_mn": "Ихэнх тохиолдолд 很 зөвхөн дүрмийн холбоос, тусгайлан «их» гэж орчуулах албагүй."}, {"type": "fill", "question": "我妈妈的汉语___好。（үгүйсгэ）", "answer": "不", "why_mn": "Тэмдэг нэрийг үгүйсгэхдээ 很-г хасаад 不 тавина."}, {"type": "choice", "question": "「你好吗？」гэдэг асуултад тохирох хариу аль нь вэ?", "options": ["我很好。", "我是好。", "我好很。"], "answer": "我很好。", "why_mn": "Стандарт хариу нь S + 很 + тэмдэг нэр бүтэцтэй байна."}]}, {"point": "疑问代词 怎么 (1)", "gloss_mn": "怎么 + үйл үг — «яаж?»", "structure": "怎么 + үйл үг", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "怎么 нь «яаж, хэрхэн» гэсэн асуух үг, ямар нэг үйлдлийг хэрхэн хийдгийг асуухад хэрэглэнэ.", "example": {"zh": "怎么", "pinyin": "zěnme", "mn": "яаж"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "怎么 үргэлж асуух гэж буй үйл үгийнхээ ӨМНӨ ордог: 怎么 + 写/读/说.", "example": {"zh": "这个字怎么写？", "pinyin": "Zhège zì zěnme xiě?", "mn": "Энэ үсгийг яаж бичих вэ?"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Ханз хэрхэн бичигддэг, унших вэ гэдгийг асуухад HSK1-д хамгийн түгээмэл хэрэглэгддэг: 怎么写, 怎么读.", "example": {"zh": "这个字怎么读？", "pinyin": "Zhège zì zěnme dú?", "mn": "Энэ үсгийг яаж унших вэ?"}}, {"title_mn": "4. Ялгаа", "body_mn": "怎么 нь өөрөө асуултын утгыг агуулдаг тул ард нь 吗 дахин нэмэхгүй — монгол хэлэнд «яаж бичих вэ» гэдэгт «үү» нэмээд асуудаггүйтэй адил зарчим.", "example": {"zh": "这个字怎么写？（吗 хэрэггүй）", "pinyin": "Zhège zì zěnme xiě?", "mn": "Энэ үсгийг яаж бичих вэ?"}}], "examples": [{"zh": "这个字怎么读？", "pinyin": "Zhège zì zěnme dú?", "mn": "Энэ үсгийг яаж унших вэ?"}, {"zh": "这个字怎么写？", "pinyin": "Zhège zì zěnme xiě?", "mn": "Энэ үсгийг яаж бичих вэ?"}, {"zh": "你的名字怎么写？", "pinyin": "Nǐ de míngzi zěnme xiě?", "mn": "Чиний нэрийг яаж бичдэг вэ?"}, {"zh": "你叫什么名字？", "pinyin": "Nǐ jiào shénme míngzi?", "mn": "Таны нэрийг хэн гэдэг вэ?"}, {"zh": "这个字我会读。", "pinyin": "Zhège zì wǒ huì dú.", "mn": "Энэ үсгийг би уншиж чадна."}], "mistakes": [{"wrong": "这个字怎么写吗？", "right": "这个字怎么写？", "why_mn": "怎么 өөрөө асуултын утгатай тул ард нь дахин 吗 нэмэхгүй."}, {"wrong": "怎么这个字写？", "right": "这个字怎么写？", "why_mn": "怎么 үйл үгийн шууд өмнө ордог, өгүүлбэрийн эхэнд биш."}], "drills": [{"type": "fill", "question": "这个字___写？", "answer": "怎么", "why_mn": "«Яаж бичих вэ» гэдгийг 怎么 + үйл үг гэсэн бүтцээр хэлнэ."}, {"type": "judge", "question": "怎么-гийн ард дахин 吗 нэмж болно.", "answer": "false", "why_mn": "怎么 өөрөө асуултын утгатай тул 吗 хэрэггүй."}, {"type": "choice", "question": "「这个字___读？」гэдэгт тохирох үг аль нь вэ?", "options": ["什么", "怎么", "谁"], "answer": "怎么", "why_mn": "«Яаж унших вэ» гэдэгт арга хэлбэр асуудаг 怎么 тохирно."}, {"type": "choice", "question": "怎么 хаана ордог вэ?", "options": ["Үйл үгийн өмнө", "Үйл үгийн ард", "Өгүүлбэрийн төгсгөлд"], "answer": "Үйл үгийн өмнө", "why_mn": "怎么 үргэлж асуух гэж буй үйл үгийнхээ шууд өмнө ордог."}]}, {"point": "汉字笔画 (6) — 撇折 ㇜ · 斜钩 ㇂ · 提 ㇀", "gloss_mn": "сүүлийн гурван үндсэн зурлага", "structure": "㇜ piězhé · ㇂ xiégōu · ㇀ tí", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "Өмнөх хичээлүүдэд 一 丨 丿 丶 ㇏ гэсэн таван энгийн зурлагыг сурсан. Энэ хичээлд гурван нийлмэл зурлагыг нэмж танина: ㇜ (налуу-эргэлт), ㇂ (ташуу дэгээ), ㇀ (өргөлт).", "example": {"zh": "㇜ ㇂ ㇀", "pinyin": "piězhé xiégōu tí", "mn": "гурван шинэ зурлага"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "撇折 ㇜ нь 么, 东 зэрэг ханзанд тохиолдоно; 斜钩 ㇂ нь 我, 钱 зэрэгт байдаг урт дэгээтэй налуу зурлага; 提 ㇀ нь 我, 打 зэрэгт байдаг доороос дээш өргөх богино зурлага.", "example": {"zh": "东 我", "pinyin": "dōng wǒ", "mn": "㇜ ба ㇂/㇀ зурлагатай жишээ"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Эдгээр зурлагыг мэдэрсэнээр 我 гэх мэт олонтаа хэрэглэдэг ханзыг зөв дараалал, чиглэлээр бичиж сурна.", "example": {"zh": "我", "pinyin": "wǒ", "mn": "би — ㇂ ба ㇀ зурлагатай"}}, {"title_mn": "4. Өргөтгөл", "body_mn": "Эдгээрийг сурснаар ханз бичихэд хэрэглэгддэг бүх үндсэн зурлагатай танилцаж дуусна — цаашид ханз бүрийг эдгээр зурлагын хослол гэж харж сур.", "example": {"zh": "一 丨 丿 丶 ㇏ ㇜ ㇂ ㇀", "pinyin": "8 үндсэн зурлага", "mn": "одоо бүх үндсэн зурлагатай танилцлаа"}}], "examples": [{"zh": "东", "pinyin": "dōng", "mn": "зүүн (㇜ зурлагатай)"}, {"zh": "我", "pinyin": "wǒ", "mn": "би (㇂ ба ㇀ зурлагатай)"}, {"zh": "西", "pinyin": "xī", "mn": "баруун"}, {"zh": "一 · 二 · 三", "pinyin": "yī · èr · sān", "mn": "энгийн зурлагат жишээ"}, {"zh": "你 · 好", "pinyin": "nǐ · hǎo", "mn": "өмнөх хичээлээс мэддэг ханзууд"}], "mistakes": [{"wrong": "我-г 丶 (цэг)-ээр төгсгөх", "right": "我-г ㇀ (өргөлт)-өөр төгсгөх", "why_mn": "我-ийн сүүлчийн зурлага цэг биш, доороос дээш өргөсөн 提 зурлага."}], "drills": [{"type": "choice", "question": "我 ямар онцлог зурлагуудтай вэ?", "options": ["㇜ ба ㇏", "㇂ ба ㇀", "丿 ба 丶"], "answer": "㇂ ба ㇀", "why_mn": "我-ийн баруун доод хэсэгт ташуу дэгээ ㇂, төгсгөлд нь өргөлт ㇀ орно."}, {"type": "judge", "question": "撇折 ㇜ нь налуу зурлага дундаа эргэдэг нэгдмэл зурлага.", "answer": "true", "why_mn": "撇折 нь 丿 (налуу)-гаас эхлээд чиглэлээ эргүүлдэг нэг татлагат зурлага."}, {"type": "fill", "question": "我-ийн сүүлчийн зурлагын нэрийг бич.", "answer": "提 (tí)", "why_mn": "我 нь доороос дээш өргөх 提 зурлагаар төгсдөг."}, {"type": "choice", "question": "Одоогоор нийт хэдэн үндсэн зурлага сурсан бэ?", "options": ["5", "6", "8"], "answer": "8", "why_mn": "Өмнөх 5 (一丨丿丶㇏) дээр энэ хичээлийн 3-ыг (㇜㇂㇀) нэмбэл 8 болно."}]}, {"point": "汉字结构 (1) — 独体字 ба 合体字", "gloss_mn": "дан бүтэц ба нийлмэл бүтэц", "structure": "独体字 (нэг бүхэл дүрс) vs 合体字 (хэсгүүдээс бүтсэн)", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "独体字 (дан бүтэцт ханз) нь өөр жижиг ханз, хэсэгт хуваагддаггүй, өөрөө нэг бүхэл дүрс: 人, 我, 中. 合体字 (нийлмэл бүтэцтэй ханз) нь хоёр ба түүнээс олон хэсгээс бүтдэг: 你, 做.", "example": {"zh": "人 我 中", "pinyin": "rén wǒ zhōng", "mn": "дан бүтэцтэй жишээ"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "你 гэдэг ханзыг задлавал 亻(хүн) + 尔 гэсэн хоёр хэсэгтэй, харин 我-г ямар ч жижиг ханзад задалж болохгүй, зөвхөн зурлагуудаас шууд тогтоно.", "example": {"zh": "你 = 亻 + 尔", "pinyin": "nǐ", "mn": "хоёр хэсгээс бүтсэн (合体字)"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Ханз шинээр сурахдаа эхлээд «энэ дан бүтэцтэй юу, эсвэл хэсгүүдээс тогтсон уу» гэдгийг тогтоовол цээжлэхэд илүү хялбар болно — нийлмэл ханзны хэсэг бүр ихэвчлэн утга эсвэл дуудлагатай холбоотой байдаг.", "example": {"zh": "做", "pinyin": "zuò", "mn": "合体字 — хэсгүүдийн нэг нь утга, нэг нь дуудлага заана"}}, {"title_mn": "4. Ялгаа", "body_mn": "Монгол бичигт үсэг бүр адилхан зарчмаар зэрэгцдэг бол хятад ханзанд зарим нь бүхэлдээ нэг дүрс (独体字), зарим нь хэд хэдэн утга/дуудлага заасан хэсгээс (合体字) тогтдог гэдгийг сана.", "example": {"zh": "我 vs 你", "pinyin": "wǒ vs nǐ", "mn": "独体字 vs 合体字"}}], "examples": [{"zh": "人 · 我 · 中", "pinyin": "rén · wǒ · zhōng", "mn": "дан бүтэцтэй (独体字)"}, {"zh": "你 · 做", "pinyin": "nǐ · zuò", "mn": "нийлмэл бүтэцтэй (合体字)"}, {"zh": "一 · 二 · 三", "pinyin": "yī · èr · sān", "mn": "дан бүтэцтэй энгийн тоо"}, {"zh": "十", "pinyin": "shí", "mn": "дан бүтэцтэй"}, {"zh": "好", "pinyin": "hǎo", "mn": "合体字 — 女 + 子"}], "mistakes": [{"wrong": "我-г хэсэгт задалж утгыг нь тайлбарлах", "right": "我-г бүхэлд нь дан дүрс гэж үзэх", "why_mn": "我 独体字 тул хэсэгт задлан утга тайлбарлах гэж оролдох нь буруу арга — бүхэлд нь цээжил."}], "drills": [{"type": "choice", "question": "我 ямар бүтэцтэй ханз вэ?", "options": ["独体字 (дан)", "合体字 (нийлмэл)", "хоёулаа"], "answer": "独体字 (дан)", "why_mn": "我-г жижиг ханзад задалж болохгүй, зөвхөн зурлагуудаас шууд тогтдог тул дан бүтэцтэй."}, {"type": "choice", "question": "你 ямар бүтэцтэй ханз вэ?", "options": ["独体字 (дан)", "合体字 (нийлмэл)", "аль нь ч биш"], "answer": "合体字 (нийлмэл)", "why_mn": "你 нь 亻 ба 尔 гэсэн хоёр хэсгээс тогтдог тул нийлмэл бүтэцтэй."}, {"type": "judge", "question": "独体字-г цаашид жижиг утгатай ханзад задалж болно.", "answer": "false", "why_mn": "独体字 бол өөрөө бүхэл дүрс, цаашид ханз хэлбэрээр задардаггүй."}, {"type": "fill", "question": "人, 我, 中 — эдгээрийг нэг үгээр нэрлэ.", "answer": "独体字", "why_mn": "Эдгээр гурав бүгд задардаггүй, дан бүтэцтэй ханз."}]}], "hanzi": [{"hanzi": "东", "pinyin": "dōng", "meaning_mn": "зүүн", "story_mn": "东-ийн уламжлалт хэлбэр 東 нь мод (木)-ны цаана нар (日) мандаж буй дүрс байсан гэж үздэг — нар мандах зүг тул «зүүн». Хялбаршуулсан 东 хэлбэрт энэ хуучин дүрс шууд харагдахгүй болсон тул зурлагуудаас нь шууд бүхэлд нь дан дүрс болгон цээжил.", "stroke_count": 5, "stroke_tips_mn": ["Эхлээд дээд хэвтээ зурлагыг зүүнээс баруун тийш тат", "Дараа нь налуу-эргэлт ㇜ зурлагыг тат", "Дунд босоо дэгээг нэмээд, эцэст нь зүүн налуу, цэгийг тат"], "words": [{"zh": "东西", "pinyin": "dōngxi", "mn": "юм, зүйл"}, {"zh": "东边", "pinyin": "dōngbian", "mn": "зүүн тал"}]}, {"hanzi": "我", "pinyin": "wǒ", "meaning_mn": "би", "story_mn": "我-ийн эртний хэлбэр нь олон иртэй, эрч зэвсэг маягийн дүрс байсан гэж үздэг. Хожим анхны утгаа алдаж, авиа зээлдэж «би» гэсэн төлөөний үг болсон — олон ханзны түүхэнд ийм «зээлдэлт» түгээмэл тохиолддог.", "stroke_count": 7, "stroke_tips_mn": ["Зүүн талын налуу зурлагуудыг эхэлж тат", "Дараа нь дунд хэвтээ, босоо зурлагуудыг тат", "Баруун доод ташуу дэгээ ㇂-г татаад, эцэст нь өргөлт ㇀-г нэмнэ"], "confusable": [{"zh": "找", "pinyin": "zhǎo", "mn": "хайх", "diff_mn": "我 ба 找 хоёул баруун талдаа ижил төстэй ташуу дэгээтэй хэсэгтэй ч 找-д зүүн талд нь гар (扌) радикал орсноороо ялгаатай."}], "words": [{"zh": "我们", "pinyin": "wǒmen", "mn": "бид"}, {"zh": "我的", "pinyin": "wǒ de", "mn": "миний"}]}, {"hanzi": "西", "pinyin": "xī", "meaning_mn": "баруун", "story_mn": "西-ийн эртний хэлбэр шувуу орой болоход үүрэндээ ор дэвссэн дүрс байсан гэж үздэг — нар жаргаж, шувуу үүрэндээ буцах цаг тул «баруун» гэсэн утгатай холбогдсон.", "stroke_count": 6, "stroke_tips_mn": ["Дээд хэвтээ зурлагыг зүүнээс баруун тийш тат", "Зүүн ба баруун талын босоо зурлагуудыг дараалуулан тат", "Дотор талын налуу зурлага, доод хэвтээ зурлагыг эцэст нь тат"], "confusable": [{"zh": "酉", "pinyin": "yǒu", "mn": "(тоо тэмдэглэдэг эртний ханз)", "diff_mn": "西 ба 酉 дүрсээрээ маш төстэй ч 酉-д дотор нь нэмэлт хэвтээ зураас байдгаараа ялгаатай."}], "words": [{"zh": "西边", "pinyin": "xībian", "mn": "баруун тал"}, {"zh": "东西", "pinyin": "dōngxi", "mn": "юм, зүйл (эсрэг чиглэлийн хоёр ханзнаас тогтсон холбоо үг)"}]}], "pronunciation": {"focus_mn": "Энэ хичээлд 1-р хөгөөр эхэлсэн хоёр үет үгсийн хөгийн хослолыг сайтар сонсож дадлагажина. Ялангуяа хослол доторх 3-р хөг бүрэн ∨ биш, намхан «211» маягаар дуудагддагийг анхаараарай.", "drills": [{"title_mn": "Хослол: 1-р хөг + 1/2-р хөг", "instruction_mn": "Хосыг дараалан чангаар хэлж, эхний үений өндөр тэгш хөгийг тогтвортой бариарай.", "pairs": [{"a": {"zh": "今天", "pinyin": "jīntiān", "mn": "өнөөдөр"}, "b": {"zh": "公司", "pinyin": "gōngsī", "mn": "компани"}, "note_mn": "Хоёул 1-р хөг + 1-р хөг — хоёр үеийг ижил өндөрт тэгш барь."}, {"a": {"zh": "咖啡", "pinyin": "kāfēi", "mn": "кофе"}, "b": {"zh": "今年", "pinyin": "jīnnián", "mn": "энэ жил"}, "note_mn": "1-р хөг + 1-р хөг ба 1-р хөг + 2-р хөг-ийн ялгааг чихээрээ мэдэр."}, {"a": {"zh": "公园", "pinyin": "gōngyuán", "mn": "цэцэрлэгт хүрээлэн"}, "b": {"zh": "欢迎", "pinyin": "huānyíng", "mn": "тавтай морил"}, "note_mn": "Хоёул 1+2 хослол — эхний үе тэгш, хоёр дахь нь дээшилнэ."}]}, {"title_mn": "Хослол: 1-р хөг + 3-р хөг (намхан 211)", "instruction_mn": "Хоёр дахь үеийг бүрэн ∨ болгохгүй, намхан барьж дадлагажаарай.", "pairs": [{"a": {"zh": "经理", "pinyin": "jīnglǐ", "mn": "менежер"}, "b": {"zh": "操场", "pinyin": "cāochǎng", "mn": "талбай"}, "note_mn": "Хоёул 3-р хөгийг намхан 211 маягаар дуудна, бүрэн 214 болгож эргүүлэхгүй."}, {"a": {"zh": "机场", "pinyin": "jīchǎng", "mn": "нисэх буудал"}, "b": {"zh": "经理", "pinyin": "jīnglǐ", "mn": "менежер"}, "note_mn": "chǎng ба lǐ хоёулаа намхан, богино дуудагдана."}]}, {"title_mn": "Хослол: 1-р хөг + 4-р хөг", "instruction_mn": "Хоёр дахь үеийг өндрөөс огцом буулгаж дадлагажаарай.", "pairs": [{"a": {"zh": "车票", "pinyin": "chēpiào", "mn": "тасалбар"}, "b": {"zh": "鸡蛋", "pinyin": "jīdàn", "mn": "өндөг"}, "note_mn": "Хоёул 1+4 хослол — эхний үе тэгш, хоёр дахь нь огцом буунана."}, {"a": {"zh": "高兴", "pinyin": "gāoxìng", "mn": "баяртай"}, "b": {"zh": "车站", "pinyin": "chēzhàn", "mn": "буудал"}, "note_mn": "xìng ба zhàn хоёулаа өндрөөс шулуухан унана."}, {"a": {"zh": "今天", "pinyin": "jīntiān", "mn": "өнөөдөр"}, "b": {"zh": "高兴", "pinyin": "gāoxìng", "mn": "баяртай"}, "note_mn": "1+1 ба 1+4 хослолын ялгааг зэрэгцүүлж давт."}]}], "tips_mn": ["Хослол доторх 3-р хөгийг бүрэн буугаад эргэж дээшлүүлэхгүй, зөвхөн намхан барь — энэ нь «211» дүрэм.", "1-р хөг үргэлж тэгш, өндөр байх ёстой — хоёр дахь үе өөрчлөгдсөн ч эхний үеэ бүү сулруул.", "会, 说, 写, 读 гэх мэт шинэ үйл үгсийг өдөр бүр чангаар хэлж, зөв аялгыг булчиндаа сургаарай."]}}'::jsonb)
