       payload = excluded.payload;

insert into public.lesson_deep_teaching (lesson_id, version, payload)
values ('hsk1-l07', 1, '{"words": [{"zh": "请", "pinyin": "qǐng", "teach_mn": "«请» нь хүндэтгэлтэй хандах, эсвэл хэн нэгнийг ямар нэг зүйл хийхийг эелдгээр урихад хэрэглэдэг үг. «请问» (уучлаарай, асууя) гэдэг хослолоор HSK1-д хамгийн түгээмэл тааралддаг — танихгүй хүнээс юм асуухын өмнө эелдгээр хандах гарц үг. Монгол хэлэнд «уучлаарай», «...ханд» гэсэн олон янзын үгээр илэрхийлдэг эелдэг байдлыг хятад хэлэнд 请 нэг үгээр өгдөг.", "usage_mn": ["问-ийн өмнө орж 请问 (уучлаарай, асууя) гэсэн эелдэг хандлага үүсгэнэ", "Танихгүй хүнээс зүйл асуух, хүсэх өгүүлбэрийн эхэнд байрлана"], "examples": [{"zh": "请问，今天几号？", "pinyin": "Qǐngwèn, jīntiān jǐ hào?", "mn": "Уучлаарай, өнөөдөр хэдний өдөр вэ?"}, {"zh": "请问，你叫什么名字？", "pinyin": "Qǐngwèn, nǐ jiào shénme míngzi?", "mn": "Уучлаарай, таны нэрийг хэн гэдэг вэ?"}, {"zh": "请问，你是老师吗？", "pinyin": "Qǐngwèn, nǐ shì lǎoshī ma?", "mn": "Уучлаарай, та багш мөн үү?"}], "mistakes": [{"wrong": "问请，今天几号？", "right": "请问，今天几号？", "why_mn": "请 ба 问-ийн дараалал тогтмол, 请 үргэлж 问-ийн өмнө ордог."}]}, {"zh": "问", "pinyin": "wèn", "teach_mn": "«问» нь «асуух» гэсэн энгийн үйл үг. Ганцаараа ч, 请-ийн ард орж 请问 (уучлаарай, асууя) гэсэн тогтсон эелдэг хэллэг болж ч хэрэглэгддэг. Монгол хэлэнд «асуух» гэдэг үгтэй адилхан утгатай.", "usage_mn": ["请-ийн ард орж эелдэг асуулт эхлүүлэхэд хэрэглэнэ: 请问", "Ганцаараа ч «асуух» гэсэн энгийн үйл үг болж хэрэглэгдэнэ"], "examples": [{"zh": "请问。", "pinyin": "Qǐngwèn.", "mn": "Асууя (уучлаарай)."}, {"zh": "请问，今天几号？", "pinyin": "Qǐngwèn, jīntiān jǐ hào?", "mn": "Уучлаарай, өнөөдөр хэдний өдөр вэ?"}], "mistakes": []}, {"zh": "今天", "pinyin": "jīntiān", "teach_mn": "«今天» нь «өнөөдөр» гэсэн цагийн үг, өгүүлбэрийн эхэнд буюу эзэн биеийн дараа орж болно. 昨天 (өчигдөр), 明天 (маргааш)-тай хамт гурвуулаа адил бүтэцтэй: цаг заасан үг + 天 (өдөр). Монгол хэлэнд ч «өнөө», «өчиг», «margаа» гэсэн язгуураар гурван цагийг ялгадагтай төстэй логиктой.", "usage_mn": ["Огноо, гараг хэлэхийн өмнө байрлана: 今天几号, 今天星期几", "昨天, 明天-тай хамт гурвыг зэрэгцүүлж цээжлэхэд хялбар"], "examples": [{"zh": "今天几号？", "pinyin": "Jīntiān jǐ hào?", "mn": "Өнөөдөр хэдний өдөр вэ?"}, {"zh": "今天9月1号。", "pinyin": "Jīntiān jiǔ yuè yī hào.", "mn": "Өнөөдөр 9 сарын 1."}, {"zh": "今天星期几？", "pinyin": "Jīntiān xīngqī jǐ?", "mn": "Өнөөдөр ямар гараг вэ?"}, {"zh": "今天星期三。", "pinyin": "Jīntiān xīngqī sān.", "mn": "Өнөөдөр Лхагва гараг."}], "mistakes": [{"wrong": "今天是几号？（алдаа биш ч)", "right": "今天几号？", "why_mn": "Огноо асуухад 是 орхигдож болно, гэхдээ оруулах нь ч буруу биш — HSK1-д 是-гүй энгийн хэлбэрийг түлхүү сурна."}], "compare": [{"zh": "昨天", "pinyin": "zuótiān", "mn": "өчигдөр", "diff_mn": "今天 нь өнөөдрийг, 昨天 нь өчигдрийг заана — хоёулаа ижил 天 язгууртай."}, {"zh": "明天", "pinyin": "míngtiān", "mn": "маргааш", "diff_mn": "今天 нь өнөөдрийг, 明天 нь маргаашийг заана."}]}, {"zh": "号", "pinyin": "hào", "teach_mn": "«号» нь сарын аль өдөр болохыг заахад хэрэглэдэг үг — «...ний өдөр» гэж орчуулж болно. Тоо ба 号-г хамт хэлж огноо үүсгэнэ: 1号, 9月1号. Ярианд 号 хэрэглэдэг бол албан бичигт үүний оронд 日 хэрэглэдэг гэдгийг сана. Монгол хэлэнд «сарын нэгэн» гэхэд «-н» нөхцөл залгадаг бол хятад хэлэнд 号 тусдаа үг байдгаараа ялгаатай.", "usage_mn": ["Тооны ард орж сарын өдрийг заана: 1号, 2号...31号", "Ярианд 号, албан бичигт 日 хэрэглэдэг — хоёул нэг утгатай"], "examples": [{"zh": "今天几号？", "pinyin": "Jīntiān jǐ hào?", "mn": "Өнөөдөр хэдний өдөр вэ?"}, {"zh": "今天9月1号。", "pinyin": "Jīntiān jiǔ yuè yī hào.", "mn": "Өнөөдөр 9 сарын 1."}, {"zh": "昨天是8月31号。", "pinyin": "Zuótiān shì bā yuè sānshíyī hào.", "mn": "Өчигдөр 8 сарын 31 байсан."}, {"zh": "明天是9月2号。", "pinyin": "Míngtiān shì jiǔ yuè èr hào.", "mn": "Маргааш 9 сарын 2."}], "mistakes": [{"wrong": "9号月", "right": "9月1号", "why_mn": "Огноог хэлэхдээ эхлээд сар (月), дараа нь өдөр (号) гэж томоос жижиг рүү хэлнэ."}], "compare": [{"zh": "日", "pinyin": "rì", "mn": "өдөр (огноонд, бичгийн хэлбэр)", "diff_mn": "号 ярианд, 日 албан бичигт хэрэглэгддэг ижил утгатай хос үг."}]}, {"zh": "月", "pinyin": "yuè", "teach_mn": "«月» нь «сар» гэсэн үг, тооны ард орж он жилийн сарыг заана: 9月 (9-р сар). Мөн «сар» гэдэг тэнгэрийн биетийг ч заадаг эртний утгатай. Монгол хэлэнд «9-р сар» гэхэд дараалал ижил — тоо эхэлж, дараа нь «сар» гэдэг үг ордог тул амархан цээжлэгдэнэ.", "usage_mn": ["Тооны ард орж сарын нэрийг үүсгэнэ: 1月...12月", "Огноонд эхэлж сар, дараа нь өдөр (号) орно"], "examples": [{"zh": "今天9月1号。", "pinyin": "Jīntiān jiǔ yuè yī hào.", "mn": "Өнөөдөр 9 сарын 1."}, {"zh": "昨天是8月31号。", "pinyin": "Zuótiān shì bā yuè sānshíyī hào.", "mn": "Өчигдөр 8 сарын 31 байсан."}, {"zh": "明天是9月2号。", "pinyin": "Míngtiān shì jiǔ yuè èr hào.", "mn": "Маргааш 9 сарын 2."}], "mistakes": []}, {"zh": "星期", "pinyin": "xīngqī", "teach_mn": "«星期» нь «долоо хоног» гэсэн ерөнхий утгатай ба ард нь тоо авч тухайн гарагийг заана: 星期一 (Даваа) — 星期六 (Бямба). Ням гараг онцгой, тоогүй 星期日 эсвэл 星期天 гэж хэлдэг. Монгол хэлэнд гарагийн нэрс тус бүр өөр үгтэй (Даваа, Мягмар...) бол хятад хэлэнд 星期 + тоогоор системтэй байгуулагддаг нь том ялгаа.", "usage_mn": ["Тооны өмнө орж гарагийг заана: 星期 + 1–6", "Ням гарагт тоо биш 日/天 хэрэглэнэ: 星期日/星期天"], "examples": [{"zh": "今天星期几？", "pinyin": "Jīntiān xīngqī jǐ?", "mn": "Өнөөдөр ямар гараг вэ?"}, {"zh": "星期三。", "pinyin": "Xīngqī sān.", "mn": "Лхагва гараг."}, {"zh": "明天星期六，你去学校吗？", "pinyin": "Míngtiān xīngqī liù, nǐ qù xuéxiào ma?", "mn": "Маргааш бямба гараг, чи сургуульдаа явах уу?"}, {"zh": "明天是9月2号，星期四。", "pinyin": "Míngtiān shì jiǔ yuè èr hào, xīngqī sì.", "mn": "Маргааш 9 сарын 2, пүрэв гараг."}], "mistakes": [{"wrong": "星期七", "right": "星期日 / 星期天", "why_mn": "Ням гарагт 星期七 гэж тоо хэрэглэдэггүй, зөвхөн 星期日 эсвэл 星期天 гэнэ."}]}, {"zh": "昨天", "pinyin": "zuótiān", "teach_mn": "«昨天» нь «өчигдөр» гэсэн цагийн үг. 今天 (өнөөдөр), 明天 (маргааш)-тай хамт гурвуулаа адил 天 язгууртай тул хамтад нь давтаж цээжлэхэд амархан. Хятад хэлэнд эдгээр гурван үгийн аль нэгийг сонговол дараагийн үйл үгийн цагийг дахин тэмдэглэх шаардлагагүй.", "usage_mn": ["Өнгөрсөн өдрийн тухай ярихдаа өгүүлбэрийн эхэнд байрлуулна", "今天, 明天-тай зэрэгцүүлж гурвыг нэг бүлгээр цээжил"], "examples": [{"zh": "昨天是8月31号。", "pinyin": "Zuótiān shì bā yuè sānshíyī hào.", "mn": "Өчигдөр 8 сарын 31 байсан."}, {"zh": "昨天是几月几号？", "pinyin": "Zuótiān shì jǐ yuè jǐ hào?", "mn": "Өчигдөр хэдэн сарын хэдэн байсан бэ?"}, {"zh": "昨天是8月31号，星期二。", "pinyin": "Zuótiān shì bā yuè sānshíyī hào, xīngqī èr.", "mn": "Өчигдөр 8 сарын 31, мягмар гараг байсан."}], "mistakes": []}, {"zh": "明天", "pinyin": "míngtiān", "teach_mn": "«明天» нь «маргааш» гэсэн цагийн үг. Ирээдүйн тухай ярихад хэрэглэнэ, 是-г орхиж болно: 明天星期三. 昨天, 今天-тай хамт «天» язгуурт гурвыг нэгэн зэрэг санаж болно.", "usage_mn": ["Ирэх өдрийн тухай ярихдаа өгүүлбэрийн эхэнд байрлуулна", "Гараг, огноотой хамт орж 是-г орхидог"], "examples": [{"zh": "明天呢？", "pinyin": "Míngtiān ne?", "mn": "Харин маргааш?"}, {"zh": "明天是9月2号，星期四。", "pinyin": "Míngtiān shì jiǔ yuè èr hào, xīngqī sì.", "mn": "Маргааш 9 сарын 2, пүрэв гараг."}, {"zh": "明天星期六，你去学校吗？", "pinyin": "Míngtiān xīngqī liù, nǐ qù xuéxiào ma?", "mn": "Маргааш бямба гараг, чи сургуульдаа явах уу?"}], "mistakes": [{"wrong": "明天不星期六。", "right": "明天不是星期六。", "why_mn": "明天星期六 гэдэгт 是 орхигдож болдог ч ҮГҮЙСГЭХЭД 是 заавал буцаж орно."}]}, {"zh": "去", "pinyin": "qù", "teach_mn": "«去» нь «явах, очих» гэсэн үйл үг, ард нь газрын нэр авч хаашаа явж байгааг заана: 去学校 (сургуульд явах). Мөн хоёр дахь үйл үгтэй хамт орж «очоод юу хийхээ» илэрхийлж болно: 去学校看书. Монгол хэлэнд «сургуульд явах» гэхэд газрын нэрэнд чиг заасан нөхцөл (-д, руу) залгадаг бол хятад хэлэнд 去-ийн ард шууд газрын нэрийг залгана, угтвар үг хэрэггүй.", "usage_mn": ["Ард нь газрын нэр авна: 去 + газар", "Хоёр дахь үйл үгтэй хослож зорилгыг илэрхийлнэ: 去 + газар + үйл"], "examples": [{"zh": "我去学校。", "pinyin": "Wǒ qù xuéxiào.", "mn": "Би сургууль руу явна."}, {"zh": "你去学校吗？", "pinyin": "Nǐ qù xuéxiào ma?", "mn": "Чи сургуульдаа явах уу?"}, {"zh": "你去学校做什么？", "pinyin": "Nǐ qù xuéxiào zuò shénme?", "mn": "Чи сургуульд юу хийхээр очих вэ?"}, {"zh": "我去学校看书。", "pinyin": "Wǒ qù xuéxiào kàn shū.", "mn": "Би сургуульд ном уншихаар очно."}], "mistakes": [{"wrong": "我去到学校。", "right": "我去学校。", "why_mn": "去-ийн ард шууд газрын нэр орно, дунд нь угтвар үг (到 гэх мэт) нэмэх шаардлагагүй."}]}, {"zh": "学校", "pinyin": "xuéxiào", "teach_mn": "«学校» нь «сургууль» гэсэн газрын нэр. 去 (явах)-ийн ард орж хаашаа явж байгааг заана. 学 (сурах) язгуур нь 学生 (сурагч), 汉语 сурах зэрэг олон үгтэй холбогддог — язгуураар нь холбоотой үгсийг ялгаж таньж сур.", "usage_mn": ["去-ийн ард орж «сургууль руу явах» гэсэн газрын заалт болно", "学 язгуур нь «сурах» утгатай олон үгэнд давтагдана (学生 гэх мэт)"], "examples": [{"zh": "我去学校。", "pinyin": "Wǒ qù xuéxiào.", "mn": "Би сургууль руу явна."}, {"zh": "你去学校做什么？", "pinyin": "Nǐ qù xuéxiào zuò shénme?", "mn": "Чи сургуульд юу хийхээр очих вэ?"}, {"zh": "你是学生吗？", "pinyin": "Nǐ shì xuéshēng ma?", "mn": "Чи сурагч мөн үү?"}], "mistakes": []}, {"zh": "看", "pinyin": "kàn", "teach_mn": "«看» нь «харах, үзэх» гэсэн үндсэн утгатай ч 看书 (ном унших) гэдэг шиг «унших» гэсэн утгаар ч хэрэглэгддэг өргөн хүрээтэй үйл үг. Юуг хардаг, үздэгээ ард нь шууд залгана: 看 + юу. Монгол хэлэнд «ном үзэх» гэдэг шиг ярианд «харах»-аар «унших»-ыг илэрхийлдэгтэй адил санаа.", "usage_mn": ["Ард нь юу хардгаа заасан үг авна: 看书, 看...", "«Харах» ба «унших» хоёр утгаараа хэрэглэгддэг"], "examples": [{"zh": "我去学校看书。", "pinyin": "Wǒ qù xuéxiào kàn shū.", "mn": "Би сургуульд ном уншихаар очно."}, {"zh": "你看什么？", "pinyin": "Nǐ kàn shénme?", "mn": "Чи юу хараад/уншаад байна вэ?"}], "mistakes": [], "compare": [{"zh": "读", "pinyin": "dú", "mn": "унших (авиагаар дуудах)", "diff_mn": "看书 нь нүдээр харж утгыг ойлгож унших, 读 нь ханзыг авиагаар нь дуудаж унших гэсэн ялгаатай."}]}, {"zh": "书", "pinyin": "shū", "teach_mn": "«书» нь «ном» гэсэн нэр үг. 看书 (ном үзэх/унших) гэдэг тогтсон холбоо үгээр хамгийн түгээмэл хэрэглэгдэнэ. Монгол хэлэнд «ном» гэдэг үгтэй ижил энгийн, өдөр тутмын үг.", "usage_mn": ["看-ийн ард орж 看书 (ном унших) гэсэн тогтсон холбоо үг үүсгэнэ", "Тоолуур хэрэглэхдээ 本 хэрэглэдэг (дараагийн хичээлд сурна)"], "examples": [{"zh": "我去学校看书。", "pinyin": "Wǒ qù xuéxiào kàn shū.", "mn": "Би сургуульд ном уншихаар очно."}, {"zh": "你看书吗？", "pinyin": "Nǐ kàn shū ma?", "mn": "Чи ном уншиж байна уу?"}], "mistakes": []}], "grammar": [{"point": "日期的表达 (1)", "gloss_mn": "огноог томоос жижиг рүү: сар → өдөр → гараг", "structure": "(年) + 月 + 号 + 星期", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "Хятадаар огноо хэлэхдээ томоос жижиг рүү дараалуулна: эхлээд сар (月), дараа нь өдөр (号), эцэст нь гараг (星期). Монгол хэлэнд ч ихэвчлэн ижил дараалал (9 сарын 1, лхагва) хэрэглэдэг тул амархан.", "example": {"zh": "9月1号，星期三。", "pinyin": "Jiǔ yuè yī hào, xīngqī sān.", "mn": "9 сарын 1, Лхагва."}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Тоо + 月 (сар), тоо + 号 (өдөр), 星期 + тоо (гараг) гэсэн гурван блокийг цуваа холбоно, хооронд нь холбох үг хэрэггүй, зөвхөн таслал тавина.", "example": {"zh": "8月 + 31号 + 星期二", "pinyin": "bā yuè + sānshíyī hào + xīngqī èr", "mn": "8 сар + 31 өдөр + мягмар гараг"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Өдөр бүрийн огноо, гараг асуух, хариулахад хэрэглэнэ: 今天几号？星期几？", "example": {"zh": "今天几号？", "pinyin": "Jīntiān jǐ hào?", "mn": "Өнөөдөр хэдний өдөр вэ?"}}, {"title_mn": "4. Өргөтгөл", "body_mn": "Ярианд 号 хэрэглэдэг бол албан, бичгийн хэлэнд үүний оронд 日 хэрэглэдэг гэдгийг сана.", "example": {"zh": "9月1日 (бичгийн хэлбэр)", "pinyin": "jiǔ yuè yī rì", "mn": "9 сарын 1 (бичгийн хэв)"}}], "examples": [{"zh": "9月1号，星期三。", "pinyin": "Jiǔ yuè yī hào, xīngqī sān.", "mn": "9 сарын 1, Лхагва."}, {"zh": "8月31号，星期二。", "pinyin": "Bā yuè sānshíyī hào, xīngqī èr.", "mn": "8 сарын 31, Мягмар."}, {"zh": "今天几号？", "pinyin": "Jīntiān jǐ hào?", "mn": "Өнөөдөр хэдний өдөр вэ?"}, {"zh": "今天星期几？", "pinyin": "Jīntiān xīngqī jǐ?", "mn": "Өнөөдөр ямар гараг вэ?"}, {"zh": "昨天是几月几号？", "pinyin": "Zuótiān shì jǐ yuè jǐ hào?", "mn": "Өчигдөр хэдэн сарын хэдэн байсан бэ?"}, {"zh": "明天是9月2号，星期四。", "pinyin": "Míngtiān shì jiǔ yuè èr hào, xīngqī sì.", "mn": "Маргааш 9 сарын 2, пүрэв гараг."}], "mistakes": [{"wrong": "星期三，9月1号。", "right": "9月1号，星期三。", "why_mn": "Огноог томоос жижиг рүү хэлнэ — эхлээд сар, өдөр, эцэст нь гараг."}, {"wrong": "9号1月", "right": "9月1号", "why_mn": "月 (сар) үргэлж 号 (өдөр)-ийн өмнө ордог."}], "drills": [{"type": "choice", "question": "Зөв дараалал аль нь вэ?", "options": ["9月1号，星期三", "星期三，9月1号", "1号9月，星期三"], "answer": "9月1号，星期三", "why_mn": "Хятадаар огноог томоос жижиг рүү: сар → өдөр → гараг гэж хэлнэ."}, {"type": "fill", "question": "Ням гарагийг тоогүйгээр хэлбэл ___ эсвэл ___.", "answer": "星期日 / 星期天", "why_mn": "Ням гарагт тоо биш 日 эсвэл 天 хэрэглэнэ."}, {"type": "judge", "question": "Хятадаар огноог өдөр → сар → жил гэж жижгээс том руу хэлдэг.", "answer": "false", "why_mn": "Хятадаар яг эсрэгээр, томоос жижиг рүү хэлдэг: сар → өдөр → гараг."}, {"type": "choice", "question": "「今天___号？」гэдэгт тохирох асуух үг аль нь вэ?", "options": ["几", "什么", "谁"], "answer": "几", "why_mn": "Аравтас багатай тоо асуухад 几 хэрэглэдэг, огноо ихэвчлэн 31 хүртэл тул 几 тохирно."}]}, {"point": "名词谓语句", "gloss_mn": "нэр үг өгүүлэхүүн болох нь (是 орхигдоно)", "structure": "主语 + (тоо/огноо/нас) — 是 хэрэггүй", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "Нас, цаг, огноо зэрэг тоон мэдээллийг хэлэхдээ хятад хэлэнд 是-г ихэвчлэн орхиж болно — нэр үг (эсвэл тоон хэллэг) өөрөө шууд өгүүлэхүүн болно.", "example": {"zh": "明天星期三。", "pinyin": "Míngtiān xīngqī sān.", "mn": "Маргааш Лхагва гараг."}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Эзэн бие + огноо/цаг/нас гэсэн энгийн дараалал, дунд нь ямар ч холбоос үг ордоггүй.", "example": {"zh": "今天 + 9月1号", "pinyin": "jīntiān + jiǔ yuè yī hào", "mn": "өнөөдөр + 9 сарын 1"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Өдөр тутмын ярианд огноо, гараг, нас хэлэхэд өргөн хэрэглэгддэг энгийн бүтэц.", "example": {"zh": "今天9月1号。", "pinyin": "Jīntiān jiǔ yuè yī hào.", "mn": "Өнөөдөр 9 сарын 1."}}, {"title_mn": "4. Ялгаа — асуулт, үгүйсгэлд 是 буцаж ирнэ", "body_mn": "«Байна уу» гэж баталгаажуулан асуухдаа эсвэл үгүйсгэхдээ 是 заавал буцаж орно: 昨天是几月几号？, 明天不是星期六。", "example": {"zh": "昨天是几月几号？", "pinyin": "Zuótiān shì jǐ yuè jǐ hào?", "mn": "Өчигдөр хэдэн сарын хэдэн байсан бэ?"}}], "examples": [{"zh": "明天星期三。", "pinyin": "Míngtiān xīngqī sān.", "mn": "Маргааш Лхагва гараг."}, {"zh": "今天9月1号。", "pinyin": "Jīntiān jiǔ yuè yī hào.", "mn": "Өнөөдөр 9 сарын 1."}, {"zh": "昨天是8月31号。", "pinyin": "Zuótiān shì bā yuè sānshíyī hào.", "mn": "Өчигдөр 8 сарын 31 байсан."}, {"zh": "昨天是几月几号？", "pinyin": "Zuótiān shì jǐ yuè jǐ hào?", "mn": "Өчигдөр хэдэн сарын хэдэн байсан бэ?"}, {"zh": "明天不是星期六。", "pinyin": "Míngtiān bú shì xīngqī liù.", "mn": "Маргааш бямба гараг биш."}, {"zh": "明天星期六，你去学校吗？", "pinyin": "Míngtiān xīngqī liù, nǐ qù xuéxiào ma?", "mn": "Маргааш бямба гараг, чи сургуульдаа явах уу?"}], "mistakes": [{"wrong": "明天不星期六。", "right": "明天不是星期六。", "why_mn": "Үгүйсгэхдээ 是 заавал буцаж орно, 不-г шууд нэр үгийн өмнө тавьж болохгүй."}, {"wrong": "今天是9月1号是。", "right": "今天是9月1号。", "why_mn": "是 нэг өгүүлбэрт нэг л удаа орно, давхардуулж бичихгүй."}], "drills": [{"type": "judge", "question": "«明天星期三» гэдэгт 是 заавал орох ёстой.", "answer": "false", "why_mn": "Батламж өгүүлбэрт нас, цаг, огноо хэлэхдээ 是 орхигдож болно."}, {"type": "fill", "question": "明天___星期六。（үгүйсгэ）", "answer": "不是", "why_mn": "Үгүйсгэхэд 是 заавал буцаж ирнэ: 不是."}, {"type": "choice", "question": "「昨天___几月几号？」гэдэгт юу дутуу вэ?", "options": ["是", "很", "了"], "answer": "是", "why_mn": "«Хэдэн байсан бэ» гэж баталгаажуулан асуухад 是 хэрэглэнэ."}, {"type": "judge", "question": "今天9月1号 гэдэг өгүүлбэр дүрмийн хувьд зөв.", "answer": "true", "why_mn": "Огноо хэлэхдээ 是-г орхиж болно тул энэ өгүүлбэр зөв."}]}, {"point": "连动句 (1)：去 + газар + үйл", "gloss_mn": "цуваа үйлт өгүүлбэр — очоод юу хийхээ хэлэх", "structure": "主语 + 去 + газар + үйл (+ юу)", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "Нэг өгүүлбэрт хоёр үйл үг цуваа орж, эхнийх нь «хаашаа», хоёр дахь нь «тэнд юу хийхийг» заана.", "example": {"zh": "我去学校看书。", "pinyin": "Wǒ qù xuéxiào kàn shū.", "mn": "Би сургуульд ном уншихаар очно."}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Эзэн бие + 去 + газар + хоёр дахь үйл үг (+ юу) гэсэн дараалал: хоёр үйл үгийн хооронд холбох үг (жишээ нь «ба») хэрэггүй.", "example": {"zh": "我 + 去 + 学校 + 看 + 书", "pinyin": "wǒ + qù + xuéxiào + kàn + shū", "mn": "би + очих + сургууль + унших + ном"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Хаашаа явж, тэнд юу хийхээ нэг өгүүлбэрт хамт хэлэхэд хэрэглэнэ — өдөр тутмын төлөвлөгөө ярихад маш түгээмэл.", "example": {"zh": "你去学校做什么？", "pinyin": "Nǐ qù xuéxiào zuò shénme?", "mn": "Чи сургуульд юу хийхээр очих вэ?"}}, {"title_mn": "4. Өргөтгөл", "body_mn": "去 + газар гэдгийг заавал хоёр дахь үйл үггүйгээр ч хэрэглэж болно — зөвхөн хаашаа явахаа хэлэхэд хангалттай: 我去学校。", "example": {"zh": "我去学校。", "pinyin": "Wǒ qù xuéxiào.", "mn": "Би сургууль руу явна."}}], "examples": [{"zh": "我去学校看书。", "pinyin": "Wǒ qù xuéxiào kàn shū.", "mn": "Би сургуульд ном уншихаар очно."}, {"zh": "你去学校做什么？", "pinyin": "Nǐ qù xuéxiào zuò shénme?", "mn": "Чи сургуульд юу хийхээр очих вэ?"}, {"zh": "我去学校。", "pinyin": "Wǒ qù xuéxiào.", "mn": "Би сургууль руу явна."}, {"zh": "你去学校吗？", "pinyin": "Nǐ qù xuéxiào ma?", "mn": "Чи сургуульдаа явах уу?"}, {"zh": "明天星期六，你去学校吗？", "pinyin": "Míngtiān xīngqī liù, nǐ qù xuéxiào ma?", "mn": "Маргааш бямба гараг, чи сургуульдаа явах уу?"}], "mistakes": [{"wrong": "我去看书学校。", "right": "我去学校看书。", "why_mn": "去-ийн ард эхлээд газар (学校), дараа нь хоёр дахь үйл үг (看书) орно, эсрэгээр байрлуулбал буруу."}, {"wrong": "我去和看书学校。", "right": "我去学校看书。", "why_mn": "Хоёр үйл үгийг цувааруулахад «和» (ба) гэсэн холбох үг хэрэглэдэггүй."}], "drills": [{"type": "choice", "question": "«Би сургуульд ном уншихаар очно» гэдгийг зөв бичсэн нь аль вэ?", "options": ["我去学校看书。", "我看书去学校。", "我去看书学校。"], "answer": "我去学校看书。", "why_mn": "去 + газар + үйл гэсэн дараалал: эхлээд хаашаа, дараа нь юу хийхээ хэлнэ."}, {"type": "fill", "question": "你去学校___什么？", "answer": "做", "why_mn": "«Юу хийхээр очих вэ» гэдгийг 做什么 гэж асууна."}, {"type": "judge", "question": "去 + газар + үйл бүтцэд хоёр үйл үгийн хооронд «和» (ба) хэрэглэнэ.", "answer": "false", "why_mn": "Цуваа үйлт өгүүлбэрт холбох үг хэрэггүй, үйл үгүүд шууд цувна."}, {"type": "choice", "question": "我去学校___。（«ном унших» гэдгийг нэм）", "options": ["看书", "书看", "看的书"], "answer": "看书", "why_mn": "«Ном унших» гэдгийг 看书 гэж шууд хэлнэ."}]}, {"point": "汉字结构 (2) — 左右 ба 左中右 бүтэц", "gloss_mn": "зүүн-баруун ба зүүн-дунд-баруун бүтэц", "structure": "左右 (хоёр хэсэг) / 左中右 (гурван хэсэг)", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "Өмнөх хичээлд 独体字 (дан) ба 合体字 (нийлмэл) гэдгийг сурсан. Энэ удаад нийлмэл ханзны нэг элбэг төрлийг — зүүн ба баруун хоёр хэсэгт хуваагдсан бүтцийг — нарийвчлан үзье.", "example": {"zh": "你 好", "pinyin": "nǐ hǎo", "mn": "зүүн-баруун бүтэцтэй жишээ"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "左右 бүтэц: ханз хоёр хэсэгт хуваагдана — зүүн хэсэг, баруун хэсэг (你 = 亻+尔). 左中右 бүтэц: гурван хэсэгт хуваагдана — зүүн, дунд, баруун (谢 = 讠+身+寸).", "example": {"zh": "谢", "pinyin": "xiè", "mn": "гурван хэсэгтэй (左中右) жишээ"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Шинэ ханз тааралдахад эхлээд «хэдэн хэсэгт хуваагддаг вэ» гэдгийг ажигласнаар бичих дараалал, хэсгийн харьцангуй хэмжээг зөв тохируулж сурна.", "example": {"zh": "做", "pinyin": "zuò", "mn": "зүүн-баруун бүтэцтэй"}}, {"title_mn": "4. Ялгаа", "body_mn": "左右 бүтэцтэй ханз бичихдээ зүүн хэсгээ арай нарийн, баруун хэсгээ арай өргөн бичих нь түгээмэл — хоёр хэсэг тэнцүү өргөн байх албагүй.", "example": {"zh": "你", "pinyin": "nǐ", "mn": "亻 нарийн, 尔 арай өргөн"}}], "examples": [{"zh": "你 好", "pinyin": "nǐ hǎo", "mn": "зүүн-баруун бүтэц"}, {"zh": "谢 树", "pinyin": "xiè shù", "mn": "зүүн-дунд-баруун бүтэц"}, {"zh": "做 说", "pinyin": "zuò shuō", "mn": "зүүн-баруун бүтэц"}, {"zh": "汉 请", "pinyin": "hàn qǐng", "mn": "зүүн-баруун бүтэц"}, {"zh": "我", "pinyin": "wǒ", "mn": "独体字 — хэсэгт хуваагддаггүй (харьцуулбал)"}], "mistakes": [{"wrong": "你-г зүүн, баруун хэсгийг тэнцүү өргөн бичих", "right": "你-г зүүн хэсгийг нарийн, баруун хэсгийг арай өргөн бичих", "why_mn": "左右 бүтэцтэй ханзны хоёр хэсэг ихэвчлэн тэнцүү өргөнгүй байдаг, харьцааг нь ажиглаж бич."}], "drills": [{"type": "choice", "question": "你 ямар бүтэцтэй вэ?", "options": ["独体字", "左右", "左中右"], "answer": "左右", "why_mn": "你 нь 亻 (зүүн) ба 尔 (баруун) гэсэн хоёр хэсэгтэй тул 左右 бүтэцтэй."}, {"type": "choice", "question": "谢 ямар бүтэцтэй вэ?", "options": ["独体字", "左右", "左中右"], "answer": "左中右", "why_mn": "谢 нь 讠(зүүн) + 身(дунд) + 寸(баруун) гэсэн гурван хэсэгтэй."}, {"type": "judge", "question": "左右 бүтэцтэй ханзны хоёр хэсэг үргэлж тэнцүү өргөн байдаг.", "answer": "false", "why_mn": "Ихэнхдээ зүүн хэсэг нарийн, баруун хэсэг арай өргөн байдаг."}, {"type": "fill", "question": "做 хэдэн хэсэгт хуваагддаг вэ? (тоо бич)", "answer": "2", "why_mn": "做 нь зүүн-баруун (左右) хоёр хэсэгтэй."}]}, {"point": "汉字偏旁 — 氵 ба 讠", "gloss_mn": "язгуур (radical) таних", "structure": "氵(ус) / 讠(хэл яриа) + фонетик хэсэг", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "偏旁 (язгуур) бол нийлмэл ханзны нэг тогтмол давтагддаг хэсэг, ихэвчлэн утгыг заана. 氵 (гурван дусал ус) — устай холбоотой утга; 讠 (үгийн язгуур) — хэл яриатай холбоотой утга.", "example": {"zh": "氵 讠", "pinyin": "shuǐ + yán", "mn": "ус + хэл яриа язгуур"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Язгуур ихэвчлэн зүүн талд, баруун тал нь дуудлагыг санамжлах фонетик хэсэг байна: 汉 (氵+又), 语 (讠+吾).", "example": {"zh": "汉 = 氵 + 又", "pinyin": "hàn", "mn": "устай холбоотой утга + фонетик хэсэг"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Шинэ ханзтай таарахад язгуурыг нь харснаар ойролцоо утгыг таамаглаж болно: 氵-тэй бол устай, 讠-тэй бол хэл яриатай холбоотой байх магадлалтай.", "example": {"zh": "河 海", "pinyin": "hé hǎi", "mn": "氵-тэй — гол, далай (устай холбоотой)"}}, {"title_mn": "4. Өргөтгөл", "body_mn": "语, 谁, 说, 请 зэрэг олон HSK1 үг 讠 язгууртай — эдгээрийг «хэл ярианы бүлэг» гэж нэг дор цээжилж болно.", "example": {"zh": "语 谁 说 请", "pinyin": "yǔ shéi shuō qǐng", "mn": "讠 язгууртай хэл ярианы үгс"}}], "examples": [{"zh": "汉 没", "pinyin": "hàn méi", "mn": "氵 устай холбоотой"}, {"zh": "语 谁", "pinyin": "yǔ shéi", "mn": "讠 хэл яриатай холбоотой"}, {"zh": "说 请", "pinyin": "shuō qǐng", "mn": "讠 язгууртай — ярианы үйл үг"}, {"zh": "河 海", "pinyin": "hé hǎi", "mn": "氵язгууртай — устай холбоотой газар нэр"}], "mistakes": [{"wrong": "氵-г «гурван зураас» гэж дурсаж, утгыг нь мартах", "right": "氵-г «ус» гэсэн утгатай гэдгийг заавал холбож сана", "why_mn": "Язгуурыг зөвхөн дүрсээр бус, утгатай нь холбож цээжлэх нь ханз таних, таамаглахад тустай."}], "drills": [{"type": "choice", "question": "氵 язгуур ямар утгатай холбоотой вэ?", "options": ["ус", "хэл яриа", "хүн"], "answer": "ус", "why_mn": "氵 нь гурван дусал усны дүрснээс гаралтай, устай холбоотой утгыг заана."}, {"type": "choice", "question": "讠 язгуур ямар утгатай холбоотой вэ?", "options": ["ус", "хэл яриа", "мод"], "answer": "хэл яриа", "why_mn": "讠 нь үгийн язгуур бөгөөд хэл яриатай холбоотой ханзанд орно."}, {"type": "judge", "question": "请 гэдэг ханз 讠 язгууртай.", "answer": "true", "why_mn": "请 зүүн талдаа 讠 язгууртай, ярианы утгатай холбоотой."}, {"type": "fill", "question": "汉 ямар язгууртай вэ?", "answer": "氵", "why_mn": "汉 зүүн талдаа 氵 (ус) язгуурыг агуулна."}]}], "hanzi": [{"hanzi": "四", "pinyin": "sì", "meaning_mn": "дөрөв", "story_mn": "四-ийн эртний бичигт зүгээр л дөрвөн хэвтээ зураас байсан гэж үздэг ч хожим одоогийн хайрцаг доторх хөл мэт хэлбэрт шилжсэн. Одоогийн дүрсийг «дөрвөлжин хайрцгийн дотор хөл» гэж төсөөлж санаж болно.", "stroke_count": 5, "stroke_tips_mn": ["Гаднах хүрээг зүүн талаас нь эхэлж бич", "Дээд ба баруун талын зурлагыг холбож тат", "Дотор талын хоёр зурлагыг эцэст нь нэмээд, доод хэвтээ зурлагаар хааж дуусга"], "confusable": [{"zh": "西", "pinyin": "xī", "mn": "баруун", "diff_mn": "四 ба 西 хоёул дөрвөлжин хүрээтэй дүрстэй ч 四-ийн дотор өөр зурлагатай, 西-ийн доторх зурлага өөр хэлбэртэй."}], "words": [{"zh": "四月", "pinyin": "sì yuè", "mn": "дөрөвдүгээр сар"}, {"zh": "十四", "pinyin": "shí sì", "mn": "арван дөрөв"}]}, {"hanzi": "五", "pinyin": "wǔ", "meaning_mn": "тав", "story_mn": "五-ийн эртний хэлбэр хоёр шугам огтлолцсон энгийн тоолуурын тэмдэглэгээнээс үүссэн гэж үздэг, хожим одоогийн хэлбэрт шилжиж тогтсон.", "stroke_count": 4, "stroke_tips_mn": ["Дээд хэвтээ зурлагыг зүүнээс баруун тийш тат", "Дунд хэсгийн эгц ба налуу зурлагуудыг дараалуулан тат", "Доод хэвтээ зурлагаар хааж дуусга"], "words": [{"zh": "五月", "pinyin": "wǔ yuè", "mn": "тавдугаар сар"}, {"zh": "十五", "pinyin": "shí wǔ", "mn": "арван тав"}]}, {"hanzi": "书", "pinyin": "shū", "meaning_mn": "ном", "story_mn": "书-ийн уламжлалт хэлбэр 書 нь гараар бийр барьж бичиж буй дүрс агуулж байсан гэж үздэг — бичсэн зүйл, тэмдэглэл гэдгээс «ном» гэсэн утга үүссэн. Хялбаршуулсан 书 хэлбэрт энэ дүрс улам жигдэрсэн байна.", "stroke_count": 4, "stroke_tips_mn": ["Дээд эргэлттэй зурлагыг эхлээд тат", "Дотор талын эргэлттэй зурлагыг нэмнэ", "Босоо зурлага, эцэст нь доод цэгийг тат"], "confusable": [{"zh": "字", "pinyin": "zì", "mn": "үсэг, тэмдэгт", "diff_mn": "书 ба 字 хоёул бичигтэй холбоотой утгатай ч дүрс огт өөр — 字 дээрээ 宀 (дээвэр) хэлбэртэй."}], "words": [{"zh": "看书", "pinyin": "kàn shū", "mn": "ном унших"}, {"zh": "书本", "pinyin": "shūběn", "mn": "ном, дэвтэр"}]}], "pronunciation": {"focus_mn": "Энэ хичээлд 2-р хөгөөр эхэлсэн хоёр үет үгсийн хөгийн хослолыг сайтар сонсож давт. 昨天, 今天, 明天 гурвыг хамтад нь чангаар хэлж, хөгийн ялгааг мэдэрч сур.", "drills": [{"title_mn": "Хослол: 2-р хөг + 1-р хөг", "instruction_mn": "Эхний үеийг доороос дээш өгсгөж, хоёр дахь үеийг тэгш өндөрт барь.", "pairs": [{"a": {"zh": "明天", "pinyin": "míngtiān", "mn": "маргааш"}, "b": {"zh": "年轻", "pinyin": "niánqīng", "mn": "залуу"}, "note_mn": "Хоёул 2+1 хослол — míng, nián дээшилж, tiān, qīng тэгш өндөрт тогтоно."}, {"a": {"zh": "明天", "pinyin": "míngtiān", "mn": "маргааш"}, "b": {"zh": "今天", "pinyin": "jīntiān", "mn": "өнөөдөр"}, "note_mn": "2+1 (míngtiān) ба 1+1 (jīntiān) хослолын ялгааг чихээрээ мэдэр."}]}, {"title_mn": "Хослол: 2-р хөг + 3-р хөг", "instruction_mn": "Эхний үеийг дээшлүүлж, хоёр дахь 3-р хөгийг намхан барь.", "pairs": [{"a": {"zh": "苹果", "pinyin": "píngguǒ", "mn": "алим"}, "b": {"zh": "词典", "pinyin": "cídiǎn", "mn": "толь бичиг"}, "note_mn": "Хоёул 2+3 хослол — эхний үе дээшилж, guǒ, diǎn намхан дуудагдана."}, {"a": {"zh": "牛奶", "pinyin": "niúnǎi", "mn": "сүү"}, "b": {"zh": "苹果", "pinyin": "píngguǒ", "mn": "алим"}, "note_mn": "2+3 хослолын жишээ хоёрыг зэрэгцүүлж давт."}]}, {"title_mn": "Хослол: 2-р хөг + 4-р хөг", "instruction_mn": "Эхний үеийг дээшлүүлж, хоёр дахь үеийг огцом буулга.", "pairs": [{"a": {"zh": "蓝色", "pinyin": "lánsè", "mn": "цэнхэр"}, "b": {"zh": "环境", "pinyin": "huánjìng", "mn": "орчин"}, "note_mn": "Хоёул 2+4 хослол — эхний үе дээшилж, хоёр дахь нь огцом унана."}, {"a": {"zh": "游戏", "pinyin": "yóuxì", "mn": "тоглоом"}, "b": {"zh": "寒假", "pinyin": "hánjià", "mn": "өвлийн амралт"}, "note_mn": "xì, jià хоёулаа өндрөөс шулуухан унана."}, {"a": {"zh": "明天", "pinyin": "míngtiān", "mn": "маргааш"}, "b": {"zh": "蓝色", "pinyin": "lánsè", "mn": "цэнхэр"}, "note_mn": "2+1 ба 2+4 хослолын ялгааг зэрэгцүүлж мэдэр."}]}], "tips_mn": ["昨天, 今天, 明天 гурвыг өдөр бүр хамт хэлж, хөгийн ялгааг булчиндаа сургаарай (zuótiān 2+1, jīntiān 1+1, míngtiān 2+1).", "2-р хөгийг дутуу дулимаг биш, доороос эхлээд бүрэн дээшлэх хүртэл тод хэл.", "Сар, гарагийн тоог (一 - 十二) хөгтэй нь хамт цээжлэх нь дараа улам их тоо сурахад суурь болно."]}}'::jsonb)
