values ('hsk1-l08', 1, '{"words": [{"zh": "想", "pinyin": "xiǎng", "teach_mn": "想 нь өөр үйл үгийн өмнө орж «...хиймээр байна» гэсэн хүсэл, төлөвлөгөө илэрхийлдэг тусгай үйл үг (能愿动词). Дангаараа бүтэн санаа болдоггүй — ард нь заавал өөр үйл үг ирнэ: 想喝 (уумаар байна), 想吃 (идмээр байна). Монгол хэлэнд энэ санааг үйл үгийн язгуур дээр «-мар/-мээр» дагавар залгаж илэрхийлдэг бол хятад хэлэнд 想-г тусад нь, үйл үгийн өмнө бичдэг гэдгээрээ ялгаатай.", "usage_mn": ["Ямар нэг зүйл хийхийг хүсч байгаагаа илэрхийлэхэд хэрэглэнэ", "Ганцаараа биш үргэлж ард нь өөр үйл үгтэй хамт хэрэглэнэ"], "examples": [{"zh": "我想喝茶。", "pinyin": "Wǒ xiǎng hē chá.", "mn": "Би цай уумаар байна.", "note_mn": "хамгийн энгийн бүтэц: эзэн + 想 + үйл үг + тусагдахуун"}, {"zh": "你想吃什么？", "pinyin": "Nǐ xiǎng chī shénme?", "mn": "Чи юу идмээр байна?", "note_mn": "хоолны газарт байнга хэрэглэгддэг асуулт"}, {"zh": "我想买一个杯子。", "pinyin": "Wǒ xiǎng mǎi yí ge bēizi.", "mn": "Би нэг аяга авмаар байна.", "note_mn": "想 + буй + тоо хэмжигчтэй нэр үг"}, {"zh": "下午我想去商店。", "pinyin": "Xiàwǔ wǒ xiǎng qù shāngdiàn.", "mn": "Үдээс хойш би дэлгүүр орох гэсэн юм.", "note_mn": "цаг заасан үг өгүүлбэрийн эхэнд ирж болно"}, {"zh": "你想喝茶吗？", "pinyin": "Nǐ xiǎng hē chá ma?", "mn": "Чи цай уумаар байна уу?", "note_mn": "ард нь 吗 нэмээд асуулт болгосон"}], "mistakes": [{"wrong": "我喝想茶。", "right": "我想喝茶。", "why_mn": "想 нь үргэлж үйл үгийн өмнө ордог, ард нь биш."}, {"wrong": "我想不喝茶。", "right": "我不喝茶。／我不想喝茶。", "why_mn": "Хүсэлгүй байгаагаа хэлэхдээ 不-г 想-ийн өмнө нэмнэ, 想 болон үйл үгийн хооронд оруулахгүй."}], "compare": [{"zh": "会", "pinyin": "huì", "mn": "чадна", "diff_mn": "会 нь сурч мэдсэн чадвар заана (жишээ нь хэл сурсан), 想 нь зүгээр л хүсэл — хоёрыг хольж болохгүй."}]}, {"zh": "喝", "pinyin": "hē", "teach_mn": "喝 нь шингэн зүйл уухыг заасан үйл үг: цай, ус зэргийг «уух» гэхэд хэрэглэнэ. Ихэвчлэн 想-тай хамт орж 想喝 (уумаар байна) гэдэг хэлбэрээр гардаг. Хоол идэхийг заасан 吃-тэй бүү андуур — 喝 зөвхөн шингэн зүйлд, 吃 хатуу хоолонд хэрэглэнэ.", "usage_mn": ["Цай, ус гэх мэт шингэн зүйл уухад хэрэглэнэ", "Хатуу хоол идэхэд хэрэглэхгүй — тэр үед 吃 хэрэглэнэ"], "examples": [{"zh": "你想喝什么？", "pinyin": "Nǐ xiǎng hē shénme?", "mn": "Чи юу уумаар байна?", "note_mn": "зочломтгой асуулт"}, {"zh": "我想喝茶。", "pinyin": "Wǒ xiǎng hē chá.", "mn": "Би цай уумаар байна.", "note_mn": "хамгийн энгийн хариулт"}, {"zh": "她喝茶吗？", "pinyin": "Tā hē chá ma?", "mn": "Тэр цай уудаг уу?", "note_mn": "гуравдагч этгээдийн тухай асуух"}, {"zh": "我不喝茶。", "pinyin": "Wǒ bù hē chá.", "mn": "Би цай уудаггүй.", "note_mn": "энгийн үгүйсгэл"}], "mistakes": [{"wrong": "我喝米饭。", "right": "我吃米饭。", "why_mn": "米饭 нь хатуу хоол тул 喝 биш 吃 хэрэглэнэ."}]}, {"zh": "茶", "pinyin": "chá", "teach_mn": "茶 нь «цай» гэсэн нэр үг, Хятадад цай уух зан заншил маш өргөн тархсан тул энэ үг эхний хичээлүүдэд заавал ордог. 喝茶 (цай уух) гэсэн хэллэгийг хамт хос болгож цээжлэх нь чухал.", "usage_mn": ["Юу уух вэ гэдгийг хариулахад нэр үг болгон хэрэглэнэ", "Ихэвчлэн 喝-тэй хамт 喝茶 гэж хосолж хэрэглэнэ"], "examples": [{"zh": "我想喝茶。", "pinyin": "Wǒ xiǎng hē chá.", "mn": "Би цай уумаар байна.", "note_mn": "хамгийн түгээмэл хэрэглээ"}, {"zh": "这是茶。", "pinyin": "Zhè shì chá.", "mn": "Энэ бол цай.", "note_mn": "зүйлийг заах энгийн өгүүлбэр"}, {"zh": "你喝茶吗？", "pinyin": "Nǐ hē chá ma?", "mn": "Чи цай уух уу?", "note_mn": "санал болгож асуух"}], "mistakes": [{"wrong": "我茶不喝。", "right": "我不喝茶。", "why_mn": "Үгүйсгэх 不 нь үйл үгийн (喝) өмнө ордог, тусагдахуун (茶) урд нь гарахгүй."}]}, {"zh": "吃", "pinyin": "chī", "teach_mn": "吃 нь хатуу хоол идэхийг заасан үндсэн үйл үг. 喝-ээс ялгаатай нь 吃 зажлаж идэх зүйлд хэрэглэгддэг. 想吃 гэвэл «идмээр байна» гэсэн утгатай болно.", "usage_mn": ["Хоол идэхийг илэрхийлэхэд хэрэглэнэ", "想-тай хамт орж хүслээ илэрхийлнэ: 想吃"], "examples": [{"zh": "你想吃什么？", "pinyin": "Nǐ xiǎng chī shénme?", "mn": "Чи юу идмээр байна?", "note_mn": "зоогийн газарт хэрэглэгддэг асуулт"}, {"zh": "我想吃米饭。", "pinyin": "Wǒ xiǎng chī mǐfàn.", "mn": "Би будаа идмээр байна.", "note_mn": "энгийн хариулт"}, {"zh": "她吃菜。", "pinyin": "Tā chī cài.", "mn": "Тэр хоол иднэ.", "note_mn": "菜 (хоол) нь L6-гийн үгтэй хамт"}, {"zh": "我不吃。", "pinyin": "Wǒ bù chī.", "mn": "Би идэхгүй.", "note_mn": "тусагдахуунгүй энгийн үгүйсгэл"}], "mistakes": [{"wrong": "我吃茶。", "right": "我喝茶。", "why_mn": "Цай бол шингэн тул 吃 биш 喝 хэрэглэнэ."}]}, {"zh": "米饭", "pinyin": "mǐfàn", "teach_mn": "米饭 нь буцалгасан цагаан будаа — Хятадын өдөр тутмын үндсэн хоолны нэг. 米 (түүхий будаа) ба 饭 (чанасан хоол) гэсэн хоёр ханзнаас тогтоно. Ихэвчлэн 吃-тэй хамт хэрэглэгддэг.", "usage_mn": ["Хоолны нэр болгон хэрэглэнэ, ихэвчлэн 吃-тэй хамт"], "examples": [{"zh": "我想吃米饭。", "pinyin": "Wǒ xiǎng chī mǐfàn.", "mn": "Би будаа идмээр байна.", "note_mn": "хамгийн түгээмэл хэрэглээ"}, {"zh": "米饭好吃吗？", "pinyin": "Mǐfàn hǎochī ma?", "mn": "Будаа амттай юу?", "note_mn": "好吃 (амттай) нь L6-гийн үг"}, {"zh": "她吃米饭。", "pinyin": "Tā chī mǐfàn.", "mn": "Тэр будаа иднэ.", "note_mn": "гуравдагч этгээдийн тухай"}], "mistakes": [{"wrong": "我喝米饭。", "right": "我吃米饭。", "why_mn": "米饭 хатуу хоол тул 喝 биш 吃 хэрэглэнэ."}]}, {"zh": "下午", "pinyin": "xiàwǔ", "teach_mn": "下午 нь өдрийн хугацаа заасан цагийн үг — үд дундаас (12ц орчим) орой болтол хугацааг хэлнэ. Цаг заасан үг өгүүлбэрийн эхэнд, эсвэл эзэн биеийн ард — үйл үгийн өмнө ордог бөгөөд «хэзээ» гэдгийг заана.", "usage_mn": ["Өдрийн аль хэсэгт нэг үйл хийхийг заахад өгүүлбэрийн эхэнд эсвэл эзэн биеийн ард хэрэглэнэ"], "examples": [{"zh": "下午你想做什么？", "pinyin": "Xiàwǔ nǐ xiǎng zuò shénme?", "mn": "Үдээс хойш чи юу хиймээр байна?", "note_mn": "做 (хийх) нь L6-гийн үг"}, {"zh": "下午我想去商店。", "pinyin": "Xiàwǔ wǒ xiǎng qù shāngdiàn.", "mn": "Үдээс хойш би дэлгүүр орох гэсэн юм.", "note_mn": "өгүүлбэрийн эхэнд орсон"}, {"zh": "我下午看书。", "pinyin": "Wǒ xiàwǔ kàn shū.", "mn": "Би үдээс хойш ном унших.", "note_mn": "эзэн биеийн ард орсон хувилбар"}], "mistakes": [{"wrong": "我去下午商店。", "right": "下午我去商店。", "why_mn": "Цаг заасан үг өгүүлбэрийн эхэнд эсвэл эзэн биеийн ард ордог, тусагдахуунтай зэрэгцэн орохгүй."}]}, {"zh": "商店", "pinyin": "shāngdiàn", "teach_mn": "商店 нь бараа худалдаалдаг газар — «дэлгүүр». 去商店 (дэлгүүр орох) гэсэн хэллэг өдөр тутамд их хэрэглэгддэг.", "usage_mn": ["Хаашаа явахаа хэлэхэд газрын нэр болгон хэрэглэнэ"], "examples": [{"zh": "下午我想去商店。", "pinyin": "Xiàwǔ wǒ xiǎng qù shāngdiàn.", "mn": "Үдээс хойш би дэлгүүр орох гэсэн юм.", "note_mn": "хамгийн энгийн хэрэглээ"}, {"zh": "商店有杯子吗？", "pinyin": "Shāngdiàn yǒu bēizi ma?", "mn": "Дэлгүүрт аяга байгаа юу?", "note_mn": "有 (байх) нь L5-ийн үг"}, {"zh": "那个商店很大。", "pinyin": "Nàge shāngdiàn hěn dà.", "mn": "Тэр дэлгүүр том.", "note_mn": "那个 (L8), 很 (L6), 大 (L5)-тай хамт"}], "mistakes": [{"wrong": "我商店去。", "right": "我去商店。", "why_mn": "去 (явах) нь газрын нэрийн өмнө ордог үйл үг, дараалал өөрчлөгдөхгүй."}]}, {"zh": "买", "pinyin": "mǎi", "teach_mn": "买 нь мөнгөөр бараа авахыг заасан үйл үг — «худалдаж авах». Ижил бичигдэлтэй дуудлагатай ч эсрэг утгатай 卖 (mài, зарах) байдгийг сана — хоёрыг зөвхөн хөгөөрөө (3-р ба 4-р хөг) ялгах ба бичихдээ 买-ийн дотор нэг зураас бага гэдгийг санаж болно.", "usage_mn": ["Дэлгүүрт бараа авахдаа хэрэглэнэ"], "examples": [{"zh": "你想买什么？", "pinyin": "Nǐ xiǎng mǎi shénme?", "mn": "Чи юу авмаар байна?", "note_mn": "дэлгүүрт түгээмэл асуулт"}, {"zh": "我想买一个杯子。", "pinyin": "Wǒ xiǎng mǎi yí ge bēizi.", "mn": "Би нэг аяга авмаар байна.", "note_mn": "想买 + тоо хэмжигчтэй нэр үг"}, {"zh": "她买茶。", "pinyin": "Tā mǎi chá.", "mn": "Тэр цай авна.", "note_mn": "энгийн хэлбэр"}], "mistakes": [{"wrong": "我买想杯子。", "right": "我想买杯子。", "why_mn": "想 үргэлж үйл үгийн (买) өмнө ордог."}], "compare": [{"zh": "卖", "pinyin": "mài", "mn": "худалдах, зарах", "diff_mn": "买 (3-р хөг) авах, 卖 (4-р хөг) зарах — эсрэг утгатай, зөвхөн хөгөөрөө ялгагдана."}]}, {"zh": "个", "pinyin": "gè", "teach_mn": "个 нь хятад хэлний хамгийн түгээмэл тоо хэмжигч (量词) — тоо ба нэр үгийн хооронд заавал ордог. Монгол хэлэнд «ширхэг» гэдгийг зарим үед л хэрэглэдэг бол хятад хэлэнд бараг бүх нэр үгийн өмнө тоо хэмжигч заавал байх ёстой, орхигдуулж болохгүй.", "usage_mn": ["Тоо ба нэр үгийн хооронд заавал орж «х ширхэг» гэсэн утга нэмнэ", "Тодорхой тоо хэмжигчгүй бол ихэнх нэр үгэнд 个-г хэрэглэж болно"], "examples": [{"zh": "我想买一个杯子。", "pinyin": "Wǒ xiǎng mǎi yí ge bēizi.", "mn": "Би нэг аяга авмаар байна.", "note_mn": "一 4-р хөгийн өмнө yí болсон дүрэм"}, {"zh": "这个杯子多少钱？", "pinyin": "Zhège bēizi duōshao qián?", "mn": "Энэ аяга ямар үнэтэй вэ?", "note_mn": "这个 = энэ (энэ + 个)"}, {"zh": "她家有三个人。", "pinyin": "Tā jiā yǒu sān ge rén.", "mn": "Түүний гэр бүлд гурван хүн байна.", "note_mn": "家有 нь L5-ийн бүтэц"}], "mistakes": [{"wrong": "我想买一杯子。", "right": "我想买一个杯子。", "why_mn": "Тоо ба нэр үгийн хооронд тоо хэмжигч (个) заавал орно, орхигдуулж болохгүй."}]}, {"zh": "杯子", "pinyin": "bēizi", "teach_mn": "杯子 нь ундаа хийж уух сав — «аяга, стакан». Тоолохдоо 个 тоо хэмжигчтэй хамт хэрэглэнэ: 一个杯子. Дэлгүүрийн ярианд үнэ асуух жишээ болгон түгээмэл гардаг.", "usage_mn": ["Дэлгүүрт зүйл авах, юм тоолох жишээ болгон түгээмэл хэрэглэгддэг"], "examples": [{"zh": "我想买一个杯子。", "pinyin": "Wǒ xiǎng mǎi yí ge bēizi.", "mn": "Би нэг аяга авмаар байна.", "note_mn": "хамгийн энгийн хэрэглээ"}, {"zh": "这个杯子多少钱？", "pinyin": "Zhège bēizi duōshao qián?", "mn": "Энэ аяга ямар үнэтэй вэ?", "note_mn": "дэлгүүрт үнэ асуух"}, {"zh": "那个杯子18块钱。", "pinyin": "Nàge bēizi shíbā kuài qián.", "mn": "Тэр аяга 18 юань.", "note_mn": "үнэ хэлэх хариулт"}], "mistakes": [{"wrong": "我想买杯子一个。", "right": "我想买一个杯子。", "why_mn": "Тоо хэмжигчийн бүтэц «тоо + 个 + нэр үг» дараалалтай, нэр үгийн ард ордоггүй."}]}, {"zh": "这", "pinyin": "zhè", "teach_mn": "这 нь ярьж буй хүнд ойрхон байгаа зүйл, хүнийг заах заах төлөөний үг — «энэ». Ганцаараа бус ихэвчлэн 个-тэй хамт орж 这个 (энэ) гэж хэлдэг. Хол байгаа зүйлд эсрэг үг 那 (тэр) хэрэглэнэ.", "usage_mn": ["Ярьж буй хүнд ойрхон байгаа зүйл, хүнийг зааж хэлэхэд хэрэглэнэ", "Ихэвчлэн 个 тоо хэмжигчтэй хамт орж 这个 болно"], "examples": [{"zh": "这个杯子多少钱？", "pinyin": "Zhège bēizi duōshao qián?", "mn": "Энэ аяга ямар үнэтэй вэ?", "note_mn": "хамгийн түгээмэл хэрэглээ"}, {"zh": "这是茶。", "pinyin": "Zhè shì chá.", "mn": "Энэ бол цай.", "note_mn": "个-гүй, шууд 是-тэй хэрэглэсэн"}, {"zh": "这是我朋友。", "pinyin": "Zhè shì wǒ péngyou.", "mn": "Энэ бол миний найз.", "note_mn": "朋友 нь L4-ийн үг"}], "mistakes": [{"wrong": "个这杯子", "right": "这个杯子", "why_mn": "这 үргэлж 个-ийн өмнө ордог, дараалал өөрчлөгдөхгүй."}], "compare": [{"zh": "那", "pinyin": "nà", "mn": "тэр", "diff_mn": "这 ойрхон зүйлд, 那 хол зүйлд хэрэглэнэ — эсрэг заах төлөөний үг."}]}, {"zh": "多少", "pinyin": "duōshao", "teach_mn": "多少 нь тоо, хэмжээ асуух асуух үг, ялангуяа 10-аас дээш тоо асуухад хэрэглэнэ. Үнэ асуухдаа 多少钱 гэдэг тогтмол хэллэгийг байнга хэрэглэнэ. Өмнөх хичээлд үзсэн 几-ээс ялгаатай нь 几 бага тоонд (ихэвчлэн 10-аас доош), 多少 том тоо, эсвэл тоо тодорхойгүй үед хэрэглэгддэг.", "usage_mn": ["Тоо, үнэ, хэмжээ асуухад хэрэглэнэ, ялангуяа тоо их байж болзошгүй үед", "Ард нь тоо хэмжигч орж болно, заримдаа орхигддог: 多少个, 多少钱"], "examples": [{"zh": "这个杯子多少钱？", "pinyin": "Zhège bēizi duōshao qián?", "mn": "Энэ аяга ямар үнэтэй вэ?", "note_mn": "дэлгүүрийн хамгийн хэрэгтэй асуулт"}, {"zh": "你们学校有多少个学生？", "pinyin": "Nǐmen xuéxiào yǒu duōshao ge xuésheng?", "mn": "Танай сургууль хэдэн сурагчтай вэ?", "note_mn": "学校,学生 нь L3,L7-ийн үг"}, {"zh": "你有多少钱？", "pinyin": "Nǐ yǒu duōshao qián?", "mn": "Чамд хэдэн төгрөг байна?", "note_mn": "有 нь L5-ийн үг"}], "mistakes": [{"wrong": "你家有多少口人？", "right": "你家有几口人？", "why_mn": "Гэр бүлийн хүний тоо ихэвчлэн бага (10-аас цөөн) байдаг тул 几 хэрэглэнэ, том тоонд 多少 хэрэглэнэ."}], "compare": [{"zh": "几", "pinyin": "jǐ", "mn": "хэд (бага тоо)", "diff_mn": "几 нь ихэвчлэн 10-аас доош, аль хэдийн мэдэгдэж болзошгүй тоонд, 多少 том буюу тодорхойгүй тоонд хэрэглэнэ."}]}, {"zh": "钱", "pinyin": "qián", "teach_mn": "钱 нь «мөнгө» гэсэн нэр үг. Үнэ асуухад 多少钱 (ямар үнэтэй вэ) гэсэн хэллэгийн нэг хэсэг болж түгээмэл орно.", "usage_mn": ["Үнэ, мөнгөний хэмжээ асуух, хэлэхэд хэрэглэнэ"], "examples": [{"zh": "多少钱？", "pinyin": "Duōshao qián?", "mn": "Ямар үнэтэй вэ?", "note_mn": "хамгийн богино, тогтмол хэллэг"}, {"zh": "这个杯子多少钱？", "pinyin": "Zhège bēizi duōshao qián?", "mn": "Энэ аяга ямар үнэтэй вэ?", "note_mn": "зүйлийн нэртэй хамт"}, {"zh": "那个杯子18块钱。", "pinyin": "Nàge bēizi shíbā kuài qián.", "mn": "Тэр аяга 18 юань.", "note_mn": "钱 нь 块-ийн ард нэмэлт тодотгол болж орсон"}], "mistakes": [{"wrong": "钱多少？", "right": "多少钱？", "why_mn": "Асуух хэллэг 多少 нь 钱-ийн өмнө ордог тогтсон дараалалтай."}]}, {"zh": "块", "pinyin": "kuài", "teach_mn": "块 нь Хятадын мөнгөн тэмдэгтийн ярианы нэгж — бидний «төгрөг» шиг өдөр тутмын ярианд хэрэглэдэг үг. Бичгийн хэлбэр нь 元 (yuán) боловч ярианд бараг үргэлж 块-г хэрэглэдэг.", "usage_mn": ["Тоо шууд өмнө нь орж үнэ хэлэхэд хэрэглэнэ: 二十八块"], "examples": [{"zh": "28块。", "pinyin": "Èrshíbā kuài.", "mn": "28 юань.", "note_mn": "дэлгүүрийн хамгийн энгийн хариулт"}, {"zh": "那个杯子18块钱。", "pinyin": "Nàge bēizi shíbā kuài qián.", "mn": "Тэр аяга 18 юань.", "note_mn": "钱-тэй хамт хэлсэн бүтэн хэлбэр"}, {"zh": "一块钱", "pinyin": "yí kuài qián", "mn": "нэг юань", "note_mn": "一 нь 4-р хөгийн өмнө yí болсон"}], "mistakes": [{"wrong": "块二十八。", "right": "二十八块。", "why_mn": "Тоо 块-ийн өмнө ордог, ард нь орохгүй."}]}, {"zh": "那", "pinyin": "nà", "teach_mn": "那 нь ярьж буй хүнээс хол байгаа зүйл, хүнийг заах заах төлөөний үг — «тэр». 这 (энэ)-ийн эсрэг заах үг. Ихэвчлэн 个-тэй хамт орж 那个 гэж хэлдэг.", "usage_mn": ["Ярьж буй хүнээс хол байгаа зүйлийг зааж хэлэхэд хэрэглэнэ"], "examples": [{"zh": "那个杯子多少钱？", "pinyin": "Nàge bēizi duōshao qián?", "mn": "Тэр аяга ямар үнэтэй вэ?", "note_mn": "хамгийн түгээмэл хэрэглээ"}, {"zh": "那是我妈妈。", "pinyin": "Nà shì wǒ māma.", "mn": "Тэр бол миний ээж.", "note_mn": "妈妈 нь L6-гийн үг"}, {"zh": "那个杯子18块钱。", "pinyin": "Nàge bēizi shíbā kuài qián.", "mn": "Тэр аяга 18 юань.", "note_mn": "үнэ хэлэх хариулт"}], "mistakes": [{"wrong": "个那杯子", "right": "那个杯子", "why_mn": "那 үргэлж 个-ийн өмнө ордог, дараалал өөрчлөгдөхгүй."}], "compare": [{"zh": "这", "pinyin": "zhè", "mn": "энэ", "diff_mn": "那 хол зүйлд, 这 ойрхон зүйлд хэрэглэнэ — эсрэг заах төлөөний үг."}]}], "grammar": [{"point": "能愿动词 想", "gloss_mn": "хүсэх — «...маар байна»", "structure": "эзэн бие + 想 + үйл үг + (тусагдахуун)", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "想 бол «хүсэх» гэсэн санааны тусгай үйл үг (能愿动词). Өөрөө дангаараа бүтэн санаа болдоггүй — үргэлж өөр үйл үгийн өмнө орж түүнийг хийхийг хүсэж байгааг заана.", "example": {"zh": "我想喝茶。", "pinyin": "Wǒ xiǎng hē chá.", "mn": "Би цай уумаар байна."}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Эзэн бие + 想 + үйл үг + (тусагдахуун) гэсэн тогтсон дараалалтай: 我 + 想 + 喝 + 茶 = 我想喝茶.", "example": {"zh": "我+想+买+一个杯子", "pinyin": "Wǒ + xiǎng + mǎi + yí ge bēizi", "mn": "би + хүсэх + авах + нэг аяга"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Ямар нэг зүйл хиймээр байгаагаа, төлөвлөж байгаагаа хэлэхэд хэрэглэнэ — хоол захиалах, төлөвлөгөө хэлэлцэх зэрэгт өдөр бүр гардаг.", "example": {"zh": "下午我想去商店。", "pinyin": "Xiàwǔ wǒ xiǎng qù shāngdiàn.", "mn": "Үдээс хойш би дэлгүүр орох гэсэн юм."}}, {"title_mn": "4. Үгүйсгэл, асуулт", "body_mn": "Үгүйсгэхдээ 想-ийн өмнө 不-г нэмж 不想 гэнэ. Асуухдаа өгүүлбэрийн төгсгөлд 吗 нэмнэ.", "example": {"zh": "我不想吃米饭。", "pinyin": "Wǒ bù xiǎng chī mǐfàn.", "mn": "Би будаа идэхийг хүсэхгүй байна."}}], "examples": [{"zh": "我想喝茶。", "pinyin": "Wǒ xiǎng hē chá.", "mn": "Би цай уумаар байна."}, {"zh": "你想吃什么？", "pinyin": "Nǐ xiǎng chī shénme?", "mn": "Чи юу идмээр байна?"}, {"zh": "我想买一个杯子。", "pinyin": "Wǒ xiǎng mǎi yí ge bēizi.", "mn": "Би нэг аяга авмаар байна."}, {"zh": "下午我想去商店。", "pinyin": "Xiàwǔ wǒ xiǎng qù shāngdiàn.", "mn": "Үдээс хойш би дэлгүүр орох гэсэн юм."}, {"zh": "我不想吃米饭。", "pinyin": "Wǒ bù xiǎng chī mǐfàn.", "mn": "Би будаа идэхийг хүсэхгүй байна."}, {"zh": "你想喝茶吗？", "pinyin": "Nǐ xiǎng hē chá ma?", "mn": "Чи цай уумаар байна уу?"}, {"zh": "她想看书。", "pinyin": "Tā xiǎng kàn shū.", "mn": "Тэр ном унших хүсэлтэй байна."}], "mistakes": [{"wrong": "我喝想茶。", "right": "我想喝茶。", "why_mn": "想 нь үргэлж үйл үгийн өмнө ордог, ард нь биш."}, {"wrong": "我想不喝茶。", "right": "我不想喝茶。", "why_mn": "Үгүйсгэх 不 нь 想-ийн өмнө ордог, 想 болон үйл үгийн хооронд орохгүй."}], "drills": [{"type": "choice", "question": "我___喝茶。（хүсэлтэй байгаагаа хэлэх）", "options": ["想", "不", "吗"], "answer": "想", "why_mn": "想 нь хүсэл, төлөвлөгөө заана."}, {"type": "judge", "question": "想-ийн ард үргэлж өөр үйл үг байх ёстой.", "answer": "true", "why_mn": "想 дангаараа «хиймээр байна» гэсэн бүтэн санаа болдоггүй, ард нь заавал үйл үг ирнэ."}, {"type": "fill", "question": "«Би идэхийг хүсэхгүй байна» гэдгийг хятадаар бич (吃-г ашигла).", "answer": "我不想吃", "why_mn": "Үгүйсгэх 不 нь 想-ийн өмнө орно."}, {"type": "choice", "question": "你想___什么？（хоол идэхийг асуух）", "options": ["喝", "吃", "买"], "answer": "吃", "why_mn": "Хоол идэх гэдэгт 吃 хэрэглэнэ, 喝 биш."}]}, {"point": "疑问代词 多少", "gloss_mn": "10-аас дээш тоо, үнэ асуух — хэд, хэчнээн", "structure": "多少 + (量词) + нэр үг", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "多少 нь тоо хэмжээ асуух асуух үг, ялангуяа тоо их байж болзошгүй үед (10-аас дээш) хэрэглэнэ.", "example": {"zh": "多少钱？", "pinyin": "Duōshao qián?", "mn": "Ямар үнэтэй вэ?"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "多少-ийн ард шууд нэр үг орж болно, эсвэл 多少 + 个 + нэр үг гэж тоо хэмжигчтэй хамт орж болно — 个-г ихэвчлэн орхигдуулдаг.", "example": {"zh": "多少(个)学生", "pinyin": "duōshao (ge) xuésheng", "mn": "хэдэн сурагч"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Дэлгүүрт үнэ асуухад 多少钱 гэдэг хэллэгийг бараг үргэлж хэрэглэнэ. Хүний тоо, зүйлийн тоо асуухад бас хэрэглэнэ.", "example": {"zh": "这个杯子多少钱？", "pinyin": "Zhège bēizi duōshao qián?", "mn": "Энэ аяга ямар үнэтэй вэ?"}}, {"title_mn": "4. Ялгаа", "body_mn": "Бага тоо (ихэвчлэн 10-аас доош, жишээ нь гэр бүлийн хүний тоо) асуухад 几 хэрэглэдэг байсныг сана, харин 多少 том тоонд ч, тоо тодорхойгүй үед ч хэрэглэж болно.", "example": {"zh": "几口人 vs 多少个学生", "pinyin": "jǐ kǒu rén vs duōshao ge xuésheng", "mn": "хэдэн хүн (гэр бүл) vs хэдэн сурагч (сургууль)"}}], "examples": [{"zh": "这个杯子多少钱？", "pinyin": "Zhège bēizi duōshao qián?", "mn": "Энэ аяга ямар үнэтэй вэ?"}, {"zh": "你们学校有多少个学生？", "pinyin": "Nǐmen xuéxiào yǒu duōshao ge xuésheng?", "mn": "Танай сургууль хэдэн сурагчтай вэ?"}, {"zh": "多少钱？", "pinyin": "Duōshao qián?", "mn": "Ямар үнэтэй вэ?"}, {"zh": "那个杯子多少钱？", "pinyin": "Nàge bēizi duōshao qián?", "mn": "Тэр аяга ямар үнэтэй вэ?"}, {"zh": "你有多少钱？", "pinyin": "Nǐ yǒu duōshao qián?", "mn": "Чамд хэдэн төгрөг байна?"}, {"zh": "学校有多少老师？", "pinyin": "Xuéxiào yǒu duōshao lǎoshī?", "mn": "Сургуульд хэдэн багш байдаг вэ?"}], "mistakes": [{"wrong": "你家有多少口人？", "right": "你家有几口人？", "why_mn": "Гэр бүлийн хүний тоо ихэвчлэн бага (10-аас цөөн) байдаг тул 几 хэрэглэнэ, 多少 биш."}, {"wrong": "多少钱这个杯子？", "right": "这个杯子多少钱？", "why_mn": "多少钱 асуух хэллэг нь тухайн зүйлийн нэрийн ард ордог."}], "drills": [{"type": "choice", "question": "这个杯子___钱？", "options": ["几", "多少", "什么"], "answer": "多少", "why_mn": "Үнэ асуухад 多少钱 тогтмол хэллэг хэрэглэнэ."}, {"type": "judge", "question": "多少 нь зөвхөн жижиг тоонд хэрэглэгддэг.", "answer": "false", "why_mn": "多少 ялангуяа том тоонд, тоо тодорхойгүй үед хэрэглэгддэг."}, {"type": "fill", "question": "«Хэдэн сурагчтай вэ?» гэдгийг хятадаар бич.", "answer": "有多少个学生", "why_mn": "有 + 多少 + (个) + нэр үг гэсэн бүтэцтэй."}, {"type": "choice", "question": "Гэрийн гишүүдийн тоог асуухдаа ямар үг хэрэглэх вэ?", "options": ["多少", "几", "那"], "answer": "几", "why_mn": "Гэр бүлийн хүний тоо бага байдаг тул 几 хэрэглэнэ."}]}, {"point": "量词 个 / 口", "gloss_mn": "тоо хэмжигч үгс", "structure": "тоо + 个/口 + нэр үг", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "Хятад хэлэнд тоо ба нэр үгийн хооронд тоо хэмжигч (量词) заавал орох ёстой. 个 хамгийн түгээмэл, бараг бүх зүйлд хэрэглэж болно. 口 зөвхөн гэр бүлийн гишүүдийн тоог хэлэхэд ашиглагдана.", "example": {"zh": "个 / 口", "pinyin": "gè / kǒu", "mn": "ерөнхий тоо хэмжигч / гэр бүлийн хүн тоолох тоо хэмжигч"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Тоо + тоо хэмжигч + нэр үг гэсэн дараалалтай: 一个杯子, 三口人.", "example": {"zh": "三口人", "pinyin": "sān kǒu rén", "mn": "гурван хүн (гэр бүл)"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "个 өдөр тутмын ихэнх зүйлд (杯子, 学生, 人 гэх мэт), 口 зөвхөн гэр бүлийн хүн тоолоход л хэрэглэгдэнэ гэдгийг сана.", "example": {"zh": "我家有六口人。", "pinyin": "Wǒ jiā yǒu liù kǒu rén.", "mn": "Манай гэр бүл зургуулаа."}}, {"title_mn": "4. Ялгаа", "body_mn": "Монгол хэлэнд тоо хэмжигчийг зарим тохиолдолд л хэрэглэдэг («гурван хүн» гэхэд тоо хэмжигчгүй ч болно), харин хятад хэлэнд заавал байх ёстой.", "example": {"zh": "一个杯子", "pinyin": "yí ge bēizi", "mn": "нэг аяга (个-г орхиж болохгүй)"}}], "examples": [{"zh": "一个杯子", "pinyin": "yí ge bēizi", "mn": "нэг аяга"}, {"zh": "三个老师", "pinyin": "sān ge lǎoshī", "mn": "гурван багш"}, {"zh": "五个学生", "pinyin": "wǔ ge xuésheng", "mn": "таван сурагч"}, {"zh": "我家有六口人。", "pinyin": "Wǒ jiā yǒu liù kǒu rén.", "mn": "Манай гэр бүл зургуулаа."}, {"zh": "李老师家有六口人。", "pinyin": "Lǐ lǎoshī jiā yǒu liù kǒu rén.", "mn": "Ли багшийнх зургуулаа."}, {"zh": "这个杯子", "pinyin": "zhège bēizi", "mn": "энэ аяга"}], "mistakes": [{"wrong": "一杯子", "right": "一个杯子", "why_mn": "Тоо ба нэр үгийн хооронд тоо хэмжигч заавал орно."}, {"wrong": "三口老师", "right": "三个老师", "why_mn": "口 зөвхөн гэр бүлийн хүн тоолоход хэрэглэгддэг, багш нарт 个 хэрэглэнэ."}], "drills": [{"type": "choice", "question": "我家有五___人。", "options": ["个", "口", "这"], "answer": "口", "why_mn": "Гэр бүлийн хүн тоолоход 口 хэрэглэнэ."}, {"type": "fill", "question": "«нэг аяга» гэдгийг хятадаар бич.", "answer": "一个杯子", "why_mn": "тоо + 个 + нэр үг дараалалтай."}, {"type": "judge", "question": "个-г бараг бүх зүйл тоолоход хэрэглэж болно.", "answer": "true", "why_mn": "个 хамгийн түгээмэл, ерөнхий тоо хэмжигч."}, {"type": "choice", "question": "三___学生", "options": ["口", "个", "那"], "answer": "个", "why_mn": "Сурагч тоолоход ерөнхий тоо хэмжигч 个 хэрэглэнэ."}]}, {"point": "钱数的表达", "gloss_mn": "мөнгөний нэгж хэлэх — 块", "structure": "тоо + 块 + (钱)", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "Хятадын мөнгөн тэмдэгтийн үндсэн нэгжийг бичгээр 元 (yuán) гэдэг ч ярианд бараг үргэлж 块 (kuài) гэж хэлдэг.", "example": {"zh": "块", "pinyin": "kuài", "mn": "юань (ярианы нэгж)"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Тоо + 块 + (钱) гэсэн дараалалтай: 二十八块(钱).", "example": {"zh": "二十八块", "pinyin": "èrshíbā kuài", "mn": "28 юань"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Дэлгүүрт үнэ хэлэх, асуухад хэрэглэнэ — өдөр тутмын хамгийн хэрэгтэй хэллэгийн нэг.", "example": {"zh": "这个杯子多少钱？——二十八块。", "pinyin": "Zhège bēizi duōshao qián? — Èrshíbā kuài.", "mn": "Энэ аяга ямар үнэтэй вэ? — 28 юань."}}, {"title_mn": "4. Ялгаа", "body_mn": "Монгол хэлэнд «төгрөг» гэдэг мэт хятад хэлэнд ч ярианы нэгж (块) бичгийн нэгжээс (元) ялгаатай гэдгийг сана — Монгол хэлэнд ийм бичиг/ярианы хос нэгж байдаггүй тул шинэ ойлголт.", "example": {"zh": "元 (бичиг) / 块 (яриа)", "pinyin": "yuán / kuài", "mn": "хоёул «юань» гэсэн утгатай ч хэрэглэх орчин өөр"}}], "examples": [{"zh": "28块。", "pinyin": "Èrshíbā kuài.", "mn": "28 юань."}, {"zh": "一百块", "pinyin": "yìbǎi kuài", "mn": "100 юань"}, {"zh": "那个杯子18块钱。", "pinyin": "Nàge bēizi shíbā kuài qián.", "mn": "Тэр аяга 18 юань."}, {"zh": "一块钱", "pinyin": "yí kuài qián", "mn": "нэг юань"}, {"zh": "这个杯子多少钱？——二十八块。", "pinyin": "Zhège bēizi duōshao qián? — Èrshíbā kuài.", "mn": "Энэ аяга ямар үнэтэй вэ? — 28 юань."}], "mistakes": [{"wrong": "块二十八", "right": "二十八块", "why_mn": "Тоо 块-ийн өмнө ордог."}, {"wrong": "二十八元（ярианд）", "right": "二十八块（ярианд）", "why_mn": "元 бичгийн хэлбэр, ярианд 块-г хэрэглэдэг."}], "drills": [{"type": "fill", "question": "28 юань гэдгийг хятадаар бич.", "answer": "二十八块", "why_mn": "тоо + 块 дараалалтай."}, {"type": "judge", "question": "块 бол бичгийн хэлбэр, 元 ярианы хэлбэр.", "answer": "false", "why_mn": "Эсрэгээрээ — 元 бичгийн, 块 ярианы хэлбэр."}, {"type": "choice", "question": "Дэлгүүрт үнэ хэлэхэд ихэвчлэн юу хэрэглэдэг вэ?", "options": ["元", "块", "钱数"], "answer": "块", "why_mn": "Ярианд бараг үргэлж 块 хэрэглэдэг."}, {"type": "choice", "question": "二十八___。", "options": ["块", "个", "口"], "answer": "块", "why_mn": "Мөнгөний нэгж 块 хэрэглэнэ."}]}, {"point": "汉字 — 少 个, дээд-доод бүтэц, 钅/口 язгуур", "gloss_mn": "Ханзны бүтэц ба язгуур", "structure": "上下结构 (дээд-доод) · 左右结构 (зүүн-баруун) · 钅/口 язгуур", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "少 (цөөн) нь 多 (олон)-гийн эсрэг утгатай, 个 нь тоо хэмжигч. Хоёул HSK1-ийн энгийн, өргөн хэрэглэгддэг ханз.", "example": {"zh": "少 / 个", "pinyin": "shǎo / gè", "mn": "цөөн / ширхэг"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Ханзны бүтцийг дээд-доод (上下结构), зүүн-баруун (左右结构) гэх мэт ангилдаг. 是, 爸 нь дээд-доод хоёр хэсэгтэй; 茶 нь дээд-дунд-доод гурван давхаргатай.", "example": {"zh": "是 / 茶", "pinyin": "shì / chá", "mn": "дээд-доод / дээд-дунд-доод"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Ханзны бүтцийг мэдэх нь шинэ ханз цээжлэх, зөв бичихэд тусална — язгуураар нь утгыг таамаглаж болно: 钅 (метал) орсон ханз металтай холбоотой (钟 цаг, 钱 мөнгө), 口 (ам) орсон ханз амаар хийх үйлдэлтэй холбоотой (吃 идэх, 喝 уух).", "example": {"zh": "钱 / 吃", "pinyin": "qián / chī", "mn": "钅 металтай / 口 амтай холбоотой"}}, {"title_mn": "4. Өргөтгөл", "body_mn": "Ийм язгуураар ангилж сурвал шинэ ханз харах бүрдээ утгыг нь тодорхой хэмжээгээр таамаглаж чадна.", "example": {"zh": "钟", "pinyin": "zhōng", "mn": "цаг (钅 металтай холбоотой)"}}], "examples": [{"zh": "茶", "pinyin": "chá", "mn": "дээд-дунд-доод бүтэцтэй"}, {"zh": "吃 喝", "pinyin": "chī hē", "mn": "口 амтай холбоотой язгуур"}, {"zh": "钱", "pinyin": "qián", "mn": "钅 металтай холбоотой"}, {"zh": "是", "pinyin": "shì", "mn": "дээд-доод бүтэцтэй"}, {"zh": "爸", "pinyin": "bà", "mn": "дээд-доод бүтэцтэй"}, {"zh": "少", "pinyin": "shǎo", "mn": "小 дээр налуу зурлага нэмсэн бүтэцтэй"}], "mistakes": [{"wrong": "少 болон 多 ижил утгатай гэж андуурах", "right": "少 = цөөн, 多 = олон — эсрэг утгатай", "why_mn": "Хэлбэрээрээ ялгаатай ч утгыг андуурч болзошгүй, эсрэг утгатайг сайн санах хэрэгтэй."}, {"wrong": "钱-ийн зүүн тал нь язгуур биш гэж андуурах", "right": "钱-ий зүүн тал нь 钅 (метал) язгуур", "why_mn": "Зүүн-баруун бүтэцтэй ханзны язгуур ихэвчлэн зүүн талдаа байрладаг."}], "drills": [{"type": "choice", "question": "少 ямар ханзны эсрэг утгатай вэ?", "options": ["多", "大", "小"], "answer": "多", "why_mn": "少 (цөөн) 多 (олон)-той эсрэг утгатай."}, {"type": "judge", "question": "钅 язгуур металтай холбоотой ханзанд орно.", "answer": "true", "why_mn": "钟, 钱 зэрэг метал эдлэлтэй холбоотой ханзанд 钅 ордог."}, {"type": "choice", "question": "口 язгуур ямар утгатай холбоотой ханзанд ордог вэ?", "options": ["ам, идэх/уух", "мөнгө", "газар"], "answer": "ам, идэх/уух", "why_mn": "吃, 喝 зэрэг амаар хийх үйлдэлтэй холбоотой ханзанд 口 ордог."}, {"type": "fill", "question": "茶 ямар бүтэцтэй вэ? (дээд-доод/дээд-дунд-доод гэх мэт)", "answer": "дээд-дунд-доод", "why_mn": "茶 гурван давхаргатай — 艹 (дээр), 人 (дунд), 木 (доор)."}]}], "hanzi": [{"hanzi": "少", "pinyin": "shǎo", "meaning_mn": "цөөн, бага", "radical": {"c": "小", "meaning_mn": "жижиг", "role_mn": "утга дүрсэлж, цөөн тоог санагдуулна"}, "components": [{"c": "丿", "meaning_mn": "налуу зурлага", "role_mn": "小-ийн доор нэмэгдэж 少 болгоно"}], "story_mn": "少 нь 小 (жижиг) дээр налуу зурлага нэмсэн хэлбэртэй ханз — жижиг зүйл бүр цөөн байдаг тул «цөөн, бага» гэсэн санааг илэрхийлдэг гэж ойлгож болно. 多 (олон)-гийн шууд эсрэг утгатай.", "stroke_count": 4, "stroke_tips_mn": ["Эхлээд 小-г бич (дэгээ, дараа нь хоёр цэг)", "Хамгийн сүүлд доод налуу зурлагыг нэмнэ"], "confusable": [{"zh": "多", "pinyin": "duō", "mn": "олон", "diff_mn": "утгаараа эсрэг — 少 цөөн, 多 олон."}], "words": [{"zh": "多少", "pinyin": "duōshao", "mn": "хэд, хэчнээн"}, {"zh": "不少", "pinyin": "bù shǎo", "mn": "цөөнгүй"}]}, {"hanzi": "个", "pinyin": "gè", "meaning_mn": "ширхэг", "story_mn": "个 нь уламжлалт ханз 個-ийн хялбарчилсан хэлбэр. Дүрсээрээ дан ганц зогсож буй хүн шиг харагддаг тул «ганц, нэг ширхэг» гэсэн санааг илэрхийлдэг гэж ойлгож болно.", "stroke_count": 3, "stroke_tips_mn": ["Эхлээд дээд зүүн налуу зурлагыг тат", "Дараа нь баруун налуу зурлага, эцэст нь босоо зурлагыг тат"], "confusable": [{"zh": "人", "pinyin": "rén", "mn": "хүн", "diff_mn": "个-ийн дээд хэсэг 人-тай төстэй дүрстэй, гэхдээ доор нь босоо зурлага нэмэгдсэнээрээ ялгаатай."}], "words": [{"zh": "一个", "pinyin": "yí ge", "mn": "нэг ширхэг"}, {"zh": "这个", "pinyin": "zhège", "mn": "энэ"}, {"zh": "那个", "pinyin": "nàge", "mn": "тэр"}]}], "pronunciation": {"focus_mn": "Энэ хичээлд 3-р хөгтэй хоёр үг зэрэгцэхэд эхнийх нь 2-р хөг болж дуудагддаг дүрмийг (3+3 → 2+3) сайн ойлгож, 我想 гэдэг байнга давтагддаг хэллэгээр дадлагажаарай.", "drills": [{"title_mn": "3-р хөгийн хослол ялгах: 3+1/2/3/4", "instruction_mn": "手 (shǒu) гэдэг үгийг өөр өөр хөгтэй үгтэй хослуулж, хос бүрт эхний үений хөг хэрхэн өөрчлөгдөхийг анзаар.", "pairs": [{"a": {"zh": "手机", "pinyin": "shǒujī", "mn": "гар утас"}, "b": {"zh": "手镯", "pinyin": "shǒuzhuó", "mn": "бугуйвч"}, "note_mn": "手 хоёуланд нь 3-р хөгтэй ч ард нь ирэх хөгөөс шалтгаалж арай өөр аяар дуудагдана."}, {"a": {"zh": "手表", "pinyin": "shǒubiǎo", "mn": "бугуйн цаг"}, "b": {"zh": "手套", "pinyin": "shǒutào", "mn": "бээлий"}, "note_mn": "3+3 (shǒubiǎo) үед эхний 手 2-р хөг болж shóubiǎo гэж дуудагдана, харин 3+4 (shǒutào) үед 手 хэвийн 3-р хөгөөрөө үлдэнэ."}, {"a": {"zh": "我想", "pinyin": "wǒ xiǎng", "mn": "би хүсэж байна"}, "b": {"zh": "雨伞", "pinyin": "yǔsǎn", "mn": "шүхэр"}, "note_mn": "Хоёул 3+3 хослол тул эхний үг нь 2-р хөг болж дуудагдана: wó xiǎng, yúsǎn."}, {"a": {"zh": "老师", "pinyin": "lǎoshī", "mn": "багш"}, "b": {"zh": "老人", "pinyin": "lǎorén", "mn": "настан"}, "note_mn": "lǎo хоёулаа 3-р хөгөөрөө хэвээр үлдэнэ, учир нь зөвхөн 3+3 үед л 2-р хөг болдог."}]}, {"title_mn": "3+3 хослол дадлага: чиний мэддэг үгсээр", "instruction_mn": "Доорх хосуудыг аажим, дараа нь хурдан хэлж, 3-р хөг хэрхэн 2-р хөг рүү шилждэгийг мэдэр.", "pairs": [{"a": {"zh": "你好", "pinyin": "nǐ hǎo", "mn": "сайн уу"}, "b": {"zh": "我想", "pinyin": "wǒ xiǎng", "mn": "би хүсэж байна"}, "note_mn": "Хоёул 3+3 хослол — 你 ба 我 нь 2-р хөг болж (ní hǎo, wó xiǎng) дуудагдана."}, {"a": {"zh": "雨伞", "pinyin": "yǔsǎn", "mn": "шүхэр"}, "b": {"zh": "美好", "pinyin": "měihǎo", "mn": "сайхан"}, "note_mn": "雨 ба 美 нь 2-р хөг болж (yúsǎn, méihǎo) дуудагдана."}, {"a": {"zh": "洗澡", "pinyin": "xǐ zǎo", "mn": "усанд орох"}, "b": {"zh": "手表", "pinyin": "shǒubiǎo", "mn": "бугуйн цаг"}, "note_mn": "洗 ба 手 нь 2-р хөг болж (xízǎo, shóubiǎo) дуудагдана."}]}, {"title_mn": "Ойролцоо дуудлагатай үгсийг ялгах", "instruction_mn": "Хосыг дараалан чангаар хэлж, аялгын ялгааг чихээрээ мэдэр.", "pairs": [{"a": {"zh": "买", "pinyin": "mǎi", "mn": "худалдаж авах"}, "b": {"zh": "卖", "pinyin": "mài", "mn": "худалдах, зарах"}, "note_mn": "3-р хөг (буугаад дээшилнэ) ба 4-р хөг (огцом буудаг)-аар ялгаатай ойролцоо дуудлагатай хос."}, {"a": {"zh": "茶", "pinyin": "chá", "mn": "цай"}, "b": {"zh": "钱", "pinyin": "qián", "mn": "мөнгө"}, "note_mn": "Хоёул 2-р хөг (доороос дээш өгсдөг) — адил тэгш аяар дуудна."}, {"a": {"zh": "这", "pinyin": "zhè", "mn": "энэ"}, "b": {"zh": "那", "pinyin": "nà", "mn": "тэр"}, "note_mn": "Хоёул 4-р хөг — өндрөөс огцом буугаад тод дуудна."}, {"a": {"zh": "多少", "pinyin": "duōshao", "mn": "хэд"}, "b": {"zh": "少", "pinyin": "shǎo", "mn": "цөөн"}, "note_mn": "多少 доторх 少 нь хөнгөрч сул хөгөөр (轻声-д ойр) дуудагдах хандлагатай — иймд pinyin дээр хөгийн тэмдэггүй бичигдсэн байгааг ажигла."}]}], "tips_mn": ["想 гэдэг үгээ 3-р хөгөөр тод дуудаж сур, учир нь энэ үг хичээл даяар байнга давтагддаг.", "多少钱 хэллэгийг нэг амьсгаагаар, дундуур нь тасалгаагүй хэлж дадлагажаарай.", "买 (худалдаж авах) ба 卖 (зарах)-ыг андуурахгүйн тулд аялгын өндөр-нам, чиглэлийг тодорхой ялгаж дуудаарай.", "这/那-г хэлэхдээ 4-р хөгийг эхнээсээ өндрөөс огцом бууж эхэл."]}}'::jsonb)
