values ('hsk1-l09', 1, '{"words": [{"zh": "小", "pinyin": "xiǎo", "teach_mn": "小 нь «жижиг, бяцхан» гэсэн тэмдэг нэр, өмнөх хичээлд үзсэн 大 (том)-ын эсрэг утгатай. Нэр үгийн өмнө орж тодотгол болно: 小猫 (бяцхан муур), 小狗 (гөлөг). Амьтны нэрийн өмнө орвол ихэвчлэн эрхлүүлсэн, дотно өнгө аяс өгдөг.", "usage_mn": ["Амьтан, зүйлийн жижиг, бяцхан гэдгийг тодотгож хэлэхэд нэр үгийн өмнө орно"], "examples": [{"zh": "小猫在哪儿？", "pinyin": "Xiǎo māo zài nǎr?", "mn": "Бяцхан муур хаана байна?", "note_mn": "小猫 хосолсон хэлбэр"}, {"zh": "小狗在椅子下面。", "pinyin": "Xiǎo gǒu zài yǐzi xiàmiàn.", "mn": "Гөлөг сандлын доор байна.", "note_mn": "小狗 хосолсон хэлбэр"}, {"zh": "这个杯子很小。", "pinyin": "Zhège bēizi hěn xiǎo.", "mn": "Энэ аяга жижигхэн.", "note_mn": "很 (L6), 这个/杯子 (L8)-той хамт"}], "mistakes": [{"wrong": "猫小在哪儿？", "right": "小猫在哪儿？", "why_mn": "Тодотгол үг (小) нэр үгийн (猫) өмнө ордог, ард нь орохгүй."}], "compare": [{"zh": "大", "pinyin": "dà", "mn": "том", "diff_mn": "小 (жижиг) 大 (том)-ын эсрэг утгатай."}]}, {"zh": "猫", "pinyin": "māo", "teach_mn": "猫 нь «муур» гэсэн нэр үг. Гэрийн тэжээвэр амьтдын нэрсийн нэг бөгөөд байршил заах өгүүлбэрт түгээмэл жишээ болдог.", "usage_mn": ["Амьтны нэр болгон хэрэглэнэ, ихэвчлэн 小猫 гэж хосолж хэлнэ"], "examples": [{"zh": "小猫在哪儿？", "pinyin": "Xiǎo māo zài nǎr?", "mn": "Бяцхан муур хаана байна?", "note_mn": "асуух хэлбэр"}, {"zh": "小猫在那儿。", "pinyin": "Xiǎo māo zài nàr.", "mn": "Муур тэнд байна.", "note_mn": "хариулах хэлбэр"}, {"zh": "我的猫呢？", "pinyin": "Wǒ de māo ne?", "mn": "Миний муур хаачив?", "note_mn": "的 нь L4-ийн үг"}], "mistakes": [{"wrong": "猫在哪儿小？", "right": "小猫在哪儿？", "why_mn": "小 (тодотгол) нэр үгийн (猫) өмнө шууд ордог, ард нь орохгүй."}]}, {"zh": "在", "pinyin": "zài", "teach_mn": "在 хоёр үүрэгтэй: (1) «байна» гэсэн бие даасан үйл үг (жишээ нь 他在医院 — тэр эмнэлэгт байгаа), (2) газар заасан угтвар үг («-д, -т» гэсэн утгатай, жишээ нь 他在医院工作 — тэр эмнэлэгт ажилладаг). Монгол хэлэнд «-д, -т» гэдэг нөхцөл нэр үгэнд шууд залгадаг бол хятад хэлэнд тусдаа 在 гэдэг үг хэрэглэдэг нь эрс ялгаатай, шинэ ойлголт.", "usage_mn": ["Хүн, юмны байгаа газрыг илэрхийлэхэд бие даасан үйл үг болгон хэрэглэнэ", "Үйл ажиллагаа явагдаж буй газрыг заахад үйл үгийн өмнө угтвар үг болгон хэрэглэнэ"], "examples": [{"zh": "我妈妈在家。", "pinyin": "Wǒ māma zài jiā.", "mn": "Ээж маань гэртээ байгаа.", "note_mn": "妈妈 (L6), 家 (L5)-той хамт"}, {"zh": "小狗在椅子下面。", "pinyin": "Xiǎo gǒu zài yǐzi xiàmiàn.", "mn": "Гөлөг сандлын доор байна.", "note_mn": "байршлын дэлгэрэнгүй тодотголтой"}, {"zh": "我儿子在医院工作。", "pinyin": "Wǒ érzi zài yīyuàn gōngzuò.", "mn": "Хүү маань эмнэлэгт ажилладаг.", "note_mn": "угтвар үгийн хэрэглээ"}, {"zh": "他在学校看书。", "pinyin": "Tā zài xuéxiào kàn shū.", "mn": "Тэр сургуульд ном уншиж байна.", "note_mn": "学校,看书 нь L7-гийн үгс"}], "mistakes": [{"wrong": "工作在学校。", "right": "在学校工作。", "why_mn": "在 + газар нь үйл үгийн (工作) өмнө ордог, ард нь орохгүй."}, {"wrong": "我在。（дутуу）", "right": "我在家。", "why_mn": "«байна» гэсэн 在-ийн ард ихэвчлэн байрлал заасан үг ирнэ, дангаараа дутуу үлдээхгүй."}]}, {"zh": "那儿", "pinyin": "nàr", "teach_mn": "那儿 нь «тэнд» гэсэн байршил заасан үг, ярьж буй хүнээс хол газрыг заана. 那 (тэр)-ийн ард 儿 залгаснаар байршлын утгатай болсон.", "usage_mn": ["Хол байгаа газрыг зааж хэлэхэд 在-тэй хамт хэрэглэнэ"], "examples": [{"zh": "小猫在那儿。", "pinyin": "Xiǎo māo zài nàr.", "mn": "Муур тэнд байна.", "note_mn": "хамгийн энгийн хэрэглээ"}, {"zh": "我朋友在那儿。", "pinyin": "Wǒ péngyou zài nàr.", "mn": "Найз маань тэнд байна.", "note_mn": "朋友 нь L4-ийн үг"}, {"zh": "他在那儿工作。", "pinyin": "Tā zài nàr gōngzuò.", "mn": "Тэр тэнд ажилладаг.", "note_mn": "工作-тай хамт"}], "mistakes": [{"wrong": "那儿猫在。", "right": "猫在那儿。", "why_mn": "在 + байршил нь өгүүлбэрийн төгсгөлд ирдэг тогтсон дараалалтай."}], "compare": [{"zh": "哪儿", "pinyin": "nǎr", "mn": "хаана", "diff_mn": "дуудлага төстэй ч 那儿 (4-р хөг, тэнд) 哪儿 (3-р хөг, хаана) эсрэг үүрэгтэй — сайн ялгаж сур."}]}, {"zh": "狗", "pinyin": "gǒu", "teach_mn": "狗 нь «нохой» гэсэн нэр үг. 小狗 гэвэл эрхэлүүлэн «гөлөг» гэсэн санаа өгдөг.", "usage_mn": ["Амьтны нэр болгон хэрэглэнэ"], "examples": [{"zh": "小狗在哪儿？", "pinyin": "Xiǎo gǒu zài nǎr?", "mn": "Гөлөг хаана байна?", "note_mn": "асуух хэлбэр"}, {"zh": "小狗在椅子下面。", "pinyin": "Xiǎo gǒu zài yǐzi xiàmiàn.", "mn": "Гөлөг сандлын доор байна.", "note_mn": "байрлалын тодотголтой"}, {"zh": "那是我的狗。", "pinyin": "Nà shì wǒ de gǒu.", "mn": "Тэр бол миний нохой.", "note_mn": "那,是,的-той хамт"}], "mistakes": [{"wrong": "狗小在哪儿？", "right": "小狗在哪儿？", "why_mn": "Тодотгол (小) нэр үгийн (狗) өмнө ордог."}]}, {"zh": "椅子", "pinyin": "yǐzi", "teach_mn": "椅子 нь «сандал» гэсэн нэр үг, өдөр тутмын тавилгын нэр. Байршил заахад 椅子下面 (сандлын доор) гэх мэт байрлал заасан үгтэй хамт хэрэглэгддэг.", "usage_mn": ["Тавилгын нэр болгон, ялангуяа байрлал заахад хэрэглэнэ"], "examples": [{"zh": "小狗在椅子下面。", "pinyin": "Xiǎo gǒu zài yǐzi xiàmiàn.", "mn": "Гөлөг сандлын доор байна.", "note_mn": "хамгийн түгээмэл хэрэглээ"}, {"zh": "椅子下面", "pinyin": "yǐzi xiàmiàn", "mn": "сандлын доор", "note_mn": "байршлын хэсэг үг"}, {"zh": "这个椅子很小。", "pinyin": "Zhège yǐzi hěn xiǎo.", "mn": "Энэ сандал жижигхэн.", "note_mn": "这个 (L8), 很 (L6)-той хамт"}], "mistakes": [{"wrong": "下面椅子有狗。", "right": "椅子下面有狗。", "why_mn": "Байрлал заах бүтэц «зүйл + 下面» дараалалтай, монгол хэлний «сандлын доор»-той адил."}]}, {"zh": "下面", "pinyin": "xiàmiàn", "teach_mn": "下面 нь «доор, доод тал» гэсэн байрлал заасан үг. Нэр үгийн ард орж «... доор» гэсэн байршил үүсгэнэ: 椅子下面 (сандлын доор).", "usage_mn": ["Ямар нэг зүйлийн доод талд байгааг заахад нэр үгийн ард хэрэглэнэ"], "examples": [{"zh": "椅子下面", "pinyin": "yǐzi xiàmiàn", "mn": "сандлын доор", "note_mn": "хамгийн энгийн хэлбэр"}, {"zh": "小狗在椅子下面。", "pinyin": "Xiǎo gǒu zài yǐzi xiàmiàn.", "mn": "Гөлөг сандлын доор байна.", "note_mn": "在-тэй хамт хэрэглэсэн бүтэн өгүүлбэр"}, {"zh": "猫在下面。", "pinyin": "Māo zài xiàmiàn.", "mn": "Муур доор байна.", "note_mn": "在-тай хамт энгийн хэлбэр"}], "mistakes": [{"wrong": "狗下面椅子。", "right": "狗在椅子下面。", "why_mn": "在 + зүйл + 下面 гэсэн бүтэц дутуу орхигдвол өгүүлбэр буруу болно."}]}, {"zh": "哪儿", "pinyin": "nǎr", "teach_mn": "哪儿 нь байршил асуух асуух үг — «хаана». 那儿 (тэнд)-тэй дуудлага төстэй ч 哪儿 3-р хөгтэй (асуулт), 那儿 4-р хөгтэй (заах) гэдгээрээ ялгаатай.", "usage_mn": ["Хүн, юмны байрлалыг асуухад 在-тэй хамт хэрэглэнэ"], "examples": [{"zh": "你在哪儿工作？", "pinyin": "Nǐ zài nǎr gōngzuò?", "mn": "Чи хаана ажилладаг вэ?", "note_mn": "хамгийн түгээмэл асуулт"}, {"zh": "小猫在哪儿？", "pinyin": "Xiǎo māo zài nǎr?", "mn": "Муур хаана байна?", "note_mn": "энгийн байршил асуух"}, {"zh": "你儿子在哪儿工作？", "pinyin": "Nǐ érzi zài nǎr gōngzuò?", "mn": "Хүү чинь хаана ажилладаг вэ?", "note_mn": "儿子-той хамт"}], "mistakes": [{"wrong": "你工作在哪儿？", "right": "你在哪儿工作？", "why_mn": "在 + 哪儿 нь үйл үгийн (工作) өмнө ордог."}], "compare": [{"zh": "那儿", "pinyin": "nàr", "mn": "тэнд", "diff_mn": "哪儿 (3-р хөг) асуулт «хаана», 那儿 (4-р хөг) заах «тэнд» — дуудлага төстэй тул сайн ялга."}]}, {"zh": "工作", "pinyin": "gōngzuò", "teach_mn": "工作 нь үйл үг болон нэр үг хоёр янзаар хэрэглэгддэг — «ажиллах» (үйл үг) эсвэл «ажил» (нэр үг). 在 + газар-тай хамт орж «хаана ажилладаг» гэдгийг илэрхийлнэ.", "usage_mn": ["Хаана ажилладагаа хэлэхдээ 在 + газар + 工作 гэсэн бүтцээр хэрэглэнэ", "Нэр үг болгон «ажил» гэсэн утгаар ч хэрэглэж болно"], "examples": [{"zh": "我在学校工作。", "pinyin": "Wǒ zài xuéxiào gōngzuò.", "mn": "Би сургуульд ажилладаг.", "note_mn": "在+газар+工作 бүтэц"}, {"zh": "你在哪儿工作？", "pinyin": "Nǐ zài nǎr gōngzuò?", "mn": "Чи хаана ажилладаг вэ?", "note_mn": "асуух хэлбэр"}, {"zh": "我儿子在医院工作。", "pinyin": "Wǒ érzi zài yīyuàn gōngzuò.", "mn": "Хүү маань эмнэлэгт ажилладаг.", "note_mn": "儿子-тэй хамт"}], "mistakes": [{"wrong": "我工作在学校。", "right": "我在学校工作。", "why_mn": "在 + газар нь 工作-ийн өмнө ордог, ард нь орохгүй."}]}, {"zh": "儿子", "pinyin": "érzi", "teach_mn": "儿子 нь «хүү (үр)» гэсэн нэр үг — гэр бүлийн гишүүний нэрсийн нэг. Өмнөх хичээлд үзсэн 女儿 (охин)-гийн эсрэг ойлголт.", "usage_mn": ["Гэр бүлийн гишүүнийхээ тухай ярихдаа нэр үг болгон хэрэглэнэ"], "examples": [{"zh": "你儿子在哪儿工作？", "pinyin": "Nǐ érzi zài nǎr gōngzuò?", "mn": "Хүү чинь хаана ажилладаг вэ?", "note_mn": "хамгийн түгээмэл хэрэглээ"}, {"zh": "我儿子在医院工作。", "pinyin": "Wǒ érzi zài yīyuàn gōngzuò.", "mn": "Хүү маань эмнэлэгт ажилладаг.", "note_mn": "хариулах хэлбэр"}, {"zh": "他儿子是医生。", "pinyin": "Tā érzi shì yīshēng.", "mn": "Түүний хүү эмч.", "note_mn": "是,医生-тэй хамт"}], "mistakes": [{"wrong": "儿子你在哪儿工作？", "right": "你儿子在哪儿工作？", "why_mn": "Эзэмшигч (你) нэр үгийн (儿子) өмнө ордог."}], "compare": [{"zh": "女儿", "pinyin": "nǚ''ér", "mn": "охин", "diff_mn": "儿子 хүү, 女儿 охин — эсрэг хүйсийн үр хүүхэд."}]}, {"zh": "医院", "pinyin": "yīyuàn", "teach_mn": "医院 нь «эмнэлэг» гэсэн газрын нэр. 医 (эмчлэх) ба 院 (байгууллага, хашаа) хоёр ханзнаас тогтоно.", "usage_mn": ["Ажлын газар, очих газрын нэр болгон хэрэглэнэ"], "examples": [{"zh": "我儿子在医院工作。", "pinyin": "Wǒ érzi zài yīyuàn gōngzuò.", "mn": "Хүү маань эмнэлэгт ажилладаг.", "note_mn": "工作-тэй хамт"}, {"zh": "他在医院。", "pinyin": "Tā zài yīyuàn.", "mn": "Тэр эмнэлэгт байгаа.", "note_mn": "байршил заасан энгийн хэлбэр"}, {"zh": "医院在哪儿？", "pinyin": "Yīyuàn zài nǎr?", "mn": "Эмнэлэг хаана байдаг вэ?", "note_mn": "在哪儿-тэй хамт"}], "mistakes": [{"wrong": "医院工作在。", "right": "在医院工作。", "why_mn": "在 + газар нь 工作-ийн өмнө ирдэг тогтсон дараалалтай."}]}, {"zh": "医生", "pinyin": "yīshēng", "teach_mn": "医生 нь «эмч» гэсэн мэргэжлийн нэр. 医院 (эмнэлэг)-тэй хамт цээжлэхэд амархан — эмч эмнэлэгт ажилладаг гэдгийг санаж болно.", "usage_mn": ["Хүний мэргэжлийг хэлэхдээ 是-тэй хамт хэрэглэнэ"], "examples": [{"zh": "他是医生。", "pinyin": "Tā shì yīshēng.", "mn": "Тэр эмч.", "note_mn": "是-тэй хамт мэргэжил хэлсэн"}, {"zh": "我儿子在医院工作，他是医生。", "pinyin": "Wǒ érzi zài yīyuàn gōngzuò, tā shì yīshēng.", "mn": "Хүү маань эмнэлэгт ажилладаг, тэр эмч.", "note_mn": "医院,医生-г хамт хэрэглэсэн"}, {"zh": "我爸爸是医生。", "pinyin": "Wǒ bàba shì yīshēng.", "mn": "Аав маань эмч.", "note_mn": "爸爸,是-тэй хамт"}], "mistakes": [{"wrong"