": {"zh": "我+在+学校+工作", "pinyin": "wǒ + zài + xuéxiào + gōngzuò", "mn": "би + -д + сургууль + ажиллах"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Хаана ямар үйл ажиллагаа явуулж байгаагаа хэлэхэд — ялангуяа хаана ажилладаг, юу хийж байгааг ярихад хэрэглэнэ.", "example": {"zh": "我儿子在医院工作。", "pinyin": "Wǒ érzi zài yīyuàn gōngzuò.", "mn": "Хүү маань эмнэлэгт ажилладаг."}}, {"title_mn": "4. Ялгаа", "body_mn": "Монгол хэлэнд «сургуульд ажилладаг» гэвэл нэр үгэнд шууд «-д» нөхцөл залгадаг бол хятад хэлэнд 在-г үйл үгийн өмнө тусад нь бичих ёстой — 工作在学校 гэж ард нь бичиж болохгүй.", "example": {"zh": "在学校工作 (✓) / 工作在学校 (✗)", "pinyin": "zài xuéxiào gōngzuò", "mn": "сургуульд ажиллах"}}], "examples": [{"zh": "他们在学校看书。", "pinyin": "Tāmen zài xuéxiào kàn shū.", "mn": "Тэд сургуульд ном уншиж байна."}, {"zh": "我儿子在医院工作。", "pinyin": "Wǒ érzi zài yīyuàn gōngzuò.", "mn": "Хүү маань эмнэлэгт ажилладаг."}, {"zh": "我在学校工作。", "pinyin": "Wǒ zài xuéxiào gōngzuò.", "mn": "Би сургуульд ажилладаг."}, {"zh": "我在朋友家喝茶。", "pinyin": "Wǒ zài péngyou jiā hē chá.", "mn": "Би найзындаа цай ууж байна."}, {"zh": "你在哪儿工作？", "pinyin": "Nǐ zài nǎr gōngzuò?", "mn": "Чи хаана ажилладаг вэ?"}], "mistakes": [{"wrong": "我工作在学校。", "right": "我在学校工作。", "why_mn": "在 + газар нь үйл үгийн өмнө ордог, ард нь орохгүй."}, {"wrong": "我儿子工作在医院。", "right": "我儿子在医院工作。", "why_mn": "Дараалал ижил алдаа — 在 + газар нь 工作-ийн өмнө ирнэ."}], "drills": [{"type": "choice", "question": "我___学校工作。", "options": ["是", "在", "有"], "answer": "在", "why_mn": "Газар заасан угтвар үг 在 хэрэглэнэ."}, {"type": "fill", "question": "«Тэд сургуульд ном уншиж байна» гэдгийг хятадаар бич.", "answer": "他们在学校看书", "why_mn": "在 + газар + үйл үг дараалалтай."}, {"type": "judge", "question": "在 + газар нь үйл үгийн ард ч, өмнө ч орж болно.", "answer": "false", "why_mn": "Зөвхөн үйл үгийн өмнө ордог, ард нь орохгүй."}, {"type": "choice", "question": "我儿子___医院工作。", "options": ["在", "那儿", "个"], "answer": "在", "why_mn": "Газар заах угтвар үг 在