бол зүүн-баруун бүтэцтэй гэж андуурах", "right": "医 хагас бүслэх бүтэцтэй, гадна тал нь дотоод хэсгээ хажуугаас хүрээлдэг", "why_mn": "Хагас бүслэх бүтэц нь зүүн-баруун, дээд-доодоос ялгаатай, нэг хэсэг нь нөгөөгөө хагас хүрээлдэгт оршино."}, {"wrong": "门 язгуур зөвхөн шууд «хаалга» гэсэн утгаар л орно гэж андуурах", "right": "门 язгуур байшин, өрөө, орох гарахтай холбоотой өргөн утгаар орно (问, 间)", "why_mn": "Язгуурын утга ихэвчлэн өргөжиж, шууд бус холбоотой ойлголтуудад ч ордог."}], "drills": [{"type": "choice", "question": "辶 язгуур ямар утгатай холбоотой вэ?", "options": ["алхах, хөдөлгөөн", "мөнгө", "ус"], "answer": "алхах, хөдөлгөөн", "why_mn": "这, 送 зэрэг хөдөлгөөнтэй холбоотой ханзанд 辶 ордог."}, {"type": "judge", "question": "门 язгуур орсон бүх ханз шууд «хаалга» гэсэн утгатай.", "answer": "false", "why_mn": "问 (асуух), 间 (өрөө) шиг холбоотой боловч шууд бус утгатай ч байж болно."}, {"type": "choice", "question": "医 ямар бүтэцтэй ханз вэ?", "options": ["зүүн-баруун", "хагас бүслэх", "дээд-доод"], "answer": "хагас бүслэх", "why_mn": "医-ийн гадна тал дотоод хэсгээ хагас хүрээлдэг."}, {"type": "fill", "question": "这, 送 ямар язгуур хуваалцдаг вэ?", "answer": "辶", "why_mn": "Хоёул хөдөлгөөнтэй холбоотой 辶 язгууртай."}]}], "hanzi": [{"hanzi": "在", "pinyin": "zài", "meaning_mn": "байх", "radical": {"c": "土", "meaning_mn": "шороо, газар", "role_mn": "доод хэсэгт орж газар дэвсгэрийг санагдуулна"}, "components": [{"c": "才", "meaning_mn": "дөнгөж эхлэх", "role_mn": "дээд хэсгийг бүрдүүлж дуудлагад нөлөөлнө"}], "story_mn": "在 нь дээд хэсэгтээ 才, доод хэсэгтээ 土 (шороо, газар) орсон ханз — амьд юм газар дээр «оршин байдаг» гэсэн санааг илэрхийлдэг гэж тайлбарлаж болно.", "stroke_count": 6, "stroke_tips_mn": ["Эхлээд дээд налуу зурлагаас эхэл", "Доод 土 хэсгийг зүүнээс баруун, дээрээс доош дараалалтай бич"], "confusable": [{"zh": "再", "pinyin": "zài", "mn": "дахин", "diff_mn": "ижил дуудлагатай ч 在 «байх», 再 «дахин» гэсэн огт өөр утгатай, доод хэсэг нь 土 биш."}], "words": [{"zh": "在家", "pinyin": "zài jiā", "mn": "гэртээ байх"}, {"zh": "现在", "pinyin": "xiànzài", "mn": "одоо"}]}, {"hanzi": "子", "pinyin": "zǐ", "meaning_mn": "хүүхэд", "story_mn": "子 нь эрт цагт эрхээ дэлгэсэн, толгойгоо томруулан зурсан нярай хүүхдийн энгийн дүрснээс гаралтай гэж үздэг.", "stroke_count": 3, "stroke_tips_mn": ["Эхлээд дээд эргэлдсэн зурлагыг тат", "Дараа нь босоо дэгээ, эцэст нь доод хэвтээ зурлагыг тат"], "confusable": [{"zh": "字", "pinyin": "zì", "mn": "үсэг", "diff_mn": "子 дээр 宀 (дээвэр) нэмэгдвэл 字 (үсэг, бичиг) болно."}], "words": [{"zh": "儿子", "pinyin": "érzi", "mn": "хүү"}, {"zh": "孩子", "pinyin": "háizi", "mn": "хүүхэд"}]}, {"hanzi": "工", "pinyin": "gōng", "meaning_mn": "ажил", "story_mn": "工 нь дархны хэрэглэдэг тэгш өнцгийн хэмжүүр багажны дүрснээс гаралтай гэж үздэг — ажил хийхэд хэрэглэдэг багаж тул «ажил, хөдөлмөр» гэсэн утгатай болжээ.", "stroke_count": 3, "stroke_tips_mn": ["Эхлээд дээд хэвтээ зурлагыг зүүнээс баруун тийш тат", "Дараа нь дундуур босоо зурлага, эцэст нь доод хэвтээ зурлагыг тат"], "confusable": [{"zh": "土", "pinyin": "tǔ", "mn": "шороо, хөрс", "diff_mn": "工-ийн хоёр хэвтээ зурлага ойролцоо уртай байдаг бол 土-д доод хэвтээ зурлага илүү урт бөгөөд дунд хэсгээс нь босоо зурлага доош гарч ирдэг."}], "words": [{"zh": "工作", "pinyin": "gōngzuò", "mn": "ажил, ажиллах"}, {"zh": "工人", "pinyin": "gōngrén", "mn": "ажилчин"}]}], "pronunciation": {"focus_mn": "Энэ хичээлд 4-р хөгөөр эхэлсэн хоёр үет үгсийн хослолд анхаараарай — 4-р хөг үргэлж өндрөөс огцом бууна, ард нь ирэх хөгөөс үл хамааран энэ шинж чанараа хадгална. 医院, 医生 гэдэг шинэ үгсээ 1-р хөгөөр тод, тэгш дуудахыг бас дадлагажаарай.", "drills": [{"title_mn": "4-р хөгийн хослол: 4+1/2/3/4", "instruction_mn": "电 (diàn, цахилгаан) гэдэг үгийг өөр өөр хөгтэй үгтэй хослуулж, 4-р хөг тогтвортой хэвээрээ байгааг ажигла.", "pairs": [{"a": {"zh": "电灯", "pinyin": "diàndēng", "mn": "чийдэн"}, "b": {"zh": "电池", "pinyin": "diànchí", "mn": "батарей"}, "note_mn": "电 хоёуланд нь 4-р хөгтэй, ард нь 1-р ба 2-р хөг ирсэн ч 电 өөрчлөгдөхгүй."}, {"a": {"zh": "电影", "pinyin": "diànyǐng", "mn": "кино"}, "b": {"zh": "电视", "pinyin": "diànshì", "mn": "зурагт"}, "note_mn": "电 нь 3-р ба 4-р хөгийн өмнө ч мөн адил огцом буудаг 4-р хөгөөрөө хэвээр үлдэнэ."}, {"a": {"zh": "电脑", "pinyin": "diànnǎo", "mn": "компьютер"}, "b": {"zh": "电话", "pinyin": "diànhuà", "mn": "утас"}, "note_mn": "diànnǎo нь 4+3, diànhuà нь 4+4 хослол — 电 хоёуланд нь тогтвортой 4-р хөгөөрөө үлдэнэ."}]}, {"title_mn": "医-тэй үгс болон бусад 1-р хөгийн хослол", "instruction_mn": "医院, 医生-г хамт цээжилж, 医-ийн 1-р хөгийг өндөр тэгш дуудахад анхаар.", "pairs": [{"a": {"zh": "医院", "pinyin": "yīyuàn", "mn": "эмнэлэг"}, "b": {"zh": "医生", "pinyin": "yīshēng", "mn": "эмч"}, "note_mn": "医 хоёуланд нь 1-р хөгтэй, эхнийх нь 1+4, хоёр дахь нь 1+1 хослол."}, {"a": {"zh": "工作", "pinyin": "gōngzuò", "mn": "ажил"}, "b": {"zh": "中国", "pinyin": "Zhōngguó", "mn": "хятад улс"}, "note_mn": "工,中 хоёул 1-р хөгөөр эхэлдэг ч ард нь ирэх хөг өөр (1+4, 1+2)."}, {"a": {"zh": "今天", "pinyin": "jīntiān", "mn": "өнөөдөр"}, "b": {"zh": "星期", "pinyin": "xīngqī", "mn": "долоо хоног"}, "note_mn": "Хоёул 1+1 хослол — өмнөх хичээлд үзсэн, өндөр тэгш аяараа хэвээр давт."}]}, {"title_mn": "Ойролцоо дуудлагатай үгсийг ялгах", "instruction_mn": "Хосыг дараалан хэлж, аялгын ялгааг чихээрээ мэдэр.", "pairs": [{"a": {"zh": "哪儿", "pinyin": "nǎr", "mn": "хаана"}, "b": {"zh": "那儿", "pinyin": "nàr", "mn": "тэнд"}, "note_mn": "哪儿 3-р хөг (буугаад дээшилнэ, асуулт), 那儿 4-р хөг (огцом буудаг, заах) — эсрэг үүрэгтэй ойролцоо дуудлагатай хос."}, {"a": {"zh": "小", "pinyin": "xiǎo", "mn": "жижиг"}, "b": {"zh": "少", "pinyin": "shǎo", "mn": "цөөн"}, "note_mn": "Хоёул 3-р хөг ба ойролцоо дуудлагатай — 小 тэмдэг нэр (жижиг), 少 тоо хэмжээ (цөөн)."}, {"a": {"zh": "儿子", "pinyin": "érzi", "mn": "хүү"}, "b": {"zh": "椅子", "pinyin": "yǐzi", "mn": "сандал"}, "note_mn": "儿 (2-р хөг) ба 椅 (3-р хөг), 子 хоёуланд нь хөнгөрсөн (轻声) дуудагдана."}, {"a": {"zh": "爸爸", "pinyin": "bàba", "mn": "аав"}, "b": {"zh": "妈妈", "pinyin": "māma", "mn": "ээж"}, "note_mn": "爸爸 эхний үе 4-р хөг, 妈妈 эхний үе 1-р хөг — хоёуланд хоёр дахь үе нь хөнгөрсөн (轻声) дуудагдана."}]}], "tips_mn": ["哪儿 ба 那儿-г ярианд сонсоход анхаарал төвлөрүүлж дасгал хийгээрэй — утга нь эсрэг тул андуурвал ойлголцол алдагдана.", "4-р хөгийг үргэлж өндрөөс эхлээд огцом буулгаж дуудаарай, аль ч хослолд энэ шинж чанар өөрчлөгдөхгүй.", "医院, 医生-г хосоор нь цээжилж, 医-г 1-р хөгөөр тэгш, урт дуудахад анхаар.", "子 дагавартай үгсэд (儿子, 椅子) төгсгөлийн 子 үргэлж хөнгөрч (轻声) дуудагддагийг сана."]}}'::jsonb)
