insert into public.lesson_deep_teaching (lesson_id, version, payload)
values ('hsk1-l10', 1, '{"words": [{"zh": "桌子", "pinyin": "zhuōzi", "teach_mn": "«桌子» нь «ширээ» гэсэн энгийн нэр үг. Ард нь орсон «子» бол сул хөгтэй дагавар, дангаараа утгагүй, зөвхөн нэр үгийг бүрдүүлж байна. Байршил хэлэх өгүүлбэрт «桌子上» (ширээн дээр) гэдэг хэлбэрээр маш их хэрэглэгдэнэ. Монгол хэлэнд «ширээ» гэдэг үг дангаараа хангалттай, харин хятадад олон нэр үгэнд ийм «子» дагавар байдгийг сана.", "usage_mn": ["Байшин, өрөөний тавилга нэрлэхэд хэрэглэнэ", "Ихэвчлэн 上 (дээр), 里 (дотор) зэрэг байршлын үгтэй хамт орно"], "examples": [{"zh": "桌子上有什么？", "pinyin": "Zhuōzi shang yǒu shénme?", "mn": "Ширээн дээр юу байна?", "note_mn": "байршил асуух үндсэн загвар"}, {"zh": "桌子上有一个电脑和一本书。", "pinyin": "Zhuōzi shang yǒu yí ge diànnǎo hé yì běn shū.", "mn": "Ширээн дээр компьютер, нэг ном байна.", "note_mn": "有 өгүүлбэрийн жишээ"}, {"zh": "杯子在桌子里。", "pinyin": "Bēizi zài zhuōzi li.", "mn": "Аяга ширээн дотор байна.", "note_mn": "里 (дотор)-тэй хослуулсан хэлбэр"}, {"zh": "我的书在桌子上。", "pinyin": "Wǒ de shū zài zhuōzi shang.", "mn": "Миний ном ширээн дээр байна.", "note_mn": "хувийн зүйлээ байршуулж хэлэх жишээ"}], "mistakes": [{"wrong": "书在桌子。", "right": "书在桌子上。", "why_mn": "Байршил заахдаа зүйлийн ард 上/里/前面 гэх мэт байршлын үгийг заавал нэмнэ, ганцаараа 桌子 гэж орхиж болохгүй."}]}, {"zh": "上", "pinyin": "shang", "teach_mn": "«上» нь «дээр» гэсэн байршил заасан үг. Нэр үгийн ард залгагдаж, тухайн зүйлийн дээд хэсэгт юу байгааг заана: 桌子上 (ширээн дээр). Байршил заах энэ хэрэглээндээ сул хөгтэй дуудагддаг. Монгол хэлэнд «дээр» гэдэг нөхцөл нэр үгийн ард залгадагтай адил боловч хятадад энэ нь тусдаа үг хэвээрээ бичигдэнэ.", "usage_mn": ["Байршил заах 有/在 өгүүлбэрт нэр үгийн ард орно", "Ганцаараа биш, үргэлж нэр үгтэй хослуулан хэрэглэнэ"], "examples": [{"zh": "桌子上有什么？", "pinyin": "Zhuōzi shang yǒu shénme?", "mn": "Ширээн дээр юу байна?"}, {"zh": "桌子上有一个电脑和一本书。", "pinyin": "Zhuōzi shang yǒu yí ge diànnǎo hé yì běn shū.", "mn": "Ширээн дээр компьютер, нэг ном байна."}, {"zh": "椅子上没有书。", "pinyin": "Yǐzi shang méiyǒu shū.", "mn": "Сандал дээр ном байхгүй."}], "mistakes": [{"wrong": "电脑桌子上。", "right": "桌子上有电脑。", "why_mn": "Хятадад ЭХЛЭЭД байршил (桌子上), дараа нь 有, эцэст нь зүйл (电脑) гэсэн тогтсон дараалалтай, монгол шиг эрх чөлөөтэй эргүүлж хэлж болохгүй."}]}, {"zh": "电脑", "pinyin": "diànnǎo", "teach_mn": "«电脑» нь «компьютер» гэсэн нэр үг, 电 (цахилгаан) ба 脑 (тархи) хоёр ханзнаас бүтсэн — шууд утгаараа «цахилгаан тархи». Өдөр тутмын юмсыг нэрлэх энгийн нэр үг тул бусад эд зүйлийн адил 一个 гэх мэт тоолуураар тоологдоно. Монгол хэлэнд «компьютер» гэдэг гадаад үг хэвээрээ орсон бол хятад хэлэнд орчуулсан утгаар нь шинэ үг зохиосон нь ялгаа.", "usage_mn": ["Ажлын байр, гэрийн тавилга тоочихдоо хэрэглэнэ", "Тоолохдоо 个 тоолуур авна: 一个电脑"], "examples": [{"zh": "桌子上有一个电脑和一本书。", "pinyin": "Zhuōzi shang yǒu yí ge diànnǎo hé yì běn shū.", "mn": "Ширээн дээр компьютер, нэг ном байна."}, {"zh": "这是我的电脑。", "pinyin": "Zhè shì wǒ de diànnǎo.", "mn": "Энэ бол миний компьютер."}, {"zh": "电脑在桌子上。", "pinyin": "Diànnǎo zài zhuōzi shang.", "mn": "Компьютер ширээн дээр байна."}], "mistakes": [{"wrong": "一电脑", "right": "一个电脑", "why_mn": "Тоо ба нэр үгийн хооронд 个 гэх мэт тоолуур заавал орно, монгол шиг шууд тоо+нэр үг гэж хэлж болохгүй."}]}, {"zh": "和", "pinyin": "hé", "teach_mn": "«和» нь монгол хэлний «ба» эсвэл «-тай/-тэй» гэсэн холбох үгтэй адил, хоёр буюу түүнээс олон зэрэгцсэн нэр үгийг холбоход хэрэглэнэ: 爸爸和妈妈 (аав ба ээж). Зөвхөн нэр үг холбоход хэрэглэдэг, хоёр өгүүлбэр буюу үйл үг холбоход ашигладаггүй нь монгол хэлнээс ялгаатай тал. Гурав ба түүнээс олон зүйл жагсаахад эхнийхийг таслалаар, хамгийн сүүлийн хоёрыг 和-оор холбоно.", "usage_mn": ["Хоёр буюу түүнээс олон нэр үгийг зэрэгцүүлж жагсаахад хэрэглэнэ", "Өгүүлбэр, үйл үг холбоход хэрэглэдэггүй"], "examples": [{"zh": "爸爸和妈妈", "pinyin": "bàba hé māma", "mn": "аав ээж хоёр"}, {"zh": "桌子上有一个电脑和一本书。", "pinyin": "Zhuōzi shang yǒu yí ge diànnǎo hé yì běn shū.", "mn": "Ширээн дээр компьютер, нэг ном байна."}, {"zh": "我有一个中国朋友和一个美国朋友。", "pinyin": "Wǒ yǒu yí ge Zhōngguó péngyou hé yí ge Měiguó péngyou.", "mn": "Надад нэг хятад найз, нэг америк найз бий."}, {"zh": "桌子和椅子", "pinyin": "zhuōzi hé yǐzi", "mn": "ширээ, сандал"}], "mistakes": [{"wrong": "我去商店和看电影。", "right": "我去商店，看电影。", "why_mn": "和 зөвхөн нэр үг холбодог, хоёр үйл үгийг 和-оор холбож болохгүй."}, {"wrong": "爸爸妈妈和", "right": "爸爸和妈妈", "why_mn": "和 хоёр зүйлийн ДУНД ордог, ард нь тавьж болохгүй."}]}, {"zh": "本", "pinyin": "běn", "teach_mn": "«本» бол ном, дэвтэр зэрэг ном хэлбэртэй зүйлийг тоолох тоолуур үг. Хятад хэлэнд тоо болон нэр үгийн хооронд заавал тохирсон тоолуур орох ёстой бөгөөд 本 нь номонд зориулагдсан тусгай тоолуур. Монгол хэлэнд «нэг ном» гэхэд тусгай тоолуур хэрэггүй ч хятадад «нэг+本+ном» гэж заавал тоолуураа хэлнэ.", "usage_mn": ["Ном, дэвтэр, тэмдэглэлийн дэвтэр тоолоход хэрэглэнэ", "Тоо ба номын нэрийн хооронд заавал орно: 一本书"], "examples": [{"zh": "桌子上有一个电脑和一本书。", "pinyin": "Zhuōzi shang yǒu yí ge diànnǎo hé yì běn shū.", "mn": "Ширээн дээр компьютер, нэг ном байна."}, {"zh": "我有五本汉语书。", "pinyin": "Wǒ yǒu wǔ běn Hànyǔ shū.", "mn": "Надад таван хятад хэлний ном бий."}, {"zh": "这是一本书。", "pinyin": "Zhè shì yì běn shū.", "mn": "Энэ бол нэг ном."}], "mistakes": [{"wrong": "一书", "right": "一本书", "why_mn": "Ном тоолоход 本 тоолуурыг заавал хэрэглэнэ, тоо ба нэр үгийг шууд залгаж болохгүй."}]}, {"zh": "里", "pinyin": "li", "teach_mn": "«里» нь «дотор» гэсэн байршил заасан үг, нэр үгийн ард орж тухайн зүйлийн дотоод орон зайг заана: 桌子里 (ширээний дотор, жишээ нь шургуулга). 上 (дээр)-тэй адил сул хөгтэй дуудагддаг бөгөөд ганцаараа биш үргэлж нэр үгтэй хамт хэрэглэгдэнэ.", "usage_mn": ["Сав, өрөө, тавилганы дотоод орон зайг заахад хэрэглэнэ", "上, 前面, 后面-тэй адил ганцаараа орохгүй, нэр үгийн ард залгагдана"], "examples": [{"zh": "杯子在桌子里。", "pinyin": "Bēizi zài zhuōzi li.", "mn": "Аяга ширээн дотор байна."}, {"zh": "桌子里没有书。", "pinyin": "Zhuōzi li méiyǒu shū.", "mn": "Ширээний дотор ном байхгүй."}, {"zh": "电脑在桌子里吗？", "pinyin": "Diànnǎo zài zhuōzi li ma?", "mn": "Компьютер ширээний дотор байна уу?"}], "mistakes": [{"wrong": "书里桌子", "right": "书在桌子里。", "why_mn": "Байршил илэрхийлэхдээ 在 + газар + 里/上 гэсэн дараалал баримтална, үгсийг эргүүлж хэлж болохгүй."}]}, {"zh": "前面", "pinyin": "qiánmiàn", "teach_mn": "«前面» нь «урд тал» гэсэн байршлын нэр үг. 前 (урд) ба 面 (тал) хоёроос бүтсэн бөгөөд өөрөө бие даан «тухайн зүйлийн урд орших орон зай»-г заана: 前面那个人 (урд байгаа тэр хүн). 上/里-ээс ялгаатай нь 前面 бол өөрөө бие даасан байршлын үг тул ганцаараа өгүүлбэрийн эхэнд ч орж чадна.", "usage_mn": ["Хүн, зүйлийн байрлалыг заахад хэрэглэнэ: 前面那个人", "Ганцаараа өгүүлбэрийн эхэнд орж болно"], "examples": [{"zh": "前面那个人叫什么名字？", "pinyin": "Qiánmiàn nàge rén jiào shénme míngzi?", "mn": "Урд байгаа хүнийг хэн гэдэг вэ?"}, {"zh": "前面有一个商店。", "pinyin": "Qiánmiàn yǒu yí ge shāngdiàn.", "mn": "Урд талд нэг дэлгүүр байна."}, {"zh": "我在你前面。", "pinyin": "Wǒ zài nǐ qiánmiàn.", "mn": "Би чиний урд байна."}], "mistakes": [{"wrong": "人前面那个", "right": "前面那个人", "why_mn": "Байршлын үг 前面 заасан зүйлийнхээ ӨМНӨ ордог, ард нь биш."}], "compare": [{"zh": "后面", "pinyin": "hòumiàn", "mn": "ард тал", "diff_mn": "утга нь яг эсрэг — ард талыг заана."}]}, {"zh": "后面", "pinyin": "hòumiàn", "teach_mn": "«后面» нь 前面-ийн эсрэг утгатай «ард тал» гэсэн байршлын үг. Бүтэц, хэрэглээ нь 前面-тэй яг адилхан, зөвхөн заасан чиглэл нь эсрэг. 后面那个人 гэвэл «ард байгаа тэр хүн» гэсэн үг.", "usage_mn": ["Хүн, зүйлийн ард талын байрлалыг заахад хэрэглэнэ", "前面-тэй ижил бүтэцтэй, ганцаараа орж болно"], "examples": [{"zh": "后面那个人呢？", "pinyin": "Hòumiàn nàge rén ne?", "mn": "Ард байгаа хүн нь?"}, {"zh": "我家后面有一个商店。", "pinyin": "Wǒ jiā hòumiàn yǒu yí ge shāngdiàn.", "mn": "Манай гэрийн ард нэг дэлгүүр байна."}, {"zh": "他在我后面。", "pinyin": "Tā zài wǒ hòumiàn.", "mn": "Тэр миний ард байна."}], "mistakes": [{"wrong": "那个人后面", "right": "后面那个人", "why_mn": "Байршлын үгийг заасан зүйлийнхээ өмнө хэлнэ."}], "compare": [{"zh": "前面", "pinyin": "qiánmiàn", "mn": "урд тал", "diff_mn": "эсрэг чиглэлийг заана."}]}, {"zh": "这儿", "pinyin": "zhèr", "teach_mn": "«这儿» нь «энд» гэсэн байршил заасан төлөөний үг, ярьж буй хүний ойролцоох газрыг заана. 这 (энэ) дээр 儿 (эр өнгө) залгагдсан хэлбэр. Эсрэг нь 那儿 (тэнд), асуух нь 哪儿 (хаана). 在/坐 зэрэг үйл үгийн ард орж «энд ... хийх» гэсэн утга өгнө.", "usage_mn": ["Ярьж буй хүний ойролцоох газрыг заахад хэрэглэнэ", "在/坐 зэрэг үйл үгийн ард орж ''энд ... хийх'' гэсэн утга өгнө"], "examples": [{"zh": "这儿有人吗？", "pinyin": "Zhèr yǒu rén ma?", "mn": "Энд хүн байна уу?"}, {"zh": "我能坐这儿吗？", "pinyin": "Wǒ néng zuò zhèr ma?", "mn": "Би энд сууж болох уу?"}, {"zh": "你的书在这儿。", "pinyin": "Nǐ de shū zài zhèr.", "mn": "Чиний ном энд байна."}], "mistakes": [{"wrong": "这有人吗？", "right": "这儿有人吗？", "why_mn": "''Энд'' гэдэг утгаар хэрэглэхдээ 这儿 гэж 儿-г заавал нэмнэ, ганц 这 нь ''энэ'' гэсэн өөр утгатай."}]}, {"zh": "没有（没）", "pinyin": "méiyǒu (méi)", "teach_mn": "«没有» нь 有 (байна)-ийн үгүйсгэл хэлбэр, «байхгүй, алга» гэсэн утгатай. Ярианд товчлоод зөвхөн 没 гэж хэлж болно. Бусад үйл үгийн үгүйсгэлд 不 хэрэглэдэг байсан бол 有-г үгүйсгэхдээ 不 биш зөвхөн 没 хэрэглэдэг нь HSK1-ийн онцгой дүрэм.", "usage_mn": ["有 (байна)-г үгүйсгэхэд хэрэглэнэ, 不有 гэж хэлдэггүй", "Ард нь тооны үг орохгүй: 没有一本书 биш 没有书"], "examples": [{"zh": "椅子下面没有小狗。", "pinyin": "Yǐzi xiàmiàn méiyǒu xiǎo gǒu.", "mn": "Сандлын доор гөлөг байхгүй."}, {"zh": "这儿有人吗？— 没有。", "pinyin": "Zhèr yǒu rén ma? — Méi yǒu.", "mn": "Энд хүн байна уу? — Байхгүй."}, {"zh": "桌子上没有电脑。", "pinyin": "Zhuōzi shang méiyǒu diànnǎo.", "mn": "Ширээн дээр компьютер байхгүй."}], "mistakes": [{"wrong": "不有书", "right": "没有书", "why_mn": "有-г үгүйсгэхэд 不 биш заавал 没 хэрэглэнэ, энэ бол HSK1-ийн онцгой дүрэм."}]}, {"zh": "能", "pinyin": "néng", "teach_mn": "«能» нь чадвар, зөвшөөрлийн боломжийг заасан туслах үйл үг, «чадах, болох» гэж орчуулна. Үйл үгийн ӨМНӨ ордог: 能坐 (суух боломжтой), 能去 (явж чадна). Асуух хэлбэр 能……吗？ нь эелдгээр зөвшөөрөл хүсэхэд хэрэглэгдэнэ: 我能坐这儿吗？(Би энд сууж болох уу?).", "usage_mn": ["Биеийн чадвар, гадаад нөхцлийн боломжийг заахад хэрэглэнэ", "能……吗？ хэлбэрээр эелдгээр зөвшөөрөл хүснэ"], "examples": [{"zh": "我能坐这儿吗？", "pinyin": "Wǒ néng zuò zhèr ma?", "mn": "Би энд сууж болох уу?"}, {"zh": "明天下午我能去商店。", "pinyin": "Míngtiān xiàwǔ wǒ néng qù shāngdiàn.", "mn": "Маргааш үдээс хойш би дэлгүүр явж чадна."}, {"zh": "你能在这儿写你的名字吗？", "pinyin": "Nǐ néng zài zhèr xiě nǐ de míngzi ma?", "mn": "Та энд нэрээ бичиж болох уу?"}], "mistakes": [{"wrong": "我坐能这儿。", "right": "我能坐这儿。", "why_mn": "能 нь үргэлж үйл үгийн ӨМНӨ ордог, ард нь орж болохгүй."}]}, {"zh": "坐", "pinyin": "zuò", "teach_mn": "«坐» нь «суух» гэсэн энгийн үйл үг. 请坐 (сууна уу) гэдэг нь зочломтгой байдлаар санал болгох маш түгээмэл хэллэг. 坐-ийн ард газрын нэр орж болно: 坐这儿 (энд суух).", "usage_mn": ["Хүнийг суухыг урих, зөвшөөрөл хүсэхэд хэрэглэнэ", "Ард нь газрын нэр орж болно: 坐这儿"], "examples": [{"zh": "请坐。", "pinyin": "Qǐng zuò.", "mn": "Сууна уу."}, {"zh": "我能坐这儿吗？", "pinyin": "Wǒ néng zuò zhèr ma?", "mn": "Би энд сууж болох уу?"}, {"zh": "你坐这儿，我坐那儿。", "pinyin": "Nǐ zuò zhèr, wǒ zuò nàr.", "mn": "Чи энд суу, би тэнд суух болъё."}], "mistakes": [{"wrong": "坐请。", "right": "请坐。", "why_mn": "请 нь хүсэлтийн үгийн ӨМНӨ ордог, ард нь орохгүй."}]}, {"zh": "王方 / 谢朋", "pinyin": "Wáng Fāng / Xiè Péng", "teach_mn": "«王方» ба «谢朋» нь хятад хүний нэр — эхний үсэг нь овог (王 Ван, 谢 Се), араас нь өгсөн нэр (方, 朋) ирнэ. Хятадад овгоо эхэнд, нэрээ ард нь хэлдэг. Ажил мэргэжлээр нь 王医生 (Ван эмч), 谢老师 (Се багш) гэж хүндэтгэлтэй дуудаж болно.", "usage_mn": ["Хятад хүний нэрийг танилцуулах, дуудахад хэрэглэнэ", "Овог + мэргэжил хэлбэрээр хүндэтгэлтэй дуудаж болно"], "examples": [{"zh": "她叫王方，在医院工作。", "pinyin": "Tā jiào Wáng Fāng, zài yīyuàn gōngzuò.", "mn": "Түүнийг Ван Фан гэдэг, эмнэлэгт ажилладаг."}, {"zh": "他叫谢朋，在商店工作。", "pinyin": "Tā jiào Xiè Péng, zài shāngdiàn gōngzuò.", "mn": "Түүнийг Се Пэн гэдэг, дэлгүүрт ажилладаг."}, {"zh": "王方是医生吗？", "pinyin": "Wáng Fāng shì yīshēng ma?", "mn": "Ван Фан эмч мөн үү?"}], "mistakes": [{"wrong": "方王", "right": "王方", "why_mn": "Хятад нэрэнд овог үргэлж эхэнд ордог, монгол шиг эцгийн нэр ард нь ирдэггүй."}]}], "grammar": [{"point": "有字句", "gloss_mn": "有 өгүүлбэр: «...-д ... байна»", "structure": "Байршил + 有 + (тоо + тоолуур) + зүйл", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "有 нь «байна» гэсэн утгатай, аль нэг газарт ямар нэг зүйл байгааг хэлэхэд хэрэглэнэ. Өгүүлбэрийн эхэнд байршил, дараа нь 有, эцэст нь юу байгааг хэлнэ.", "example": {"zh": "桌子上有书。", "pinyin": "Zhuōzi shang yǒu shū.", "mn": "Ширээн дээр ном байна."}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Байршил (газар+上/里/前面...) + 有 + (тоо+тоолуур) + зүйл. Тоо, тоолуур байхгүй бол ерөнхий байдлаар байгааг л хэлнэ.", "example": {"zh": "桌子上有一个电脑和一本书。", "pinyin": "Zhuōzi shang yǒu yí ge diànnǎo hé yì běn shū.", "mn": "Ширээн дээр нэг компьютер, нэг ном байна."}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Ямар нэг газарт юу байгааг мэдээлэхдээ, эсвэл хүнээс «тэнд юу байна» гэж асуухад 有 хэрэглэнэ.", "example": {"zh": "这儿有人吗？", "pinyin": "Zhèr yǒu rén ma?", "mn": "Энд хүн байна уу?"}}, {"title_mn": "4. Үгүйсгэл", "body_mn": "有-г үгүйсгэхдээ 不 биш, зөвхөн 没 хэрэглэнэ: 没有. Ард нь тооны үг ордоггүй.", "example": {"zh": "椅子下面没有小狗。", "pinyin": "Yǐzi xiàmiàn méiyǒu xiǎo gǒu.", "mn": "Сандлын доор гөлөг байхгүй."}}], "examples": [{"zh": "桌子上有什么？", "pinyin": "Zhuōzi shang yǒu shénme?", "mn": "Ширээн дээр юу байна?"}, {"zh": "桌子上有一个电脑和一本书。", "pinyin": "Zhuōzi shang yǒu yí ge diànnǎo hé yì běn shū.", "mn": "Ширээн дээр нэг компьютер, нэг ном байна."}, {"zh": "椅子下面没有小狗。", "pinyin": "Yǐzi xiàmiàn méiyǒu xiǎo gǒu.", "mn": "Сандлын доор гөлөг байхгүй."}, {"zh": "这儿有人吗？", "pinyin": "Zhèr yǒu rén ma?", "mn": "Энд хүн байна уу?"}, {"zh": "这儿有人吗？— 没有。", "pinyin": "Zhèr yǒu rén ma? — Méi yǒu.", "mn": "Энд хүн байна уу? — Байхгүй."}, {"zh": "桌子里没有书。", "pinyin": "Zhuōzi li méiyǒu shū.", "mn": "Ширээний дотор ном байхгүй."}, {"zh": "前面有一个商店。", "pinyin": "Qiánmiàn yǒu yí ge shāngdiàn.", "mn": "Урд талд нэг дэлгүүр байна."}], "mistakes": [{"wrong": "桌子上没有一本书。", "right": "桌子上没有书。", "why_mn": "没有-ийн ард тооны үг орохгүй, зөвхөн 有-ийн батлах өгүүлбэрт тоо орно."}, {"wrong": "有桌子上书。", "right": "桌子上有书。", "why_mn": "Байршил заасан үг үргэлж 有-ийн ӨМНӨ ордог."}], "drills": [{"type": "choice", "question": "桌子上___什么？", "options": ["有", "是", "在"], "answer": "有", "why_mn": "Байршилд юу байгааг асуухдаа 有 хэрэглэнэ."}, {"type": "judge", "question": "没有-ийн ард тооны үг орж болно.", "answer": "false", "why_mn": "没有-ийн ард тооны үг ордоггүй, зөвхөн зүйлийн нэрийг л хэлнэ."}, {"type": "fill", "question": "椅子下面___小狗。（байхгүй гэдгийг илэрхийл）", "answer": "没有", "why_mn": "''Байхгүй'' гэдгийг илэрхийлэхэд 没有 хэрэглэнэ."}, {"type": "choice", "question": "«Урд талд нэг дэлгүүр байна» гэдгийг хятадаар хэрхэн хэлэх вэ?", "options": ["前面有一个商店。", "有前面一个商店。", "一个商店前面有。"], "answer": "前面有一个商店。", "why_mn": "Байршил (前面) эхэнд, дараа нь 有, эцэст нь зүйл ирнэ."}]}, {"point": "连词 和", "gloss_mn": "和 холбоос: «ба»", "structure": "нэр үг1 + 和 + нэр үг2", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "和 нь монгол хэлний «ба» эсвэл хоёр зүйлийг хамт дурдахад хэрэглэдэг холбох үг. Зөвхөн нэр үг холбоход хэрэглэнэ.", "example": {"zh": "爸爸和妈妈", "pinyin": "bàba hé māma", "mn": "аав ээж хоёр"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Хоёр нэр үгийн дунд шууд 和-г тавина, өмнө/ард нь таслал хэрэггүй.", "example": {"zh": "电脑和书", "pinyin": "diànnǎo hé shū", "mn": "компьютер, ном"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Гурав ба түүнээс олон зүйл жагсаахад эхний зүйлүүдийг таслалаар, хамгийн сүүлийн хоёрыг 和-оор холбоно.", "example": {"zh": "我有一个中国朋友和一个美国朋友。", "pinyin": "Wǒ yǒu yí ge Zhōngguó péngyou hé yí ge Měiguó péngyou.", "mn": "Надад нэг хятад найз, нэг америк найз бий."}}, {"title_mn": "4. Ялгаа", "body_mn": "Монгол хэлэнд «аав, ээж хоёр» гэхэд «хоёр» гэдэг тоо нэмдэг бол хятадад тоо нэмэлгүй зөвхөн 和-г ашиглана.", "example": {"zh": "爸爸和妈妈", "pinyin": "bàba hé māma", "mn": "аав ээж хоёр (тоо нэмэлгүй)"}}], "examples": [{"zh": "爸爸和妈妈", "pinyin": "bàba hé māma", "mn": "аав ээж хоёр"}, {"zh": "桌子上有一个电脑和一本书。", "pinyin": "Zhuōzi shang yǒu yí ge diànnǎo hé yì běn shū.", "mn": "Ширээн дээр компьютер, ном байна."}, {"zh": "我有一个中国朋友和一个美国朋友。", "pinyin": "Wǒ yǒu yí ge Zhōngguó péngyou hé yí ge Měiguó péngyou.", "mn": "Надад нэг хятад найз, нэг америк найз бий."}, {"zh": "你和我", "pinyin": "nǐ hé wǒ", "mn": "чи бид хоёр"}, {"zh": "桌子和椅子", "pinyin": "zhuōzi hé yǐzi", "mn": "ширээ, сандал"}, {"zh": "电脑和书在桌子上。", "pinyin": "Diànnǎo hé shū zài zhuōzi shang.", "mn": "Компьютер, ном ширээн дээр байна."}], "mistakes": [{"wrong": "我去商店和看电影。", "right": "我去商店，看电影。", "why_mn": "和 зөвхөн нэр үг холбодог, хоёр үйл үгийг 和-оор холбож болохгүй."}, {"wrong": "爸爸妈妈和", "right": "爸爸和妈妈", "why_mn": "和 хоёр зүйлийн ДУНД ордог, ард нь тавьж болохгүй."}], "drills": [{"type": "choice", "question": "«Ширээ, сандал» гэдгийг хятадаар хэлбэл?", "options": ["桌子和椅子", "和桌子椅子", "桌子椅子和"], "answer": "桌子和椅子", "why_mn": "和 хоёр нэр үгийн дунд ордог."}, {"type": "judge", "question": "和-г хоёр үйл үг холбоход хэрэглэж болно.", "answer": "false", "why_mn": "和 зөвхөн нэр үг холбоход хэрэглэнэ."}, {"type": "fill", "question": "爸爸___妈妈（ба）", "answer": "和", "why_mn": "''Ба'' гэсэн утгаар хоёр хүнийг холбохдоо 和 хэрэглэнэ."}]}, {"point": "能愿动词 能", "gloss_mn": "能: чадах, болох — 能……吗？ зөвшөөрөл хүсэх", "structure": "能 + үйл үг (+ газар) (+ 吗？)", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "能 бол туслах үйл үг, өөрөө ганцаараа орж чадахгүй, үргэлж өөр нэг үйл үгийн өмнө орж «чадах, боломжтой» гэсэн утга нэмнэ.", "example": {"zh": "能坐", "pinyin": "néng zuò", "mn": "суух боломжтой"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "能 + үйл үг (+газар) хэлбэрээр угсрагдана. Асуухдаа өгүүлбэрийн төгсгөлд 吗 нэмнэ.", "example": {"zh": "我能坐这儿吗？", "pinyin": "Wǒ néng zuò zhèr ma?", "mn": "Би энд сууж болох уу?"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Бодит чадвар, гадаад нөхцлийн зөвшөөрөл хоёуланд нь хэрэглэнэ. 能……吗？ нь эелдэг байдлаар зөвшөөрөл хүсэх хамгийн түгээмэл хэлбэр.", "example": {"zh": "你能在这儿写你的名字吗？", "pinyin": "Nǐ néng zài zhèr xiě nǐ de míngzi ma?", "mn": "Та энд нэрээ бичиж болох уу?"}}, {"title_mn": "4. Хариулах", "body_mn": "Зөвшөөрвөл 能 гэж хариулж, татгалзвал 不能 гэнэ.", "example": {"zh": "能。/ 不能。", "pinyin": "Néng. / Bù néng.", "mn": "Болно. / Болохгүй."}}], "examples": [{"zh": "我能坐这儿吗？", "pinyin": "Wǒ néng zuò zhèr ma?", "mn": "Би энд сууж болох уу?"}, {"zh": "明天下午我能去商店。", "pinyin": "Míngtiān xiàwǔ wǒ néng qù shāngdiàn.", "mn": "Маргааш үдээс хойш би дэлгүүр явж чадна."}, {"zh": "你能在这儿写你的名字吗？", "pinyin": "Nǐ néng zài zhèr xiě nǐ de míngzi ma?", "mn": "Та энд нэрээ бичиж болох уу?"}, {"zh": "这儿有人吗？— 没有。— 我能坐这儿吗？", "pinyin": "Zhèr yǒu rén ma? — Méi yǒu. — Wǒ néng zuò zhèr ma?", "mn": "Энд хүн байна уу? — Байхгүй. — Би энд сууж болох уу?"}, {"zh": "能。", "pinyin": "Néng.", "mn": "Болно."}, {"zh": "不能。", "pinyin": "Bù néng.", "mn": "Болохгүй."}], "mistakes": [{"wrong": "我坐能这儿。", "right": "我能坐这儿。", "why_mn": "能 үргэлж үйл үгийн өмнө ордог."}, {"wrong": "我能吗坐这儿？", "right": "我能坐这儿吗？", "why_mn": "吗 үргэлж өгүүлбэрийн ХАМГИЙН ТӨГСГӨЛД ордог."}], "drills": [{"type": "fill", "question": "我___坐这儿吗？（чадах уу гэдгийг нэм）", "answer": "能", "why_mn": "Зөвшөөрөл хүсэхдээ 能 хэрэглэнэ."}, {"type": "choice", "question": "«Та энд нэрээ бичиж болох уу?» гэдгийг хамгийн зөв хэлбэрээр сонго.", "options": ["你能在这儿写你的名字吗？", "你在这儿能写你的名字吗吗？", "你写能在这儿名字吗？"], "answer": "你能在这儿写你的名字吗？", "why_mn": "能 нь 写-ийн (үйл үгийн) шууд өмнө орно."}, {"type": "judge", "question": "能-ийн үгүйсгэл нь 没能 биш 不能 юм.", "answer": "true", "why_mn": "能-ийг өдөр тутмын ярианд ихэвчлэн 不 -ээр үгүйсгэдэг."}]}, {"point": "用 请 的祈使句", "gloss_mn": "请-тэй хүсэлтийн өгүүлбэр", "structure": "请 + үйл үг", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "请 нь хэн нэгэнд эелдгээр санал болгох, хүсэхэд хэрэглэдэг үг, монгол хэлний «...ноо уу» гэдэг эелдэг хэлбэртэй утгаараа төстэй.", "example": {"zh": "请坐。", "pinyin": "Qǐng zuò.", "mn": "Сууна уу."}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "请 өгүүлбэрийн эхэнд ордог, дараа нь шууд үйл үг ирнэ, өөр юу ч завсарт орохгүй.", "example": {"zh": "请喝茶。", "pinyin": "Qǐng hē chá.", "mn": "Цайгаа зооглоно уу."}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Зочинд, шинэ танилдаа, сурагчдадаа эелдгээр ямар нэг зүйл хийхийг санал болгоход хэрэглэнэ: суух, цай уух, нэрээ бичих гэх мэт.", "example": {"zh": "请写您的名字。", "pinyin": "Qǐng xiě nín de míngzi.", "mn": "Нэрээ бичнэ үү."}}, {"title_mn": "4. Өргөтгөл", "body_mn": "请 өөрөө нэр биш үйл үг тул ард нь заавал үйл үг ирэх ёстой, ганцаараа хэрэглэж болохгүй.", "example": {"zh": "请坐，请喝茶。", "pinyin": "Qǐng zuò, qǐng hē chá.", "mn": "Сууна уу, цайгаа зооглоно уу."}}], "examples": [{"zh": "请喝茶。", "pinyin": "Qǐng hē chá.", "mn": "Цайгаа зооглоно уу."}, {"zh": "请坐。", "pinyin": "Qǐng zuò.", "mn": "Сууна уу."}, {"zh": "请写您的名字。", "pinyin": "Qǐng xiě nín de míngzi.", "mn": "Нэрээ бичнэ үү."}, {"zh": "请坐，请喝茶。", "pinyin": "Qǐng zuò, qǐng hē chá.", "mn": "Сууна уу, цайгаа зооглоно уу."}, {"zh": "您好，请坐。", "pinyin": "Nín hǎo, qǐng zuò.", "mn": "Та сайн байна уу, сууна уу."}], "mistakes": [{"wrong": "坐请。", "right": "请坐。", "why_mn": "请 үргэлж өгүүлбэрийн ЭХЭНД ордог."}, {"wrong": "请。", "right": "请坐。", "why_mn": "请-ийн ард заавал үйл үг ирэх ёстой, ганцаараа хэрэглэдэггүй."}], "drills": [{"type": "fill", "question": "___坐。（эелдгээр «сууна уу» гэж хэл）", "answer": "请坐", "why_mn": "Эелдгээр санал болгохдоо 请 + үйл үг хэлбэрийг хэрэглэнэ."}, {"type": "choice", "question": "Зочиндоо цай санал болгохдоо юу гэж хэлэх вэ?", "options": ["请喝茶。", "喝请茶。", "茶请喝。"], "answer": "请喝茶。", "why_mn": "请 өгүүлбэрийн эхэнд, дараа нь үйл үг, эцэст нь зүйл ирнэ."}, {"type": "judge", "question": "请 ганцаараа, ард нь үйл үггүйгээр хэрэглэгддэг.", "answer": "false", "why_mn": "请-ийн ард заавал үйл үг ирнэ."}]}, {"point": "汉字 — 上 下 本 末, бүтэн бүслэх бүтэц, 囗/礻 язгуур", "gloss_mn": "Ханзны бүтэц ба язгуур", "structure": "上/下/本/末 дан бүтэцт; 囗 бүтэн бүслэх; 礻 шүтээний язгуур", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "上 (дээр), 下 (доор) хоёр бие биенийхээ эсрэг утгатай, зурлагын байрлалаараа ялгаатай дан бүтэцт ханз. 本 (үндэс) ба 末 (үзүүр) хоёр ч мөн адил 木 (мод)-нд тэмдэг нэмсэн эсрэг санааны хос.", "example": {"zh": "上 / 下", "pinyin": "shàng / xià", "mn": "дээр / доор"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "本 нь 木 (мод) ханзны ёроолд нэг зураас нэмж «модны үндэс» гэсэн санааг заасан бол 末 нь модны оройд зураас нэмж «үзүүр» гэсэн утга өгсөн.", "example": {"zh": "本 = 木 + доод зураас", "pinyin": "běn", "mn": "үндэс — модны ёроолд тэмдэг"}}, {"title_mn": "3. Бүтэн бүслэх бүтэц ба язгуур", "body_mn": "囗 язгуур нь ханзыг бүрэн хүрээлж «хүрээлэгдсэн орон зай» гэсэн санааг өгдөг: 国 (улс), 四 (дөрөв). 礻 язгуур нь шүтээн, ёслолтой холбоотой утга өгдөг: 视 (харах), 祝 (ерөөх).", "example": {"zh": "国 / 视", "pinyin": "guó / shì", "mn": "улс / харах"}}, {"title_mn": "4. Ялгаа", "body_mn": "上/下, 本/末 зэрэг хосуудыг ганцхан жижиг зурлагын байрлалаар ялгадаг тул бичихдээ болгоомжтой байх хэрэгтэй.", "example": {"zh": "本 vs 末", "pinyin": "běn vs mò", "mn": "зураас доор — үндэс, зураас дээр — үзүүр"}}], "examples": [{"zh": "四 国", "pinyin": "sì guó", "mn": "бүтэн бүслэх бүтэцтэй"}, {"zh": "视 祝", "pinyin": "shì zhù", "mn": "礻 язгууртай — шүтлэг, ерөөлтэй холбоотой"}, {"zh": "上", "pinyin": "shàng", "mn": "дээр"}, {"zh": "下", "pinyin": "xià", "mn": "доор"}, {"zh": "本", "pinyin": "běn", "mn": "үндэс"}, {"zh": "末", "pinyin": "mò", "mn": "үзүүр"}], "mistakes": [{"wrong": "本 ба 末-ийг ижил гэж андуурах", "right": "本 нь зураас ДООР, 末 нь зураас ДЭЭР", "why_mn": "Хоёр ханз бараг ижил дүрстэй тул зурааны байрлалыг сайн ажиглах хэрэгтэй."}], "drills": [{"type": "choice", "question": "末-ийн нэмэлт зураас модны аль хэсэгт байдаг вэ?", "options": ["дээд хэсэгт", "доод хэсэгт", "дунд хэсэгт"], "answer": "дээд хэсэгт", "why_mn": "末 нь модны оройд зураас нэмж «үзүүр» гэсэн утга авдаг."}, {"type": "judge", "question": "囗 язгуур нь «хүрээлэгдсэн орон зай» гэсэн санаа өгдөг.", "answer": "true", "why_mn": "囗 ханзыг бүрэн хүрээлж орших тул ийм утгатай."}, {"type": "fill", "question": "«Дээр» гэдгийг ханзаар бич.", "answer": "上", "why_mn": "上 бол «дээр» гэсэн утгатай."}]}], "hanzi": [{"hanzi": "上", "pinyin": "shàng", "meaning_mn": "дээр", "story_mn": "上 нь эртний зурган бичигт үндсэн шугамын ДЭЭР жижиг тэмдэг тавьсан дүрснээс гаралтай — «дээр» гэдэг байршлыг шууд заасан энгийн тэмдэг.", "stroke_count": 3, "stroke_tips_mn": ["Эхлээд дундах богино босоо зурлагыг тат", "Дараа нь дээд богино хэвтээ, эцэст нь доод урт хэвтээ зурлагыг тат"], "confusable": [{"zh": "下", "pinyin": "xià", "mn": "доор", "diff_mn": "上 нь шугамын дээр тэмдэгтэй, 下 нь шугамын доор тэмдэгтэй — эсрэг утгатай хос."}], "words": [{"zh": "桌子上", "pinyin": "zhuōzi shang", "mn": "ширээн дээр"}, {"zh": "上午", "pinyin": "shàngwǔ", "mn": "өглөө (үдээс өмнө)"}]}, {"hanzi": "下", "pinyin": "xià", "meaning_mn": "доор", "story_mn": "下 нь 上-ийн эсрэг тэмдэг — үндсэн шугамын ДООР жижиг зураас тавьсан дүрснээс гаралтай.", "stroke_count": 3, "stroke_tips_mn": ["Эхлээд дээд хэвтээ зурлагыг тат", "Дараа нь дундах богино босоог тат", "Эцэст нь баруун доод цэгийг тат"], "confusable": [{"zh": "上", "pinyin": "shàng", "mn": "дээр", "diff_mn": "тэмдгийн байрлал эсрэг — 下-д тэмдэг шугамын доор байна."}], "words": [{"zh": "下面", "pinyin": "xiàmiàn", "mn": "доор, доод тал"}, {"zh": "下午", "pinyin": "xiàwǔ", "mn": "үдээс хойш"}]}, {"hanzi": "本", "pinyin": "běn", "meaning_mn": "үндэс; ном тоолох нэгж", "radical": {"c": "木", "meaning_mn": "мод", "role_mn": "үндсэн дүрсийг өгнө"}, "components": [{"c": "一", "meaning_mn": "тэмдэг", "role_mn": "модны ёроолыг зааж «үндэс» гэсэн утга нэмнэ"}], "story_mn": "本 нь 木 (мод) ханзны ёроолд нэг богино зураас нэмж, модны үндсийг тодотгосноос «үндэс» гэсэн үндсэн утгатай болсон. Хожим ном, дэвтэр зэргийг тоолох тоолуур болж хөгжсөн.", "stroke_count": 5, "stroke_tips_mn": ["木-г эхлээд бич", "Эцэст нь ёроолд нь богино хэвтээ зураас нэм"], "confusable": [{"zh": "末", "pinyin": "mò", "mn": "үзүүр", "diff_mn": "本-д зураас модны ДООР, 末-д зураас модны ДЭЭР байна."}], "words": [{"zh": "一本书", "pinyin": "yì běn shū", "mn": "нэг ном"}, {"zh": "课本", "pinyin": "kèběn", "mn": "сурах бичиг"}]}, {"hanzi": "末", "pinyin": "mò", "meaning_mn": "үзүүр, төгсгөл", "radical": {"c": "木", "meaning_mn": "мод", "role_mn": "үндсэн дүрсийг өгнө"}, "components": [{"c": "一", "meaning_mn": "тэмдэг", "role_mn": "модны орой дээр нэмэгдэж «үзүүр» гэсэн утга өгнө"}], "story_mn": "末 нь 木 (мод)-ны оройд урт зураас нэмж, модны хамгийн дээд үзүүрийг тодотгосон — 本-ийн яг эсрэг байрлалтай тэмдэгтэй.", "stroke_count": 5, "stroke_tips_mn": ["木-г эхлээд бич", "Эцэст нь дээд талд урт хэвтээ зураас нэм"], "confusable": [{"zh": "本", "pinyin": "běn", "mn": "үндэс", "diff_mn": "末-д зураас модны ДЭЭР, 本-д зураас модны ДООР байна."}], "words": [{"zh": "周末", "pinyin": "zhōumò", "mn": "амралтын өдрүүд (долоо хоногийн эцэс)"}, {"zh": "末了", "pinyin": "mòliǎo", "mn": "эцэст нь"}]}], "pronunciation": {"focus_mn": "Энэ хичээлд сул хөг (轻声)-ийг сайн сурах хэрэгтэй: 桌子, 椅子 зэрэг 子 төгсгөлтэй үгсийн сүүлийн үе өмнөх хөгөөс хамааран өндөр багатайгаар хөнгөн дуудагдана.", "drills": [{"title_mn": "Сул хөг: 1/2/4-р хөгийн дараа", "instruction_mn": "Хосыг дараалан хэлж, сул хөгийг хөнгөн дуудахыг анзаар.", "pairs": [{"a": {"zh": "桌子", "pinyin": "zhuōzi", "mn": "ширээ"}, "b": {"zh": "妈妈", "pinyin": "māma", "mn": "ээж"}, "note_mn": "Хоёул 1-р хөгийн дараа сул хөгтэй, сүүлийн үеийг НАМХАН хэл."}, {"a": {"zh": "爷爷", "pinyin": "yéye", "mn": "өвөө"}, "b": {"zh": "弟弟", "pinyin": "dìdi", "mn": "дүү"}, "note_mn": "2, 4-р хөгийн дараа ч сул хөг адил намхан дуудагдана."}, {"a": {"zh": "谢谢", "pinyin": "xièxie", "mn": "баярлалаа"}, "b": {"zh": "桌子", "pinyin": "zhuōzi", "mn": "ширээ"}, "note_mn": "4-р хөгийн дараах сул хөг мөн намхан."}]}, {"title_mn": "Сул хөг: 3-р хөгийн дараа", "instruction_mn": "3-р хөгийн дараах сул хөг арай өндөр дуудагдахыг анхаар.", "pairs": [{"a": {"zh": "椅子", "pinyin": "yǐzi", "mn": "сандал"}, "b": {"zh": "奶奶", "pinyin": "nǎinai", "mn": "эмээ"}, "note_mn": "3-р хөгийн дараах сул хөг өмнөхөөсөө ӨНДӨРДҮҮ дуудагдана."}, {"a": {"zh": "姐姐", "pinyin": "jiějie", "mn": "эгч"}, "b": {"zh": "椅子", "pinyin": "yǐzi", "mn": "сандал"}, "note_mn": "Хоёул 3-р хөгийн дараах сул хөгтэй жишээ."}]}, {"title_mn": "们/子/头 дагаврын сул хөг", "instruction_mn": "Дагаврыг хөнгөн, тодгүй дуудаж дадлагажаарай.", "pairs": [{"a": {"zh": "我们", "pinyin": "wǒmen", "mn": "бид"}, "b": {"zh": "你们", "pinyin": "nǐmen", "mn": "та нар"}, "note_mn": "们 дагавар үргэлж сул хөгтэй."}, {"a": {"zh": "杯子", "pinyin": "bēizi", "mn": "аяга"}, "b": {"zh": "被子", "pinyin": "bèizi", "mn": "хөнжил"}, "note_mn": "Эхний үений хөгөөрөө ялгаж, 子-г адилхан сул дуудна."}, {"a": {"zh": "里头", "pinyin": "lǐtou", "mn": "дотор тал"}, "b": {"zh": "外头", "pinyin": "wàitou", "mn": "гадна тал"}, "note_mn": "头 дагавар мөн сул хөгтэй."}]}], "tips_mn": ["子, 头, 们 дагавар харагдвал үргэлж сул хөгөөр богино дуудна.", "3-р хөгийн дараах сул хөгийг бага зэрэг өндөрдүүлж дуудвал байгалийн жигд урсгалтай болно."]}}'::jsonb)
