insert into public.lesson_deep_teaching (lesson_id, version, payload)
values ('hsk1-l11', 1, '{"words": [{"zh": "现在", "pinyin": "xiànzài", "teach_mn": "«现在» нь «одоо» гэсэн цаг заасан үг, өгүүлбэрийн эхэнд эсвэл эзэн биеийн ард ордог. Ямар нэг зүйл яг энэ мөчид болж байгааг заахад хэрэглэнэ: 现在几点？(Одоо хэдэн цаг вэ?). Монгол хэлэнд ч «одоо» гэдэг үг ижил байршилд, өгүүлбэрийн эхэнд ордог тул хэрэглээ нь төстэй.", "usage_mn": ["Одоогийн цаг үеийг асуух, хэлэхэд хэрэглэнэ", "Өгүүлбэрийн эхэнд эсвэл эзэн биеийн ард ордог"], "examples": [{"zh": "现在几点？", "pinyin": "Xiànzài jǐ diǎn?", "mn": "Одоо хэдэн цаг болж байна?"}, {"zh": "现在十点十分。", "pinyin": "Xiànzài shí diǎn shí fēn.", "mn": "Одоо арван цаг арван минут."}, {"zh": "我现在在家。", "pinyin": "Wǒ xiànzài zài jiā.", "mn": "Би одоо гэртээ байна."}], "mistakes": [{"wrong": "几点现在？", "right": "现在几点？", "why_mn": "现在 цагийн үг ихэвчлэн өгүүлбэрийн ЭХЭНД ордог, асуух үг 几点-ийн ард биш өмнө нь ирнэ."}]}, {"zh": "点", "pinyin": "diǎn", "teach_mn": "«点» нь цаг хэлэхэд хэрэглэдэг нэгж үг, монголоор «цаг» гэж орчуулна: 十点 (арван цаг). Тоо ба 点-ийн хооронд өөр тоолуур ордоггүй, шууд залгана. 2 цаг гэхдээ 二点 биш 两点 гэдгийг сайн санах хэрэгтэй.", "usage_mn": ["Цаг хэлэхэд тоо+点 хэлбэрээр хэрэглэнэ", "2 цаг гэхэд 二 биш 两 хэрэглэнэ: 两点"], "examples": [{"zh": "现在十点十分。", "pinyin": "Xiànzài shí diǎn shí fēn.", "mn": "Одоо арван цаг арван минут."}, {"zh": "两点零五分。", "pinyin": "Liǎng diǎn líng wǔ fēn.", "mn": "Хоёр цаг тав минут."}, {"zh": "下午三点十分。", "pinyin": "Xiàwǔ sān diǎn shí fēn.", "mn": "Үдээс хойш гурван цаг арван минут."}], "mistakes": [{"wrong": "二点", "right": "两点", "why_mn": "2 цаг гэхэд 二 биш заавал 两 хэрэглэнэ."}]}, {"zh": "分", "pinyin": "fēn", "teach_mn": "«分» нь минутыг заасан үг, 点-ийн ард орж бүтэн цагийн дараах минутыг хэлнэ: 十点十分 (10 цаг 10 минут). Минут нэг оронтой (жишээ нь 05) байвал өмнө нь 零 гэдэг үгийг нэмж хэлдэг: 两点零五分.", "usage_mn": ["Цаг+минут хэлэхэд 点-ийн ард орно", "Минут нэг оронтой бол өмнө нь 零 нэмнэ"], "examples": [{"zh": "现在十点十分。", "pinyin": "Xiànzài shí diǎn shí fēn.", "mn": "Одоо арван цаг арван минут."}, {"zh": "六点三十分。", "pinyin": "Liù diǎn sānshí fēn.", "mn": "Зургаан цаг гучин минут."}, {"zh": "两点零五分。", "pinyin": "Liǎng diǎn líng wǔ fēn.", "mn": "Хоёр цаг тав минут."}], "mistakes": [{"wrong": "十点五分", "right": "十点零五分", "why_mn": "Минут нэг оронтой байвал (жишээ нь 05) 点-ийн ард 零-г нэмж хэлэх нь стандарт бөгөөд ойлгомжтой байдаг."}]}, {"zh": "中午", "pinyin": "zhōngwǔ", "teach_mn": "«中午» нь өдрийн дундах цагийг заана, ойролцоогоор 11-13 цагийн хооронд. 上午 (өглөө), 下午 (үдээс хойш)-той хамт өдрийг гурван хэсэгт хуваадаг цагийн үгсийн нэг. Ихэвчлэн хоол идэх цагтай холбоотой хэлэгддэг.", "usage_mn": ["Өдрийн дундах цагийг заахад хэрэглэнэ", "上午/下午-тэй хамт цагийн систем бүрдүүлнэ"], "examples": [{"zh": "中午几点吃饭？", "pinyin": "Zhōngwǔ jǐ diǎn chī fàn?", "mn": "Үд дунд хэдэн цагт хооллох вэ?"}, {"zh": "中午十二点我们吃饭。", "pinyin": "Zhōngwǔ shí''èr diǎn wǒmen chī fàn.", "mn": "Үд дундын арван хоёр цагт бид хооллоно."}, {"zh": "中午我在家。", "pinyin": "Zhōngwǔ wǒ zài jiā.", "mn": "Үд дунд би гэртээ байна."}], "mistakes": [{"wrong": "午前", "right": "上午", "why_mn": "Хятад хэлэнд «үдээс өмнө» гэдгийг 午前 биш 上午 гэж хэлдэг."}]}, {"zh": "吃饭", "pinyin": "chī fàn", "teach_mn": "«吃饭» нь «хоол идэх, хооллох» гэсэн тогтмол хослол, 吃 (идэх) ба 饭 (хоол, будаа) хоёроос бүтнэ. Цагийн үгийн ард ордог: 十二点吃饭 (арван хоёр цагт хооллоно). Тодорхой хоол дурдахгүй, ерөнхийд нь «хооллох» гэхэд хэрэглэнэ.", "usage_mn": ["Ерөнхийд нь хооллохыг илэрхийлэхэд хэрэглэнэ", "Цагийн үгийн АРД, өөрөөр хэлбэл өөрийнх нь ӨМНӨ цаг ирнэ"], "examples": [{"zh": "中午几点吃饭？", "pinyin": "Zhōngwǔ jǐ diǎn chī fàn?", "mn": "Үд дунд хэдэн цагт хооллох вэ?"}, {"zh": "十二点吃饭。", "pinyin": "Shí''èr diǎn chī fàn.", "mn": "Арван хоёр цагт хооллоно."}, {"zh": "我们中午吃饭。", "pinyin": "Wǒmen zhōngwǔ chī fàn.", "mn": "Бид үд дундаа хооллоно."}], "mistakes": [{"wrong": "吃饭十二点。", "right": "十二点吃饭。", "why_mn": "Цагийн үг үйл үгийн (吃饭) ӨМНӨ ордог, ард нь орохгүй."}]}, {"zh": "时候", "pinyin": "shíhou", "teach_mn": "«时候» нь «үе, цаг хугацаа» гэсэн ерөнхий утгатай нэр үг, ихэвчлэн 什么时候 (хэзээ) хэлбэрээр асуух үгэнд орж хэрэглэгдэнэ. Дангаараа тодорхой цаг заахгүй, харин ерөнхий агшин, мөчийг л заана.", "usage_mn": ["什么时候 хэлбэрээр «хэзээ» гэж асуухад хэрэглэнэ", "Тодорхой цаг бус ерөнхий үе мөчийг заана"], "examples": [{"zh": "爸爸什么时候回家？", "pinyin": "Bàba shénme shíhou huí jiā?", "mn": "Аав хэзээ гэртээ харих вэ?"}, {"zh": "我们什么时候去看电影？", "pinyin": "Wǒmen shénme shíhou qù kàn diànyǐng?", "mn": "Бид хэзээ кино үзэхээр явах вэ?"}, {"zh": "你什么时候去北京？", "pinyin": "Nǐ shénme shíhou qù Běijīng?", "mn": "Чи хэзээ Бээжин явах вэ?"}], "mistakes": [{"wrong": "什么时候几点回家？", "right": "爸爸什么时候回家？", "why_mn": "什么时候 ба 几点 хоёулаа цаг асуудаг тул хамт давхар хэрэглэдэггүй, аль нэгийг л сонгоно."}]}, {"zh": "回", "pinyin": "huí", "teach_mn": "«回» нь «буцах, харих» гэсэн үйл үг, ихэвчлэн 回家 (гэртээ харих) хэлбэрээр хамт хэрэглэгдэнэ. Хаанаас гарсан газраа буцаж очихыг заана.", "usage_mn": ["回家 хэлбэрээр гэртээ харихыг илэрхийлэхэд хэрэглэнэ", "Цагийн үгийн ард орж хэзээ буцахыг заана"], "examples": [{"zh": "爸爸什么时候回家？", "pinyin": "Bàba shénme shíhou huí jiā?", "mn": "Аав хэзээ гэртээ харих вэ?"}, {"zh": "他星期五回家。", "pinyin": "Tā xīngqīwǔ huí jiā.", "mn": "Тэр баасан гарагт гэртээ харина."}, {"zh": "星期五前能回家吗？", "pinyin": "Xīngqī wǔ qián néng huí jiā ma?", "mn": "Баасан гарагаас өмнө гэртээ харьж чадах уу?"}], "mistakes": [{"wrong": "回去家", "right": "回家", "why_mn": "''Гэр рүү буцах'' гэдгийг 回家 гэж шууд хэлдэг, 回去家 гэж давхар хэлдэггүй."}]}, {"zh": "我们", "pinyin": "wǒmen", "teach_mn": "«我们» нь 我 (би) дээр 们 (олон тооны дагавар) залгасан «бид, бид нар» гэсэн үг. 你们 (та нар)-тэй яг адил бүтэцтэй, зөвхөн 我 дээр суурилсан нь ялгаатай.", "usage_mn": ["Өөрийгөө болон бусдыг хамруулан ярихад хэрэглэнэ", "你们, 他们-тэй ижил 们 дагавартай"], "examples": [{"zh": "我们什么时候去看电影？", "pinyin": "Wǒmen shénme shíhou qù kàn diànyǐng?", "mn": "Бид хэзээ кино үзэхээр явах вэ?"}, {"zh": "我们中午吃饭。", "pinyin": "Wǒmen zhōngwǔ chī fàn.", "mn": "Бид үд дундаа хооллоно."}, {"zh": "我们是朋友。", "pinyin": "Wǒmen shì péngyou.", "mn": "Бид найзууд."}], "mistakes": [{"wrong": "我们们", "right": "我们", "why_mn": "们 дагаврыг зөвхөн нэг удаа л залгана, давхар хэрэглэдэггүй."}], "compare": [{"zh": "你们", "pinyin": "nǐmen", "mn": "та нар", "diff_mn": "адил бүтэцтэй ч 你 (чи) дээр суурилсан, өгүүлэгч өөрийгөө хамруулахгүй."}]}, {"zh": "电影", "pinyin": "diànyǐng", "teach_mn": "«电影» нь «кино» гэсэн нэр үг, 电 (цахилгаан) ба 影 (сүүдэр, дүрс) хоёроос бүтнэ. 看电影 (кино үзэх) гэдэг тогтмол хослолоор ихэвчлэн хэрэглэгдэнэ.", "usage_mn": ["看电影 хэлбэрээр кино үзэхийг илэрхийлэхэд хэрэглэнэ", "Тоолохдоо 一个电影 гэх мэт 个 тоолуур авна"], "examples": [{"zh": "我们什么时候去看电影？", "pinyin": "Wǒmen shénme shíhou qù kàn diànyǐng?", "mn": "Бид хэзээ кино үзэхээр явах вэ?"}, {"zh": "我们去看电影。", "pinyin": "Wǒmen qù kàn diànyǐng.", "mn": "Бид кино үзэхээр явна."}, {"zh": "六点三十分我们看电影。", "pinyin": "Liù diǎn sānshí fēn wǒmen kàn diànyǐng.", "mn": "Зургаан цаг гучин минутад бид кино үзнэ."}], "mistakes": [{"wrong": "看一个电影。", "right": "看电影。", "why_mn": "''Кино үзэх'' гэдгийг ерөнхийд нь хэлэхдээ тоо, тоолуур нэмэлгүй 看电影 гэж хэлдэг нь элбэг."}]}, {"zh": "住", "pinyin": "zhù", "teach_mn": "«住» нь «амьдрах, байрлах, буудаллах» гэсэн үйл үг, тодорхой газарт хэр удаан байхыг хэлэхэд хэрэглэнэ: 住三天 (гурав хонох), 住在北京 (Бээжинд амьдрах).", "usage_mn": ["Хугацааны үгтэй хамт хэдэн хоног/жил байхыг хэлэхэд хэрэглэнэ", "在-тэй хамт 住在... хэлбэрээр газрыг зааж болно"], "examples": [{"zh": "你想在北京住几天？", "pinyin": "Nǐ xiǎng zài Běijīng zhù jǐ tiān?", "mn": "Чи Бээжинд хэд хоног байхаар байна?"}, {"zh": "住三天。", "pinyin": "Zhù sān tiān.", "mn": "Гурав хононо."}, {"zh": "我住在北京。", "pinyin": "Wǒ zhù zài Běijīng.", "mn": "Би Бээжинд амьдардаг."}], "mistakes": [{"wrong": "住三天在北京。", "right": "在北京住三天。", "why_mn": "Газар (在北京) ихэвчлэн үйл үгийн (住) ӨМНӨ, харин үргэлжлэх хугацаа (三天) ард нь ордог."}]}, {"zh": "前", "pinyin": "qián", "teach_mn": "Энэ хичээлд 前 нь цаг хугацааны утгаар «...-аас өмнө» гэсэн үг, нэр үгийн ард залгагдана: 星期五前 (баасан гарагаас өмнө). Энэ нь L9-д үзсэн 前面 (байршлын «урд тал»)-аас өөр хэрэглээ болохыг анхаарах хэрэгтэй — энд орон зай биш цаг хугацааг заана.", "usage_mn": ["Цаг хугацааны ард орж ''тэрнээс өмнө'' гэсэн утга өгнө", "前面-ээс ялгаатай, энд орон зай биш цаг хугацааг заана"], "examples": [{"zh": "星期五前能回家吗？", "pinyin": "Xīngqī wǔ qián néng huí jiā ma?", "mn": "Баасан гарагаас өмнө гэртээ харьж чадах уу?"}, {"zh": "八点前", "pinyin": "bā diǎn qián", "mn": "найман цагаас өмнө"}, {"zh": "你什么时候去学校？— 八点前。", "pinyin": "Nǐ shénme shíhou qù xuéxiào? — Bā diǎn qián.", "mn": "Чи хэзээ сургууль руу явах вэ? — 8 цагаас өмнө."}], "mistakes": [{"wrong": "前星期五", "right": "星期五前", "why_mn": "前 цаг хугацааны утгаар хэрэглэхдээ ЗААСАН ЦАГИЙН АРД ордог, өмнө нь орохгүй."}], "compare": [{"zh": "前面", "pinyin": "qiánmiàn", "mn": "урд тал", "diff_mn": "前面 орон зайн ''урд тал''-ыг заана, харин энэ хичээлийн 前 цаг хугацааны ''өмнө''-г заана."}]}, {"zh": "北京", "pinyin": "Běijīng", "teach_mn": "«北京» бол Хятад улсын нийслэл хотын нэр, өөрөө хувийн нэр тул хятад бичигтээ өөрчлөгддөггүй. Газрын нэрийн өмнө 去 (явах), 在 (байх), 住在 (амьдрах) зэрэг үйл үг ордог.", "usage_mn": ["Хот, улсын нэр учир 去/在-тэй хамт хэрэглэгдэнэ", "Өөрөө хувийн нэр тул орчуулагдахгүй, дуудлагаараа л авагддаг"], "examples": [{"zh": "我星期一去北京。", "pinyin": "Wǒ xīngqī yī qù Běijīng.", "mn": "Би даваа гарагт Бээжин явна."}, {"zh": "你想在北京住几天？", "pinyin": "Nǐ xiǎng zài Běijīng zhù jǐ tiān?", "mn": "Чи Бээжинд хэд хоног байхаар байна?"}, {"zh": "我住在北京。", "pinyin": "Wǒ zhù zài Běijīng.", "mn": "Би Бээжинд амьдардаг."}], "mistakes": [{"wrong": "北京去我。", "right": "我去北京。", "why_mn": "Хятад өгүүлбэрт эзэн бие эхэнд, дараа нь үйл үг, эцэст нь газрын нэр ордог."}]}], "grammar": [{"point": "时间的表达 — 点/分", "gloss_mn": "Цаг хэлэх: ……点……分", "structure": "(тоо)点(тоо)分", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "Хятад хэлэнд цаг хэлэхдээ том нэгжээс жижиг рүү, өөрөөр хэлбэл эхлээд цаг (点), дараа нь минут (分)-ыг хэлнэ.", "example": {"zh": "十点十分", "pinyin": "shí diǎn shí fēn", "mn": "арван цаг арван минут"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Цагийн тоо+点+минутын тоо+分 гэсэн дараалалтай. Минут нь тэгээр эхэлбэл (жишээ нь 05) 零-г нэмж хэлнэ.", "example": {"zh": "两点零五分", "pinyin": "liǎng diǎn líng wǔ fēn", "mn": "хоёр цаг тав минут"}}, {"title_mn": "3. 2 цагийг хэлэх онцгой дүрэм", "body_mn": "2 цаг гэхэд 二点 биш заавал 两点 гэж хэлнэ. Энэ бол HSK1-ийн хамгийн элбэг гардаг алдаа тул сайн санах хэрэгтэй.", "example": {"zh": "两点", "pinyin": "liǎng diǎn", "mn": "хоёр цаг"}}, {"title_mn": "4. Өглөө/үдээс хойшийг ялгах", "body_mn": "Өглөө, үдээс хойшийг ялгахдаа цагийн өмнө 上午 (өглөө) эсвэл 下午 (үдээс хойш) гэдэг үгийг нэмж хэлнэ.", "example": {"zh": "下午三点十分", "pinyin": "xiàwǔ sān diǎn shí fēn", "mn": "үдээс хойш 3 цаг 10 минут"}}], "examples": [{"zh": "现在十点十分。", "pinyin": "Xiànzài shí diǎn shí fēn.", "mn": "Одоо 10 цаг 10 минут."}, {"zh": "下午三点十分。", "pinyin": "Xiàwǔ sān diǎn shí fēn.", "mn": "Үдээс хойш 3 цаг 10 минут."}, {"zh": "两点零五分。", "pinyin": "Liǎng diǎn líng wǔ fēn.", "mn": "Хоёр цаг тав минут."}, {"zh": "六点三十分。", "pinyin": "Liù diǎn sānshí fēn.", "mn": "Зургаан цаг гучин минут."}, {"zh": "现在几点？", "pinyin": "Xiànzài jǐ diǎn?", "mn": "Одоо хэдэн цаг вэ?"}, {"zh": "十二点吃饭。", "pinyin": "Shí''èr diǎn chī fàn.", "mn": "Арван хоёр цагт хооллоно."}], "mistakes": [{"wrong": "二点", "right": "两点", "why_mn": "2 цаг гэхэд 二 биш заавал 两 хэрэглэнэ."}, {"wrong": "十点五分", "right": "十点零五分", "why_mn": "Минут нэг оронтой (жишээ нь 05) байвал 点-ийн ард 零-г заавал нэмнэ."}], "drills": [{"type": "choice", "question": "2 цагийг хятадаар хэрхэн хэлэх вэ?", "options": ["二点", "两点", "二分"], "answer": "两点", "why_mn": "2 цаг гэхэд 二 биш 两 хэрэглэдэг онцгой дүрэм."}, {"type": "fill", "question": "10:10 гэдгийг хятадаар бич.", "answer": "十点十分", "why_mn": "Цаг+点+минут+分 дарааллаар хэлнэ."}, {"type": "judge", "question": "Хятад хэлэнд цаг хэлэхдээ эхлээд минут, дараа нь цагий