Юу гэсэн үг вэ", "body_mn": "午 (үд, 11-13 цаг) ба 电 (цахилгаан) хоёул өөр жижиг ханз, радикал агуулаагүй бие даасан дан бүтэцт ханз.", "example": {"zh": "午 / 电", "pinyin": "wǔ / diàn", "mn": "үд / цахилгаан"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "电-ийн дүрс эрт цагт аянга цахилгааны гялбааг дүрсэлсэн зурган бичигээс гаралтай гэж үздэг.", "example": {"zh": "电", "pinyin": "diàn", "mn": "цахилгаан — аянгын дүрснээс"}}, {"title_mn": "3. Язгуураар утга таних", "body_mn": "阝 язгуур ихэвчлэн газар байршилтай холбоотой ханзанд ордог: 院 (хашаа, эмнэлэг), 阳 (нар). 亻 язгуур хүнтэй холбоотой ханзанд ордог: 你, 他.", "example": {"zh": "院 阳 / 你 他", "pinyin": "yuàn yáng / nǐ tā", "mn": "газартай холбоотой / хүнтэй холбоотой"}}, {"title_mn": "4. Ашиг тус", "body_mn": "Шинэ ханз харахдаа язгуурыг нь ажигласнаар утгыг нь урьдчилан таамаглаж болно — жишээ нь 阝-тэй ханз харвал газар, байшинтай холбоотой байх магадлалтай.", "example": {"zh": "阝 → 院", "pinyin": "yuàn", "mn": "хашаа, эмнэлэг"}}], "examples": [{"zh": "院 阳", "pinyin": "yuàn yáng", "mn": "阝 газар байршилтай"}, {"zh": "你 他", "pinyin": "nǐ tā", "mn": "亻 хүнтэй холбоотой"}, {"zh": "午", "pinyin": "wǔ", "mn": "үд"}, {"zh": "电", "pinyin": "diàn", "mn": "цахилгаан"}, {"zh": "电脑 电影", "pinyin": "diànnǎo diànyǐng", "mn": "电-тэй холбоотой үгс"}], "mistakes": [{"wrong": "阝 болон 亻-г андуурах", "right": "阝 газартай, 亻 хүнтэй холбоотой", "why_mn": "Хоёр язгуур дүрсээрээ жижиг ялгаатай тул анхааралтай ажиглах хэрэгтэй."}], "drills": [{"type": "choice", "question": "阝 язгуур ямар утгатай ханзанд ордог вэ?", "options": ["хүнтэй холбоотой", "газар байршилтай холбоотой", "тоотой холбоотой"], "answer": "газар байршилтай холбоотой", "why_mn": "阝 ихэвчлэн газар, байшинтай холбоотой ханзанд ордог."}, {"type": "judge", "question": "电 ханз аянгын дүрснээс гаралтай гэж үздэг.", "answer": "true", "why_mn": "电-ийн зурган хэлбэр эрт цагт аянгыг дүрсэлсэн гэж үздэг."}, {"type": "fill", "question": "«Үд» гэдгийг ханзаар бич.", "answer": "午", "why_mn": "午 бол «үд, 11-13 цаг» гэсэн утгатай."}]}], "hanzi": [{"hanzi": "午", "pinyin": "wǔ", "meaning_mn": "үд", "story_mn": "午 бол дан бүтэцт ханз, өөр жижиг ханз агуулаагүй. Гарал үүсэл нь тодорхойгүй тул зохиомол домог гаргахгүй, зөвхөн «11-13 цагийн хоорондох цагийг заана» гэдгийг сана.", "stroke_count": 4, "stroke_tips_mn": ["Эхлээд зүүн налуу зурлагыг тат", "Дараа нь хэвтээ зурлагыг тат", "Эцэст нь дунд хэсгийн урт босоог дээрээс доош тат"], "words": [{"zh": "中午", "pinyin": "zhōngwǔ", "mn": "үд дунд"}, {"zh": "上午", "pinyin": "shàngwǔ", "mn": "өглөө (үдээс өмнө)"}]}, {"hanzi": "电", "pinyin": "diàn", "meaning_mn": "цахилгаан", "story_mn": "电-ийн эртний зурган хэлбэр аянга цахилгааны гялбааг дүрсэлсэн гэж үздэг — дээд хэсэг нь үүл, доод хэсэг нь мушгирсан аянгын зураас.", "stroke_count": 5, "stroke_tips_mn": ["Дээд хэсгийн хүрээг эхэлж бич", "Дотор талын хэвтээ зурлагуудыг дараа нь тат", "Эцэст нь доод мушгиа зурлагыг тат"], "confusable": [{"zh": "申", "pinyin": "shēn", "mn": "мэдэгдэх, сунгах", "diff_mn": "电-д доод хэсэгт мушгиа зураас нэмэгдсэн байдаг бол 申-д зөвхөн шулуун босоо зураас байдаг."}], "words": [{"zh": "电脑", "pinyin": "diànnǎo", "mn": "компьютер"}, {"zh": "电影", "pinyin": "diànyǐng", "mn": "кино"}]}], "pronunciation": {"focus_mn": "Энэ хичээлд «2 цаг» гэхэд 二 биш 两 хэрэглэдгийг бататгаж, мөн сул хөг зөвхөн дуудлага биш УТГА хүртэл ялгадгийг (жишээ нь dōngxi/dōngxī) анхаарч сур.", "drills": [{"title_mn": "两 vs 二: 2 гэдэг тоог зөв хэлэх", "instruction_mn": "Хосыг харьцуулж, аль тохиолдолд 两, аль тохиолдолд 二 хэрэглэдгийг ялга.", "pairs": [{"a": {"zh": "两点", "pinyin": "liǎng diǎn", "mn": "хоёр цаг"}, "b": {"zh": "二月", "pinyin": "èr yuè", "mn": "хоёрдугаар сар"}, "note_mn": "Цаг хэлэхэд 两, сарын дугаарт 二 хэрэглэнэ."}, {"a": {"zh": "两个人", "pinyin": "liǎng ge rén", "mn": "хоёр хүн"}, "b": {"zh": "第二", "pinyin": "dì èr", "mn": "хоёрдугаар"}, "note_mn": "Зүйл тоолоход 两, дараалал заахад 二 хэрэглэнэ."}]}, {"title_mn": "Сул хөг утга ялгана: dōngxi / dōngxī", "instruction_mn": "Хосыг дараалан хэлж, хөгийн ялгаагаар утга хэрхэн өөрчлөгдөхийг сонс.", "pairs": [{"a": {"zh": "东西", "pinyin": "dōngxi", "mn": "юм, эд зүйл"}, "b": {"zh": "东西", "pinyin": "dōngxī", "mn": "зүүн баруун"}, "note_mn": "Хоёр дахь үе сул бол «юм», 1-р хөгтэй бол «зүүн баруун»."}, {"a": {"zh": "买卖", "pinyin": "mǎimai", "mn": "наймаа"}, "b": {"zh": "买卖", "pinyin": "mǎimài", "mn": "худалдах, худалдан авах"}, "note_mn": "Сул хөг — нэр үг, 4-р хөг — үйл үг гэсэн утгын ялгаа."}]}, {"title_mn": "3-3 хөгийн хувирал: 几点", "instruction_mn": "Хоёр 3-р хөг зэрэгцэхэд эхнийх нь 2-р хөг шиг дуудагдахыг дадлагажуул.", "pairs": [{"a": {"zh": "几点", "pinyin": "jǐ diǎn", "mn": "хэдэн цаг"}, "b": {"zh": "你好", "pinyin": "nǐ hǎo", "mn": "сайн уу"}, "note_mn": "Хоёул хоёр 3-р хөг зэрэгцсэн тул эхний үг 2-р хөг шиг өгсдөг."}, {"a": {"zh": "几点", "pinyin": "jǐ diǎn", "mn": "хэдэн цаг"}, "b": {"zh": "九点", "pinyin": "jiǔ diǎn", "mn": "есөн цаг"}, "note_mn": "几点 хоёулаа 3-р хөгтэй тул хувирна, 九点 нь 3+3 биш тул хувирахгүй."}]}], "tips_mn": ["2 гэдэг тоог цаг, ширхэг тоолоход 两 гэж хэлдгийг сайн санаарай, 二 гэж бүү хэл.", "Сул хөгийг зөв дуудахгүй бол утга бүрмөсөн өөр болж хувирдгийг мартуузай."]}}'::jsonb)
