values ('hsk1-l12', 1, '{"words": [{"zh": "天气", "pinyin": "tiānqì", "teach_mn": "天气 гэдэг нь “цаг агаар” гэсэн утгатай нэр үг. 天 (тэнгэр) ба 气 (агаар) хоёр нийлж тогтмол нэг ойлголт болсон. Өгүүлбэрт ихэвчлэн газар, цагийн нэрийн дараа орж, “...ийн цаг агаар” гэсэн утгаар хэрэглэгддэг. 怎么样-тай хамт асуухад “цаг агаар ямар байна” гэсэн маш түгээмэл асуулт болдог.", "usage_mn": ["Цаг агаарын байдал асуух, ярихад хэрэглэнэ", "Ганцаараа зөвхөн “агаар” гэсэн утгаар хэрэглэдэггүй, 气 гэж тусад нь тайрч хэлдэггүй"], "examples": [{"zh": "明天天气怎么样？", "pinyin": "Míngtiān tiānqì zěnmeyàng?", "mn": "Маргааш тэнгэр ямар байх вэ?", "note_mn": "цаг агаар асуух хамгийн түгээмэл өгүүлбэр"}, {"zh": "今天天气很好。", "pinyin": "Jīntiān tiānqì hěn hǎo.", "mn": "Өнөөдөр цаг агаар сайхан байна.", "note_mn": "很-ээр энгийн үнэлгээ өгөх"}, {"zh": "天气太热了。", "pinyin": "Tiānqì tài rè le.", "mn": "Цаг агаар хэтэрхий халуун байна.", "note_mn": "太……了-гээр хэтэрснийг нэмж хэлэх"}, {"zh": "昨天北京的天气怎么样？", "pinyin": "Zuótiān Běijīng de tiānqì zěnmeyàng?", "mn": "Өчигдөр Бээжинд тэнгэр ямар байсан бэ?", "note_mn": "газрын нэрийг 的-ээр холбож асуух"}], "mistakes": [{"wrong": "天气怎么样天气？", "right": "天气怎么样？", "why_mn": "«天气» гэдэг үгийг өгүүлбэрт нэг л удаа хэлнэ, монгол хэлний адилаар давтан хэлэх шаардлагагүй."}, {"wrong": "今天气怎么样？", "right": "今天天气怎么样？", "why_mn": "今天 (өнөөдөр) ба 天气 (цаг агаар) хоёр өөр үг тул хоёуланг нь бүтнээр нь бичих ёстой, товчлж нэгтгэж болохгүй."}], "compare": [{"zh": "天", "pinyin": "tiān", "mn": "тэнгэр; өдөр", "diff_mn": "天 дангаараа “өдөр/тэнгэр” гэсэн утгатай, 天气 бол “цаг агаар” гэсэн тогтвортой нийлмэл үг."}]}, {"zh": "怎么样", "pinyin": "zěnmeyàng", "teach_mn": "怎么样 гэдэг нь ямар нэг зүйлийн байдал, чанарыг асуухад хэрэглэдэг асуух төлөөний үг. Өгүүлбэрийн төгсгөлд ирж “...ямар вэ?” гэсэн утга өгдөг. Хүний бие, ажил, сурлага, цаг агаар зэргийг ерөнхийд нь асуухад тохиромжтой.", "usage_mn": ["Ерөнхий байдал, чанарыг асуухад хэрэглэнэ (нарийвчилсан асуулт биш)", "Тоо хэмжээ асуухад хэрэглэдэггүй — тоо асуухад 多少/几 хэрэглэнэ"], "examples": [{"zh": "你的汉语怎么样？", "pinyin": "Nǐ de Hànyǔ zěnmeyàng?", "mn": "Хятад хэл чинь ямар байна?"}, {"zh": "明天天气怎么样？", "pinyin": "Míngtiān tiānqì zěnmeyàng?", "mn": "Маргааш тэнгэр ямар байх вэ?"}, {"zh": "你妈妈身体怎么样？", "pinyin": "Nǐ māma shēntǐ zěnmeyàng?", "mn": "Ээжийн чинь бие ямар байна?"}, {"zh": "你身体怎么样？", "pinyin": "Nǐ shēntǐ zěnmeyàng?", "mn": "Бие чинь ямар байна?"}], "mistakes": [{"wrong": "怎么样你的汉语？", "right": "你的汉语怎么样？", "why_mn": "怎么样 нь өгүүлбэрийн төгсгөлд ордог, монгол хэлний “ямар вэ” шиг эхэнд тавьж болохгүй."}]}, {"zh": "太（太……了）", "pinyin": "tài (tài…le)", "teach_mn": "太 нь хэмжээ хэтэрсэн байдлыг заана, ихэвчлэн өгүүлбэрийн төгсгөлд 了-той хамт орж “太……了” хэлбэрээр хэрэглэгддэг. Энэ нь зүгээр л “их” гэснээс илүү “хэтэрхий, дэндүү” гэсэн сэтгэл ханамжгүй буюу гайхсан утгыг агуулна. Үгүйсгэхэд 了-г хассан “不太……” хэлбэрийг хэрэглэнэ, энэ үед “тийм ч ...биш” гэсэн зөөлөн утгатай болно.", "usage_mn": ["Хэт ихийг гомдоллох, гайхах утгаар хэрэглэнэ (太热了, 太冷了)", "Үгүйсгэхэд 了-г хасаад 不太 гэж хэрэглэнэ — 不太……了 гэж хамт хэрэглэдэггүй"], "examples": [{"zh": "太热了。", "pinyin": "Tài rè le.", "mn": "Хэтэрхий халуун байна."}, {"zh": "天气太冷了。", "pinyin": "Tiānqì tài lěng le.", "mn": "Тэнгэр хэтэрхий хүйтэн байна."}, {"zh": "我身体不太好。", "pinyin": "Wǒ shēntǐ bú tài hǎo.", "mn": "Миний бие тааруухан байна."}, {"zh": "太好了！", "pinyin": "Tài hǎo le!", "mn": "Гоё байна!"}], "mistakes": [{"wrong": "我身体不太好了。", "right": "我身体不太好。", "why_mn": "Үгүйсгэлийн 不太 хэлбэрт 了 нэмдэггүй, 了 зөвхөн батлах 太……了 хэлбэрт ордог."}], "compare": [{"zh": "很", "pinyin": "hěn", "mn": "их, маш", "diff_mn": "很 бол энгийн үнэлгээ (их сайн), 太……了 бол хэтэрсэн, гомдолтой утгатай (хэтэрхий)."}]}, {"zh": "热", "pinyin": "rè", "teach_mn": "热 нь халуун байдлыг заасан чанарын үг. Цаг агаар, хоол, орчны халуунд адилхан хэрэглэгддэг. Түүнтэй эсрэг утгатай үг нь 冷 (хүйтэн).", "usage_mn": ["Цаг агаар, орчин, зүйлийн халуун байдлыг тодорхойлоход хэрэглэнэ", "很 болон 太……了-тай хамт хэрэглэгдэх нь их түгээмэл"], "examples": [{"zh": "天气太热了。", "pinyin": "Tiānqì tài rè le.", "mn": "Цаг агаар хэтэрхий халуун байна."}, {"zh": "今天很热。", "pinyin": "Jīntiān hěn rè.", "mn": "Өнөөдөр их халуун байна."}, {"zh": "不冷不热。", "pinyin": "Bù lěng bú rè.", "mn": "Хүйтэн ч биш халуун ч биш."}], "mistakes": [{"wrong": "天气很热了。", "right": "天气很热。", "why_mn": "很-тэй хэрэглэхэд 了 авдаггүй, 了 зөвхөн 太……了 бүтэцтэй холбоотой."}], "compare": [{"zh": "冷", "pinyin": "lěng", "mn": "хүйтэн", "diff_mn": "Эсрэг утгатай үг."}]}, {"zh": "冷", "pinyin": "lěng", "teach_mn": "冷 нь 热-ийн эсрэг утгатай, хүйтэн байдлыг заана. Цаг агаар, ус, өрөөний температур зэрэгт хэрэглэгддэг чанарын үг.", "usage_mn": ["Цаг агаар хүйтэн байгааг хэлэхэд хэрэглэнэ", "热-тэй хамт 不冷不热 гэсэн тогтсон хэлц болж хэрэглэгддэг"], "examples": [{"zh": "天气太冷了。", "pinyin": "Tiānqì tài lěng le.", "mn": "Тэнгэр хэтэрхий хүйтэн байна."}, {"zh": "今天很冷。", "pinyin": "Jīntiān hěn lěng.", "mn": "Өнөөдөр их хүйтэн байна."}, {"zh": "不冷不热，很好。", "pinyin": "Bù lěng bú rè, hěn hǎo.", "mn": "Хүйтэн ч биш халуун ч биш, сайхан байна."}], "mistakes": [{"wrong": "我很冷天气。", "right": "天气很冷。", "why_mn": "Өгүүлэгдэхүүн (天气) өгүүлбэрийн эхэнд ордог, “би хүйтэн цаг агаартай” гэж шууд орчуулж болохгүй."}]}, {"zh": "下雨", "pinyin": "xià yǔ", "teach_mn": "下雨 нь “бороо орох” гэсэн нийлмэл хэллэг. 下 нь “буух” 雨 нь “бороо” гэсэн утгатай тул шууд утгаараа “бороо буух”. Цаг уурын байдал тайлбарлахад голчлон хэрэглэгддэг.", "usage_mn": ["Цаг агаарын тухай ярихдаа бороо орох эсэхийг хэлэхэд хэрэглэнэ", "会-тэй хамт хэрэглэвэл “бороо орох байх” гэсэн таамаглал болно"], "examples": [{"zh": "今天会下雨吗？", "pinyin": "Jīntiān huì xià yǔ ma?", "mn": "Өнөөдөр бороо орох болов уу?"}, {"zh": "今天不会下雨。", "pinyin": "Jīntiān bú huì xià yǔ.", "mn": "Өнөөдөр бороо орохгүй."}, {"zh": "明天会下雨吗？", "pinyin": "Míngtiān huì xià yǔ ma?", "mn": "Маргааш бороо орох болов уу?"}], "mistakes": [{"wrong": "今天下雨会吗？", "right": "今天会下雨吗？", "why_mn": "会 нь үйл үгийн өмнө ордог, “орох болов уу” гэсэн монгол дарааллыг шууд хятад руу оруулж болохгүй."}]}, {"zh": "小姐", "pinyin": "xiǎojiě", "teach_mn": "小姐 нь эмэгтэй хүнийг хүндэтгэн дуудах үг, овгийн ард залгаж хэрэглэдэг. Монгол хэлний “...гуай” шиг үүрэгтэй. Гэрлээгүй залуу эмэгтэйд илүү тохиромжтой боловч зарим орчинд эелдгээр дуудахад ч хэрэглэдэг.", "usage_mn": ["Овгийн ард нэмж эмэгтэй хүнийг хүндэтгэн дуудахад хэрэглэнэ (王小姐)", "Гэр бүлийн гишүүнийг дуудахад хэрэглэдэггүй"], "examples": [{"zh": "王小姐今天会来吗？", "pinyin": "Wáng xiǎojiě jīntiān huì lái ma?", "mn": "Ван хатагтай өнөөдөр ирэх болов уу?"}, {"zh": "她是王小姐。", "pinyin": "Tā shì Wáng xiǎojiě.", "mn": "Тэр бол Ван хатагтай."}, {"zh": "谢谢你，小姐。", "pinyin": "Xièxie nǐ, xiǎojiě.", "mn": "Баярлалаа, хатагтай аа."}], "mistakes": [{"wrong": "小姐王", "right": "王小姐", "why_mn": "Овог нь 小姐-ийн өмнө ордог, хятад хэлэнд цол үргэлж овгийн ард ирнэ."}]}, {"zh": "来", "pinyin": "lái", "teach_mn": "来 нь “ирэх” гэсэн энгийн үйл үг, өгүүлэгч рүү чиглэсэн хөдөлгөөнийг заана. Эсрэг утгатай нь 去 (явах, тэнд рүү).", "usage_mn": ["Ярьж буй хүн рүү ойртох хөдөлгөөнд хэрэглэнэ", "Явах чиглэлд 去 хэрэглэнэ, 来-тэй андуурч болохгүй"], "examples": [{"zh": "她会来。", "pinyin": "Tā huì lái.", "mn": "Тэр ирнэ."}, {"zh": "她不会来。", "pinyin": "Tā bú huì lái.", "mn": "Тэр ирэхгүй."}, {"zh": "明天她会来吗？", "pinyin": "Míngtiān tā huì lái ma?", "mn": "Маргааш тэр ирэх болов уу?"}], "mistakes": [{"wrong": "她来会。", "right": "她会来。", "why_mn": "会 үргэлж үйл үгийн өмнө ордог, “ирнэ болов уу” гэдэг монгол дарааллаар шууд орчуулж болохгүй."}], "compare": [{"zh": "去", "pinyin": "qù", "mn": "явах", "diff_mn": "Чиглэл эсрэг: 来 ярьж буй хүн рүү, 去 тэндээс холдох."}]}, {"zh": "身体", "pinyin": "shēntǐ", "teach_mn": "身体 нь хүний биеийг заасан нэр үг бөгөөд эрүүл мэндийн утгаар “бие ямар байна” гэж асуухад хэрэглэгддэг. Энэ бол монгол хэлний “сайн байна уу” шиг эелдэг мэндчилгээний нэг хэлбэр.", "usage_mn": ["Хэн нэгний эрүүл мэндийг эелдгээр асуухад хэрэглэнэ", "Зүгээр л анатомийн “бие” гэсэн утгаар ярианд бага хэрэглэгддэг"], "examples": [{"zh": "你身体怎么样？", "pinyin": "Nǐ shēntǐ zěnmeyàng?", "mn": "Бие чинь ямар байна?"}, {"zh": "你妈妈身体怎么样？", "pinyin": "Nǐ māma shēntǐ zěnmeyàng?", "mn": "Ээжийн чинь бие ямар байна?"}, {"zh": "我身体不太好。", "pinyin": "Wǒ shēntǐ bú tài hǎo.", "mn": "Миний бие тааруухан байна."}], "mistakes": [{"wrong": "你怎么样身体？", "right": "你身体怎么样？", "why_mn": "怎么样 өгүүлбэрийн төгсгөлд ордог, 身体 нь өгүүлэгдэхүүний дараах сэдэв."}]}, {"zh": "爱", "pinyin": "ài", "teach_mn": "爱 нь “хайрлах” гэсэн хүчтэй мэдрэмж заасан үйл үг боловч ярианд “их дуртай байх” гэсэн зөөлөн утгаар ч хэрэглэгддэг. Гэр бүлийн гишүүд, дотны хүмүүст хайр илэрхийлэхээс гадна үйл ажиллагаанд их дуртайг илэрхийлж болно.", "usage_mn": ["Хүнд хайр илэрхийлэхэд болон ямар нэг зүйлд их дуртайгаа хэлэхэд хэрэглэнэ", "喜欢-ээс илүү хүчтэй мэдрэмж заана, өдөр тутмын жижиг зүйлд хэтрүүлж хэрэглэвэл хачин сонсогдоно"], "examples": [{"zh": "不爱吃饭。", "pinyin": "Bú ài chī fàn.", "mn": "Хоол идэх дургүй байна."}, {"zh": "天气太热了，不爱吃饭。", "pinyin": "Tiānqì tài rè le, bú ài chī fàn.", "mn": "Хэт халуун болохоор хоол идэх дургүй байна."}, {"zh": "我爱喝水。", "pinyin": "Wǒ ài hē shuǐ.", "mn": "Би ус уухдаа дуртай."}], "mistakes": [{"wrong": "我爱吃饭不。", "right": "我不爱吃饭。", "why_mn": "Үгүйсгэх 不 нь үйл үгийн өмнө ордог, монгол хэлний “...гүй” дагаврыг шууд ард залгаж болохгүй."}]}, {"zh": "些", "pinyin": "xiē", "teach_mn": "些 нь тоолж баршгүй, тодорхойгүй бага хэмжээг заасан хэмжигдэхүүний үг. Ихэвчлэн 多……些 хэлбэрээр нэр үгийн өмнө орж “цөөн хэдэн, жаахан” гэсэн утга өгдөг.", "usage_mn": ["Тодорхой бус, бага хэмжээг заахад хэрэглэнэ (多吃些水果)", "Тодорхой тоотой хамт хэрэглэдэггүй (жишээ нь 三个-той хамт 些 ордоггүй)"], "examples": [{"zh": "你多吃些水果。", "pinyin": "Nǐ duō chī xiē shuǐguǒ.", "mn": "Жимс ихээр идээрэй."}, {"zh": "多吃些水果，多喝水。", "pinyin": "Duō chī xiē shuǐguǒ, duō hē shuǐ.", "mn": "Жимс ихээр ид, ус ихээр уу."}, {"zh": "多喝些水。", "pinyin": "Duō hē xiē shuǐ.", "mn": "Ус жаахан ихээр уу."}], "mistakes": [{"wrong": "吃些三个水果。", "right": "吃三个水果 / 吃些水果", "why_mn": "些 нь тодорхой тоотой хамт хэрэглэгддэггүй, аль нэгийг нь сонгож хэрэглэнэ."}]}, {"zh": "水果", "pinyin": "shuǐguǒ", "teach_mn": "水果 нь “жимс” гэсэн ерөнхий ойлголт заасан нэр үг. 水 (ус) ба 果 (үр жимс) хоёр нийлж, шүүслэг жимсийг заана.", "usage_mn": ["Алим, банана зэрэг бүх төрлийн жимсийг ерөнхийд нь нэрлэхэд хэрэглэнэ", "Ногоо (蔬菜)-той андуурч болохгүй"], "examples": [{"zh": "多吃些水果。", "pinyin": "Duō chī xiē shuǐguǒ.", "mn": "Жимс их ид."}, {"zh": "我吃水果。", "pinyin": "Wǒ chī shuǐguǒ.", "mn": "Би жимс иднэ."}, {"zh": "多喝水，多吃水果。", "pinyin": "Duō hē shuǐ, duō chī shuǐguǒ.", "mn": "Ус ихээр уу, жимс ихээр ид."}], "mistakes": [{"wrong": "水果吃多。", "right": "多吃水果。", "why_mn": "多 (их) нь үйл үгийн өмнө ордог, монгол хэлэнд “ихээр” үйл үгийн ард ч ордог тул андуурч болохгүй."}], "compare": [{"zh": "水", "pinyin": "shuǐ", "mn": "ус", "diff_mn": "水 дангаараа “ус”, 水果 бол “жимс” гэсэн тусдаа үг."}]}, {"zh": "水", "pinyin": "shuǐ", "teach_mn": "水 нь “ус” гэсэн энгийн нэр үг. Уух ус, байгалийн ус зэрэгт хэрэглэгдэнэ. 水果 (жимс) гэдэг үгэнд язгуур утга болж ордог.", "usage_mn": ["Ус уух, ундаа гэдэг утгаар өдөр тутамд их хэрэглэгддэг", "喝水 (ус уух) хэллэгийн бүрэлдэхүүн болдог"], "examples": [{"zh": "多喝水。", "pinyin": "Duō hē shuǐ.", "mn": "Ус ихээр уу."}, {"zh": "我喝水。", "pinyin": "Wǒ hē shuǐ.", "mn": "Би ус уудаг."}, {"zh": "我不喝水。", "pinyin": "Wǒ bù hē shuǐ.", "mn": "Би ус уухгүй."}], "mistakes": [{"wrong": "我水喝。", "right": "我喝水。", "why_mn": "Хятад хэлэнд үйл үг (喝) тухайн зүйлийн (水) өмнө ордог, монгол хэлний эсрэг дарааллыг андуурч болохгүй."}]}], "grammar": [{"point": "疑问代词 怎么样", "gloss_mn": "怎么样: «ямар вэ?» гэж байдал асуух", "structure": "Сэдэв(+нэр үг) + 怎么样？", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "怎么样 нь ямар нэг зүйл, хүний байдал, чанар ямар байгааг ерөнхийд нь асуух асуух төлөөний үг. Монгол хэлний “ямар вэ, яаж байна” гэсэнтэй адил.", "example": {"zh": "怎么样？", "pinyin": "Zěnmeyàng?", "mn": "Ямар байна?"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Асуух зүйлээ (сэдвээ) өгүүлбэрийн эхэнд тавиад, төгсгөлд нь 怎么样 залгана: 天气 + 怎么样 → 天气怎么样？", "example": {"zh": "天气怎么样？", "pinyin": "Tiānqì zěnmeyàng?", "mn": "Цаг агаар ямар байна?"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Хүний эрүүл мэнд, ажил, сурлага, цаг агаар зэргийг ерөнхийд нь асуухдаа хэрэглэнэ. Тоо хэмжээ, нэр асуухад хэрэглэдэггүй.", "example": {"zh": "你的汉语怎么样？", "pinyin": "Nǐ de Hànyǔ zěnmeyàng?", "mn": "Хятад хэл чинь ямар байна?"}}, {"title_mn": "4. Хариулах хэлбэр", "body_mn": "怎么样 гэсэн асуултад тодорхой шинж чанар заасан үгээр хариулна: 很好, 不太好, 太热了 гэх мэт.", "example": {"zh": "很好。", "pinyin": "Hěn hǎo.", "mn": "Сайхан байна."}}], "examples": [{"zh": "明天天气怎么样？", "pinyin": "Míngtiān tiānqì zěnmeyàng?", "mn": "Маргааш тэнгэр ямар байх вэ?"}, {"zh": "你妈妈身体怎么样？", "pinyin": "Nǐ māma shēntǐ zěnmeyàng?", "mn": "Ээжийн чинь бие ямар байна?"}, {"zh": "你身体怎么样？", "pinyin": "Nǐ shēntǐ zěnmeyàng?", "mn": "Бие чинь ямар байна?"}, {"zh": "你的汉语怎么样？", "pinyin": "Nǐ de Hànyǔ zěnmeyàng?", "mn": "Хятад хэл чинь ямар байна?"}, {"zh": "今天天气很好。", "pinyin": "Jīntiān tiānqì hěn hǎo.", "mn": "Өнөөдөр цаг агаар сайхан байна."}, {"zh": "昨天北京的天气怎么样？", "pinyin": "Zuótiān Běijīng de tiānqì zěnmeyàng?", "mn": "Өчигдөр Бээжинд тэнгэр ямар байсан бэ?"}], "mistakes": [{"wrong": "怎么样天气？", "right": "天气怎么样？", "why_mn": "怎么样 үргэлж өгүүлбэрийн төгсгөлд ордог."}, {"wrong": "天气怎么样吗？", "right": "天气怎么样？", "why_mn": "怎么样 өөрөө асуултын утгатай тул төгсгөлд 吗 нэмж давхар асуух шаардлагагүй."}], "drills": [{"type": "choice", "question": "你身体___？", "answer": "怎么样", "why_mn": "Байдал асуухад 怎么样 хэрэглэнэ, 什么 юм асуух, 吗 тийм/үгүй асуултад хэрэглэнэ.", "options": ["怎么样", "什么", "吗"]}, {"type": "fill", "question": "明天天气___？（ямар байх вэ гэж асуу）", "answer": "怎么样", "why_mn": "“Ямар байх вэ” гэдгийг 怎么样-аар илэрхийлнэ."}, {"type": "judge", "question": "怎么样天气好吗？ гэдэг өгүүлбэр зөв үү?", "answer": "false", "why_mn": "怎么样-г өгүүлбэрийн эхэнд тавьсан нь буруу, мөн 吗-той хамт хэрэглэх шаардлагагүй давхардал бий."}, {"type": "choice", "question": "你妈妈___？（эрүүл мэндийг нь асуу）", "answer": "身体怎么样", "why_mn": "Сэдэв (身体) эхэнд, 怎么样 төгсгөлд ордог дараалал зөв хэлбэр.", "options": ["身体怎么样", "怎么样身体", "身体什么"]}]}, {"point": "主谓谓语句", "gloss_mn": "Өгүүлэгдэхүүн-өгүүлэхүүн бүтэцтэй өгүүлбэр", "structure": "Том сэдэв + жижиг сэдэв + чанарын үг — 我 + 身体 + 不太好", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "Хятад өгүүлбэрт заримдаа “өгүүлэхүүн” хэсэг нь өөрөө дахин “өгүүлэгдэхүүн+өгүүлэхүүн” гэсэн жижиг бүтэцтэй байдаг. Жишээ нь 我身体不太好 гэхэд “би” том сэдэв, “бие тааруухан” нь жижиг өгүүлбэр шиг ажилладаг.", "example": {"zh": "我身体不太好。", "pinyin": "Wǒ shēntǐ bú tài hǎo.", "mn": "Миний бие тааруухан."}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Том сэдэв (хүн) + жижиг сэдэв (биеийн эрхтэн/тал) + чанар заасан үг. Монгол хэлэнд “Миний бие” гэж холбож хэлдэг бол хятад хэлэнд “би, бие, муу” гэж дараалан жагсаадаг.", "example": {"zh": "你身体怎么样？", "pinyin": "Nǐ shēntǐ zěnmeyàng?", "mn": "Бие чинь ямар байна?"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Хүний бие эрхтэн, цаг агаарын нэг хэсэг зэргийг тодотгон тайлбарлахад ашигтай. Ялангуяа биеийн байдал, цаг агаар зэрэг сэдвүүдэд түгээмэл.", "example": {"zh": "明天天气很好。", "pinyin": "Míngtiān tiānqì hěn hǎo.", "mn": "Маргааш тэнгэр сайхан байна."}}, {"title_mn": "4. Монгол хэлтэй харьцуулбал", "body_mn": "Монгол хэлэнд “миний бие өвдөж байна” гэж харьяалахын нөхцөл ашигладаг бол хятад хэлэнд ямар ч нөхцөлгүйгээр гурван үгийг зэрэгцүүлж хэлдэг.", "example": {"zh": "我身体不太好。", "pinyin": "Wǒ shēntǐ bú tài hǎo.", "mn": "Миний бие тааруухан байна."}}], "examples": [{"zh": "我身体不太好。", "pinyin": "Wǒ shēntǐ bú tài hǎo.", "mn": "Миний бие тааруухан байна."}, {"zh": "你身体怎么样？", "pinyin": "Nǐ shēntǐ zěnmeyàng?", "mn": "Бие чинь ямар байна?"}, {"zh": "明天天气很好。", "pinyin": "Míngtiān tiānqì hěn hǎo.", "mn": "Маргааш тэнгэр сайхан байна."}, {"zh": "你妈妈身体怎么样？", "pinyin": "Nǐ māma shēntǐ zěnmeyàng?", "mn": "Ээжийн чинь бие ямар байна?"}, {"zh": "今天天气很好，不冷不热。", "pinyin": "Jīntiān tiānqì hěn hǎo, bù lěng bú rè.", "mn": "Өнөөдөр цаг агаар сайхан, хүйтэн ч биш халуун ч биш."}], "mistakes": [{"wrong": "我的身体不太好是。", "right": "我身体不太好。", "why_mn": "Энэ бүтэцт 是 хэрэглэх шаардлагагүй, чанарын үг шууд өгүүлэхүүн болдог."}, {"wrong": "身体我不太好。", "right": "我身体不太好。", "why_mn": "Том сэдэв (би) заавал эхэнд ордог, дараа нь жижиг сэдэв (бие)."}], "drills": [{"type": "choice", "question": "___不太好。（миний бие тааруу гэж хэл）", "answer": "我身体", "why_mn": "Том сэдэв 我 эхэнд, жижиг сэдэв 身体 дараа нь ордог.", "options": ["我身体", "身体我", "我是身体"]}, {"type": "judge", "question": "我身体不太好是。 Энэ өгүүлбэр зөв үү?", "answer": "false", "why_mn": "Энд 是 хэрэггүй, чанарын үг (不太好) шууд өгүүлэхүүн болдог."}, {"type": "fill", "question": "妈妈___很好。（ээжийн бие сайхан гэж хэл）", "answer": "身体", "why_mn": "Жижиг сэдэв 身体-г том сэдвийн (妈妈) дараа тавина."}]}, {"point": "程度副词 太", "gloss_mn": "太……了: «хэтэрхий»", "structure": "太 + чанарын үг + (了)", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "太 нь хэмжээ хэтэрснийг заасан дэрэглэсэн үг, ихэвчлэн төгсгөлд 了-той хамт ирж сэтгэл ханамжгүй буюу гайхсан утга илэрхийлнэ.", "example": {"zh": "太热了。", "pinyin": "Tài rè le.", "mn": "Хэтэрхий халуун байна."}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "太 нь чанарын үгийн өмнө, 了 нь өгүүлбэрийн төгсгөлд ордог: 太 + 冷/热/好 + 了.", "example": {"zh": "天气太冷了。", "pinyin": "Tiānqì tài lěng le.", "mn": "Тэнгэр хэтэрхий хүйтэн байна."}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Ямар нэг зүйл хэвийн хэмжээнээс хэтэрсэн гэдгийг гомдоллох, эсвэл эсрэгээрээ баясах өнгө аястайгаар хэлэхэд хэрэглэнэ (太好了! — Гоё байна!).", "example": {"zh": "太好了！", "pinyin": "Tài hǎo le!", "mn": "Гоё байна!"}}, {"title_mn": "4. Үгүйсгэх хэлбэр", "body_mn": "Үгүйсгэхдээ 不太 гэж хэрэглэнэ, энэ үед 了 авдаггүй бөгөөд “тийм ч ...биш” гэсэн зөөлөн утгатай болдог: 不太好 (тийм ч сайн биш).", "example": {"zh": "我身体不太好。", "pinyin": "Wǒ shēntǐ bú tài hǎo.", "mn": "Миний бие тааруухан байна."}}], "examples": [{"zh": "太热了。", "pinyin": "Tài rè le.", "mn": "Хэтэрхий халуун байна."}, {"zh": "天气太冷了。", "pinyin": "Tiānqì tài lěng le.", "mn": "Тэнгэр хэтэрхий хүйтэн байна."}, {"zh": "我身体不太好。", "pinyin": "Wǒ shēntǐ bú tài hǎo.", "mn": "Миний бие тааруухан байна."}, {"zh": "太好了！", "pinyin": "Tài hǎo le!", "mn": "Гоё байна!"}, {"zh": "天气太热了，不爱吃饭。", "pinyin": "Tiānqì tài rè le, bú ài chī fàn.", "mn": "Хэт халуун болохоор хоол идэх дургүй байна."}, {"zh": "不会来，天气太冷了。", "pinyin": "Bú huì lái, tiānqì tài lěng le.", "mn": "Ирэхгүй, хэтэрхий хүйтэн байна."}], "mistakes": [{"wrong": "我身体不太好了。", "right": "我身体不太好。", "why_mn": "Үгүйсгэлд 了 авдаггүй."}, {"wrong": "天气热太了。", "right": "天气太热了。", "why_mn": "太 үргэлж чанарын үгийн өмнө ордог, ард нь ордоггүй."}], "drills": [{"type": "choice", "question": "天气___冷了。", "answer": "太", "why_mn": "了-той хамт “хэтэрхий” гэсэн утгыг 太 л илэрхийлнэ.", "options": ["太", "很", "不太"]}, {"type": "fill", "question": "我身体___好。（тийм ч сайн биш гэж хэл）", "answer": "不太", "why_mn": "Үгүйсгэхэд 不太 хэрэглэнэ, 了 авахгүй."}, {"type": "judge", "question": "我身体不太好了。 гэдэг зөв үү?", "answer": "false", "why_mn": "不太-тэй хамт 了 хэрэглэдэггүй."}, {"type": "choice", "question": "___了！（гайхширсан баяр илэрхийл）", "answer": "太好了", "why_mn": "太……了 хамтдаа хэрэглэгдэж гайхсан баясал илэрхийлнэ.", "options": ["太好", "太好了", "很好了"]}]}, {"point": "能愿动词 会 (2)", "gloss_mn": "会: магадлал — «болов уу, болно»", "structure": "Сэдэв + 会 + үйл үг + (吗)", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "会 нь энд “чадах” гэсэн урьд сурсан утгаараа биш, ямар нэг зүйл тохиолдох магадлалыг заана — “...байх, болов уу” гэсэн санаа.", "example": {"zh": "今天会下雨吗？", "pinyin": "Jīntiān huì xià yǔ ma?", "mn": "Өнөөдөр бороо орох болов уу?"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "会 нь үйл үгийн өмнө ордог, асуухдаа төгсгөлд 吗 нэмнэ: 会 + 下雨 + 吗？", "example": {"zh": "她会来吗？", "pinyin": "Tā huì lái ma?", "mn": "Тэр ирэх болов уу?"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Ирээдүйд болох магадлалтай зүйлийг таамаглахад хэрэглэнэ, ялангуяа цаг агаар, хүний ирэх эсэх зэрэгт түгээмэл.", "example": {"zh": "她会来。", "pinyin": "Tā huì lái.", "mn": "Тэр ирнэ."}}, {"title_mn": "4. Үгүйсгэх хэлбэр", "body_mn": "Үгүйсгэхдээ 不会 гэж хэлнэ: 不会下雨 (бороо орохгүй байх).", "example": {"zh": "今天不会下雨。", "pinyin": "Jīntiān bú huì xià yǔ.", "mn": "Өнөөдөр бороо орохгүй."}}], "examples": [{"zh": "今天会下雨吗？", "pinyin": "Jīntiān huì xià yǔ ma?", "mn": "Өнөөдөр бороо орох болов уу?"}, {"zh": "今天不会下雨。", "pinyin": "Jīntiān bú huì xià yǔ.", "mn": "Өнөөдөр бороо орохгүй."}, {"zh": "王小姐今天会来吗？", "pinyin": "Wáng xiǎojiě jīntiān huì lái ma?", "mn": "Ван хатагтай өнөөдөр ирэх болов уу?"}, {"zh": "不会来，天气太冷了。", "pinyin": "Bú huì lái, tiānqì tài lěng le.", "mn": "Ирэхгүй, хэтэрхий хүйтэн байна."}, {"zh": "明天她会来吗？—她会来。", "pinyin": "Míngtiān tā huì lái ma? — Tā huì lái.", "mn": "Маргааш тэр ирэх болов уу? — Ирнэ."}, {"zh": "她不会来。", "pinyin": "Tā bú huì lái.", "mn": "Тэр ирэхгүй."}], "mistakes": [{"wrong": "今天下雨会吗？", "right": "今天会下雨吗？", "why_mn": "会 үйл үгийн өмнө ордог."}, {"wrong": "她会不来。", "right": "她不会来。", "why_mn": "Үгүйсгэх 不 нь 会-ийн өмнө ордог, дунд нь ордоггүй."}], "drills": [{"type": "choice", "question": "今天___下雨吗？", "answer": "会", "why_mn": "Магадлал асуухад 会 хэрэглэнэ.", "options": ["会", "是", "很"]}, {"type": "fill", "question": "她___来。（ирэхгүй байх гэж хэл）", "answer": "不会", "why_mn": "Үгүйсгэхдээ 不会 гэж хэлнэ."}, {"type": "judge", "question": "他会不来。 гэдэг зөв өгүүлбэр үү?", "answer": "false", "why_mn": "Зөв хэлбэр нь 他不会来, 不 нь 会-ийн өмнө ордог."}]}, {"point": "汉字 — 天 气 雨, 女/饣 язгуур", "gloss_mn": "Ханзны бүтэц ба язгуур", "structure": "天 (тэнгэр), 气 (агаар), 雨 (бороо); 女-язгууртай нь эмэгтэйтэй, 饣-язгууртай нь хоолтой холбоотой", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "Энэ хичээлд гурван шинэ ханз (天, 气, 雨) болон хоёр язгуур (女, 饣) үзнэ. Язгуур гэдэг нь ханзны утгыг тодорхойлж өгдөг тогтмол хэсэг.", "example": {"zh": "天气", "pinyin": "tiānqì", "mn": "天+气=цаг агаар"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "天 хүний толгой дээрх зурааснаас тэнгэр, 气 уур дээшлэх хэлбэрээс агаар, 雨 тэнгэрээс унах дуслуудаас бороо гэсэн санааг тус тус илэрхийлнэ.", "example": {"zh": "雨", "pinyin": "yǔ", "mn": "дөрвөн дусал бороо"}}, {"title_mn": "3. Язгуурын үүрэг", "body_mn": "女 язгууртай ханз ихэвчлэн эмэгтэй хүнтэй холбоотой байна: 姐 (эгч), 妈 (ээж). 饣 язгууртай ханз хоол хүнстэй холбоотой: 饭 (хоол), 饮 (уух).", "example": {"zh": "姐 妈", "pinyin": "jiě mā", "mn": "女-эмэгтэй холбоотой"}}, {"title_mn": "4. Хэрхэн ашиглах вэ", "body_mn": "Шинэ ханз таарахад дотор нь эдгээр язгуурыг олж харвал утгыг нь урьдчилан таамаглаж болно, санахад тус болно.", "example": {"zh": "饭 饮", "pinyin": "fàn yǐn", "mn": "饣-хоол холбоотой"}}], "examples": [{"zh": "天气", "pinyin": "tiānqì", "mn": "цаг агаар"}, {"zh": "下雨", "pinyin": "xià yǔ", "mn": "бороо орох"}, {"zh": "姐 妈", "pinyin": "jiě mā", "mn": "女 эмэгтэй холбоотой жишээ"}, {"zh": "饭 饮", "pinyin": "fàn yǐn", "mn": "饣 хоол холбоотой жишээ"}, {"zh": "明天天气很好。", "pinyin": "Míngtiān tiānqì hěn hǎo.", "mn": "Маргааш тэнгэр сайхан байна."}], "mistakes": [{"wrong": "饭属于女字旁", "right": "饭属于饣字旁（食字旁）", "why_mn": "饭 (хоол) нь хоолтой холбоотой 饣 язгууртай, эмэгтэйтэй холбоотой 女 биш."}], "drills": [{"type": "choice", "question": "姐, 妈 ямар язгуурт багтах вэ?", "answer": "女", "why_mn": "Хоёул эмэгтэй хүнтэй холбоотой тул 女 язгуурт багтана.", "options": ["女", "饣", "氵"]}, {"type": "choice", "question": "饭, 饮 ямар язгуурт багтах вэ?", "answer": "饣", "why_mn": "Хоёул хоол, уух үйлтэй холбоотой тул 饣 язгуурт багтана.", "options": ["女", "饣", "日"]}, {"type": "fill", "question": "雨 ханз нь юу дүрсэлсэн бэ? (нэг үгээр)", "answer": "бороо", "why_mn": "雨-ийн доторх дөрвөн зураас бороо дуслыг дүрсэлдэг."}]}], "hanzi": [{"hanzi": "天", "pinyin": "tiān", "meaning_mn": "тэнгэр; өдөр", "components": [{"c": "一", "meaning_mn": "дээд зураас", "role_mn": "толгойноос ч дээш байгааг заана"}, {"c": "大", "meaning_mn": "том, хүн", "role_mn": "доод хэсэг нь гараа дэлгэсэн хүний дүрс"}], "story_mn": "天 нь доод талдаа гараа дэлгэсэн хүний дүрстэй 大, дээр нь нэг зураас нэмснээр “хүний толгойноос ч дээш өндөрт байгаа зүйл” буюу тэнгэрийг заасан гэж тайлбарладаг.", "stroke_count": 4, "stroke_tips_mn": ["Дээрээс доош, зүүнээс баруун тийш", "Эхлээд хоёр хэвтээ зураас, дараа нь ㄨ хэлбэрийг гүйцээнэ"], "words": [{"zh": "天气", "pinyin": "tiānqì", "mn": "цаг агаар"}, {"zh": "明天", "pinyin": "míngtiān", "mn": "маргааш"}, {"zh": "昨天", "pinyin": "zuótiān", "mn": "өчигдөр"}, {"zh": "今天", "pinyin": "jīntiān", "mn": "өнөөдөр"}]}, {"hanzi": "气", "pinyin": "qì", "meaning_mn": "агаар, хий", "story_mn": "气 нь уур, утаа мэт зүйлийн эргэлдэн дээшлэх хэлбэрийг дүрсэлсэн гэж үздэг, тиймээс агаар, хий, амьсгал зэрэг харагдахгүй зүйлийг илэрхийлдэг ханз болсон.", "stroke_count": 4, "stroke_tips_mn": ["丿-ээр эхэлж, дараа нь хэвтээ зурлагуудыг зурна", "Ижил төстэй 三-тэй андуурахгүй, дээд зураас нь налуу"], "confusable": [{"zh": "三", "pinyin": "sān", "mn": "гурав", "diff_mn": "三 гурван тэгш хэвтээ зураастай, 气-ийн дээд зураас налуу бөгөөд доор нь тохой хэлбэртэй."}], "words": [{"zh": "天气", "pinyin": "tiānqì", "mn": "цаг агаар"}, {"zh": "客气", "pinyin": "kèqi", "mn": "эелдэг байх"}]}, {"hanzi": "雨", "pinyin": "yǔ", "meaning_mn": "бороо", "components": [{"c": "冂", "meaning_mn": "хүрээ", "role_mn": "дээд хэсэг нь тэнгэрийг хүрээлнэ"}, {"c": "丶丶丶丶", "meaning_mn": "дусал", "role_mn": "дотор дөрвөн дусал бороог заана"}], "story_mn": "雨 нь дээд хэсэгтээ тэнгэрийг заасан хүрээтэй, дотроо дусал дуслуудыг дүрсэлсэн зурган ханз — тэнгэрээс унаж буй дусал болохоор бороог илэрхийлдэг.", "stroke_count": 8, "stroke_tips_mn": ["Дээд хүрээгээ эхэлж бич", "Дотор дуслуудыг адилхан зайтай дараалуулан бич"], "words": [{"zh": "下雨", "pinyin": "xià yǔ", "mn": "бороо орох"}, {"zh": "雨天", "pinyin": "yǔtiān", "mn": "бороотой өдөр"}]}], "pronunciation": {"focus_mn": "Энэ хичээлд 太……了-ийн хөгийн онцлог, 不-гийн хувирал, мөн гурван үет үгийн 1-р хөгөөр эхэлдэг хослолуудад анхаарна.", "drills": [{"title_mn": "不-гийн хувирлыг ялгах", "instruction_mn": "Хосыг дараалан хэлж, 不-ийн аялгын өөрчлөлтийг мэдэр.", "pairs": [{"a": {"zh": "不冷", "pinyin": "bù lěng", "mn": "хүйтэн биш"}, "b": {"zh": "不热", "pinyin": "bú rè", "mn": "халуун биш"}, "note_mn": "冷 3-р хөгийн өмнө 不 хэвээрээ bù, 热 4-р хөгийн өмнө bú болж хувирна."}, {"a": {"zh": "不会", "pinyin": "bú huì", "mn": "болохгүй"}, "b": {"zh": "不来", "pinyin": "bù lái", "mn": "ирэхгүй"}, "note_mn": "会 4-р хөгийн өмнө bú, 来 2-р хөгийн өмнө bù хэвээрээ."}, {"a": {"zh": "不爱", "pinyin": "bú ài", "mn": "дургүй"}, "b": {"zh": "不好", "pinyin": "bù hǎo", "mn": "муу"}, "note_mn": "爱 4-р хөгийн өмнө bú, 好 3-р хөгийн өмнө bù хэвээрээ."}]}, {"title_mn": "太……了-г зөв дуудах", "instruction_mn": "太-г огцом 4-р хөгөөр буулгаж, ард нь 了-г сулхан хэл.", "pairs": [{"a": {"zh": "太热了", "pinyin": "tài rè le", "mn": "хэтэрхий халуун"}, "b": {"zh": "太冷了", "pinyin": "tài lěng le", "mn": "хэтэрхий хүйтэн"}, "note_mn": "太 хоёул 4-р хөгөөр огцом буугаад, le сулхан."}, {"a": {"zh": "太好了", "pinyin": "tài hǎo le", "mn": "гоё байна"}, "b": {"zh": "太热了", "pinyin": "tài rè le", "mn": "хэтэрхий халуун"}, "note_mn": "太好了 баясал, 太热了 гомдол илэрхийлдэг ч хөг ижил."}, {"a": {"zh": "不太好", "pinyin": "bú tài hǎo", "mn": "тийм ч сайн биш"}, "b": {"zh": "太冷了", "pinyin": "tài lěng le", "mn": "хэтэрхий хүйтэн"}, "note_mn": "不太 нь батлах 太……了-аас ялгаатай, 了 авдаггүй."}]}, {"title_mn": "Гурван үет үг: 1-р хөгөөр эхлэх", "instruction_mn": "Эхний үеийг тэгш өндөр авч, дараагийн хоёр үеийг хөг өөрчлөлтөөр нь хэл.", "pairs": [{"a": {"zh": "星期一", "pinyin": "xīngqī yī", "mn": "даваа гараг"}, "b": {"zh": "高脚杯", "pinyin": "gāojiǎobēi", "mn": "хундага"}, "note_mn": "Эхний 星/高 бүгд 1-р хөгөөр тэгш эхэлнэ."}, {"a": {"zh": "芭蕾舞", "pinyin": "bāléiwǔ", "mn": "балет"}, "b": {"zh": "水果", "pinyin": "shuǐguǒ", "mn": "жимс"}, "note_mn": "3+3 хослол дараалахад эхний 3-р хөг 2-р хөг шиг дуудагдана (shuíguǒ)."}, {"a": {"zh": "吃米饭", "pinyin": "chī mǐfàn", "mn": "будаа идэх"}, "b": {"zh": "加拿大", "pinyin": "Jiānádà", "mn": "Канад"}, "note_mn": "1+3+4 болон 1+2+4 хослолд эхний үе тэгш өндөр хэвээр."}]}], "tips_mn": ["太……了-г хэлэхдээ 太-г тодотгож, сэтгэл хөдлөлөө илэрхийл", "不-ийн хувирлыг цээжлэхийн оронд дараагийн үгийн хөгийг харж дадлагажуул"]}}'::jsonb)
