insert into public.lesson_deep_teaching (lesson_id, version, payload)
values ('hsk1-l13', 1, '{"words": [{"zh": "喂", "pinyin": "wèi", "teach_mn": "喂 нь утсаар ярихад хэрэглэдэг тусгай дуудлагын үг, монгол хэлний “байна уу” гэсэнтэй адил. Утас авахад эсвэл хэн нэгэнтэй утсаар холбогдож эхлэхэд өгүүлбэрийн хамгийн эхэнд тавьж хэрэглэнэ.", "usage_mn": ["Зөвхөн утсаар ярихад, ярианы эхэнд хэрэглэнэ", "Нүүр тулан уулзахад “сайн уу” гэсэн утгаар хэрэглэдэггүй"], "examples": [{"zh": "喂，你在做什么呢？", "pinyin": "Wèi, nǐ zài zuò shénme ne?", "mn": "Байна уу, чи юу хийж байна?"}, {"zh": "喂，李老师在家吗？", "pinyin": "Wèi, Lǐ lǎoshī zài jiā ma?", "mn": "Байна уу, Ли багш гэртээ байна уу?"}, {"zh": "喂，你是张小姐吗？", "pinyin": "Wèi, nǐ shì Zhāng xiǎojiě ma?", "mn": "Байна уу, та Жан хатагтай мөн үү?"}], "mistakes": [{"wrong": "你好，你在做什么呢？（утсаар авахдаа）", "right": "喂，你在做什么呢？", "why_mn": "Утсаар ярихдаа эхэлж 喂 гэж хэлдэг, ердийн уулзалтын 你好-той андуурч болохгүй."}]}, {"zh": "也", "pinyin": "yě", "teach_mn": "也 нь “бас, мөн” гэсэн утгатай дэрэглэсэн үг, өмнөх хэн нэгэнтэй адилхан зүйл хийж/байгааг нэмж хэлэхэд хэрэглэнэ. Үргэлж сэдвийн дараа, үйл үгийн өмнө ордог.", "usage_mn": ["Өмнөх өгүүлбэртэй адилхан зүйлийг нэмж хэлэхэд хэрэглэнэ", "Өгүүлбэрийн хамгийн эхэнд бус, сэдвийн дараа ордог"], "examples": [{"zh": "大卫也在看书吗？", "pinyin": "Dàwèi yě zài kàn shū ma?", "mn": "Дэвид бас ном уншиж байна уу?"}, {"zh": "我也喜欢看电影。", "pinyin": "Wǒ yě xǐhuan kàn diànyǐng.", "mn": "Би ч бас кинонд дуртай."}, {"zh": "她也会来。", "pinyin": "Tā yě huì lái.", "mn": "Тэр ч бас ирнэ."}], "mistakes": [{"wrong": "也大卫在看书吗？", "right": "大卫也在看书吗？", "why_mn": "也 нь сэдвийн (大卫) дараа, үйл үгийн (看) өмнө ордог, өгүүлбэрийн хамгийн эхэнд ордоггүй."}]}, {"zh": "学习（学）", "pinyin": "xuéxí (xué)", "teach_mn": "学习 нь “сурах, суралцах” гэсэн үйл үг, товчлон 学 гэж ганцаараа мөн хэрэглэдэг. 在学 гэвэл “сурч байна” гэсэн үргэлжлэх утгатай болно.", "usage_mn": ["Хичээл, ур чадвар эзэмших үйл ажиллагаанд хэрэглэнэ", "在 (…ж байна)-той хамт хэрэглэвэл яг одоо сурч байгааг заана"], "examples": [{"zh": "他在学做中国菜呢。", "pinyin": "Tā zài xué zuò Zhōngguó cài ne.", "mn": "Тэр хятад хоол хийж сурч байна."}, {"zh": "我在学习汉语。", "pinyin": "Wǒ zài xuéxí Hànyǔ.", "mn": "Би хятад хэл сурч байна."}, {"zh": "你在学习吗？", "pinyin": "Nǐ zài xuéxí ma?", "mn": "Чи сурч байна уу?"}], "mistakes": [{"wrong": "他在做学中国菜呢。", "right": "他在学做中国菜呢。", "why_mn": "学 (сурах) нь 做 (хийх)-ийн өмнө ирж “хийхийг сурах” гэсэн дараалалтай, эсрэгээр байрлуулж болохгүй."}]}, {"zh": "上午", "pinyin": "shàngwǔ", "teach_mn": "上午 нь өдрийн цагийг заасан цаг хугацааны үг, үдээс өмнөх хугацааг илэрхийлнэ. Өгүүлбэрт огноо, өдрийн нэрийн дараа, үйл үгийн өмнө ордог.", "usage_mn": ["Өдрийн аль хэсэг болохыг тодотгоход хэрэглэнэ (өглөө–үд)", "Цагийн тодорхой минут заахад хэрэглэдэггүй, зөвхөн өдрийн хэсгийг заана"], "examples": [{"zh": "昨天上午你在做什么呢？", "pinyin": "Zuótiān shàngwǔ nǐ zài zuò shénme ne?", "mn": "Өчигдөр өглөө чи юу хийж байсан бэ?"}, {"zh": "我上午在家。", "pinyin": "Wǒ shàngwǔ zài jiā.", "mn": "Би өглөө гэртээ байсан."}, {"zh": "你上午做什么？", "pinyin": "Nǐ shàngwǔ zuò shénme?", "mn": "Чи өглөө юу хийдэг вэ?"}], "mistakes": [{"wrong": "你在做什么呢上午？", "right": "上午你在做什么呢？", "why_mn": "Цаг хугацаа заасан үг (上午) өгүүлбэрийн эхэнд эсвэл сэдвийн дараа ордог, төгсгөлд ордоггүй."}]}, {"zh": "睡觉", "pinyin": "shuì jiào", "teach_mn": "睡觉 нь “унтах” гэсэн үйл үг-нэр үгийн нийлмэл хэллэг. 觉-ийн хэсгийг тусад нь заримдаа тоо нэмж 睡一觉 (нэг удаа унтах) гэх мэтээр ч хэрэглэдэг.", "usage_mn": ["Шөнийн ба өдрийн нойрыг хоёуланг нь заана", "在……呢-тэй хамт хэрэглэвэл яг одоо унтаж байгааг заана"], "examples": [{"zh": "我在睡觉呢。", "pinyin": "Wǒ zài shuì jiào ne.", "mn": "Би унтаж байсан."}, {"zh": "你在睡觉吗？", "pinyin": "Nǐ zài shuì jiào ma?", "mn": "Чи унтаж байна уу?"}, {"zh": "他没睡觉。", "pinyin": "Tā méi shuì jiào.", "mn": "Тэр унтаагүй байна."}], "mistakes": [{"wrong": "我睡觉在呢。", "right": "我在睡觉呢。", "why_mn": "在 нь үргэлж үйл үгийн (睡觉) өмнө ордог, ард нь орж болохгүй."}]}, {"zh": "电视", "pinyin": "diànshì", "teach_mn": "电视 нь “зурагт, телевиз” гэсэн нэр үг. 电 (цахилгаан) ба 视 (харах) хоёр нийлж, цахилгаанаар харах төхөөрөмж гэсэн санааг илэрхийлнэ.", "usage_mn": ["Гэрийн зурагт үзэх үйл ажиллагаанд хэрэглэнэ", "Кино театрт үзэх кинонд 电影 хэрэглэнэ, 电视-тэй андуурахгүй"], "examples": [{"zh": "我在家看电视呢。", "pinyin": "Wǒ zài jiā kàn diànshì ne.", "mn": "Би гэртээ зурагт үзэж байсан."}, {"zh": "你喜欢看电视吗？", "pinyin": "Nǐ xǐhuan kàn diànshì ma?", "mn": "Чи зурагт үзэх дуртай юу?"}, {"zh": "我不喜欢看电视，我喜欢看电影。", "pinyin": "Wǒ bù xǐhuan kàn diànshì, wǒ xǐhuan kàn diànyǐng.", "mn": "Би зурагтад дургүй, кинонд дуртай."}], "mistakes": [{"wrong": "我看电视电影。", "right": "我看电视，我看电影。", "why_mn": "电视 (зурагт) ба 电影 (кино) хоёр өөр зүйл тул нэг өгүүлбэрт зэрэгцүүлж дурдахдаа тусад нь хэлнэ."}], "compare": [{"zh": "电影", "pinyin": "diànyǐng", "mn": "кино", "diff_mn": "电视 гэрийн зурагтаар үзэх, 电影 театрт үзэх кино."}]}, {"zh": "喜欢", "pinyin": "xǐhuan", "teach_mn": "喜欢 нь ямар нэг зүйл, үйл ажиллагаанд дуртайгаа илэрхийлэх энгийн үйл үг. Дараа нь нэр үг эсвэл өөр үйл үг орж болно (喜欢看电视, 喜欢看电影).", "usage_mn": ["Юманд, хүнд, үйл ажиллагаанд дуртайгаа хэлэхэд хэрэглэнэ", "爱-ээс зөөлөн, өдөр тутмын жижиг зүйлд илүү тохиромжтой"], "examples": [{"zh": "你喜欢看电视吗？", "pinyin": "Nǐ xǐhuan kàn diànshì ma?", "mn": "Чи зурагт үзэх дуртай юу?"}, {"zh": "我不喜欢看电视，我喜欢看电影。", "pinyin": "Wǒ bù xǐhuan kàn diànshì, wǒ xǐhuan kàn diànyǐng.", "mn": "Би зурагтад дургүй, кинонд дуртай."}, {"zh": "她喜欢睡觉。", "pinyin": "Tā xǐhuan shuì jiào.", "mn": "Тэр унтахдаа дуртай."}], "mistakes": [{"wrong": "我喜欢不看电视。", "right": "我不喜欢看电视。", "why_mn": "Үгүйсгэх 不 нь 喜欢-ийн өмнө ордог, 喜欢 ба үйл үгийн (看) хооронд ордоггүй."}], "compare": [{"zh": "爱", "pinyin": "ài", "mn": "хайрлах, их дуртай", "diff_mn": "爱 хүчтэй мэдрэмж, 喜欢 өдөр тутмын энгийн дуртай байдал."}]}, {"zh": "给", "pinyin": "gěi", "teach_mn": "给 нь “өгөх” гэсэн үндсэн утгатай боловч энд угтвар үг шиг хэрэглэгдэж, үйлдлийг хэнд чиглүүлж байгааг заана — монгол хэлний “-д/-т” нөхцөлтэй адил үүрэгтэй.", "usage_mn": ["Хэнд ямар нэг үйлдэл хандуулж байгааг заахад хэрэглэнэ (给她打电话)", "给-г үйл үгийн дараа биш, өмнө нь тавина"], "examples": [{"zh": "我现在给她打电话。", "pinyin": "Wǒ xiànzài gěi tā dǎ diànhuà.", "mn": "Би одоо түүн рүү залгая."}, {"zh": "我给妈妈打电话。", "pinyin": "Wǒ gěi māma dǎ diànhuà.", "mn": "Би ээж рүүгээ утасдана."}, {"zh": "请给我。", "pinyin": "Qǐng gěi wǒ.", "mn": "Надад өгөөч."}], "mistakes": [{"wrong": "我打电话给妈妈。（сурах бичгийн стандарт биш）", "right": "我给妈妈打电话。", "why_mn": "Ярианд 我打电话给妈妈 гэж ч сонсогддог ч сурах бичгийн стандарт бүтэц нь 给-г эхэнд тавьсан хэлбэр."}]}, {"zh": "打电话", "pinyin": "dǎ diànhuà", "teach_mn": "打电话 нь “утсаар ярих, залгах” гэсэн нийлмэл хэллэг. 打 (цохих) энд “хийх” гэсэн ерөнхий утгаар хэрэглэгдэж, утас ашиглах үйлдлийг илэрхийлдэг.", "usage_mn": ["Утсаар холбогдох, залгах үйлдэлд хэрэглэнэ", "Хэнд залгахыг заахдаа 给 + хүн-ийг 打电话-ийн өмнө нэмнэ"], "examples": [{"zh": "他在打电话呢。", "pinyin": "Tā zài dǎ diànhuà ne.", "mn": "Тэр утсаар ярьж байна."}, {"zh": "我现在给她打电话。", "pinyin": "Wǒ xiànzài gěi tā dǎ diànhuà.", "mn": "Би одоо түүн рүү залгая."}, {"zh": "你下午打吧。", "pinyin": "Nǐ xiàwǔ dǎ ba.", "mn": "Үдээс хойш залгаарай."}], "mistakes": [{"wrong": "他打呢电话。", "right": "他在打电话呢。", "why_mn": "打电话 бол салгаж болохгүй тогтсон хэллэг, дунд нь өөр үг оруулбал буруу болно; мөн 在……呢 хэлбэрийг бүрэн хэрэглэх ёстой."}]}, {"zh": "吧", "pinyin": "ba", "teach_mn": "吧 нь өгүүлбэрийн төгсгөлд ирж, тушаал биш зөөлөн санал, урамшуулал өгч байгааг илэрхийлнэ. Монгол хэлний “...аарай, ...ъя” гэсэн зөөлөн хэлбэртэй төстэй.", "usage_mn": ["Санал, зөвлөгөө, урилгыг эелдгээр хэлэхэд хэрэглэнэ", "Хатуу тушаах өгүүлбэрт хэрэглэвэл дэндүү зөөлөрч, санал шиг болно"], "examples": [{"zh": "你下午打吧。", "pinyin": "Nǐ xiàwǔ dǎ ba.", "mn": "Үдээс хойш залгаарай."}, {"zh": "请坐吧。", "pinyin": "Qǐng zuò ba.", "mn": "Сууж байгаарай."}, {"zh": "今天我们在家吃饭吧。", "pinyin": "Jīntiān wǒmen zài jiā chī fàn ba.", "mn": "Өнөөдөр бид гэртээ хоол идье."}], "mistakes": [{"wrong": "吧你下午打。", "right": "你下午打吧。", "why_mn": "吧 үргэлж өгүүлбэрийн хамгийн төгсгөлд ордог."}]}, {"zh": "大卫", "pinyin": "Dàwèi", "teach_mn": "大卫 бол гадаад эрэгтэй нэрийг хятадаар галигласан хэлбэр — “Дэвид” гэсэн нэрийг заана. Хүний нэр учраас өгүүлбэрт шууд сэдэв болж ордог.", "usage_mn": ["Хүний нэр учраас өөрчлөгддөггүй, шууд сэдэв болгож хэрэглэнэ", "Өөр орны нэрийг ч ижил зарчмаар галиглаж болно"], "examples": [{"zh": "大卫也在看书吗？", "pinyin": "Dàwèi yě zài kàn shū ma?", "mn": "Дэвид бас ном уншиж байна уу?"}, {"zh": "他没看书，他在学做中国菜呢。", "pinyin": "Tā méi kàn shū, tā zài xué zuò Zhōngguó cài ne.", "mn": "Тэр (Дэвид) ном уншаагүй, хятад хоол хийж сурч байна."}, {"zh": "我是大卫。", "pinyin": "Wǒ shì Dàwèi.", "mn": "Би бол Дэвид."}], "mistakes": [{"wrong": "Dawei (хөгийн тэмдэггүй бичих)", "right": "Dàwèi", "why_mn": "Галиг нэрэнд ч хөгийн тэмдэг заавал тавьж дуудлагыг нь тодорхой хадгална."}]}], "grammar": [{"point": "叹词 喂", "gloss_mn": "喂: утсаар мэндлэх", "structure": "喂，+ өгүүлбэр", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "喂 бол тусгай дуудлагын үг, зөвхөн утсаар ярихад ярианы эхэнд хэлдэг “байна уу” гэсэн үг.", "example": {"zh": "喂，你在做什么呢？", "pinyin": "Wèi, nǐ zài zuò shénme ne?", "mn": "Байна уу, чи юу хийж байна?"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "喂 өгүүлбэрийн хамгийн эхэнд ганцаараа тавигдаж, ард нь таслал тавьсны дараа энгийн өгүүлбэр үргэлжилнэ.", "example": {"zh": "喂，李老师在家吗？", "pinyin": "Wèi, Lǐ lǎoshī zài jiā ma?", "mn": "Байна уу, Ли багш гэртээ байна уу?"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Зөвхөн утсаар холбогдоход хэрэглэнэ, нүүр тулан уулзахад хэрэглэдэггүй.", "example": {"zh": "喂，你是张小姐吗？", "pinyin": "Wèi, nǐ shì Zhāng xiǎojiě ma?", "mn": "Байна уу, та Жан хатагтай мөн үү?"}}, {"title_mn": "4. Монгол хэлтэй харьцуулбал", "body_mn": "Монгол хэлэнд утас авахдаа “байна уу” гэдэгтэй яг адилхан үүрэгтэй тул сурахад амархан.", "example": {"zh": "喂？", "pinyin": "Wèi?", "mn": "Байна уу?"}}], "examples": [{"zh": "喂，你在做什么呢？", "pinyin": "Wèi, nǐ zài zuò shénme ne?", "mn": "Байна уу, чи юу хийж байна?"}, {"zh": "喂，李老师在家吗？", "pinyin": "Wèi, Lǐ lǎoshī zài jiā ma?", "mn": "Байна уу, Ли багш гэртээ байна уу?"}, {"zh": "喂，你是张小姐吗？", "pinyin": "Wèi, nǐ shì Zhāng xiǎojiě ma?", "mn": "Байна уу, та Жан хатагтай мөн үү?"}, {"zh": "喂，你在家吗？", "pinyin": "Wèi, nǐ zài jiā ma?", "mn": "Байна уу, чи гэртээ байна уу?"}, {"zh": "喂，是王小姐吗？", "pinyin": "Wèi, shì Wáng xiǎojiě ma?", "mn": "Байна уу, Ван хатагтай мөн үү?"}], "mistakes": [{"wrong": "你好，你在做什么呢？（утсаар авахдаа）", "right": "喂，你在做什么呢？", "why_mn": "Утсаар ярихдаа 你好 биш 喂 гэж эхэлдэг."}, {"wrong": "你在做什么呢，喂？", "right": "喂，你在做什么呢？", "why_mn": "喂 үргэлж өгүүлбэрийн хамгийн эхэнд ордог, төгсгөлд ордоггүй."}], "drills": [{"type": "choice", "question": "Утсаар ярихдаа юу гэж эхэлдэг вэ?", "answer": "喂", "why_mn": "喂 бол утсаар ярихад л хэрэглэдэг тусгай үг.", "options": ["你好", "喂", "早上好"]}, {"type": "judge", "question": "Нүүр тулан уулзахдаа 喂 гэж мэндэлдэг үү?", "answer": "false", "why_mn": "喂 зөвхөн утсаар ярихад хэрэглэдэг, биечлэн уулзахад 你好 хэрэглэнэ."}, {"type": "fill", "question": "___，李老师在家吗？", "answer": "喂", "why_mn": "Утсаар асуухдаа 喂-ээр эхэлнэ."}]}, {"point": "在……呢", "gloss_mn": "在……呢: яг одоо болж буй үйлдэл", "structure": "Сэдэв + 在 + үйл үг + (объект) + 呢", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "在……呢 нь үйлдэл яг тухайн мөчид болж байгааг заана, монгол хэлний “...ж байна” гэсэнтэй тохирно.", "example": {"zh": "我在看书呢。", "pinyin": "Wǒ zài kàn shū ne.", "mn": "Би ном уншиж байна."}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "在 нь үйл үгийн өмнө, 呢 нь өгүүлбэрийн төгсгөлд ордог. Хоёулаа заавал байх албагүй, гэхдээ хамт байвал “яг одоо” гэдгийг илүү тодотгоно.", "example": {"zh": "我在睡觉呢。", "pinyin": "Wǒ zài shuì jiào ne.", "mn": "Би унтаж байсан."}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Утсаар ярихад, эсвэл хэн нэгэн юу хийж байгааг асуухад, хариулахад голчлон хэрэглэнэ.", "example": {"zh": "喂，你在做什么呢？", "pinyin": "Wèi, nǐ zài zuò shénme ne?", "mn": "Байна уу, чи юу хийж байна?"}}, {"title_mn": "4. Үгүйсгэх хэлбэр", "body_mn": "Үгүйсгэхдээ 没(在) гэж хэлж, 呢-г бүрэн хасна: 他没看书 (тэр ном уншаагүй). 在……呢-ийг хамтад нь үгүйсгэдэггүй.", "example": {"zh": "他没看书。", "pinyin": "Tā méi kàn shū.", "mn": "Тэр ном уншаагүй."}}], "examples": [{"zh": "我在看书呢。", "pinyin": "Wǒ zài kàn shū ne.", "mn": "Би ном уншиж байна."}, {"zh": "我在睡觉呢。", "pinyin": "Wǒ zài shuì jiào ne.", "mn": "Би унтаж байсан."}, {"zh": "喂，你在做什么呢？", "pinyin": "Wèi, nǐ zài zuò shénme ne?", "mn": "Байна уу, чи юу хийж байна?"}, {"zh": "他没看书，他在学做中国菜呢。", "pinyin": "Tā méi kàn shū, tā zài xué zuò Zhōngguó cài ne.", "mn": "Тэр ном уншаагүй, хятад хоол хийж сурч байна."}, {"zh": "昨天上午你在做什么呢？", "pinyin": "Zuótiān shàngwǔ nǐ zài zuò shénme ne?", "mn": "Өчигдөр өглөө чи юу хийж байсан бэ?"}, {"zh": "她在工作呢，你下午打吧。", "pinyin": "Tā zài gōngzuò ne, nǐ xiàwǔ dǎ ba.", "mn": "Тэр ажиллаж байна, үдээс хойш залгаарай."}], "mistakes": [{"wrong": "我没在看电视呢。", "right": "我没在看电视。", "why_mn": "Үгүйсгэхэд 呢-г хасна, 没在……呢 гэж хамт хэрэглэдэггүй."}, {"wrong": "我看呢书在。", "right": "我在看书呢。", "why_mn": "在 үйл үгийн өмнө, 呢 өгүүлбэрийн төгсгөлд гэсэн байрлалыг андуурч болохгүй."}], "drills": [{"type": "choice", "question": "我___看书___。（яг одоо уншиж байна）", "answer": "在...呢", "why_mn": "Яг одоо болж буй үйлдлийг 在……呢-ээр илэрхийлнэ.", "options": ["在...呢", "会...吗", "是...的"]}, {"type": "fill", "question": "他___看书。（ном уншаагүй гэж хэл）", "answer": "没", "why_mn": "在……呢-ийн үгүйсгэл нь 没, 呢-г хасна."}, {"type": "judge", "question": "我没在看电视呢。 зөв өгүүлбэр үү?", "answer": "false", "why_mn": "Үгүйсгэхэд 呢 үлддэггүй."}, {"type": "choice", "question": "喂，你___做什么呢？", "answer": "在", "why_mn": "Яг одоогийн үйлдэл асуухад 在……呢 хэрэглэнэ.", "options": ["在", "会", "是"]}]}, {"point": "电话号码的表达", "gloss_mn": "Утасны дугаар хэлэх", "structure": "Тоо тус бүрийг дараалан уншина, 1 = yāo, 0 = líng", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "Хятад хэлэнд утасны дугаарыг нэгтгэсэн тоо биш, цифр бүрийг тус тусад нь нэг нэгээр нь уншдаг.", "example": {"zh": "82304156", "pinyin": "bā èr sān líng sì yāo wǔ liù", "mn": "Тоо бүрийг тусад нь хэлнэ."}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Цифр бүрийг өөрийн дуудлагаар дараалуулан хэлнэ, тоо нэгтгэж “наян хоёр мянга” гэх мэтээр уншдаггүй.", "example": {"zh": "13851897623", "pinyin": "yāo sān bā wǔ yāo bā jiǔ qī liù èr sān", "mn": "Гар утасны дугаарыг цифрээр нь унших."}}, {"title_mn": "3. Онцлог дуудлага", "body_mn": "1-ийг ердийн yī гэж биш yāo гэж, 0-ийг líng гэж дууддаг, учир нь yī нь 7 (qī)-тэй андуурагдахаас сэргийлдэг.", "example": {"zh": "82304156", "pinyin": "bā èr sān líng sì yāo wǔ liù", "mn": "1 = yāo, 0 = líng."}}, {"title_mn": "4. Хаана хэрэглэх", "body_mn": "Утасны дугаар солилцох, лавлах үед л энэ дүрмийг хэрэглэнэ, ердийн тоо тоолоход энгийн yī, líng хэвээр байна.", "example": {"zh": "她的电话是82304156。", "pinyin": "Tā de diànhuà shì bā èr sān líng sì yāo wǔ liù.", "mn": "Түүний утасны дугаар 82304156."}}], "examples": [{"zh": "82304156", "pinyin": "bā èr sān líng sì yāo wǔ liù", "mn": "Утасны дугаар."}, {"zh": "13851897623", "pinyin": "yāo sān bā wǔ yāo bā jiǔ qī liù èr sān", "mn": "Гар утасны дугаар."}, {"zh": "82304155，这是李老师的电话吗？", "pinyin": "Bā èr sān líng sì yāo wǔ wǔ, zhè shì Lǐ lǎoshī de diànhuà ma?", "mn": "82304155 — энэ Ли багшийн дугаар мөн үү?"}, {"zh": "不是。她的电话是82304156。", "pinyin": "Bú shì. Tā de diànhuà shì bā èr sān líng sì yāo wǔ liù.", "mn": "Биш. Түүний дугаар 82304156."}, {"zh": "好，我现在给她打电话。", "pinyin": "Hǎo, wǒ xiànzài gěi tā dǎ diànhuà.", "mn": "За, би одоо түүн рүү залгая."}], "mistakes": [{"wrong": "82304156-г “найман сая хорин гурван мянга…” гэж унших", "right": "bā èr sān líng sì yāo wǔ liù гэж тус тусад нь унших", "why_mn": "Хятад хэлэнд утасны дугаарыг тоон утгаар нь биш, цифр бүрийг тус тусад нь дуудна."}], "drills": [{"type": "fill", "question": "82304156 дахь “1”-ийг яаж дуудах вэ?", "answer": "yāo", "why_mn": "Утасны дугаарт 1-ийг yāo гэж дууддаг, 7 (qī)-тэй андуурахгүйн тулд."}, {"type": "choice", "question": "82304156 дахь “0”-ийг яаж дуудах вэ?", "answer": "líng", "why_mn": "0 үргэлж líng гэж дуудагдана.", "options": ["líng", "yāo", "èr"]}, {"type": "judge", "question": "Утасны дугаарыг мянга, зуугаар нь нэгтгэж уншдаг уу?", "answer": "false", "why_mn": "Утасны дугаарыг цифр бүрээр нь тус тусад нь уншина."}]}, {"point": "语气助词 吧", "gloss_mn": "吧: зөөлөн санал, хүсэлт", "structure": "Өгүүлбэр + 吧", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "吧 нь өгүүлбэрийн төгсгөлд ирж, тушаалыг зөөлрүүлж, санал болгож буй өнгө аяс өгдөг.", "example": {"zh": "你下午打吧。", "pinyin": "Nǐ xiàwǔ dǎ ba.", "mn": "Үдээс хойш залгаарай."}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Ердийн өгүүлбэрийн төгсгөлд шууд 吧-г нэмнэ, өөр ямар ч өөрчлөлт хийх шаардлагагүй.", "example": {"zh": "请坐吧。", "pinyin": "Qǐng zuò ba.", "mn": "Сууж байгаарай."}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Хэн нэгэнд зөвлөгөө өгөх, урих, санал болгоход хэрэглэнэ, ялангуяа 请 үгтэй хамт эелдэг байдлыг нэмэгдүүлнэ.", "example": {"zh": "今天我们在家吃饭吧。", "pinyin": "Jīntiān wǒmen zài jiā chī fàn ba.", "mn": "Өнөөдөр бид гэртээ хоол идье."}}, {"title_mn": "4. Монгол хэлтэй харьцуулбал", "body_mn": "Монгол хэлэнд “...аарай” “...ъя” гэсэн нөхцлүүд ижил үүрэг гүйцэтгэдэг тул 吧-г мэдрэмжээрээ дадлагажуулбал ойлгомжтой.", "example": {"zh": "你下午打吧。", "pinyin": "Nǐ xiàwǔ dǎ ba.", "mn": "Үдээс хойш залгаарай."}}], "examples": [{"zh": "你下午打吧。", "pinyin": "Nǐ xiàwǔ dǎ ba.", "mn": "Үдээс хойш залгаарай."}, {"zh": "请坐吧。", "pinyin": "Qǐng zuò ba.", "mn": "Сууж байгаарай."}, {"zh": "今天我们在家吃饭吧。", "pinyin": "Jīntiān wǒmen zài jiā chī fàn ba.", "mn": "Өнөөдөр бид гэртээ хоол идье."}, {"zh": "她在工作呢，你下午打吧。", "pinyin": "Tā zài gōngzuò ne, nǐ xiàwǔ dǎ ba.", "mn": "Тэр ажиллаж байна, үдээс хойш залгаарай."}, {"zh": "这儿没有人，请坐吧。", "pinyin": "Zhèr méiyǒu rén, qǐng zuò ba.", "mn": "Энд хүнгүй, сууж байгаарай."}], "mistakes": [{"wrong": "吧你下午打。", "right": "你下午打吧。", "why_mn": "吧 үргэлж өгүүлбэрийн хамгийн төгсгөлд ордог."}, {"wrong": "你下午打吗吧。", "right": "你下午打吧。", "why_mn": "吧 (санал) ба 吗 (тийм/үгүй асуулт) хоёрыг хамт хэрэглэдэггүй."}], "drills": [{"type": "choice", "question": "请坐___。（эелдгээр санал болго）", "answer": "吧", "why_mn": "吧 нь зөөлөн санал, урилга илэрхийлнэ.", "options": ["吧", "吗", "呢"]}, {"type": "judge", "question": "吧-г өгүүлбэрийн эхэнд тавьж болох уу?", "answer": "false", "why_mn": "吧 үргэлж өгүүлбэрийн төгсгөлд ордог."}, {"type": "fill", "question": "你下午打___。（санал болгож хэл）", "answer": "吧", "why_mn": "Зөөлөн санал болгохдоо 吧 нэмнэ."}]}, {"point": "汉字 — 日 目 习, 日/目 язгуур", "gloss_mn": "Ханзны бүтэц ба язгуур", "structure": "日 (нар), 目 (нүд), 习 (давтах); 日-язгууртай нь цаг хугацаатай, 目-язгууртай нь нүдтэй холбоотой", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "Энэ хичээлд 日, 目, 习 гэсэн гурван шинэ ханз, мөн 日 ба 目 хэмээх хоёр язгуурыг үзнэ.", "example": {"zh": "日 目 习", "pinyin": "rì mù xí", "mn": "нар, нүд, давтах"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "日 нь дугуй нарыг дүрсэлсэн дөрвөлжин, 目 үүнээс нэг зураас илүүтэй, нүдийг дүрсэлсэн, 习 бол шувууны жигүүрний сэгсрэлтээс гаралтай гэж тайлбарладаг.", "example": {"zh": "目", "pinyin": "mù", "mn": "日-ээс нэг зураасаар илүү"}}, {"title_mn": "3. Язгуурын үүрэг", "body_mn": "日 язгууртай ханз цаг хугацаатай холбоотой байдаг: 明 (гэрэл/маргааш), 时 (цаг), 昨 (өчигдөр). 目 язгууртай ханз нүдтэй холбоотой: 眼 (нүд), 睡 (унтах).", "example": {"zh": "明 时", "pinyin": "míng shí", "mn": "日-цаг хугацаатай холбоотой"}}, {"title_mn": "4. Хэрхэн ашиглах вэ", "body_mn": "Шинэ ханз таарахад дотор нь 日 эсвэл 目 байвал утгыг нь цаг хугацаа эсвэл нүд/харах үйлтэй холбож таамаглаж болно.", "example": {"zh": "眼 睡", "pinyin": "yǎn shuì", "mn": "目-нүдтэй холбоотой"}}], "examples": [{"zh": "明 时", "pinyin": "míng shí", "mn": "日 цаг хугацаатай холбоотой"}, {"zh": "眼 睡", "pinyin": "yǎn shuì", "mn": "目 нүдтэй холбоотой"}, {"zh": "学习", "pinyin": "xuéxí", "mn": "сурах"}, {"zh": "明天上午", "pinyin": "míngtiān shàngwǔ", "mn": "маргааш өглөө"}, {"zh": "我在睡觉呢。", "pinyin": "Wǒ zài shuì jiào ne.", "mn": "Би унтаж байсан."}], "mistakes": [{"wrong": "眼 нь 日 язгууртай", "right": "眼 нь 目 язгуурт багтана", "why_mn": "眼 нь нүдтэй холбоотой утгатай тул 目 язгуурт багтана, 日-тэй андуурч болохгүй."}], "drills": [{"type": "choice", "question": "明, 时, 昨 ямар язгуурт багтах вэ?", "answer": "日", "why_mn": "Гурвуулаа цаг хугацаатай холбоотой тул 日 язгуурт багтана.", "options": ["日", "目", "氵"]}, {"type": "choice", "question": "眼, 睡 ямар язгуурт багтах вэ?", "answer": "目", "why_mn": "Хоёул нүд, харах үйлтэй холбоотой тул 目 язгуурт багтана.", "options": ["日", "目", "女"]}, {"type": "fill", "question": "习 ханзны утга юу вэ?", "answer": "давтах/сурах", "why_mn": "习 нь давтан сурах гэсэн утгатай."}]}], "hanzi": [{"hanzi": "日", "pinyin": "rì", "meaning_mn": "нар; өдөр", "story_mn": "日 нь эртний хятад бичигт дугуй нарыг доторх цэгтэйгээр дүрсэлсэн байсан бөгөөд цаг хугацааны явцад дөрвөлжин хэлбэр болж хувирсан.", "stroke_count": 4, "stroke_tips_mn": ["Зүүн талын босоо зурлагаас эхэл", "Дотор хэвтээ зураас нэмэхээ бүү март"], "confusable": [{"zh": "目", "pinyin": "mù", "mn": "нүд", "diff_mn": "日-ээс нэг хэвтээ зураасаар цөөн, өндөр богино харьцаа өөр."}], "words": [{"zh": "明天", "pinyin": "míngtiān", "mn": "маргааш"}, {"zh": "昨天", "pinyin": "zuótiān", "mn": "өчигдөр"}, {"zh": "生日", "pinyin": "shēngrì", "mn": "төрсөн өдөр"}]}, {"hanzi": "目", "pinyin": "mù", "meaning_mn": "нүд", "story_mn": "目 нь эртний бичигт нүдний хэлбэрийг хэвтээгээр дүрсэлсэн байсан ба хожим босоо байрлалд орж, доторх зурлагууд нь нүдний харц, зовхийг илэрхийлдэг болсон гэж үздэг.", "stroke_count": 5, "stroke_tips_mn": ["日-тэй адил бичээд дотор нь нэг хэвтээ зураас нэмж ялгана", "Дээрээс доош, зүүнээс баруун дараалалтай"], "confusable": [{"zh": "日", "pinyin": "rì", "mn": "нар, өдөр", "diff_mn": "目 дотроо нэг илүү хэвтээ зураастай тул 日-ээс арай өндөр харагдана."}], "words": [{"zh": "眼睛", "pinyin": "yǎnjing", "mn": "нүд"}, {"zh": "睡觉", "pinyin": "shuì jiào", "mn": "унтах"}]}, {"hanzi": "习", "pinyin": "xí", "meaning_mn": "давтах, сурах", "story_mn": "习 нь анх шувууны жигүүрийг олон удаа сэгсрэн нисэхийг сурах дүрснээс гаралтай гэж тайлбарладаг, тиймээс “давтан сурах” гэсэн утгатай болсон.", "stroke_count": 3, "stroke_tips_mn": ["Зүүн доошоо татсан зурлагаас эхэл", "Гурван зурлагыг нягт, жижиг зайтай бич"], "words": [{"zh": "学习", "pinyin": "xuéxí", "mn": "сурах"}, {"zh": "练习", "pinyin": "liànxí", "mn": "дасгал хийх"}]}], "pronunciation": {"focus_mn": "Энэ хичээлд 呢/吧 зэрэг сул хөгийн үгс, утасны дугаарын 1=yāo дуудлага, мөн 2-р хөгөөр эхэлдэг гурван үет үгийн хослолд анхаарна.", "drills": [{"title_mn": "Сул хөгийг ялгах: 呢 ба 吧", "instruction_mn": "Өгүүлбэрийг төгсгөлийн үгээрээ ялгаж, сулхан дуудаж дадлагажуул.", "pairs": [{"a": {"zh": "我在看书呢", "pinyin": "wǒ zài kàn shū ne", "mn": "Би ном уншиж байна"}, "b": {"zh": "你下午打吧", "pinyin": "nǐ xiàwǔ dǎ ba", "mn": "Үдээс хойш залгаарай"}, "note_mn": "呢 ба 吧 хоёул сул хөгтэй, төгсгөлд нь дуу хоолойгоо бүү өндөрсгө."}, {"a": {"zh": "我在睡觉呢", "pinyin": "wǒ zài shuì jiào ne", "mn": "Би унтаж байсан"}, "b": {"zh": "请坐吧", "pinyin": "qǐng zuò ba", "mn": "Сууж байгаарай"}, "note_mn": "呢 мэдээлэл үргэлжилж буйг, 吧 санал буюу зөвшөөрлийг заана."}, {"a": {"zh": "他在打电话呢", "pinyin": "tā zài dǎ diànhuà ne", "mn": "Тэр утсаар ярьж байна"}, "b": {"zh": "今天我们吃饭吧", "pinyin": "jīntiān wǒmen chī fàn ba", "mn": "Өнөөдөр бид хоол идье"}, "note_mn": "Хоёул төгсгөлийн сул хөгтэй боловч утга өөр."}]}, {"title_mn": "Утасны дугаарын дуудлага", "instruction_mn": "Цифр бүрийг тусад нь, тодорхой дуудаж дадлагажуул.", "pairs": [{"a": {"zh": "1", "pinyin": "yāo", "mn": "нэг (утасны дугаарт)"}, "b": {"zh": "7", "pinyin": "qī", "mn": "долоо"}, "note_mn": "yāo ба qī андуурагдахаас сэргийлж 1-ийг тод дуудна."}, {"a": {"zh": "0", "pinyin": "líng", "mn": "тэг"}, "b": {"zh": "6", "pinyin": "liù", "mn": "зургаа"}, "note_mn": "líng-ийг сунжруулан, liù-г богино тод хэл."}, {"a": {"zh": "82304156", "pinyin": "bā èr sān líng sì yāo wǔ liù", "mn": "утасны дугаар жишээ"}, "b": {"zh": "13851897623", "pinyin": "yāo sān bā wǔ yāo bā jiǔ qī liù èr sān", "mn": "гар утасны дугаар жишээ"}, "note_mn": "Урт дугаарыг гурав гурваар нь бүлэглэж амьсгаагаад унших нь илүү тодорхой сонсогдоно."}]}, {"title_mn": "Гурван үет үг: 2-р хөгөөр эхлэх", "instruction_mn": "Эхний үеийг өргөж, дараагийн хөгийн өөрчлөлтийг мэдэрч хэл.", "pairs": [{"a": {"zh": "图书馆", "pinyin": "túshūguǎn", "mn": "номын сан"}, "b": {"zh": "服务员", "pinyin": "fúwùyuán", "mn": "зөөгч"}, "note_mn": "Хоёул 2-р хөгөөр эхэлж, дараагийн хөг өөр өөр хэв маягтай."}, {"a": {"zh": "人民币", "pinyin": "rénmínbì", "mn": "юань"}, "b": {"zh": "博物馆", "pinyin": "bówùguǎn", "mn": "музей"}, "note_mn": "2+2+4 болон 2+4+3 хослолыг ялгаж дуудна."}, {"a": {"zh": "韩国人", "pinyin": "Hánguó rén", "mn": "солонгос хүн"}, "b": {"zh": "游泳池", "pinyin": "yóuyǒngchí", "mn": "усан сан"}, "note_mn": "Эхний үе 2-р хөгөөр өргөгдөж эхэлнэ."}]}], "tips_mn": ["呢 ба 吧-г хэлэхдээ дуу хоолойгоо бүү өндөрсгө, сулхан унагаж дуусга", "Утасны дугаар хэлэхдээ гурав гурваар нь бүлэглэж амьсгаа авбал сонсогчид ойлгомжтой"]}}'::jsonb)
