       payload = excluded.payload;

insert into public.lesson_deep_teaching (lesson_id, version, payload)
values ('hsk1-l14', 1, '{"words": [{"zh": "东西", "pinyin": "dōngxi", "teach_mn": "«东西» гэдэг нь «зүйл, юм» гэсэн ерөнхий утгатай нэр үг, ямар нэгэн биет зүйлийг тодорхойгүйгээр нэрлэхэд хэрэглэнэ. Ихэвчлэн 买 (худалдаж авах) үйл үгтэй хамт «买东西» (юм авах, дэлгүүр хэсэх) хэлбэрээр гардаг. Монгол хэлний «юм» гэдэг тодорхойгүй нэр үгтэй адилхан санагдаж болно.", "usage_mn": ["Тодорхой бус, ерөнхий зүйл, эд хэрэглэлийг нэрлэхэд хэрэглэнэ", "Тодорхой нэртэй зүйл байвал шууд тэр нэрийг нь хэлнэ, 东西-г заавал хэрэглэхгүй"], "examples": [{"zh": "我去商店买东西了。", "pinyin": "Wǒ qù shāngdiàn mǎi dōngxi le.", "mn": "Би дэлгүүрт юм авахаар явсан.", "note_mn": "хамгийн түгээмэл хэллэг — 买东西"}, {"zh": "这些都是王方的东西。", "pinyin": "Zhèxiē dōu shì Wáng Fāng de dōngxi.", "mn": "Эдгээр нь бүгд Ван Фанийн юм.", "note_mn": "的-ийн ард орж хэний юм болохыг заана"}, {"zh": "你买什么东西了？", "pinyin": "Nǐ mǎi shénme dōngxi le?", "mn": "Чи ямар юм авсан бэ?", "note_mn": "什么-той хамт асуулт болгож болно"}, {"zh": "我没买东西。", "pinyin": "Wǒ méi mǎi dōngxi.", "mn": "Би юм аваагүй.", "note_mn": "үгүйсгэхдээ 没 хэрэглэнэ, 了 унана"}], "mistakes": [{"wrong": "我东西买了。", "right": "我买东西了。", "why_mn": "юмны нэр (东西) нь үйл үгийн (买) ард ордог, монгол хэлний адил өмнө нь тавьж болохгүй."}]}, {"zh": "一点儿", "pinyin": "yìdiǎnr", "teach_mn": "«一点儿» гэдэг нь «жаахан, бага зэрэг» гэсэн тоо хэмжээ багатайг заасан үг, нэрийн өмнө орж тоо хэмжээг тодорхойгүй бага гэдгийг илэрхийлнэ. Өгүүлбэрт «үйл үг + 一点儿 + нэр үг» хэлбэрээр ордог. Ярианд 一 нь заримдаа уначихдаг: 买点儿苹果 гэж ч хэлж болно.", "usage_mn": ["Тоо хэмжээ бага байгааг тодорхойгүйгээр заахад хэрэглэнэ", "Тэмдэг нэрийн ард орвол «арай илүү» гэсэн харьцуулсан утга өгнө"], "examples": [{"zh": "我买了一点儿苹果。", "pinyin": "Wǒ mǎile yìdiǎnr píngguǒ.", "mn": "Би жаахан алим авсан."}, {"zh": "我想喝一点儿茶。", "pinyin": "Wǒ xiǎng hē yìdiǎnr chá.", "mn": "Би жаахан цай уумаар байна."}, {"zh": "请给我一点儿水。", "pinyin": "Qǐng gěi wǒ yìdiǎnr shuǐ.", "mn": "Надад жаахан ус өгөөч."}, {"zh": "今天天气冷一点儿。", "pinyin": "Jīntiān tiānqì lěng yìdiǎnr.", "mn": "Өнөөдөр цаг агаар арай хүйтэн байна.", "note_mn": "тэмдэг нэрийн ард орж «арай илүү» гэсэн утга өгнө"}], "mistakes": [{"wrong": "我买一点儿了苹果。", "right": "我买了一点儿苹果。", "why_mn": "了 нь үйл үгийн ард шууд ордог, 一点儿苹果 гэдэг нэрийн холбоо цуг явна, 了-г дундуур нь тусгаарлаж болохгүй."}]}, {"zh": "苹果", "pinyin": "píngguǒ", "teach_mn": "«苹果» бол «алим» гэсэн энгийн нэр үг, тоологдох зүйл тул тоо, тоолуур (个) хамт хэрэглэж болно. HSK1-ийн жимсний үгсийн нэг бөгөөд өдөр тутмын ярианд элбэг хэрэглэгддэг.", "usage_mn": ["Жимс худалдаж авах, идэх тухай ярихад хэрэглэнэ", "Тоо хэмжээ жижиг байвал 一点儿-ийн ард орж болно"], "examples": [{"zh": "我买了一点儿苹果。", "pinyin": "Wǒ mǎile yìdiǎnr píngguǒ.", "mn": "Би жаахан алим авсан."}, {"zh": "我喜欢吃苹果。", "pinyin": "Wǒ xǐhuan chī píngguǒ.", "mn": "Би алим идэхэд дуртай."}, {"zh": "这个苹果很好吃。", "pinyin": "Zhège píngguǒ hěn hǎochī.", "mn": "Энэ алим их амттай."}, {"zh": "商店里有苹果吗？", "pinyin": "Shāngdiàn li yǒu píngguǒ ma?", "mn": "Дэлгүүрт алим байгаа юу?"}], "mistakes": [{"wrong": "我买一苹果。", "right": "我买一个苹果。", "why_mn": "тоолж болох биет зүйлийн өмнө тоо ба тоолуур хоёул орох ёстой, тоолуурыг орхиж болохгүй."}]}, {"zh": "看见", "pinyin": "kànjiàn", "teach_mn": "«看见» бол 看 (харах) ба 见 (харагдах, олж харах) хоёр ханз нийлж «харж олсон, харсан» гэсэн үр дүнг заасан үйл үг. Зөвхөн «харах гэж оролдох» биш, бодитоор нүдэнд орж харагдсаныг илэрхийлнэ. Ихэвчлэн 了-той хамт «харчихсан» гэсэн утгаар хэрэглэгддэг.", "usage_mn": ["Хэн нэгнийг эсвэл ямар нэг зүйлийг нүдээрээ бодитоор харсан гэдгийг батлахад хэрэглэнэ", "Зөвхөн 看 гэхээс илүү «харсан үр дүн гарсан» гэдгийг тодотгоно"], "examples": [{"zh": "你看见张先生了吗？", "pinyin": "Nǐ kànjiàn Zhāng xiānsheng le ma?", "mn": "Чи Жан ноёныг харсан уу?"}, {"zh": "看见了，他去学开车了。", "pinyin": "Kànjiàn le, tā qù xué kāi chē le.", "mn": "Харсан, тэр машин барьж сурахаар явсан."}, {"zh": "我没看见你的书。", "pinyin": "Wǒ méi kànjiàn nǐ de shū.", "mn": "Би чиний номыг хараагүй."}, {"zh": "我在商店看见他了。", "pinyin": "Wǒ zài shāngdiàn kànjiàn tā le.", "mn": "Би түүнийг дэлгүүрт харсан."}], "mistakes": [{"wrong": "我看见没他。", "right": "我没看见他。", "why_mn": "үгүйсгэх 没 нь үйл үгийн ӨМНӨ ордог, ард нь тавьж болохгүй."}], "compare": [{"zh": "看", "pinyin": "kàn", "mn": "харах (үйл явц)", "diff_mn": "看 нь зөвхөн харах үйлдлийг л заана, харсан эсэх үр дүнг баталгаажуулдаггүй; 看见 бол «харж олсон» гэсэн үр дүнтэй."}]}, {"zh": "先生", "pinyin": "xiānsheng", "teach_mn": "«先生» нь эрэгтэй хүнийг хүндэтгэлтэй дуудах үг, монголоор «ноён» гэж орчуулна. Овгийнх нь ард залгаж хэрэглэдэг: 张先生 (Жан ноён). Монгол хэлэнд ч эрэгтэй хүнийг «ноён» гэж хүндэтгэн дуудахтай төстэй.", "usage_mn": ["Эрэгтэй хүний овгийн ард залгаж хүндэтгэлтэй дуудахад хэрэглэнэ", "Танихгүй буюу албан ёсны харилцаанд илүү тохиромжтой"], "examples": [{"zh": "张先生去学开车了。", "pinyin": "Zhāng xiānsheng qù xué kāi chē le.", "mn": "Жан ноён машин барьж сурахаар явсан."}, {"zh": "你看见张先生了吗？", "pinyin": "Nǐ kànjiàn Zhāng xiānsheng le ma?", "mn": "Чи Жан ноёныг харсан уу?"}, {"zh": "先生，您好！", "pinyin": "Xiānsheng, nín hǎo!", "mn": "Ноён оо, сайн байна уу!"}, {"zh": "王先生是我们的老师。", "pinyin": "Wáng xiānsheng shì wǒmen de lǎoshī.", "mn": "Ван ноён бол манай багш."}], "mistakes": [{"wrong": "先生张", "right": "张先生", "why_mn": "хятад хэлэнд овог нэр ЭХЭНД, хүндэтгэлийн үг (先生) АРД ордог."}], "compare": [{"zh": "小姐", "pinyin": "xiǎojiě", "mn": "хатагтай, бүсгүй", "diff_mn": "先生 эрэгтэйд, 小姐 эмэгтэйд хэрэглэнэ."}]}, {"zh": "开", "pinyin": "kāi", "teach_mn": "«开» нь үндсэн утгаараа «нээх» гэсэн үг боловч 车-тэй хамт «开车» гэвэл «машин барих, жолоодох» гэсэн утга болдог. Нэг ханз хэдэн өөр орчинд өөр утгатай болохыг анзаараарай. HSK1-д голчлон 开车 хэлбэрээр л таарна.", "usage_mn": ["车-ийн өмнө орж «жолоодох» гэсэн утга өгнө", "Ганцаараа ч «нээх» гэсэн ерөнхий утгатай"], "examples": [{"zh": "他去学开车了。", "pinyin": "Tā qù xué kāi chē le.", "mn": "Тэр машин барьж сурахаар явсан."}, {"zh": "他会开车。", "pinyin": "Tā huì kāi chē.", "mn": "Тэр машин барьж чадна."}, {"zh": "你会开车吗？", "pinyin": "Nǐ huì kāi chē ma?", "mn": "Чи машин барьж чадах уу?"}, {"zh": "我不会开车。", "pinyin": "Wǒ bú huì kāi chē.", "mn": "Би машин барьж чаддаггүй."}], "mistakes": [{"wrong": "他开会车。", "right": "他会开车。", "why_mn": "чадвар заасан 会 нь үйл үгийн (开) ӨМНӨ ордог, дунд нь тусгаарлаж болохгүй."}]}, {"zh": "车", "pinyin": "chē", "teach_mn": "«车» бол дугуйтай тээврийн хэрэгслийг ерөнхийд нь нэрлэдэг үг — машин, тэрэг гэх мэтийг хамарч болно. Ганцаараа мөн бусад үгтэй нийлж (出租车 такси, 火车 галт тэрэг) шинэ үг үүсгэдэг язгуур ч мөн.", "usage_mn": ["Ерөнхий тээврийн хэрэгслийг нэрлэхэд хэрэглэнэ", "Өөр үгтэй нийлж (出租车, 火车 гэх мэт) шинэ тодорхой утгатай үг үүсгэнэ"], "examples": [{"zh": "他会开车。", "pinyin": "Tā huì kāi chē.", "mn": "Тэр машин барьж чадна."}, {"zh": "这是我的车。", "pinyin": "Zhè shì wǒ de chē.", "mn": "Энэ бол миний машин."}, {"zh": "你的车在哪儿？", "pinyin": "Nǐ de chē zài nǎr?", "mn": "Чиний машин хаана байна?"}, {"zh": "我们坐车去吧。", "pinyin": "Wǒmen zuò chē qù ba.", "mn": "Бид машинтай явцгаая."}], "mistakes": [{"wrong": "我车有。", "right": "我有车。", "why_mn": "нэр үг (车) нь 有 үйл үгийн ард ордог, монгол хэлний адил өмнө нь тавьж болохгүй."}]}, {"zh": "回来", "pinyin": "huílai", "teach_mn": "«回来» нь 回 (буцах) ба 来 (ирэх) хоёр нийлж «буцаж ирэх» гэсэн чиглэл заасан үйл үг. Ярьж буй хүн рүү чиглэсэн хөдөлгөөнийг заана — «энд, надтай ойр газарт эргэж ирэх» гэсэн санаа.", "usage_mn": ["Хэн нэгэн явсан газраасаа ярьж буй хүн рүү эргэж ирэхийг заана", "Цаг хугацааны хамт хэрэглэж хэзээ ирэхийг заана"], "examples": [{"zh": "他什么时候能回来？", "pinyin": "Tā shénme shíhou néng huílai?", "mn": "Тэр хэзээ буцаж ирж чадах вэ?"}, {"zh": "四十分钟后回来。", "pinyin": "Sìshí fēnzhōng hòu huílai.", "mn": "40 минутын дараа буцаж ирнэ."}, {"zh": "我明天回来。", "pinyin": "Wǒ míngtiān huílai.", "mn": "Би маргааш буцаж ирнэ."}, {"zh": "他今天不回来。", "pinyin": "Tā jīntiān bù huílai.", "mn": "Тэр өнөөдөр буцаж ирэхгүй."}], "mistakes": [{"wrong": "他回来能什么时候？", "right": "他什么时候能回来？", "why_mn": "асуух үг 什么时候 нь өгүүлбэрийн эхэнд ойр, чадлын 能-ийн өмнө ордог."}]}, {"zh": "分钟", "pinyin": "fēnzhōng", "teach_mn": "«分钟» нь хугацааны үргэлжлэх хэмжээг тоолоход хэрэглэдэг «минут» гэсэн үг. Анхаарах зүйл: цагийн заалт хэлэхдээ (жишээ нь «3 цаг 10 минут») 分 гэж хэлдэг, харин үргэлжлэх хугацаа хэлэхдээ 分钟 гэж хэлнэ.", "usage_mn": ["Үйл ажиллагааны үргэлжлэх хугацааг тоолоход хэрэглэнэ", "Тоо + 分钟 хэлбэрээр ордог: 40分钟"], "examples": [{"zh": "四十分钟后回来。", "pinyin": "Sìshí fēnzhōng hòu huílai.", "mn": "40 минутын дараа буцаж ирнэ."}, {"zh": "我等了十分钟。", "pinyin": "Wǒ děngle shí fēnzhōng.", "mn": "Би 10 минут хүлээсэн."}, {"zh": "五分钟后见。", "pinyin": "Wǔ fēnzhōng hòu jiàn.", "mn": "5 минутын дараа уулзая."}], "mistakes": [{"wrong": "现在三点十分钟。", "right": "现在三点十分。", "why_mn": "цагийн ЗААЛТ хэлэхдээ 分 гэж хэлнэ, харин ХУГАЦААНЫ УРТЫГ хэлэхдээ 分钟 гэж хэлнэ."}]}, {"zh": "后", "pinyin": "hòu", "teach_mn": "«后» нь цаг хугацааны нэрийн ард орж «...-ын дараа» гэсэн утга өгдөг үг. Энэ нь L11-д үзсэн 前 (өмнө)-ийн шууд эсрэг тал. Орон зайд ч мөн «хойно, ард» гэсэн утгаар хэрэглэгддэг (жишээ нь 后面).", "usage_mn": ["Цаг хугацааны хэмжигдэхүүний ард орж «...-ын дараа» гэсэн утга өгнө", "前-ийн эсрэг утгатай — үргэлж хос болгож харьцуулж сурах нь тустай"], "examples": [{"zh": "四十分钟后回来。", "pinyin": "Sìshí fēnzhōng hòu huílai.", "mn": "40 минутын дараа буцаж ирнэ."}, {"zh": "八点后我去工作。", "pinyin": "Bā diǎn hòu wǒ qù gōngzuò.", "mn": "8 цагийн дараа би ажилдаа явна."}, {"zh": "三天后我们再见面。", "pinyin": "Sān tiān hòu wǒmen zài jiànmiàn.", "mn": "3 хоногийн дараа бид дахин уулзана."}], "mistakes": [{"wrong": "后八点我去工作。", "right": "八点后我去工作。", "why_mn": "后 нь цаг хугацааны үгийн ӨМНӨ биш АРД ордог тогтсон дараалалтай."}], "compare": [{"zh": "前", "pinyin": "qián", "mn": "өмнө", "diff_mn": "前 цаг хугацааны өмнөх мөчийг, 后 дараагийн мөчийг заана — 八点前 (8 цагаас өмнө) ба 八点后 (8 цагийн дараа)."}]}, {"zh": "衣服", "pinyin": "yīfu", "teach_mn": "«衣服» бол «хувцас» гэсэн ерөнхий нэр үг, ямар ч төрлийн хувцсыг нэгэн зэрэг хамарч болно. Тоолуурыг нь 件 гэж хэлдэг ч HSK1-д ихэвчлэн тоохгүйгээр л 买衣服, 衣服漂亮 гэх мэт хэлбэрээр гардаг.", "usage_mn": ["Хувцас худалдаж авах, өмсөх тухай ерөнхийд нь ярихад хэрэглэнэ", "Тодорхой төрлийг нь ялгах шаардлагагүй үед л энэ ерөнхий үгийг хэрэглэнэ"], "examples": [{"zh": "她买了不少衣服。", "pinyin": "Tā mǎile bùshǎo yīfu.", "mn": "Тэр их олон хувцас авчээ."}, {"zh": "王方的衣服太漂亮了！", "pinyin": "Wáng Fāng de yīfu tài piàoliang le!", "mn": "Ван Фанийн хувцас үнэхээр хөөрхөн юм!"}, {"zh": "我想买衣服。", "pinyin": "Wǒ xiǎng mǎi yīfu.", "mn": "Би хувцас авмаар байна."}, {"zh": "这些衣服都是我的。", "pinyin": "Zhèxiē yīfu dōu shì wǒ de.", "mn": "Эдгээр хувцас бүгд минийх."}], "mistakes": [{"wrong": "我买衣服一个。", "right": "我买了一件衣服。", "why_mn": "衣服-ийн тоолуур нь 个 биш 件 гэдгийг сана, гэхдээ HSK1-д тоохгүйгээр ерөнхийд нь хэлж болно."}]}, {"zh": "漂亮", "pinyin": "piàoliang", "teach_mn": "«漂亮» нь хүн, эд зүйл, байгаль гэх мэт харагдах байдал сайхныг магтахад хэрэглэдэг тэмдэг нэр. Ихэвчлэн 很 эсвэл 太……了-той хамт орж «маш хөөрхөн» гэсэн эрчимжсэн утга өгдөг.", "usage_mn": ["Хувцас, гадаад төрх, байгалийн үзэмж зэргийг магтахад хэрэглэнэ", "太……了 хэлбэрт орж «үнэхээр хөөрхөн» гэсэн эрчимтэй сэтгэгдэл заана"], "examples": [{"zh": "王方的衣服太漂亮了！", "pinyin": "Wáng Fāng de yīfu tài piàoliang le!", "mn": "Ван Фанийн хувцас үнэхээр хөөрхөн юм!"}, {"zh": "这个杯子很漂亮。", "pinyin": "Zhège bēizi hěn piàoliang.", "mn": "Энэ аяга их хөөрхөн."}, {"zh": "那个学校很漂亮。", "pinyin": "Nàge xuéxiào hěn piàoliang.", "mn": "Тэр сургууль их хөөрхөн."}, {"zh": "你的衣服真漂亮。", "pinyin": "Nǐ de yīfu zhēn piàoliang.", "mn": "Чиний хувцас үнэхээр хөөрхөн байна."}], "mistakes": [{"wrong": "衣服很漂亮了。", "right": "衣服很漂亮。", "why_mn": "тэмдэг нэрийн энгийн мэдэгдэлд 了 хэрэггүй, зөвхөн өөрчлөлт заах үед 了 нэмнэ."}]}, {"zh": "少（不少）", "pinyin": "shǎo (bùshǎo)", "teach_mn": "«少» өөрөө «цөөн» гэсэн утгатай ч 不少 (үгүйсгэл+少) гэвэл «цөөнгүй, нэлээд олон» гэсэн эсрэг санаа болж хувирдгийг сайн ажиглаарай — энэ бол монгол хэлэнд ч бий «цөөнгүй» гэдэгтэй яг адил логик.", "usage_mn": ["少 дангаараа тоо хэмжээ бага гэдгийг заана", "不少 хэлбэрээр «цөөнгүй, олон» гэсэн эсрэг санаа болдгийг сана"], "examples": [{"zh": "她买了不少衣服。", "pinyin": "Tā mǎile bùshǎo yīfu.", "mn": "Тэр цөөнгүй хувцас авсан."}, {"zh": "这儿的人不少。", "pinyin": "Zhèr de rén bùshǎo.", "mn": "Энд хүн цөөнгүй байна."}, {"zh": "我的钱不多，也不少。", "pinyin": "Wǒ de qián bù duō, yě bù shǎo.", "mn": "Миний мөнгө их ч биш, цөөн ч биш."}], "mistakes": [{"wrong": "她买了不少的衣服。", "right": "她买了不少衣服。", "why_mn": "不少 нь тэмдэг нэр шиг шууд нэрийн өмнө ордог, 的 нэмэх шаардлагагүй."}], "compare": [{"zh": "多", "pinyin": "duō", "mn": "олон", "diff_mn": "多 шууд «олон» гэсэн энгийн үг, 不少 бол «цөөн биш, тэгэхээр олон» гэсэн эргэлт бүхий илэрхийлэл."}]}, {"zh": "这些", "pinyin": "zhèxiē", "teach_mn": "«这些» нь 这 (энэ) дээр олон тооны 些 залгаж «эдгээр» гэсэн үг болгосон заах төлөөний үг. Нэгээс олон зүйлийг зэрэг зааж хэлэхэд хэрэглэнэ.", "usage_mn": ["Нэгээс олон зүйлийг хамтад нь зааж хэлэхэд хэрэглэнэ", "Ганц зүйл заахад ердийн 这-г хэрэглэнэ, 这些-г хэрэглэхгүй"], "examples": [{"zh": "这些都是王方的东西。", "pinyin": "Zhèxiē dōu shì Wáng Fāng de dōngxi.", "mn": "Эдгээр нь бүгд Ван Фанийн юм."}, {"zh": "这些苹果很好吃。", "pinyin": "Zhèxiē píngguǒ hěn hǎochī.", "mn": "Эдгээр алим их амттай."}, {"zh": "这些书是我的。", "pinyin": "Zhèxiē shū shì wǒ de.", "mn": "Эдгээр ном минийх."}], "mistakes": [{"wrong": "这个些衣服", "right": "这些衣服", "why_mn": "这些 нь өөрөө «энэ+олон тоо» гэсэн бэлэн үг тул дахин 个 нэмж хэрэглэхгүй."}], "compare": [{"zh": "那些", "pinyin": "nàxiē", "mn": "тэдгээр", "diff_mn": "这些 ойрхон зүйлд, 那些 холын зүйлд хэрэглэнэ."}]}, {"zh": "都", "pinyin": "dōu", "teach_mn": "«都» нь «бүгд» гэсэн дайвар үг, хамрагдах зүйл нь 都-ийн ӨМНӨ ирдэг гэдгийг сайн санах хэрэгтэй. Өгүүлэгдэхүүн бүхэлдээ хамрагдана гэдгийг онцолно.", "usage_mn": ["Хамрагдах олон тооны нэр/төлөөний үгийн АРД, гол үйл үгийн ӨМНӨ орж «бүгд» гэсэн утга нэмнэ", "Ганц зүйлийн өмнө хэрэглэдэггүй, зөвхөн олон зүйл/хүнийг хамруулахад л хэрэглэнэ"], "examples": [{"zh": "我们都是中国人。", "pinyin": "Wǒmen dōu shì Zhōngguó rén.", "mn": "Бид бүгд хятад хүн."}, {"zh": "这些都是王方的东西。", "pinyin": "Zhèxiē dōu shì Wáng Fāng de dōngxi.", "mn": "Эдгээр нь бүгд Ван Фанийн юм."}, {"zh": "他们都喜欢喝茶。", "pinyin": "Tāmen dōu xǐhuan hē chá.", "mn": "Тэд бүгд цайнд дуртай."}, {"zh": "我们都想去。", "pinyin": "Wǒmen dōu xiǎng qù.", "mn": "Бид бүгд явмаар байна."}], "mistakes": [{"wrong": "都我们是中国人。", "right": "我们都是中国人。", "why_mn": "都-гийн хамрагдах зүйл (我们) үргэлж 都-ийн ӨМНӨ ирнэ, 都-г өгүүлбэрийн эхэнд тавьж болохгүй."}]}], "grammar": [{"point": "了 表发生或完成", "gloss_mn": "了: үйл болсон/дууссаныг заана", "structure": "Үйл үг(+тусагдахуун) + 了 / Өгүүлбэрийн төгсгөлд 了", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "了 бол цаг заасан үг биш, харин үйл АЛЬ ХЭДИЙН болсон, эсвэл ШИНЭ нөхцөл байдал үүссэнийг илэрхийлдэг туслах үг. Зөвхөн «болсон/дууссан» гэдгийг тэмдэглэнэ.", "example": {"zh": "我去商店了。", "pinyin": "Wǒ qù shāngdiàn le.", "mn": "Би дэлгүүрт явсан."}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Хоёр байрлалд орж болно — (а) өгүүлбэрийн ЭЦЭСТ: 我去商店了; (б) үйл үгийн АРД, ялангуяа тусагдахуун нь тодотголтой үед: 她买了一点儿苹果.", "example": {"zh": "她买了一点儿苹果。", "pinyin": "Tā mǎile yìdiǎnr píngguǒ.", "mn": "Тэр жаахан алим авсан."}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Аль хэдийн болсон үйлийг мэдээлэхдээ, эсвэл асуухдаа хэрэглэнэ. Ярианы гол цэг бол «энэ явдал одоо болсон байна» гэдгийг сонсогчид ойлгуулах явдал.", "example": {"zh": "你看见张先生了吗？", "pinyin": "Nǐ kànjiàn Zhāng xiānsheng le ma?", "mn": "Чи Жан ноёныг харсан уу?"}}, {"title_mn": "4. Хэрэв хэрэгтэй бол өргөтгөл/үгүйсгэл", "body_mn": "Үгүйсгэхдээ 没-г үйл үгийн өмнө тавьж, 了-г БҮРЭН УНАГААНА: 我没买 зөв, 我没买了 буруу.", "example": {"zh": "我没买。", "pinyin": "Wǒ méi mǎi.", "mn": "Би аваагүй."}}], "examples": [{"zh": "他去学开车了。", "pinyin": "Tā qù xué kāi chē le.", "mn": "Тэр машин барьж сурахаар явсан."}, {"zh": "我没买。", "pinyin": "Wǒ méi mǎi.", "mn": "Би аваагүй (了 хэрэглэхгүй)."}, {"zh": "我去商店买东西了。", "pinyin": "Wǒ qù shāngdiàn mǎi dōngxi le.", "mn": "Би дэлгүүрт юм авахаар явсан."}, {"zh": "你买什么了？", "pinyin": "Nǐ mǎi shénme le?", "mn": "Чи юу авсан бэ?"}, {"zh": "她买了不少衣服。", "pinyin": "Tā mǎile bùshǎo yīfu.", "mn": "Тэр их олон хувцас авчээ."}, {"zh": "看见了，他去学开车了。", "pinyin": "Kànjiàn le, tā qù xué kāi chē le.", "mn": "Харсан, тэр машин барьж сурахаар явсан."}, {"zh": "我没看见你。", "pinyin": "Wǒ méi kànjiàn nǐ.", "mn": "Би чамайг хараагүй."}], "mistakes": [{"wrong": "我没买了。", "right": "我没买。", "why_mn": "没-гээр үгүйсгэсэн өгүүлбэрт 了 орохгүй."}, {"wrong": "她昨天去商店了买东西。", "right": "她昨天去商店买东西了。", "why_mn": "了 нь бүхэл үйл ЯВДЛЫН эцэст ордог, дундуур нь тавьж болохгүй."}], "drills": [{"type": "choice", "question": "她买___一点儿苹果。（аль хэдийн болсон）", "options": ["了", "的", "吗"], "answer": "了", "why_mn": "аль хэдийн болсон үйлийг заахын тулд 了-г үйл үгийн ард залгана."}, {"type": "fill", "question": "«Тэр машин барьж сурахаар явсан» гэдгийг бич.", "answer": "他去学开车了。", "why_mn": "болсон үйл явдлыг өгүүлбэрийн эцэст 了-гээр тэмдэглэнэ."}, {"type": "judge", "question": "我没买了 гэдэг өгүүлбэр зөв.", "answer": "false", "why_mn": "没-гээр үгүйсгэхэд 了 орохгүй тул энэ өгүүлбэр буруу."}, {"type": "choice", "question": "«Чи юу авсан бэ?» гэдгийг зөв илэрхийлбэл:", "options": ["你买什么了？", "你了买什么？", "你买了什么吗？"], "answer": "你买什么了？", "why_mn": "болсон үйлийг асуухдаа 了-г өгүүлбэрийн эцэст тавина."}]}, {"point": "名词 后", "gloss_mn": "后: «...-ын дараа»", "structure": "Цаг хугацааны нэр/тоо + 后", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "后 нь цаг хугацааны хэмжигдэхүүний ард орж тухайн мөчөөс хойшхи цагийг заана — монголоор «...-ын дараа» гэж орчуулна.", "example": {"zh": "八点后", "pinyin": "bā diǎn hòu", "mn": "8 цагийн дараа"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Цаг заасан үг/хэллэгийн ШУУД АРД 后-г залгана, өөр үг завсарлуулахгүй: 五点后, 40分钟后.", "example": {"zh": "四十分钟后", "pinyin": "sìshí fēnzhōng hòu", "mn": "40 минутын дараа"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Ямар нэг үйл ХЭЗЭЭ болохыг ирээдүйн чиглэлд заахад хэрэглэнэ — хэдэн минутын дараа ирэх, хэдэн цагийн дараа явах гэх мэт.", "example": {"zh": "他什么时候能回来？— 四十分钟后回来。", "pinyin": "Tā shénme shíhou néng huílai? — Sìshí fēnzhōng hòu huílai.", "mn": "Хэзээ буцаж ирэх вэ? — 40 минутын дараа."}}, {"title_mn": "4. Ялгаа", "body_mn": "L11-д үзсэн 前 (өмнө)-тэй яг эсрэг утгатай хос гэдгийг сана: 八点前 (8 цагаас өмнө) — 八点后 (8 цагийн дараа).", "example": {"zh": "八点前 / 八点后", "pinyin": "bā diǎn qián / bā diǎn hòu", "mn": "8 цагаас өмнө / 8 цагийн дараа"}}], "examples": [{"zh": "他什么时候能回来？— 四十分钟后回来。", "pinyin": "Tā shénme shíhou néng huílai? — Sìshí fēnzhōng hòu huílai.", "mn": "Хэзээ буцаж ирэх вэ? — 40 минутын дараа."}, {"zh": "你几点去工作？— 八点后。", "pinyin": "Nǐ jǐ diǎn qù gōngzuò? — Bā diǎn hòu.", "mn": "Хэдэн цагт ажилдаа явах вэ? — 8 цагийн дараа."}, {"zh": "三天后我们再见面。", "pinyin": "Sān tiān hòu wǒmen zài jiànmiàn.", "mn": "3 хоногийн дараа бид дахин уулзана."}, {"zh": "五分钟后见。", "pinyin": "Wǔ fēnzhōng hòu jiàn.", "mn": "5 минутын дараа уулзая."}, {"zh": "星期三后我有时间。", "pinyin": "Xīngqīsān hòu wǒ yǒu shíjiān.", "mn": "Лхагва гарагийн дараа надад цаг гарна."}, {"zh": "下课后我们去吃饭。", "pinyin": "Xiàkè hòu wǒmen qù chīfàn.", "mn": "Хичээл дууссаны дараа бид хоол идэхээр явна."}], "mistakes": [{"wrong": "后八点我去工作。", "right": "八点后我去工作。", "why_mn": "后 цаг хугацааны үгийн АРД ордог, өмнө нь тавьж болохгүй."}, {"wrong": "四十分钟后了回来。", "right": "四十分钟后回来。", "why_mn": "энд болох гэж буй ирээдүйн үйл тул 了 хэрэггүй."}], "drills": [{"type": "choice", "question": "他八点___去工作。", "options": ["前", "后", "都"], "answer": "后", "why_mn": "цаг хугацааны ард орж «дараа» гэсэн утга өгнө."}, {"type": "judge", "question": "八点前 гэдэг нь «8 цагийн дараа» гэсэн утгатай.", "answer": "false", "why_mn": "前 бол «өмнө» гэсэн утгатай, 后 нь «дараа»."}, {"type": "fill", "question": "«5 минутын дараа» гэдгийг хятадаар бич.", "answer": "五分钟后", "why_mn": "тоо+分钟+后 хэлбэрээр угсарна."}, {"type": "choice", "question": "他什么时候能回来？хариултыг сонго.", "options": ["四十分钟后回来。", "后四十分钟回来。", "回来四十分钟后。"], "answer": "四十分钟后回来。", "why_mn": "цаг хугацаа+后 нь өгүүлбэрийн эхэнд ордог."}]}, {"point": "语气助词 啊", "gloss_mn": "啊: батлах, сэтгэл хөдлөлийн өнгө", "structure": "Өгүүлбэр + 啊 (өгүүлбэрийн төгсгөлд)", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "啊 бол утга агуулаагүй, харин ярианд илэрхийлэл, сэтгэл хөдлөл нэмдэг өнгө үг. Хариулт баталгаажуулах, зөвшөөрөх зэрэгт хэрэглэнэ.", "example": {"zh": "是啊。", "pinyin": "Shì a.", "mn": "Тийм ээ."}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Өгүүлбэрийн ХАМГИЙН ТӨГСГӨЛД ордог, өөр тусгай дараалал шаардахгүй.", "example": {"zh": "好啊。", "pinyin": "Hǎo a.", "mn": "За тэгье!"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Хэн нэгний асуултад зөвшөөрч, баталгаажуулж хариулахдаа, эсвэл өөрийн мэдрэмжийг илэрхий болгохдоо хэрэглэнэ.", "example": {"zh": "你想去吃中国菜吗？— 好啊。", "pinyin": "Nǐ xiǎng qù chī Zhōngguó cài ma? — Hǎo a.", "mn": "Хятад хоол идэх үү? — За тэгье!"}}, {"title_mn": "4. Өргөтгөл", "body_mn": "啊-ийн дуудлага өмнөх үгийн сүүлийн авианаас хамаарч бага зэрэг өөрчлөгддөг ч HSK1-д зүгээр «а» гэж дуудаад болно.", "example": {"zh": "是啊", "pinyin": "shì a", "mn": "тийм ээ"}}], "examples": [{"zh": "你是王小姐吗？— 是啊。", "pinyin": "Nǐ shì Wáng xiǎojiě ma? — Shì a.", "mn": "Та Ван хатагтай мөн үү? — Тийм ээ."}, {"zh": "你想去吃中国菜吗？— 好啊。", "pinyin": "Nǐ xiǎng qù chī Zhōngguó cài ma? — Hǎo a.", "mn": "Хятад хоол идэх үү? — За тэгье!"}, {"zh": "你去商店吗？— 去啊。", "pinyin": "Nǐ qù shāngdiàn ma? — Qù a.", "mn": "Дэлгүүрт явах уу? — Явна аа."}, {"zh": "他会开车吗？— 会啊。", "pinyin": "Tā huì kāi chē ma? — Huì a.", "mn": "Тэр машин барьж чадах уу? — Чаддаг шүү дээ."}, {"zh": "你喜欢吃苹果吗？— 喜欢啊。", "pinyin": "Nǐ xǐhuan chī píngguǒ ma? — Xǐhuan a.", "mn": "Алимд дуртай юу? — Дуртай шүү дээ."}], "mistakes": [{"wrong": "啊是。", "right": "是啊。", "why_mn": "啊 үргэлж өгүүлбэрийн ЭЦЭСТ ордог, эхэнд тавьдаггүй."}, {"wrong": "是啊吗？", "right": "是啊。", "why_mn": "啊 бол мэдэгдэл, баталгаажуулах өнгө үг тул асуултын 吗-тай хамт хэрэглэдэггүй."}], "drills": [{"type": "judge", "question": "啊 нь өгүүлбэрийн эхэнд ордог.", "answer": "false", "why_mn": "啊 үргэлж өгүүлбэрийн ЭЦЭСТ ордог."}, {"type": "choice", "question": "「你想去吗？」гэсэн асуултад «За тэгье!» гэж хариулбал:", "options": ["好啊。", "啊好。", "好吗啊。"], "answer": "好啊。", "why_mn": "啊 өгүүлбэрийн эцэст орж баталгаажуулна."}, {"type": "fill", "question": "«Тийм ээ» гэдгийг 啊-той хамт бич.", "answer": "是啊。", "why_mn": "啊 нь баталгаажуулах өнгө нэмнэ."}, {"type": "judge", "question": "啊-г хэрэглэхэд өгүүлбэрийн утга огт өөрчлөгддөг.", "answer": "false", "why_mn": "啊 нь утгыг өөрчлөхгүй, зөвхөн өнгө аяс, сэтгэл хөдлөл нэмдэг."}]}, {"point": "副词 都", "gloss_mn": "都: «бүгд» — хамрах зүйл нь өмнө нь", "structure": "Хамрагдах нэр/төлөөний үг + 都 + үйл үг/тэмдэг нэр", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "都 нь «бүгд, бүрэн» гэсэн утгатай дайвар үг, ярьж буй бүх зүйл/хүнийг өгүүлбэрт нэгэн зэрэг хамруулна.", "example": {"zh": "我们都是中国人。", "pinyin": "Wǒmen dōu shì Zhōngguó rén.", "mn": "Бид бүгд хятад хүн."}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Хамрагдах зүйл (олон тоо) ЭХЭНД, дараа нь 都, дараа нь үйл үг/тэмдэг нэр ордог.", "example": {"zh": "这些都是王方的东西。", "pinyin": "Zhèxiē dōu shì Wáng Fāng de dōngxi.", "mn": "Эдгээр нь бүгд Ван Фанийн юм."}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Нэгээс олон хүн/зүйл ижил нэг зүйлийг хийж байгаа, эсвэл ижил шинжтэй гэдгийг онцлохдоо хэрэглэнэ.", "example": {"zh": "他们都喜欢喝茶。", "pinyin": "Tāmen dōu xǐhuan hē chá.", "mn": "Тэд бүгд цайнд дуртай."}}, {"title_mn": "4. Ялгаа", "body_mn": "Монгол хэлэнд «бүгд» гэдэг үгийг өгүүлбэрийн хаана ч тавьж болдог бол хятад хэлэнд 都 үргэлж хамрагдах үгийн АРД, гол үйл үгийн ӨМНӨ гэсэн тогтсон байранд л ордог.", "example": {"zh": "都我们 (буруу) → 我们都 (зөв)", "pinyin": "wǒmen dōu", "mn": "бид бүгд"}}], "examples": [{"zh": "我们都是中国人。", "pinyin": "Wǒmen dōu shì Zhōngguó rén.", "mn": "Бид бүгд хятад хүн."}, {"zh": "这些都是王方的东西。", "pinyin": "Zhèxiē dōu shì Wáng Fāng de dōngxi.", "mn": "Эдгээр нь бүгд Ван Фанийн юм."}, {"zh": "他们都喜欢喝茶。", "pinyin": "Tāmen dōu xǐhuan hē chá.", "mn": "Тэд бүгд цайнд дуртай."}, {"zh": "我们都想去。", "pinyin": "Wǒmen dōu xiǎng qù.", "mn": "Бид бүгд явмаар байна."}, {"zh": "这些苹果都很好吃。", "pinyin": "Zhèxiē píngguǒ dōu hěn hǎochī.", "mn": "Эдгээр алим бүгд амттай."}, {"zh": "你们都是学生吗？", "pinyin": "Nǐmen dōu shì xuésheng ma?", "mn": "Та нар бүгд оюутан уу?"}], "mistakes": [{"wrong": "都我们是中国人。", "right": "我们都是中国人。", "why_mn": "都-гийн хамрагдах зүйл 都-ийн ӨМНӨ ирнэ."}, {"wrong": "我们是都中国人。", "right": "我们都是中国人。", "why_mn": "都 нь 是-ийн ӨМНӨ ордог, ард нь тавьж болохгүй."}], "drills": [{"type": "choice", "question": "___是中国人。（зөв дараалал）", "options": ["都我们", "我们都", "是都我们"], "answer": "我们都", "why_mn": "хамрагдах үг эхэнд, 都 дараа нь ордог."}, {"type": "judge", "question": "都 нь ганц хүний тухай ярихад ч хэрэглэгддэг.", "answer": "false", "why_mn": "都 зөвхөн олон тооны зүйл/хүнийг хамруулахад л хэрэглэгддэг."}, {"type": "fill", "question": "«Тэд бүгд цайнд дуртай» гэдгийг бич.", "answer": "他们都喜欢喝茶。", "why_mn": "хамрагдах зүйл эхэнд, 都 дараа нь орно."}, {"type": "choice", "question": "这些___是王方的东西。", "options": ["都", "后", "啊"], "answer": "都", "why_mn": "都 нь эдгээр зүйл бүгдийг хамруулна."}]}, {"point": "汉字 — 开 车 回, 月/扌 язгуур", "gloss_mn": "Ханзны бүтэц ба язгуур", "structure": "开(4 зурлага) / 车(4 зурлага) / 回(6 зурлага); 月-язгуур, 扌-язгуур", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "Энэ хичээлд гурван шинэ ханз (开, 车, 回)-той танилцахаас гадна хоёр түгээмэл язгуур (月, 扌)-ыг таньж сурна. Язгуур гэдэг нь ханзны утгыг тодорхой хэмжээгээр илтгэдэг бүрэлдэхүүн хэсэг.", "example": {"zh": "月 / 扌", "pinyin": "yuè / shǒu", "mn": "月=бие, 扌=гар"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "开 нь дөрвөн зурлагаас, 车 дөрвөн зурлагаас, 回 зургаан зурлагаас тогтоно. 月-язгуур орсон ханз ихэвчлэн биетэй холбоотой (服, 胖), 扌-язгуур орсон ханз гарын үйлдэлтэй холбоотой (打, 找).", "example": {"zh": "服 胖", "pinyin": "fú pàng", "mn": "月 бие махбодтой холбоотой"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Шинэ ханз таарах бүрд эхлээд язгуурыг нь ялгаж, түүгээрээ ерөнхий утгыг нь таамаглах дадал зуршил үүсгэ — цээжлэхэд хялбар болгоно.", "example": {"zh": "打 找", "pinyin": "dǎ zhǎo", "mn": "扌 гарын үйлдэлтэй холбоотой"}}, {"title_mn": "4. Өргөтгөл", "body_mn": "Нэг ханз хэд хэдэн язгуургүй ч бие даасан «дан бүтэцт» байж болно — 车, 开 нь тийм жишээ. Харин 回 нь давхар хайрцаг мэт дүрстэй, доторх жижиг 口-той.", "example": {"zh": "回 = 囗 дотор 口", "pinyin": "huí", "mn": "гадна хайрцаг дотор жижиг хайрцаг"}}], "examples": [{"zh": "服 胖", "pinyin": "fú pàng", "mn": "月 бие махбодтой холбоотой"}, {"zh": "打 找", "pinyin": "dǎ zhǎo", "mn": "扌 гарын үйлдэлтэй холбоотой"}, {"zh": "开", "pinyin": "kāi", "mn": "нээх"}, {"zh": "车", "pinyin": "chē", "mn": "машин"}, {"zh": "回", "pinyin": "huí", "mn": "буцах"}, {"zh": "开车", "pinyin": "kāichē", "mn": "машин барих"}, {"zh": "回来", "pinyin": "huílai", "mn": "буцаж ирэх"}], "mistakes": [{"wrong": "开 нь 心-язгууртай.", "right": "开 нь тусгай язгуургүй, дан бүтэцтэй ханз.", "why_mn": "开 доторх хэсгүүд нь бие даасан утгат язгуур биш, зөвхөн зурлагын нийлбэр."}, {"wrong": "扌-язгуур нь ус, усны холбоотой.", "right": "扌-язгуур нь ГАРЫН үйлдэлтэй холбоотой.", "why_mn": "扌 (гарын хажуугийн хэлбэр) нь 手-с гаралтай, ус биш гарын хөдөлгөөнийг заана."}], "drills": [{"type": "choice", "question": "打, 找 ямар язгуурт хамаарах вэ?", "options": ["月", "扌", "氵"], "answer": "扌", "why_mn": "打, 找 хоёул гарын үйлдэлтэй холбоотой тул 扌-язгуур орсон."}, {"type": "choice", "question": "服, 胖 ямар язгуурт хамаарах вэ?", "options": ["月", "扌", "口"], "answer": "月", "why_mn": "服, 胖 хоёул биетэй холбоотой тул 月-язгуур орсон."}, {"type": "judge", "question": "回 нь 6 зурлагатай.", "answer": "true", "why_mn": "回 нь гадна, дотор хайрцаг хэлбэртэй нийт зургаан зурлагаас тогтоно."}, {"type": "fill", "question": "开 нь хэдэн зурлагатай вэ?", "answer": "4", "why_mn": "开 дөрвөн зурлагаас тогтоно."}]}], "hanzi": [{"hanzi": "开", "pinyin": "kāi", "meaning_mn": "нээх; барих (машин)", "story_mn": "开 нь уламжлалт бичигт 門 (хаалга) дотор хоёр гар (廾) нээгдэж буй түгжээг барьсан дүрстэй байсан бөгөөд «хаалга нээх» гэсэн анхны утгаас өргөжиж «нээх» гэдэг ерөнхий утга болсон. Хялбаршуулсан 开 нь энэ дүрсийг маш энгийн болгосон хэлбэр.", "stroke_count": 4, "stroke_tips_mn": ["Дээд хоёр хэвтээ зурлагыг зүүнээс баруун тийш дараалуулан тат", "Дараа нь зүүн налуу, эцэст нь баруун талын босоог тат"], "confusable": [{"zh": "关", "pinyin": "guān", "mn": "хаах", "diff_mn": "开 (нээх) ба 关 (хаах) утгаараа эсрэг ч дүрсээрээ ялгаатай — андуурахгүй байхын тулд хос болгож санаж ав."}], "words": [{"zh": "开车", "pinyin": "kāichē", "mn": "машин барих"}, {"zh": "开门", "pinyin": "kāimén", "mn": "хаалга нээх"}, {"zh": "开学", "pinyin": "kāixué", "mn": "хичээл эхлэх"}]}, {"hanzi": "车", "pinyin": "chē", "meaning_mn": "машин, тэрэг", "story_mn": "车 нь эртний бичигт дугуйтай тэрэгийг дээрээс харсан дүрслэлээс гаралтай — дунд нь тэнхлэг, хоёр талдаа дугуй бүхий тэрэгний схем. Хожим хялбаршиж өнөөгийн энгийн дүрс болсон.", "stroke_count": 4, "stroke_tips_mn": ["Дээд хэвтээ зурлагаас эхэлж, дундах хэсгийг дараалуулан тат", "Хамгийн сүүлд дундуур нь босоо зурлагыг татаж төгсгө"], "confusable": [{"zh": "东", "pinyin": "dōng", "mn": "зүүн", "diff_mn": "хоёул дунд хэсэгтэй дүрс боловч 东-д дээд, доод хэсэгт нэмэлт зурлага бий, 车-д байхгүй."}], "words": [{"zh": "开车", "pinyin": "kāichē", "mn": "машин барих"}, {"zh": "出租车", "pinyin": "chūzūchē", "mn": "такси"}, {"zh": "火车", "pinyin": "huǒchē", "mn": "галт тэрэг"}]}, {"hanzi": "回", "pinyin": "huí", "meaning_mn": "буцах", "story_mn": "回 нь гадна, дотор хоёр давхар хайрцаг (囗 дотор жижиг 口) хэлбэртэй бөгөөд эргэлдэн буцаж буй ус, эсвэл гадагшаа гараад дахин дотогшоо орж ирэх зам мэт дүрслэлээс гаралтай гэж тайлбарладаг.", "stroke_count": 6, "stroke_tips_mn": ["Эхлээд гадна хайрцгийг зурна: зүүн тал, дээд тал, баруун тал, доод тал", "Дараа нь дотор жижиг хайрцгийг мөн адил дарааллаар зур"], "confusable": [{"zh": "因", "pinyin": "yīn", "mn": "учир нь", "diff_mn": "хоёул гадна хайрцагтай ч 回-ийн дотор жижиг 口, 因-ийн дотор 大 байдгаараа ялгаатай."}], "words": [{"zh": "回来", "pinyin": "huílai", "mn": "буцаж ирэх"}, {"zh": "回家", "pinyin": "huí jiā", "mn": "гэртээ буцах"}, {"zh": "回去", "pinyin": "huíqu", "mn": "буцаж явах"}]}], "pronunciation": {"focus_mn": "Энэ хичээлд 了, 啊 зэрэг сул хөгтэй туслах үгсийн богино, сулхан дуудлагад анхаарах хэрэгтэй. Мөн 3-р хөгөөр эхэлсэн гурван үет үгсийн хөгийн хослолыг сайн дадлагажуулаарай.", "drills": [{"title_mn": "Сул хөг (轻声) дадлага: 了 / 啊", "instruction_mn": "Хосыг дараалан хэлж, 了/啊 нэмэгдэхэд сүүлийн үе хэрхэн сулран богиноссоныг анзаараарай.", "pairs": [{"a": {"zh": "买", "pinyin": "mǎi", "mn": "худалдаж авах"}, "b": {"zh": "买了", "pinyin": "mǎile", "mn": "худалдаж авсан"}, "note_mn": "了 нэмэгдэхэд сүүлийн үе сулран богиноссоныг анзаар."}, {"a": {"zh": "是", "pinyin": "shì", "mn": "мөн"}, "b": {"zh": "是啊", "pinyin": "shì a", "mn": "тийм ээ"}, "note_mn": "啊 нь бие даасан хөггүй, сулхан «а» болж дуудагдана."}, {"a": {"zh": "去", "pinyin": "qù", "mn": "явах"}, "b": {"zh": "去了", "pinyin": "qùle", "mn": "явсан"}, "note_mn": "了 үргэлж сул хөгтэй, чангаар бүү дуудаарай."}, {"a": {"zh": "看见", "pinyin": "kànjiàn", "mn": "харах"}, "b": {"zh": "看见了", "pinyin": "kànjiàn le", "mn": "харсан"}, "note_mn": "了-г богино, түргэн дуудна."}]}, {"title_mn": "3-р хөгөөр эхэлсэн гурван үет хослол", "instruction_mn": "Хосыг сонсоод дага, эхний 3-р хөгийг намхан, тэгш бари.", "pairs": [{"a": {"zh": "洗衣机", "pinyin": "xǐyījī", "mn": "угаалгын машин"}, "b": {"zh": "火车票", "pinyin": "huǒchē piào", "mn": "галт тэрэгний тасалбар"}, "note_mn": "3+1+1 ба 3+1+4 хослол — эхний 3-р хөгийг нам бөгөөд тэгш бари."}, {"a": {"zh": "警察局", "pinyin": "jǐngchájú", "mn": "цагдаагийн газар"}, "b": {"zh": "表演家", "pinyin": "biǎoyǎnjiā", "mn": "жүжигчин"}, "note_mn": "3+2+x ба 3+3+x хослолыг ялгаж дуудна."}, {"a": {"zh": "打字机", "pinyin": "dǎzìjī", "mn": "бичгийн машин"}, "b": {"zh": "打电话", "pinyin": "dǎ diànhuà", "mn": "утсаар ярих"}, "note_mn": "打-г намхан 3-р хөгөөр эхэлж, дараагийн үеийг тодорхой хэл."}]}, {"title_mn": "儿化 дуудлага: 一点儿", "instruction_mn": "儿-тэй ба чгүй хосыг харьцуулан хэлж, 儿-ийг өмнөх үетэйгээ нийлүүлж дуудахыг дадлагажуул.", "pairs": [{"a": {"zh": "一点", "pinyin": "yìdiǎn", "mn": "жаахан (儿-гүй)"}, "b": {"zh": "一点儿", "pinyin": "yìdiǎnr", "mn": "жаахан (儿-тэй)"}, "note_mn": "儿 нэмэгдэхэд өмнөх үетэйгээ нийлж нэг үе шиг сонсогдоно, тусад нь бүү дуудаарай."}, {"a": {"zh": "那", "pinyin": "nà", "mn": "тэр"}, "b": {"zh": "那儿", "pinyin": "nàr", "mn": "тэнд"}, "note_mn": "儿化 нь газар зааж буй үгэнд элбэг таардаг."}, {"a": {"zh": "哪", "pinyin": "nǎ", "mn": "аль"}, "b": {"zh": "哪儿", "pinyin": "nǎr", "mn": "хаана"}, "note_mn": "儿 нэмэгдэхэд хөг өөрчлөгддөггүй, зөвхөн эцсийн авиа r болно."}]}], "tips_mn": ["了, 啊, 吧, 呢 зэрэг бүх сул хөгт үгсийг богино бөгөөд бага хүчээр дуудна.", "儿化 үгсийг тусад нь бус өмнөх үетэйгээ нийлүүлж нэг амьсгалаар хэл.", "3-р хөгөөр эхэлсэн олон үет үгэнд эхний үеийг хэт гүн бүү ав, дараагийн үедээ анхаарлаа шилжүүл."]}}'::jsonb)
