values ('hsk1-l15', 1, '{"words": [{"zh": "认识", "pinyin": "rènshi", "teach_mn": "«认识» нь хүнтэй танилцах, эсвэл зүйл, үсэг таних гэсэн хоёр утгатай үйл үг. Хүний тухай ярихдаа «танил, танилцсан» гэсэн утгаар голчлон хэрэглэгддэг. Хэн нэгэнтэй анх удаа уулзаж танилцахдаа 认识 хэрэглэнэ.", "usage_mn": ["Хүнтэй анх удаа танилцах, дараа нь тухайн хүнийг таньдаг болсноо илэрхийлэхэд хэрэглэнэ", "Тэмдэгт, ном, газар зэргийг «таньдаг» гэдгийг илэрхийлэхэд ч хэрэглэж болно"], "examples": [{"zh": "你们是什么时候认识的？", "pinyin": "Nǐmen shì shénme shíhou rènshi de?", "mn": "Та нар хэзээ танилцсан бэ?"}, {"zh": "我们是2011年9月认识的。", "pinyin": "Wǒmen shì èr líng yī yī nián jiǔ yuè rènshi de.", "mn": "Бид 2011 оны 9-р сард танилцсан."}, {"zh": "很高兴认识您！", "pinyin": "Hěn gāoxìng rènshi nín!", "mn": "Тантай танилцсандаа баяртай байна!"}, {"zh": "我不认识他。", "pinyin": "Wǒ bú rènshi tā.", "mn": "Би түүнийг танихгүй."}], "mistakes": [{"wrong": "我认识他了昨天。", "right": "我昨天认识他了。", "why_mn": "цаг заасан үг (昨天) нь үйл үгийн ӨМНӨ ордог, ард нь тавьж болохгүй."}]}, {"zh": "年", "pinyin": "nián", "teach_mn": "«年» нь «он, жил» гэсэн цаг хугацааны нэгж. Он хэлэхдээ цифрийг нэг нэгээр нь уншиж 年-г ард нь залгана: 2011年 = èr líng yī yī nián. Мөн «жил тутам» гэсэн ойлголтод ч хэрэглэгдэнэ.", "usage_mn": ["Тодорхой оныг хэлэхдээ цифр бүрийг тусад нь уншаад ард нь залгана", "Хэдэн жил гэдгийг тоолоход ч хэрэглэнэ"], "examples": [{"zh": "我们是2011年9月认识的。", "pinyin": "Wǒmen shì èr líng yī yī nián jiǔ yuè rènshi de.", "mn": "Бид 2011 оны 9-р сард танилцсан."}, {"zh": "明天是2014年5月11号。", "pinyin": "Míngtiān shì èr líng yī sì nián wǔ yuè shíyī hào.", "mn": "Маргааш 2014 оны 5 сарын 11."}, {"zh": "今年我二十岁。", "pinyin": "Jīnnián wǒ èrshí suì.", "mn": "Энэ жил би хорин настай."}, {"zh": "我在这个学校学习了一年。", "pinyin": "Wǒ zài zhège xuéxiào xuéxíle yì nián.", "mn": "Би энэ сургуульд нэг жил сурсан."}], "mistakes": [{"wrong": "二千零十一年", "right": "二零一一年", "why_mn": "оныг хэлэхдээ бүхэл тоо биш цифр БҮРИЙГ тусад нь дараалуулан уншина."}]}, {"zh": "大学", "pinyin": "dàxué", "teach_mn": "«大学» нь дунд сургуулиас дараагийн шатны боловсролын байгууллага, «их сургууль» гэсэн утгатай. 大 (том)+学(сургууль) хоёр ханзнаас бүрдэнэ.", "usage_mn": ["Их сургуульд суралцах, ажиллах тухай ярихад хэрэглэнэ", "大学同学 гэвэл «их сургуулийн курсын найз» гэсэн утга болно"], "examples": [{"zh": "她是我大学同学。", "pinyin": "Tā shì wǒ dàxué tóngxué.", "mn": "Тэр миний их сургуулийн курсын найз."}, {"zh": "我在大学学习汉语。", "pinyin": "Wǒ zài dàxué xuéxí Hànyǔ.", "mn": "Би их сургуульд хятад хэл сурч байна."}, {"zh": "这是北京的一个大学。", "pinyin": "Zhè shì Běijīng de yí gè dàxué.", "mn": "Энэ бол Бээжингийн нэг их сургууль."}], "mistakes": [{"wrong": "我大学是学生。", "right": "我是大学生。", "why_mn": "«их сургуулийн оюутан» гэдгийг 大学生 гэж нэг үг болгож хэлэх нь зөв, 大学 ба 是-г шууд залгаж болохгүй."}]}, {"zh": "饭店", "pinyin": "fàndiàn", "teach_mn": "«饭店» нь анх «ресторан» гэсэн утгатай байсан ч орчин үед «зочид буудал» гэсэн утгаар ч элбэг хэрэглэгддэг — 饭 (хоол) + 店 (дэлгүүр) гэсэн хоёр ханзнаас тогтоно. Утга нь ярианы орчноос шалтгаалж тодорхойлогддог.", "usage_mn": ["Зочид буудал, эсвэл томоохон рестораныг нэрлэхэд хэрэглэнэ", "Аль утгаар нь хэрэглэж байгааг ойролцоо үгнээс (жишээ нь 住 «байрлах» эсвэл 吃饭 «хоол идэх») таамаглаж болно"], "examples": [{"zh": "你们是怎么来饭店的？", "pinyin": "Nǐmen shì zěnme lái fàndiàn de?", "mn": "Та нар зочид буудалд яаж ирсэн бэ?"}, {"zh": "我住在这个饭店。", "pinyin": "Wǒ zhù zài zhège fàndiàn.", "mn": "Би энэ зочид буудалд байрладаг."}, {"zh": "我们去饭店吃饭吧。", "pinyin": "Wǒmen qù fàndiàn chīfàn ba.", "mn": "Бид рестораны явж хоол идье."}], "mistakes": [{"wrong": "我在饭店买东西。", "right": "我在商店买东西。", "why_mn": "饭店 нь хоол идэх, байрлах газар, харин 商店 нь юм худалдаж авах дэлгүүр — хольж хэрэглэж болохгүй."}]}, {"zh": "出租车", "pinyin": "chūzūchē", "teach_mn": "«出租车» нь 出租 (түрээслэх) + 车 (машин) гэсэн үгнээс тогтсон, «такси» гэсэн утгатай. Ямар нэгэн газар явахдаа мөнгөөр түрээслэдэг машиныг ингэж нэрлэдэг.", "usage_mn": ["Такси унах, дуудах тухай ярихад хэрэглэнэ", "坐出租车 (таксинд суух) гэдэг хэллэгээр голчлон гардаг"], "examples": [{"zh": "我们是坐出租车来的。", "pinyin": "Wǒmen shì zuò chūzūchē lái de.", "mn": "Бид таксигаар ирсэн."}, {"zh": "请给我叫一辆出租车。", "pinyin": "Qǐng gěi wǒ jiào yí liàng chūzūchē.", "mn": "Надад такси дуудаж өгөөч."}, {"zh": "出租车在哪儿？", "pinyin": "Chūzūchē zài nǎr?", "mn": "Такси хаана байна?"}], "mistakes": [{"wrong": "我开出租车来的。", "right": "我坐出租车来的。", "why_mn": "такси унах гэдэг нь жолоочийн машинд «сууж» явна гэсэн үг тул 坐 хэрэглэнэ, 开 (өөрөө жолоодох) биш."}]}, {"zh": "一起", "pinyin": "yìqǐ", "teach_mn": "«一起» нь «хамт, цуг» гэсэн дайвар үг, хоёр ба түүнээс дээш хүн нэг үйлийг хамтдаа хийж байгааг заана. Ихэвчлэн «和……一起» (…-тай хамт) хэлбэрээр өмнөх хүнтэйгээ хамтарч байна гэдгийг тодотгодог.", "usage_mn": ["Хоёр ба түүнээс дээш хүн ижил үйлийг хамт хийж байгааг заахад хэрэглэнэ", "和 + хүн + 一起 + үйл үг хэлбэрээр их хэрэглэгддэг"], "examples": [{"zh": "他是和朋友一起开车来的。", "pinyin": "Tā shì hé péngyou yìqǐ kāi chē lái de.", "mn": "Тэр найзтайгаа хамт машинаар ирсэн."}, {"zh": "我们一起去吃饭吧。", "pinyin": "Wǒmen yìqǐ qù chīfàn ba.", "mn": "Бид хамт хоол идэхээр явцгаая."}, {"zh": "我和他一起学习汉语。", "pinyin": "Wǒ hé tā yìqǐ xuéxí Hànyǔ.", "mn": "Би түүнтэй хамт хятад хэл сурдаг."}], "mistakes": [{"wrong": "我一起和他去。", "right": "我和他一起去。", "why_mn": "和+хүн нь эхэлж ирнэ, 一起 дараа нь орж хамт хийж байгааг тодотгоно."}]}, {"zh": "高兴", "pinyin": "gāoxìng", "teach_mn": "«高兴» нь тухайн мөчид сэтгэл ханамжтай, баяртай байгаа мэдрэмжийг заасан тэмдэг нэр. Хэн нэгэнтэй танилцаад 很高兴认识你 гэдэг хэллэгийг өдөр тутам их ашигладаг.", "usage_mn": ["Тухайн үед мэдэрч буй баяр хөөрийг илэрхийлэхэд хэрэглэнэ", "很高兴认识你/您 хэлбэрээр танилцсаны дараа ёсоор хэлдэг тогтмол хэллэг болдог"], "examples": [{"zh": "很高兴认识您！", "pinyin": "Hěn gāoxìng rènshi nín!", "mn": "Тантай танилцсандаа баяртай байна!"}, {"zh": "认识你我也很高兴！", "pinyin": "Rènshi nǐ wǒ yě hěn gāoxìng!", "mn": "Би ч бас тантай танилцсандаа баяртай байна!"}, {"zh": "今天我很高兴。", "pinyin": "Jīntiān wǒ hěn gāoxìng.", "mn": "Өнөөдөр би их баяртай байна."}], "mistakes": [{"wrong": "我高兴很。", "right": "我很高兴。", "why_mn": "хэмжээ заасан 很 нь тэмдэг нэрийн ӨМНӨ ордог, ард нь тавьж болохгүй."}]}, {"zh": "听", "pinyin": "tīng", "teach_mn": "«听» нь «сонсох» гэсэн энгийн үйл үг. «听……说» гэдэг тогтмол хэллэг нь «...-аас сонссоноор» гэсэн утгатай, мэдээллийн эх сурвалжаа дурдахад хэрэглэгддэг.", "usage_mn": ["Ямар нэг дуу авиа, хэн нэгний ярианыг сонсох тухай ярихад хэрэглэнэ", "听……说 хэлбэрээр мэдээллийн эх сурвалжийг дурдахад хэрэглэнэ"], "examples": [{"zh": "听张先生说，您是坐飞机来北京的。", "pinyin": "Tīng Zhāng xiānsheng shuō, nín shì zuò fēijī lái Běijīng de.", "mn": "Жан ноёноос сонссоноор та онгоцоор Бээжинд ирсэн гэсэн."}, {"zh": "我喜欢听音乐。", "pinyin": "Wǒ xǐhuan tīng yīnyuè.", "mn": "Би хөгжим сонсоход дуртай."}, {"zh": "你听说了吗？", "pinyin": "Nǐ tīngshuō le ma?", "mn": "Чи сонссон уу?"}], "mistakes": [{"wrong": "我说听音乐。", "right": "我听音乐。", "why_mn": "«сонсох» гэдэг үйл үг 听-г 说 (ярих)-той хольж хэрэглэж болохгүй, тус тусдаа өөр утгатай."}]}, {"zh": "飞机", "pinyin": "fēijī", "teach_mn": "«飞机» нь 飞 (нисэх) + 机 (машин) гэсэн хоёр ханзнаас тогтсон «онгоц» гэсэн үг. Тээврийн хэрэгслээр аялах тухай ярихдаа 坐飞机 (онгоцоор явах) гэдэг хэлбэрээр их хэрэглэнэ.", "usage_mn": ["Онгоцоор аялах тухай ярихад хэрэглэнэ", "坐飞机 гэдэг тогтмол хэллэгийн нэг хэсэг болж ордог"], "examples": [{"zh": "我是坐飞机来的。", "pinyin": "Wǒ shì zuò fēijī lái de.", "mn": "Би онгоцоор ирсэн."}, {"zh": "我是坐飞机来北京的。", "pinyin": "Wǒ shì zuò fēijī lái Běijīng de.", "mn": "Би онгоцоор Бээжинд ирсэн."}, {"zh": "飞机什么时候到？", "pinyin": "Fēijī shénme shíhou dào?", "mn": "Онгоц хэзээ ирэх вэ?"}], "mistakes": [{"wrong": "我开飞机来的。", "right": "我坐飞机来的。", "why_mn": "энгийн зорчигч онгоцонд «сууж» явдаг тул 坐 хэрэглэнэ, 开 (өөрөө жолоодох) зөвхөн нисгэгчид хамаарна."}]}], "grammar": [{"point": "是……的 句", "gloss_mn": "是……的: цаг, газар, аргыг онцлох", "structure": "(是) + цаг/газар/арга + үйл үг + 的", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "是……的 бол АЛЬ ХЭДИЙН болсон, тодорхой үйлийн ХЭЗЭЭ, ХААНА, ЯАЖ болсныг тодотгож онцлоход хэрэглэдэг бүтэц. Тухайн үйл болсон эсэх нь мэдэгдэж байгаа, зөвхөн нарийвчилсан мэдээллийг л асууж, хэлж байна.", "example": {"zh": "我是昨天来的。", "pinyin": "Wǒ shì zuótiān lái de.", "mn": "Би өчигдөр ирсэн (юм)."}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "是 нь үйл үгийн ӨМНӨ, 的 нь өгүүлбэрийн ЭЦЭСТ ордог: 是 + (цаг/газар/арга) + үйл үг + 的.", "example": {"zh": "我们是在学校认识的。", "pinyin": "Wǒmen shì zài xuéxiào rènshi de.", "mn": "Бид сургуульд танилцсан."}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Аль хэдийн болсон явдлын НАРИЙВЧЛАЛ дээр анхаарал хандуулж асуух, хариулахад хэрэглэнэ — хэн нэгэн хэдийн ирснийг мэдэж байгаа ч ЯАЖ ирснийг мэдэхгүй байх үед.", "example": {"zh": "你们是怎么来饭店的？", "pinyin": "Nǐmen shì zěnme lái fàndiàn de?", "mn": "Та нар зочид буудалд яаж ирсэн бэ?"}}, {"title_mn": "4. Хэрэв хэрэгтэй бол өргөтгөл/үгүйсгэл", "body_mn": "Батлах өгүүлбэрт 是-г ярианд орхиж болно, гэхдээ ҮГҮЙСГЭХДЭЭ 是-г ОРХИЖ БОЛОХГҮЙ: 我不是昨天来的 зөв, 我不昨天来的 буруу.", "example": {"zh": "我不是昨天来的。", "pinyin": "Wǒ bú shì zuótiān lái de.", "mn": "Би өчигдөр ирээгүй (өөр өдөр ирсэн)."}}], "examples": [{"zh": "我们是坐出租车来的。", "pinyin": "Wǒmen shì zuò chūzūchē lái de.", "mn": "Бид таксигаар ирсэн."}, {"zh": "我们是在学校认识的。", "pinyin": "Wǒmen shì zài xuéxiào rènshi de.", "mn": "Бид сургуульд танилцсан."}, {"zh": "我是坐飞机来的。", "pinyin": "Wǒ shì zuò fēijī lái de.", "mn": "Би онгоцоор ирсэн."}, {"zh": "你们是怎么来饭店的？", "pinyin": "Nǐmen shì zěnme lái fàndiàn de?", "mn": "Та нар зочид буудалд яаж ирсэн бэ?"}, {"zh": "我不是昨天来的。", "pinyin": "Wǒ bú shì zuótiān lái de.", "mn": "Би өчигдөр ирээгүй."}, {"zh": "我们是2011年9月认识的。", "pinyin": "Wǒmen shì èr líng yī yī nián jiǔ yuè rènshi de.", "mn": "Бид 2011 оны 9-р сард танилцсан."}, {"zh": "他是和朋友一起开车来的。", "pinyin": "Tā shì hé péngyou yìqǐ kāi chē lái de.", "mn": "Тэр найзтайгаа хамт машинаар ирсэн."}], "mistakes": [{"wrong": "我不昨天来的。", "right": "我不是昨天来的。", "why_mn": "是……的 бүтцийн үгүйсгэлд 是-г заавал үлдээнэ, орхиж болохгүй."}, {"wrong": "我是来的昨天。", "right": "我是昨天来的。", "why_mn": "цаг/газар/арга заасан үг нь үйл үгийн ӨМНӨ, 的 нь өгүүлбэрийн хамгийн ЭЦЭСТ ордог."}], "drills": [{"type": "choice", "question": "你们是___来饭店的？", "options": ["怎么", "什么", "谁"], "answer": "怎么", "why_mn": "«яаж» гэдэг аргыг асуухад 怎么 хэрэглэнэ."}, {"type": "fill", "question": "«Бид таксигаар ирсэн» гэдгийг 是……的-ээр бич.", "answer": "我们是坐出租车来的。", "why_mn": "арга онцлохдоо 是+坐出租车+来+的 хэлбэрээр угсарна."}, {"type": "judge", "question": "我不昨天来的 гэдэг өгүүлбэр зөв.", "answer": "false", "why_mn": "үгүйсгэлд 是-г заавал үлдээх ёстой тул энэ өгүүлбэр буруу."}, {"type": "choice", "question": "Хамгийн зөв өгүүлбэрийг сонго.", "options": ["我是在学校认识的。", "我在学校是认识的。", "我认识是在学校的。"], "answer": "我是在学校认识的。", "why_mn": "是 үйл үгийн бүлгийн өмнө, 的 өгүүлбэрийн эцэст ордог."}]}, {"point": "日期的表达 (2)", "gloss_mn": "Он сар өдөр хэлэх: 年-月-日-星期", "structure": "он(цифр тус тус)+年 сар(тоо)+月 өдөр(тоо)+号 [гараг]", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "Хятад хэлэнд огноог ХАМГИЙН ТОМ нэгжээс ХАМГИЙН ЖИЖИГ нэгж рүү дараалуулан хэлдэг: он → сар → өдөр → гараг. Энэ нь монгол хэлний дараалалтай ижил.", "example": {"zh": "2008年8月8号，星期五", "pinyin": "èr líng líng bā nián bā yuè bā hào, xīngqīwǔ", "mn": "2008 оны 8 сарын 8, баасан гараг"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "Оныг ЦИФР БҮРИЙГ тусад нь дараалуулан уншиж, ард нь 年 залгана. Сар, өдрийг бол бүхэл тоогоор нь уншина.", "example": {"zh": "2011年9月", "pinyin": "èr líng yī yī nián jiǔ yuè", "mn": "2011 оны 9-р сар"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Төрсөн он, аялсан огноо, уулзалт товлохдоо огноог бүтнээр хэлэхэд хэрэглэнэ.", "example": {"zh": "明天是2014年5月11号。", "pinyin": "Míngtiān shì èr líng yī sì nián wǔ yuè shíyī hào.", "mn": "Маргааш 2014 оны 5 сарын 11."}}, {"title_mn": "4. Ялгаа", "body_mn": "Хятад хэлэнд оныг зөвхөн ЦИФР БҮРЭЭР тусад нь уншина, «хоёр мянга арван нэг» гэж нэг бүхэл тоо шиг уншдаггүй.", "example": {"zh": "2011 → èr líng yī yī", "pinyin": "èr líng yī yī nián", "mn": "2011 он"}}], "examples": [{"zh": "明天是2014年5月11号。", "pinyin": "Míngtiān shì èr líng yī sì nián wǔ yuè shíyī hào.", "mn": "Маргааш 2014 оны 5 сарын 11."}, {"zh": "我们是2011年9月认识的。", "pinyin": "Wǒmen shì èr líng yī yī nián jiǔ yuè rènshi de.", "mn": "Бид 2011 оны 9-р сард танилцсан."}, {"zh": "今天是几月几号？", "pinyin": "Jīntiān shì jǐ yuè jǐ hào?", "mn": "Өнөөдөр хэдэн сарын хэд вэ?"}, {"zh": "我的生日是十月八号。", "pinyin": "Wǒ de shēngri shì shí yuè bā hào.", "mn": "Миний төрсөн өдөр 10 сарын 8."}, {"zh": "2008年8月8号是星期五。", "pinyin": "Èr líng líng bā nián bā yuè bā hào shì xīngqīwǔ.", "mn": "2008 оны 8 сарын 8 нь баасан гараг."}], "mistakes": [{"wrong": "8号5月2014年", "right": "2014年5月8号", "why_mn": "хятад хэлэнд огноог ЯМАГТ он→сар→өдөр дарааллаар хэлнэ, эсрэгээр эргүүлж хэлж болохгүй."}, {"wrong": "二千零十一年", "right": "二零一一年", "why_mn": "оныг мянга, зуу гэх мэт бүхэл нэгжээр биш, цифр БҮРИЙГ тусад нь дараалуулан уншина."}], "drills": [{"type": "fill", "question": "2011 оныг хятадаар цифрээр унш.", "answer": "二零一一年", "why_mn": "цифр бүрийг тусад нь дараалуулан уншина."}, {"type": "choice", "question": "Огноог зөв дараалалд оруул.", "options": ["2014年5月11号", "11号5月2014年", "5月2014年11号"], "answer": "2014年5月11号", "why_mn": "он-сар-өдөр гэсэн том→жижиг дараалалтай."}, {"type": "judge", "question": "Хятад хэлэнд оныг бүхэл тоо шиг уншдаг.", "answer": "false", "why_mn": "оныг цифр бүрээр тусад нь уншдаг, бүхэл тоо шиг уншдаггүй."}, {"type": "fill", "question": "«Өнөөдөр хэдэн сарын хэд вэ?» гэж хятадаар асуу.", "answer": "今天是几月几号？", "why_mn": "几月几号 нь сар, өдрийг хамт асуух хэлбэр."}]}, {"point": "坐/开 + тээвэр", "gloss_mn": "Тээврээр явахаа хэлэх", "structure": "坐 + тээврийн хэрэгсэл (зорчигчоор) / 开 + 车 (жолоочоор) / 和 + хүн + 一起", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "Тээврийн хэрэгслээр явахаа хэлэхдээ ХЭН ЯАЖ ЯВАХААС нь хамаараад 坐 (сууж явах, зорчигч) эсвэл 开 (өөрөө жолоодож явах) гэсэн өөр үйл үг сонгоно.", "example": {"zh": "坐飞机 / 开车", "pinyin": "zuò fēijī / kāi chē", "mn": "онгоцонд суух / машин жолоодох"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "坐/开 + тээврийн хэрэгслийн нэр, дараа нь чиглэл заасан үйл үг (来/去): 坐飞机来, 开车来.", "example": {"zh": "我是坐飞机来北京的。", "pinyin": "Wǒ shì zuò fēijī lái Běijīng de.", "mn": "Би онгоцоор Бээжинд ирсэн."}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Хэн нэгэн хэрхэн, ямар тээврээр ирснийг, явснаа хэлэхдээ хэрэглэнэ. Хэн нэгэнтэй хамт явсан бол 和……一起-г нэмж болно.", "example": {"zh": "他是和朋友一起开车来的。", "pinyin": "Tā shì hé péngyou yìqǐ kāi chē lái de.", "mn": "Тэр найзтайгаа хамт машинаар ирсэн."}}, {"title_mn": "4. Ялгаа", "body_mn": "坐出租车 (такси мэт машинд ЗОРЧИГЧООР сууж явах) ба 开车 (ӨӨРӨӨ жолоодох) хоёрыг андуурч болохгүй — ялгаа нь ХЭН ЖОЛОО БАРЬЖ БАЙГААГААС хамаарна.", "example": {"zh": "坐出租车 / 开车", "pinyin": "zuò chūzūchē / kāi chē", "mn": "таксинд суух / өөрөө жолоодох"}}], "examples": [{"zh": "我是坐飞机来北京的。", "pinyin": "Wǒ shì zuò fēijī lái Běijīng de.", "mn": "Би онгоцоор Бээжинд ирсэн."}, {"zh": "他是和朋友一起开车来的。", "pinyin": "Tā shì hé péngyou yìqǐ kāi chē lái de.", "mn": "Тэр найзтайгаа хамт машинаар ирсэн."}, {"zh": "我们是坐出租车来的。", "pinyin": "Wǒmen shì zuò chūzūchē lái de.", "mn": "Бид таксигаар ирсэн."}, {"zh": "你是怎么来的？— 我是坐车来的。", "pinyin": "Nǐ shì zěnme lái de? — Wǒ shì zuò chē lái de.", "mn": "Чи яаж ирсэн бэ? — Би машинтай ирсэн."}, {"zh": "他会开车，但是今天他是坐出租车来的。", "pinyin": "Tā huì kāi chē, dànshì jīntiān tā shì zuò chūzūchē lái de.", "mn": "Тэр машин барьж чаддаг ч өнөөдөр таксигаар ирсэн."}], "mistakes": [{"wrong": "我坐开车来的。", "right": "我开车来的。", "why_mn": "坐 (зорчигчоор) ба 开 (жолоочоор)-ыг хамт хэрэглэж болохгүй, аль нэгийг сонго."}, {"wrong": "他和一起朋友开车来的。", "right": "他和朋友一起开车来的。", "why_mn": "和+хүн эхэлж ирнэ, 一起 дараа нь орно, дараалал андуурч болохгүй."}], "drills": [{"type": "choice", "question": "Онгоцонд зорчигчоор явахыг хэлэхэд аль үйл үгийг ашиглах вэ?", "options": ["坐", "开", "听"], "answer": "坐", "why_mn": "онгоцонд зорчигчоор сууж явдаг тул 坐 хэрэглэнэ."}, {"type": "judge", "question": "开车 гэдэг нь заавал өөрөө жолоо барьж явна гэсэн үг.", "answer": "true", "why_mn": "开 нь жолоодох үйлдлийг заана."}, {"type": "fill", "question": "«Тэр найзтайгаа хамт машинаар ирсэн» гэдгийг бич.", "answer": "他是和朋友一起开车来的。", "why_mn": "和+хүн+一起+开车+来+的 гэсэн дараалалтай."}, {"type": "choice", "question": "«Бид таксигаар ирсэн» гэдгийг зөв илэрхийлбэл:", "options": ["我们是坐出租车来的。", "我们是开出租车来的。", "我们是坐出租车去的。"], "answer": "我们是坐出租车来的。", "why_mn": "такси зорчигчоор сууж явдаг тул 坐, чиглэл нь ярьж буй газар руу тул 来."}]}, {"point": "听……说", "gloss_mn": "听……说: «...-аас сонссоноор»", "structure": "听 + хэн + 说, + агуулга", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "听……说 нь мэдээллийг ХЭНЭЭС сонссоноо тодорхой дурдаж, дараа нь ЮУ сонссоноо хэлэхэд хэрэглэдэг хэллэг. Монгол хэлний «...-аас сонссоноор» гэдэгтэй яг адил утгатай.", "example": {"zh": "听老师说……", "pinyin": "tīng lǎoshī shuō……", "mn": "багшаас сонссоноор..."}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "听 + мэдээллийн эх сурвалж (хүн) + 说, дараа нь таслалаар тусгаарлаад агуулгыг нь өгүүлнэ.", "example": {"zh": "听张先生说，您是坐飞机来北京的。", "pinyin": "Tīng Zhāng xiānsheng shuō, nín shì zuò fēijī lái Běijīng de.", "mn": "Жан ноёноос сонссоноор та онгоцоор Бээжинд ирсэн гэсэн."}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Өөрөө биш, өөр хүнээс дамжуулж мэдсэн мэдээллийг ярихдаа хэрэглэнэ — мэдээллийн үнэн эсэхийг бүрэн батлаагүй байгааг ч далд илэрхийлдэг.", "example": {"zh": "听朋友说，那个饭店很好吃。", "pinyin": "Tīng péngyou shuō, nàge fàndiàn hěn hǎochī.", "mn": "Найзаасаа сонссоноор тэр рестораны хоол их амттай."}}, {"title_mn": "4. Өргөтгөл", "body_mn": "Хэнээс сонссоноо тодорхой хэлэхгүй ерөнхийд нь мэдээлэхэд «听说» гэж хоёуланг нь залгаад л хэлж болно.", "example": {"zh": "听说他回来了。", "pinyin": "Tīngshuō tā huílai le.", "mn": "Сонссоноор тэр буцаж ирсэн гэсэн."}}], "examples": [{"zh": "听张先生说，您是坐飞机来北京的。", "pinyin": "Tīng Zhāng xiānsheng shuō, nín shì zuò fēijī lái Běijīng de.", "mn": "Жан ноёноос сонссоноор та онгоцоор Бээжинд ирсэн гэсэн."}, {"zh": "听朋友说，那个饭店很好吃。", "pinyin": "Tīng péngyou shuō, nàge fàndiàn hěn hǎochī.", "mn": "Найзаасаа сонссоноор тэр рестораны хоол их амттай."}, {"zh": "听说他回来了。", "pinyin": "Tīngshuō tā huílai le.", "mn": "Сонссоноор тэр буцаж ирсэн гэсэн."}, {"zh": "听老师说，明天没有课。", "pinyin": "Tīng lǎoshī shuō, míngtiān méiyǒu kè.", "mn": "Багшаас сонссоноор маргааш хичээлгүй гэсэн."}, {"zh": "听你说，你是在大学认识她的。", "pinyin": "Tīng nǐ shuō, nǐ shì zài dàxué rènshi tā de.", "mn": "Чиний хэлснээр чи түүнтэй их сургуульд танилцсан гэсэн."}], "mistakes": [{"wrong": "张先生听说……", "right": "听张先生说……", "why_mn": "听 нь ЭХЭНД, дараа нь мэдээллийн эх сурвалж, дараа нь 说 гэсэн дараалалтай тогтмол хэллэг."}, {"wrong": "我听说了他回来了了。", "right": "我听说他回来了。", "why_mn": "нэг өгүүлбэрт 了-г хоёр удаа давхар хэрэглэх шаардлагагүй."}], "drills": [{"type": "fill", "question": "«Багшаас сонссоноор маргааш хичээлгүй» гэдгийг бич.", "answer": "听老师说，明天没有课。", "why_mn": "听+эх сурвалж+说+агуулга гэсэн дараалалтай."}, {"type": "choice", "question": "«...-аас сонссоноор» гэдгийг илэрхийлэхэд аль хэллэгийг ашиглах вэ?", "options": ["听……说", "看……说", "说……听"], "answer": "听……说", "why_mn": "энэ бол мэдээллийн эх сурвалжийг заасан тогтмол хэллэг."}, {"type": "judge", "question": "听说 гэдгийг хэнээс сонссоноо тодорхойгүйгээр ерөнхийд нь хэлэхэд ашиглаж болно.", "answer": "true", "why_mn": "хэнээс гэдгийг тусгайлан дурдахгүй бол зүгээр 听说 гэж хэлж болно."}, {"type": "choice", "question": "Зөв дараалалтай өгүүлбэрийг сонго.", "options": ["听张先生说，您是坐飞机来的。", "张先生听说，您是坐飞机来的。", "您说听张先生，是坐飞机来的。"], "answer": "听张先生说，您是坐飞机来的。", "why_mn": "听+эх сурвалж+说 бол тогтсон дараалал."}]}, {"point": "汉字 — 年 出 飞, 艹/宀 язгуур", "gloss_mn": "Ханзны бүтэц ба язгуур", "structure": "年(6 зурлага) / 出(5 зурлага) / 飞(3 зурлага); 艹-язгуур, 宀-язгуур", "steps": [{"title_mn": "1. Юу гэсэн үг вэ", "body_mn": "Энэ хичээлд гурван шинэ ханз (年, 出, 飞)-той танилцахын зэрэгцээ хоёр язгуур (艹, 宀)-ыг таньж сурна.", "example": {"zh": "艹 / 宀", "pinyin": "cǎo / mián", "mn": "艹=ургамал, 宀=байшин"}}, {"title_mn": "2. Бүтэц нь яаж угсрагддаг", "body_mn": "年 зургаан зурлага, 出 таван зурлага, 飞 гурван зурлага. 艹-язгуур орсон ханз ургамалтай холбоотой (茶, 菜, 草, 苹), 宀-язгуур орсон ханз байшинтай холбоотой (家, 安, 室).", "example": {"zh": "茶 菜", "pinyin": "chá cài", "mn": "艹 ургамалтай холбоотой"}}, {"title_mn": "3. Хаана, хэзээ хэрэглэх", "body_mn": "Шинэ ханз таарах бүрд эхлээд язгуурыг нь ялгаж, утгыг таамаглах дадал зуршлаа үргэлжлүүлэн бэхжүүл.", "example": {"zh": "家 安", "pinyin": "jiā ān", "mn": "宀 байшинтай холбоотой"}}, {"title_mn": "4. Өргөтгөл", "body_mn": "HSK1 төгсөхөд нийт зургаан язгуур (亻, 氵, 扌, 月, 艹, 宀) үзсэн байна, эдгээрийг цуглуулж давтвал ирээдүйн шинэ ханз танихад их тус болно.", "example": {"zh": "亻 氵 扌 月 艹 宀", "pinyin": "zǒng liù gè bùshǒu", "mn": "HSK1-д үзсэн зургаан язгуур"}}], "examples": [{"zh": "茶 菜", "pinyin": "chá cài", "mn": "艹 ургамалтай холбоотой"}, {"zh": "家 安", "pinyin": "jiā ān", "mn": "宀 байшинтай холбоотой"}, {"zh": "年", "pinyin": "nián", "mn": "жил"}, {"zh": "出", "pinyin": "chū", "mn": "гарах"}, {"zh": "飞", "pinyin": "fēi", "mn": "нисэх"}, {"zh": "草", "pinyin": "cǎo", "mn": "艹 ургамалтай холбоотой нэмэлт жишээ"}, {"zh": "室", "pinyin": "shì", "mn": "宀 байшинтай холбоотой нэмэлт жишээ"}], "mistakes": [{"wrong": "苹 нь 亻-язгууртай.", "right": "苹 нь 艹-язгууртай.", "why_mn": "苹 (алим) ургамлын нэг тул 艹-язгууртай, хүний язгуур 亻-тай биш."}, {"wrong": "宀-язгуур нь малтай холбоотой.", "right": "宀-язгуур нь БАЙШИНТАЙ холбоотой.", "why_mn": "宀 нь дээвэр хэлбэртэй дүрс, байшин, гэр орноос гаралтай ойлголтуудад л ордог."}], "drills": [{"type": "choice", "question": "茶, 菜 ямар язгуурт хамаарах вэ?", "options": ["艹", "宀", "月"], "answer": "艹", "why_mn": "хоёул ургамалтай холбоотой тул 艹-язгуур орсон."}, {"type": "choice", "question": "家, 安 ямар язгуурт хамаарах вэ?", "options": ["艹", "宀", "扌"], "answer": "宀", "why_mn": "хоёул байшинтай холбоотой тул 宀-язгуур орсон."}, {"type": "judge", "question": "飞 нь 3 зурлагатай.", "answer": "true", "why_mn": "飞 хамгийн бага зурлагатай ханзны нэг, гурван зурлагаас тогтоно."}, {"type": "fill", "question": "出 нь хэдэн зурлагатай вэ?", "answer": "5", "why_mn": "出 таван зурлагаас тогтоно."}]}], "hanzi": [{"hanzi": "年", "pinyin": "nián", "meaning_mn": "он, жил", "story_mn": "年 нь эртний бичигт хүн нуруундаа ургацын баглаа үүрч яваа дүрснээс гаралтай гэж үздэг — жил бүр ургац хураадаг явдлаас «жил» гэсэн ойлголт бий болсон.", "stroke_count": 6, "stroke_tips_mn": ["Эхний зурлагыг зүүн налуугаар эхэл", "Дараа нь гурван хэвтээ зурлагыг дараалуулан тат, эцэст нь босоог татаж төгсгө"], "confusable": [{"zh": "午", "pinyin": "wǔ", "mn": "үд", "diff_mn": "хоёул төстэй дүрстэй ч 年 илүү олон зурлагатай, дунд хэсэгтээ илүү зурлагатай."}], "words": [{"zh": "今年", "pinyin": "jīnnián", "mn": "энэ жил"}, {"zh": "明年", "pinyin": "míngnián", "mn": "ирэх жил"}, {"zh": "年级", "pinyin": "niánjí", "mn": "анги (курс)"}]}, {"hanzi": "出", "pinyin": "chū", "meaning_mn": "гарах", "story_mn": "出 нь эртний бичигт нэг хөл нүхнээс, эсвэл агуйнаас гадагш алхаж буй дүрснээс гаралтай гэж тайлбарладаг — дотогшоос гадагш хөдлөх санааг илэрхийлнэ.", "stroke_count": 5, "stroke_tips_mn": ["Зүүн талын босоо, налуу зурлагуудыг дээрээс доош дараалуулан тат", "Баруун талын ижил төстэй хэсгийг мөн адил дарааллаар давтаж тат"], "confusable": [{"zh": "山", "pinyin": "shān", "mn": "уул", "diff_mn": "出 нь 山-тэй төстэй хоёр давхар оройтой дүрстэй ч 出 илүү олон зурлагатай, өргөн дүрстэй."}], "words": [{"zh": "出租车", "pinyin": "chūzūchē", "mn": "такси"}, {"zh": "出去", "pinyin": "chūqu", "mn": "гадагшаа явах"}, {"zh": "出来", "pinyin": "chūlai", "mn": "гадагшаа гарч ирэх"}]}, {"hanzi": "飞", "pinyin": "fēi", "meaning_mn": "нисэх", "story_mn": "飞 нь уламжлалт бичигт 飛 хэлбэртэй бөгөөд шувууны дэлгэсэн жигүүрийг дүрсэлсэн гэж тайлбарладаг. 